	constexpr std::uintptr_t kRVA_BSTArrayAllocatorFunctorHeapVtable = 0x2C4A948;  
	constexpr std::uintptr_t kRVA_BSTArrayIAllocatorFunctorVtable = 0x2C496C8;     
	constexpr std::uintptr_t kRVA_BSTArrayBase_AddUninitialized = 0x1B10D80;        
