	std::uint32_t SubgraphContainerAdd240(std::uint8_t* container, std::uint64_t handle) noexcept
	{
		struct AllocatorFunctor
		{
			std::uintptr_t vtable;
			std::uint8_t* array;
		};
		using AddUninitialized_t = std::uint32_t (*)(std::uint8_t*, AllocatorFunctor*, std::uint32_t, std::uint32_t);
		using ArrayBaseCtor_t = void (*)(void*);
		const auto base = REL::Module::get().base();
		AllocatorFunctor functor{ base + ReflectionRuntime::Rva(kRVA_BSTArrayAllocatorFunctorHeapVtable), container };
		const auto index = reinterpret_cast<AddUninitialized_t>(base + ReflectionRuntime::Rva(kRVA_BSTArrayBase_AddUninitialized))(
			container + 0x10u, std::addressof(functor), *reinterpret_cast<const std::uint32_t*>(container + 8u), 0x48u);
		functor.vtable = base + ReflectionRuntime::Rva(kRVA_BSTArrayIAllocatorFunctorVtable);
		if (index != 0xFFFFFFFFu) {
			auto* entries = *reinterpret_cast<std::uint8_t**>(container);
			if (entries) {
				auto* entry = entries + static_cast<std::size_t>(index) * 0x48u;
				*reinterpret_cast<std::uint64_t*>(entry + 8u) = 0u;
				*reinterpret_cast<std::uint64_t*>(entry) = handle;
				*reinterpret_cast<std::uint32_t*>(entry + 0x10u) = 0x80000000u;
				reinterpret_cast<ArrayBaseCtor_t>(base + ReflectionRuntime::Rva(kRVA_BSTArrayBase_Ctor))(entry + 0x38u);
				*reinterpret_cast<std::uint16_t*>(entry + 0x40u) = 0u;
			}
		}
		return index;
	}
