	[[nodiscard]] bool PlayerThirdPersonModelShown(const RE::PlayerCharacter* player) noexcept
	{
		if (!player)
			return false;
		if (REL::Module::IsVR())
			return (*(reinterpret_cast<const std::uint8_t*>(player) + 0x129Eu) & 0x10u) != 0;

		return player->is3rdPersonModelShown;
	}

	[[nodiscard]] RE::NiAVObject* PlayerThirdPersonRoot(RE::PlayerCharacter* player) noexcept
	{
		if (!player)
			return nullptr;
		if (REL::Module::IsVR())
			return player->loadedData ? player->loadedData->data3D.get() : nullptr;
		return player->Get3D(false);
	}

