	struct PlayerCellIdentity { std::uint32_t formID; const char* editorID; bool interior; bool valid; };
	PlayerCellIdentity ReadPlayerCellIdentity() noexcept
	{
		PlayerCellIdentity identity{};
		__try {
			auto* player = RE::PlayerCharacter::GetSingleton();
			auto* cell = player ? player->GetParentCell() : nullptr;
			if (cell) {
				identity.formID = cell->GetFormID();
				identity.editorID = cell->GetFormEditorID();
				identity.interior = cell->IsInterior();
				identity.valid = true;
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) { identity = {}; }
		return identity;
	}

