	void ConstructCullingGroupsDefault240(void* array, std::uint32_t start, std::uint32_t count) noexcept
	{
		auto* data = *reinterpret_cast<std::uint8_t**>(reinterpret_cast<std::uint8_t*>(array) + 8);
		auto* group = data + static_cast<std::size_t>(start) * 0x170u;
		for (; count != 0u; --count, group += 0x170u) {
			if (!group)
				continue;
			auto* p = reinterpret_cast<std::uint64_t*>(group + 0x70u);
			auto self = [&](std::ptrdiff_t index) { return reinterpret_cast<std::uint64_t>(p + index); };
			auto put32 = [&](std::ptrdiff_t index) { *reinterpret_cast<std::uint32_t*>(p + index) = 0u; };
			p[-2] = 0; p[0] = 0; p[1] = 0; p[2] = 0; p[3] = 0; put32(4); p[-1] = self(-2);
			p[5] = 0; p[7] = 0; p[8] = 0; p[9] = 0; p[10] = 0; put32(11); p[6] = self(5);
			p[12] = 0; p[13] = 0; p[15] = 0; p[16] = 0; p[17] = 0; p[18] = 0; put32(19); p[14] = self(13);
			p[20] = 0; p[23] = 0; p[24] = 0; p[25] = 0; p[26] = 0; put32(27); p[21] = 0; p[22] = self(21);
			p[28] = 0; p[29] = 0; p[30] = 0;
			*reinterpret_cast<std::uint16_t*>(p + 31) = 0u;
			*(group + 0x70u + 0xFAu) = 0u;
		}
	}  
