	template <class T>
	class NeverDestroyed
	{
	public:
		NeverDestroyed() noexcept(std::is_nothrow_default_constructible_v<T>) :
			value_(::new (static_cast<void*>(storage_)) T{})
		{}

		NeverDestroyed(const NeverDestroyed&) = delete;
		NeverDestroyed& operator=(const NeverDestroyed&) = delete;

		[[nodiscard]] T& Get() noexcept { return *value_; }
		[[nodiscard]] const T& Get() const noexcept { return *value_; }

	private:
		alignas(T) std::byte storage_[sizeof(T)]{};
		T* value_{ nullptr };
	};

