	struct LivePlayerAncestry
	{
		static constexpr std::size_t kCapacity = 64;
		std::array<const std::uint8_t*, kCapacity> ancestors{};
		std::size_t count = 0;
		std::array<const std::uint8_t*, 2> roots{};
		std::uint64_t containersSplit = 0;
		std::uint32_t splitLogs = 0;

		void Reset() noexcept
		{
			count = 0;
			roots = {};
		}
		[[nodiscard]] bool IsRoot(const std::uint8_t* node) const noexcept
		{
			return node && (node == roots[0] || node == roots[1]);
		}
		[[nodiscard]] bool Holds(const std::uint8_t* node) const noexcept
		{
			if (!node)
				return false;
			for (std::size_t i = 0; i < count; ++i)
				if (ancestors[i] == node)
					return true;
			return false;
		}
	};
	LivePlayerAncestry g_livePlayerAncestry;

	void AddLivePlayerAncestryUnsafe(const RE::NiAVObject* root, std::size_t slot) noexcept
	{
		if (!root || slot >= g_livePlayerAncestry.roots.size())
			return;
		g_livePlayerAncestry.roots[slot] = reinterpret_cast<const std::uint8_t*>(root);
		auto* current = root->parent;
		for (unsigned depth = 0; current && depth < 48; ++depth, current = current->parent) {
			const auto* bytes = reinterpret_cast<const std::uint8_t*>(current);
			if (g_livePlayerAncestry.Holds(bytes))
				continue;
			if (g_livePlayerAncestry.count >= g_livePlayerAncestry.ancestors.size())
				return;
			g_livePlayerAncestry.ancestors[g_livePlayerAncestry.count++] = bytes;
		}
	}

	void RecordLivePlayerAncestry(const RE::NiAVObject* thirdPerson, const RE::NiAVObject* firstPerson) noexcept
	{
		g_livePlayerAncestry.Reset();
		__try {
			AddLivePlayerAncestryUnsafe(thirdPerson, 0);
			AddLivePlayerAncestryUnsafe(firstPerson, 1);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			
		}
	}

	constexpr std::size_t kMaximumPrivateGoreSuppressions = 512;
	RE::NiAVObject* g_privateGoreSuppressedObjects[kMaximumPrivateGoreSuppressions] = {};
	std::uint32_t g_privateGoreSuppressedCount = 0;

	void SuppressPrivateGoreCapsUnsafe(RE::NiAVObject* root, std::uint32_t depth) noexcept
	{
		
		constexpr std::uint32_t kMaximumDepth = 6;
		constexpr std::uint32_t kMaximumChildren = 512;
		if (!root || depth > kMaximumDepth ||
			g_privateGoreSuppressedCount >= kMaximumPrivateGoreSuppressions)
			return;
		
		if (g_livePlayerAncestry.IsRoot(reinterpret_cast<const std::uint8_t*>(root)))
			return;
		if (PrivatePlayerGeometryIsDismembermentCap(root)) {
			if (!root->GetAppCulled()) {
				NiVirtualDispatch::SetAppCulled(root, true);
				g_privateGoreSuppressedObjects[g_privateGoreSuppressedCount++] = root;
			}
			return;
		}
		auto* node = root->IsNode();
		if (!node)
			return;
		const std::uint32_t children = node->GetRuntimeData().children.size();
		if (children > kMaximumChildren)
			return;
		for (std::uint32_t index = 0; index < children; ++index)
			SuppressPrivateGoreCapsUnsafe(node->GetRuntimeData().children[index].get(), depth + 1);
	}

	void SuppressPrivateGoreCaps(std::uint8_t* nodeB) noexcept
	{
		if (!nodeB)
			return;
		__try {
			SuppressPrivateGoreCapsUnsafe(reinterpret_cast<RE::NiAVObject*>(nodeB), 0);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			
		}
	}

	bool RestorePrivateGoreCapSuppressions() noexcept
	{
		bool restored = true;
		const auto count = (std::min)(
			g_privateGoreSuppressedCount,
			static_cast<std::uint32_t>(kMaximumPrivateGoreSuppressions));
		g_privateGoreSuppressedCount = 0;
		for (std::uint32_t reverse = count; reverse != 0; --reverse) {
			auto*& slot = g_privateGoreSuppressedObjects[reverse - 1u];
			auto* object = slot;
			slot = nullptr;
			if (!object)
				continue;
			__try {
				NiVirtualDispatch::SetAppCulled(object, false);
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				restored = false;
			}
		}
		return restored;
	}

	bool RestorePrivateAppCullOverrides() noexcept
	{
		bool restored = true;
		const auto count = (std::min)(
			g_privateAppCullOverrideCount,
			static_cast<std::uint32_t>(kMaximumPrivateAppCullOverrides));
		g_privateAppCullOverrideCount = 0;
		for (std::uint32_t reverse = count; reverse != 0; --reverse) {
			auto*& slot = g_privateAppCullOverrideObjects[reverse - 1u];
			auto* object = slot;
			slot = nullptr;
			if (!object)
				continue;
			__try {
				NiVirtualDispatch::SetAppCulled(object, true);
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				restored = false;
			}
		}
		if (!RestorePrivateGoreCapSuppressions())
			restored = false;
		if (!restored)
			g_faulted = true;
		return restored;
	}

	[[nodiscard]] bool PrivatePlayerSourceGeometryAppCulled(const RE::BSGeometry* geometry) noexcept
	{
		if (!geometry)
			return false;
		bool culled = false;
		__try {
			culled = geometry->GetAppCulled();
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			culled = false;
		}
		return culled;
	}

	[[nodiscard]] bool PrivatePlayerGeometryIsDismembermentCap(const RE::NiAVObject* object) noexcept
	{
		if (!object)
			return false;
		const char* name = nullptr;
		__try {
			name = object->name.c_str();
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return false;
		}
		if (!name)
			return false;
		for (const char* cursor = name; *cursor; ++cursor) {
			if ((cursor[0] == 'G' || cursor[0] == 'g') &&
				(cursor[1] == 'O' || cursor[1] == 'o') &&
				(cursor[2] == 'R' || cursor[2] == 'r') &&
				(cursor[3] == 'E' || cursor[3] == 'e'))
				return true;
		}
		return false;
	}

	bool ArmPrivateAppCullOverride(const CullEntry& entry) noexcept
	{
		if (!entry.privateAppCullOverrideEligible || !entry.node)
			return true;
		bool armed = false;
		__try {
			auto* object = reinterpret_cast<RE::NiAVObject*>(entry.node);
			if (!object->GetAppCulled())
				return true;

			if (PrivatePlayerGeometryIsDismembermentCap(object))
				return true;
			if (g_privateAppCullOverrideCount >= kMaximumPrivateAppCullOverrides)
				return false;
			g_privateAppCullOverrideObjects[g_privateAppCullOverrideCount++] = object;
			NiVirtualDispatch::SetAppCulled(object, false);
			armed = true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			armed = false;
		}
		return armed;
	}

	bool ArmNativeWorldLivePlayerExclusion(
		RE::NiAVObject* object, const std::uint8_t* receiverRoot) noexcept
	{
		if (!object || reinterpret_cast<const std::uint8_t*>(object) == receiverRoot)
			return true;
		for (std::uint32_t index = 0; index < g_armNativeWorldLivePlayerExclusionCount; ++index) {
			if (g_armNativeWorldLivePlayerExclusions[index].object == object)
				return true;
		}
		if (g_armNativeWorldLivePlayerExclusionCount >=
			g_armNativeWorldLivePlayerExclusions.size())
			return false;
		bool armed = false;
		__try {
			auto& slot = g_armNativeWorldLivePlayerExclusions[
				g_armNativeWorldLivePlayerExclusionCount];
			slot.object = object;
			slot.appCulledSaved = object->GetAppCulled();
			NiVirtualDispatch::SetAppCulled(object, true);
			armed = object->GetAppCulled();
			if (armed)
				++g_armNativeWorldLivePlayerExclusionCount;
			else
				slot = {};
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			armed = false;
		}
		return armed;
	}

	bool RestoreNativeWorldLivePlayerExclusions() noexcept
	{
		bool restored = true;
		const auto count = (std::min)(
			g_armNativeWorldLivePlayerExclusionCount,
			static_cast<std::uint32_t>(g_armNativeWorldLivePlayerExclusions.size()));
		g_armNativeWorldLivePlayerExclusionCount = 0;
		for (std::uint32_t reverse = count; reverse != 0; --reverse) {
			auto& slot = g_armNativeWorldLivePlayerExclusions[reverse - 1u];
			auto* object = slot.object;
			const bool appCulledSaved = slot.appCulledSaved;
			slot = {};
			if (!object)
				continue;
			__try {
				NiVirtualDispatch::SetAppCulled(object, appCulledSaved);
				if (object->GetAppCulled() != appCulledSaved)
					restored = false;
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				restored = false;
			}
		}
		if (!restored)
			g_faulted = true;
		return restored;
	}

	void ResetSubmittedNodes() noexcept
	{
		g_submittedNodeTable.Clear();
		g_privateGroupSubmittedRootCount = 0;
		g_privateGroupSubmissionRecordFaulted = false;
	}

	void SuppressPrivateGoreCaps(std::uint8_t* nodeB) noexcept;  

	void RecordPrivateGroupSubmission(std::uint8_t* node, const void* bound) noexcept
	{
		if (!node || !bound || g_privateGroupSubmittedRootCount >= kMaximumPrivateGroupSubmissions) {
			g_privateGroupSubmissionRecordFaulted = true;
			return;
		}

		SuppressPrivateGoreCaps(node);
		bool copied = false;
		__try {
			const auto index = g_privateGroupSubmittedRootCount;
			g_privateGroupSubmittedRoots[index] = reinterpret_cast<RE::NiAVObject*>(node);
			std::memcpy(
				std::addressof(g_privateGroupSubmittedBounds[index]), bound,
				sizeof(g_privateGroupSubmittedBounds[index]));
			++g_privateGroupSubmittedRootCount;
			copied = true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
		}
		if (!copied)
			g_privateGroupSubmissionRecordFaulted = true;
	}

	bool MarkSubmittedNode(std::uint8_t* node) noexcept
	{
		if (!node || reinterpret_cast<std::uintptr_t>(node) <= 0x10000)
			return false;
		return g_submittedNodeTable.Insert(node); 
	}

	[[nodiscard]] bool SubmittedNodeRecorded(const RE::NiAVObject* node) noexcept
	{
		return g_submittedNodeTable.Contains(node);
	}

	[[nodiscard]] bool PrivateGroupSubmissionsPairwiseSubtreeDisjoint() noexcept
	{
		if (g_privateGroupSubmissionRecordFaulted || g_privateGroupSubmittedRootCount == 0 ||
			g_privateGroupSubmittedRootCount > kMaximumPrivateGroupSubmissions)
			return false;
		for (std::uint32_t index = 0; index < g_privateGroupSubmittedRootCount; ++index) {
			auto* root = g_privateGroupSubmittedRoots[index];
			if (!root || !SubmittedNodeRecorded(root))
				return false;
			auto* parent = root->parent;
			std::uint32_t depth = 0;
			for (; parent && depth < 64u; ++depth) {
				if (parent == root || SubmittedNodeRecorded(parent))
					return false;
				parent = parent->parent;
			}
			if (parent != nullptr)
				return false;
		}
		return true;
	}

