	constexpr bool MirrorReceiverExclusionReady(
		bool receiverHasStandaloneRoot,
		bool authoredReceiverWithout3D,
		std::uint32_t receiverRootsSkipped,
		bool receiverDirectlyCollected,
		bool receiverCullArmed = false,
		bool receiverCensusComplete = false,
		std::uint32_t receiverPasses = 0u) noexcept
	{

		return !receiverDirectlyCollected && receiverPasses == 0u &&
			(receiverHasStandaloneRoot ?
				(!authoredReceiverWithout3D && (receiverRootsSkipped != 0u ||
					(receiverCullArmed && receiverCensusComplete))) : authoredReceiverWithout3D);
	}

	static_assert(MirrorReceiverExclusionReady(true, false, 1u, false));
	static_assert(!MirrorReceiverExclusionReady(true, false, 0u, false));
	static_assert(!MirrorReceiverExclusionReady(true, false, 1u, true));
	
	static_assert(MirrorReceiverExclusionReady(false, true, 0u, false));
	static_assert(!MirrorReceiverExclusionReady(false, false, 0u, false));
	static_assert(!MirrorReceiverExclusionReady(false, false, 1u, false));
	static_assert(!MirrorReceiverExclusionReady(false, true, 0u, true));
	static_assert(!MirrorReceiverExclusionReady(true, true, 1u, false));
	static_assert(MirrorReceiverExclusionReady(true, false, 0u, false, true, true, 0u));
	static_assert(!MirrorReceiverExclusionReady(true, false, 0u, false, false, true, 0u));
	static_assert(!MirrorReceiverExclusionReady(true, false, 0u, false, true, false, 0u));
	static_assert(!MirrorReceiverExclusionReady(true, false, 1u, false, true, true, 1u));

	PlayerPassChainStats InspectPlayerPassChains(
		void* accumulator,
		const std::uint8_t* playerRoot,
		const std::uint8_t* faceRoot,
		const std::uint8_t* exactRugRoot,
		const std::uint8_t* receiverRoot = nullptr) noexcept
	{
		PlayerPassChainStats result{};
		if (!accumulator)
			return result;

		auto plausiblePointer = [](const void* pointer) noexcept {
			const auto address = reinterpret_cast<std::uintptr_t>(pointer);
			return address > 0x10000 && address <= 0x00007FFFFFFFFFFFULL && (address & 7u) == 0;
		};
		if (!plausiblePointer(accumulator) ||
			(playerRoot && !plausiblePointer(playerRoot)) ||
			(faceRoot && !plausiblePointer(faceRoot)) ||
			(exactRugRoot && !plausiblePointer(exactRugRoot)) ||
			(receiverRoot && !plausiblePointer(receiverRoot))) {
			result.malformed = true;
			return result;
		}
		constexpr std::size_t kRenderPassArrayOffset = 0x8;
		constexpr std::size_t kRenderPassArrayStride = 0x18;
		constexpr std::size_t kPassGroupStride = 0x10;
		constexpr std::size_t kGeometryGroupsOffset = 0x358;
		constexpr std::size_t kGeometryGroupBatch = 0x0;
		constexpr std::size_t kGeometryGroupPersistentHead = 0x8;
		constexpr std::size_t kGeometryGroupCount = 0x1C;
		constexpr std::size_t kGeometryGroupFlags = 0x20;
		constexpr std::size_t kPassNextSibling = 0x40;
		constexpr std::size_t kPassProperty = 0x10;
		constexpr std::size_t kPassGeometry = 0x18;
		constexpr std::size_t kPropertyMaterial = 0x58;
		constexpr std::uint32_t kArrayCount = 13;
		constexpr std::uint32_t kGeometryGroupArrayCount = 0x17;
		constexpr std::uint32_t kMaxPassGroups = 0x10000;
		constexpr std::uint32_t kMaxPassesPerChain = 0x20000;
		constexpr std::uint32_t kMaxPassesTotal = 0x40000;
		constexpr std::uint32_t kMaxParentDepth = 64;

		auto readNext = [&](const std::uint8_t* pass) noexcept -> const std::uint8_t* {
			if (!pass)
				return nullptr;
			if (!plausiblePointer(pass)) {
				result.malformed = true;
				return nullptr;
			}
			auto* next = *reinterpret_cast<std::uint8_t* const*>(pass + kPassNextSibling);
			if (next && !plausiblePointer(next)) {
				result.malformed = true;
				return nullptr;
			}
			return next;
		};
		struct GeometryClassification
		{
			bool player{ false };
			bool face{ false };
			bool exactRug{ false };
			bool receiver{ false };
		};
		auto classifyGeometry = [&](const void* geometry) noexcept {
			GeometryClassification classification{};
			auto* object = reinterpret_cast<const RE::NiAVObject*>(geometry);
			for (std::uint32_t depth = 0; object && depth < kMaxParentDepth; ++depth) {
				if (!plausiblePointer(object)) {
					result.malformed = true;
					return classification;
				}
				if (object == reinterpret_cast<const RE::NiAVObject*>(faceRoot))
					classification.face = true;
				if (object == reinterpret_cast<const RE::NiAVObject*>(receiverRoot)) {
					classification.receiver = true;
					return classification;
				}
				if (object == reinterpret_cast<const RE::NiAVObject*>(exactRugRoot)) {
					classification.exactRug = true;
					return classification;
				}
				if (object == reinterpret_cast<const RE::NiAVObject*>(playerRoot)) {
					classification.player = true;

					return classification;
				}
				object = object->parent;
			}
			if (object)
				++result.truncatedParentWalks;
			return classification;
		};

		std::uint32_t totalPasses = 0;
		auto recordPass = [&](const std::uint8_t* pass, bool geometryGroup,
			std::uint32_t arrayIndex) noexcept {
			++totalPasses;
			if (geometryGroup)
				++result.groupedPasses;
			else
				++result.ordinaryPasses;
			const void* passGeometry = *reinterpret_cast<void* const*>(pass + kPassGeometry);
			if (!passGeometry)
				return;
			++result.geometryPasses;
			if (!plausiblePointer(passGeometry)) {
				result.malformed = true;
				return;
			}

			const auto classification = classifyGeometry(passGeometry);
			if (classification.receiver)
				++result.receiverPasses;
			if (classification.player) {
				++result.playerPasses;
				if (classification.face) {
					auto* property = *reinterpret_cast<const std::uint8_t* const*>(
						pass + kPassProperty);
					if (property && plausiblePointer(property)) {
						auto* material = *reinterpret_cast<const std::uint8_t* const*>(
							property + kPropertyMaterial);
						if (material && plausiblePointer(material) &&
							g_skinTintMaterialVtableAddress > 0x10000u &&
							*reinterpret_cast<const std::uintptr_t*>(material) ==
								g_skinTintMaterialVtableAddress) {
							++result.faceSkinMaterialPasses;
							if (!geometryGroup && arrayIndex == 4u)
								++result.ordinaryBatch4FaceSkinMaterialPasses;
						}
					} else if (property) {
						result.malformed = true;
					}
				} else {
					++result.nonFacePlayerPasses;
				}
			} else {
				++result.environmentPasses;
			}
			if (classification.face)
				++result.facePasses;
			if (classification.exactRug)
				++result.exactRugPasses;
		};

		auto scanChain = [&](const std::uint8_t* head, bool geometryGroup,
			std::uint32_t arrayIndex) noexcept {
			auto* pass = head;
			auto* slow = head;
			auto* fast = head;
			std::uint32_t chainPasses = 0;
			while (pass && chainPasses < kMaxPassesPerChain && totalPasses < kMaxPassesTotal) {
				if (!plausiblePointer(pass)) {
					result.malformed = true;
					break;
				}
				++chainPasses;
				recordPass(pass, geometryGroup, arrayIndex);
				pass = readNext(pass);
				slow = readNext(slow);
				fast = readNext(fast);
				fast = readNext(fast);
				if (slow && slow == fast) {
					++result.truncatedChains;
					result.malformed = true;
					break;
				}
			}
			if (pass && (chainPasses >= kMaxPassesPerChain || totalPasses >= kMaxPassesTotal)) {
				++result.truncatedChains;
				result.malformed = true;
			}
		};

		auto scanBatch = [&](const std::uint8_t* batch, bool geometryGroup) noexcept {
			if (!plausiblePointer(batch)) {
				result.malformed = true;
				return;
			}
			for (std::uint32_t arrayIndex = 0;
				arrayIndex < kArrayCount && totalPasses < kMaxPassesTotal;
				++arrayIndex) {
				auto* array = batch + kRenderPassArrayOffset +
				              static_cast<std::size_t>(arrayIndex) * kRenderPassArrayStride;
				auto* groups = *reinterpret_cast<const std::uint8_t* const*>(array);
				const std::uint32_t groupCount = *reinterpret_cast<const std::uint32_t*>(array + 0x10);
				if (groupCount > kMaxPassGroups || (groupCount != 0 && !plausiblePointer(groups))) {
					result.malformed = true;
					return;
				}
				for (std::uint32_t groupIndex = 0;
					groupIndex < groupCount && totalPasses < kMaxPassesTotal;
					++groupIndex) {
					auto* pass = *reinterpret_cast<const std::uint8_t* const*>(
						groups + static_cast<std::size_t>(groupIndex) * kPassGroupStride);
					scanChain(pass, geometryGroup, arrayIndex);
				}
			}
		};

		auto* batch = reinterpret_cast<const std::uint8_t*>(accumulator) + 0xc8;
		scanBatch(batch, false);
		for (std::uint32_t groupIndex = 0;
			groupIndex < kGeometryGroupArrayCount && totalPasses < kMaxPassesTotal;
			++groupIndex) {
			auto* geometryGroup = *reinterpret_cast<const std::uint8_t* const*>(
				batch + kGeometryGroupsOffset + static_cast<std::size_t>(groupIndex) * sizeof(void*));
			if (!geometryGroup)
				continue;
			if (!plausiblePointer(geometryGroup)) {
				result.malformed = true;
				continue;
			}
			const bool persistent = (*reinterpret_cast<const std::uint8_t*>(
				geometryGroup + kGeometryGroupFlags) & 1u) != 0;
			const std::uint32_t declaredCount = *reinterpret_cast<const std::uint32_t*>(
				geometryGroup + kGeometryGroupCount);
			if (declaredCount > kMaxPassesTotal) {
				result.malformed = true;
				continue;
			}
			if (persistent) {
				auto* pass = *reinterpret_cast<const std::uint8_t* const*>(
					geometryGroup + kGeometryGroupPersistentHead);
				if ((declaredCount != 0u) != (pass != nullptr)) {
					result.malformed = true;
					if (declaredCount == 0u)
						continue;  
				}
				scanChain(pass, true, (std::numeric_limits<std::uint32_t>::max)());
			} else {
				auto* childBatch = *reinterpret_cast<const std::uint8_t* const*>(
					geometryGroup + kGeometryGroupBatch);
				if (declaredCount != 0u && !childBatch) {
					result.malformed = true;
					continue;
				}
				if (childBatch)
					scanBatch(childBatch, true);
			}
		}

		if (totalPasses >= kMaxPassesTotal)
			result.malformed = true;
		result.receiverCensusComplete = receiverRoot && !result.malformed &&
			result.truncatedChains == 0u && result.truncatedParentWalks == 0u;
		return result;
	}

	constexpr std::uint32_t kEyeDiagnosticBatchCount = 13;
	constexpr std::uint32_t kEyeDiagnosticGeometryGroupCount = 0x17;
	constexpr std::uint32_t kEyeDiagnosticEvidenceCapacity = 48;

	struct PlayerFacePassEvidence
	{
		std::uintptr_t pass{ 0 };
		std::uintptr_t geometry{ 0 };
		std::uintptr_t shader{ 0 };
		std::uintptr_t shaderVtable{ 0 };  

		std::uintptr_t property{ 0 };
		std::uintptr_t material{ 0 };
		std::uintptr_t materialVtable{ 0 };
		std::uint64_t propertyFlags{ 0 };
		std::uint32_t technique{ 0 };
		std::int32_t shaderType{ -1 };
		std::int32_t geometryGroup{ -1 };
		std::uint8_t batch{ 0xFF };
		std::uint8_t category{ 0xFF };
		bool player{ false };
		bool face{ false };
		bool exactEyeMaterial{ false };
		bool eyeLightingTechnique{ false };
		bool eyeName{ false };
		bool persistentGroup{ false };
		char name[kMaxPrivatePlayerGeometryNameLength]{};

		char texturePath[kMirrorTexturePathCapacity]{};
		std::uintptr_t baseTextureSet{ 0 };
		float boundCenter[3]{};
		float boundRadius{ 0.0f };
	};

	struct PlayerFacePassInventory
	{
		std::uintptr_t playerRootIdentity{ 0 };
		std::uintptr_t faceRootIdentity{ 0 };
		std::uint32_t totalPasses{ 0 };
		std::uint32_t mainPasses{ 0 };
		std::uint32_t groupedPasses{ 0 };
		std::uint32_t persistentPasses{ 0 };
		std::uint32_t playerPasses{ 0 };
		std::uint32_t facePasses{ 0 };
		std::uint32_t exactEyeMaterialPasses{ 0 };
		std::uint32_t playerExactEyeMaterialPasses{ 0 };
		std::uint32_t faceExactEyeMaterialPasses{ 0 };
		std::uint32_t eyeLightingTechniquePasses{ 0 };
		std::uint32_t playerEyeLightingTechniquePasses{ 0 };
		std::uint32_t faceEyeLightingTechniquePasses{ 0 };
		std::uint32_t eyeNamePasses{ 0 };
		std::uint32_t batchPasses[kEyeDiagnosticBatchCount]{};
		std::uint32_t geometryGroupPasses[kEyeDiagnosticGeometryGroupCount]{};
		std::uint32_t evidenceCount{ 0 };
		std::uint32_t droppedEvidence{ 0 };
		std::uint32_t truncatedChains{ 0 };
		std::uint32_t truncatedParentWalks{ 0 };
		bool malformed{ false };
		bool faulted{ false };
		PlayerFacePassEvidence evidence[kEyeDiagnosticEvidenceCapacity]{};
		MirrorForwardPassProof forward[kMaximumMirrorPlayerForwardRecords]{};
		MirrorPassSelection<PlayerFacePassEvidence> production{};
	};

	static_assert(std::is_trivially_copyable_v<PlayerFacePassInventory>);
	static_assert(std::is_trivially_destructible_v<PlayerFacePassInventory>);

	bool CopyLightingBaseTexturePathUnsafe(
		const std::uint8_t* material,
		char* destination,
		std::size_t destinationSize,
		std::uintptr_t* textureSetValue) noexcept
	{
		if (textureSetValue)
			*textureSetValue = 0;
		if (!material || !destination || destinationSize < 2)
			return false;
		destination[0] = '\0';
		const auto* lighting =
			reinterpret_cast<const RE::BSLightingShaderMaterialBase*>(material);
		auto* textureSet = lighting->textureSet.get();
		if (textureSetValue)
			*textureSetValue = reinterpret_cast<std::uintptr_t>(textureSet);
		const char* path = textureSet ?
			textureSet->GetTextureFilename(RE::BSShaderProperty::TextureTypeEnum::kBase) : nullptr;
		if (!path)
			return false;
		std::size_t copied = 0;
		while (copied + 1 < destinationSize && path[copied] != '\0') {
			const auto character = static_cast<unsigned char>(path[copied]);
			if (character < 0x20 || character > 0x7E) {
				destination[0] = '\0';
				return false;
			}
			destination[copied] = static_cast<char>(character);
			++copied;
		}
		if (path[copied] != '\0') {
			destination[0] = '\0';
			return false;
		}
		destination[copied] = '\0';
		return copied != 0;
	}

	bool IsPrewarTShirtBaseTexturePath(const char* path) noexcept
	{
		if (!path)
			return false;
		char normalized[kMirrorTexturePathCapacity]{};
		std::size_t count = 0;
		while (count + 1 < sizeof(normalized) && path[count] != '\0') {
			const auto character = static_cast<unsigned char>(path[count]);
			if (character < 0x20 || character > 0x7E)
				return false;
			normalized[count] = character == '\\' ? '/' :
				static_cast<char>(std::tolower(character));
			++count;
		}
		if (path[count] != '\0')
			return false;
		normalized[count] = '\0';
		const char* canonical = normalized;
		if (std::strncmp(canonical, "data/textures/", 14) == 0)
			canonical += 14;
		else if (std::strncmp(canonical, "textures/", 9) == 0)
			canonical += 9;
		while (*canonical == '/')
			++canonical;
		return std::strcmp(
			canonical, "clothes/tshirtslacks/tshirtslacksprewar_d.dds") == 0;
	}

	bool IsHumanEyeBaseTexturePath(const char* path) noexcept
	{
		if (!path)
			return false;
		char normalized[kMirrorTexturePathCapacity]{};
		std::size_t count = 0;
		while (count + 1 < sizeof(normalized) && path[count] != '\0') {
			const auto character = static_cast<unsigned char>(path[count]);
			if (character < 0x20 || character > 0x7E)
				return false;
			normalized[count] = character == '\\' ? '/' :
				static_cast<char>(std::tolower(character));
			++count;
		}
		if (path[count] != '\0')
			return false;
		normalized[count] = '\0';

		const char* canonical = normalized;
		if (std::strncmp(canonical, "data/textures/", 14) == 0)
			canonical += 14;
		else if (std::strncmp(canonical, "textures/", 9) == 0)
			canonical += 9;
		while (*canonical == '/')
			++canonical;

		const char* filename = std::strrchr(canonical, '/');
		if (!filename)
			return false;
		++filename;
		const std::size_t filenameLength = std::strlen(filename);
		if (filenameLength < 5 || std::strcmp(filename + filenameLength - 4, ".dds") != 0)
			return false;
		if (std::strstr(filename, "cubemap") || std::strstr(filename, "_n.dds") ||
			std::strstr(filename, "_s.dds") || std::strstr(filename, "_g.dds"))
			return false;
		const std::size_t folderLength = static_cast<std::size_t>(filename - canonical);
		constexpr const char* kEyeFolder = "actors/character/eyes/";
		constexpr std::size_t kEyeFolderLength = 22;
		if (folderLength == kEyeFolderLength && std::strncmp(canonical, kEyeFolder, kEyeFolderLength) == 0)
			return true;
		
		char folder[kMirrorTexturePathCapacity]{};
		std::memcpy(folder, canonical, folderLength);
		folder[folderLength] = '\0';
		return std::strstr(folder, "/eyes/") != nullptr ||
			std::strncmp(folder, "eyes/", 5) == 0;
	}

	void InspectPlayerFacePassInventoryUnsafe(
		void* accumulator,
		const std::uint8_t* playerRoot,
		const std::uint8_t* faceRoot,
		PlayerFacePassInventory* result) noexcept
	{
		if (!accumulator || !result)
			return;

		auto plausiblePointer = [](const void* pointer) noexcept {
			const auto address = reinterpret_cast<std::uintptr_t>(pointer);
			return address > 0x10000 && address <= 0x00007FFFFFFFFFFFULL && (address & 7u) == 0;
		};
		if (!plausiblePointer(accumulator) ||
			(playerRoot && !plausiblePointer(playerRoot)) ||
			(faceRoot && !plausiblePointer(faceRoot))) {
			result->malformed = true;
			return;
		}
		result->playerRootIdentity = reinterpret_cast<std::uintptr_t>(playerRoot);
		result->faceRootIdentity = reinterpret_cast<std::uintptr_t>(faceRoot);

		constexpr std::size_t kRenderPassArrayOffset = 0x8;
		constexpr std::size_t kRenderPassArrayStride = 0x18;
		constexpr std::size_t kPassGroupStride = 0x10;
		constexpr std::size_t kGeometryGroupsOffset = 0x358;
		constexpr std::size_t kGeometryGroupBatch = 0x0;
		constexpr std::size_t kGeometryGroupPersistentHead = 0x8;
		constexpr std::size_t kGeometryGroupCount = 0x1C;
		constexpr std::size_t kGeometryGroupFlags = 0x20;
		constexpr std::size_t kPassShader = 0x8;
		constexpr std::size_t kPassProperty = 0x10;
		constexpr std::size_t kPassGeometry = 0x18;
		constexpr std::size_t kPassNextSibling = 0x40;
		constexpr std::size_t kPassTechnique = 0x48;
		constexpr std::size_t kPassCategory = 0x4C;
		constexpr std::size_t kShaderType = 0x18;
		constexpr std::size_t kPropertyMaterial = 0x58;
		constexpr std::uint32_t kMaxPassGroups = 0x10000;
		constexpr std::uint32_t kMaxPassesPerChain = 0x20000;
		constexpr std::uint32_t kMaxPassesTotal = 0x40000;
		constexpr std::uint32_t kMaxParentDepth = 64;
		constexpr std::uint32_t kEyeFeature =
			static_cast<std::uint32_t>(RE::BSShaderMaterial::Feature::kEye);

		struct GeometryClassification
		{
			bool player{ false };
			bool face{ false };
		};
		auto classifyGeometry = [&](const void* geometry) noexcept {
			GeometryClassification classification{};
			auto* object = reinterpret_cast<const RE::NiAVObject*>(geometry);
			for (std::uint32_t depth = 0; object && depth < kMaxParentDepth; ++depth) {
				if (!plausiblePointer(object)) {
					result->malformed = true;
					return classification;
				}
				if (object == reinterpret_cast<const RE::NiAVObject*>(faceRoot))
					classification.face = true;
				if (object == reinterpret_cast<const RE::NiAVObject*>(playerRoot)) {
					classification.player = true;
					return classification;
				}
				object = object->parent;
			}
			if (object)
				++result->truncatedParentWalks;
			return classification;
		};

		auto readNext = [&](const std::uint8_t* pass) noexcept -> const std::uint8_t* {
			if (!pass)
				return nullptr;
			if (!plausiblePointer(pass)) {
				result->malformed = true;
				return nullptr;
			}
			auto* next = *reinterpret_cast<const std::uint8_t* const*>(pass + kPassNextSibling);
			if (next && !plausiblePointer(next)) {
				result->malformed = true;
				return nullptr;
			}
			return next;
		};

		bool collisionPass = false;
		std::uint32_t walkedPasses = 0;
		auto recordPass = [&](const std::uint8_t* pass, std::uint8_t batchIndex,
			std::int32_t geometryGroup, bool persistentGroup) noexcept {
			if (!plausiblePointer(pass)) {
				result->malformed = true;
				return;
			}
			++walkedPasses;
			if (collisionPass) {
				auto* property = *reinterpret_cast<const std::uint8_t* const*>(pass + kPassProperty);
				if (property && !plausiblePointer(property)) {
					result->malformed = true;
					return;
				}
				result->production.ObserveGroup4(
					reinterpret_cast<std::uintptr_t>(pass),
					*reinterpret_cast<const std::uintptr_t*>(pass + kPassShader),
					property ? *reinterpret_cast<const std::uintptr_t*>(property + kPropertyMaterial) : 0,
					*reinterpret_cast<const std::uint32_t*>(pass + kPassTechnique));
				return;
			}
			++result->totalPasses;
			if (geometryGroup < 0) {
				++result->mainPasses;
			} else if (static_cast<std::uint32_t>(geometryGroup) < kEyeDiagnosticGeometryGroupCount) {
				++result->groupedPasses;
				++result->geometryGroupPasses[geometryGroup];
				if (persistentGroup)
					++result->persistentPasses;
			}

			auto* shader = *reinterpret_cast<const std::uint8_t* const*>(pass + kPassShader);
			auto* property = *reinterpret_cast<const std::uint8_t* const*>(pass + kPassProperty);
			auto* geometry = *reinterpret_cast<const std::uint8_t* const*>(pass + kPassGeometry);
			const std::uint32_t technique = *reinterpret_cast<const std::uint32_t*>(pass + kPassTechnique);
			const std::uint8_t category = *reinterpret_cast<const std::uint8_t*>(pass + kPassCategory);
			std::int32_t shaderType = -1;
			if (shader) {
				if (plausiblePointer(shader))
					shaderType = *reinterpret_cast<const std::int32_t*>(shader + kShaderType);
				else
					result->malformed = true;
			}
			if (batchIndex >= kEyeDiagnosticBatchCount &&
				shaderType >= 0 && shaderType < static_cast<std::int32_t>(kEyeDiagnosticBatchCount))
				batchIndex = static_cast<std::uint8_t>(shaderType);
			if (batchIndex < kEyeDiagnosticBatchCount)
				++result->batchPasses[batchIndex];

			const GeometryClassification classification = geometry && plausiblePointer(geometry) ?
				classifyGeometry(geometry) : GeometryClassification{};
			if (geometry && !plausiblePointer(geometry))
				result->malformed = true;
			if (classification.player)
				++result->playerPasses;
			if (classification.face)
				++result->facePasses;

			char geometryName[kMaxPrivatePlayerGeometryNameLength]{};
			if (geometry && plausiblePointer(geometry)) {
				const auto* nameData = *reinterpret_cast<const char* const*>(geometry + 0x10);
				const auto nameAddress = reinterpret_cast<std::uintptr_t>(nameData);
				if (nameAddress > 0x10000 && nameAddress <= 0x00007FFFFFFFFFFFULL) {
					std::uint32_t copied = 0;
					while (copied + 1 < kMaxPrivatePlayerGeometryNameLength) {
						const char character = nameData[copied];
						if (character == '\0')
							break;
						if (character < 0x20 || static_cast<unsigned char>(character) > 0x7E) {
							copied = 0;
							break;
						}
						geometryName[copied] = character;
						++copied;
					}
					geometryName[copied] = '\0';
				}
			}
			bool eyeName = false;
			for (std::uint32_t at = 0; geometryName[at] != '\0' && at + 2 < kMaxPrivatePlayerGeometryNameLength;
				++at) {
				const auto lower = [](char value) noexcept {
					return value >= 'A' && value <= 'Z' ? static_cast<char>(value + 0x20) : value;
				};
				if (lower(geometryName[at]) == 'e' && lower(geometryName[at + 1]) == 'y' &&
					lower(geometryName[at + 2]) == 'e') {
					eyeName = true;
					break;
				}
			}
			if (eyeName)
				++result->eyeNamePasses;

			const std::uint8_t* material = nullptr;
			std::uint64_t propertyFlags = 0;
			std::uintptr_t materialVtable = 0;
			if (property) {
				if (plausiblePointer(property)) {
					propertyFlags = *reinterpret_cast<const std::uint64_t*>(property + 0x30);
					material = *reinterpret_cast<const std::uint8_t* const*>(property + kPropertyMaterial);
					if (material) {
						if (plausiblePointer(material))
							materialVtable = *reinterpret_cast<const std::uintptr_t*>(material);
						else
							result->malformed = true;
					}
				} else {
					result->malformed = true;
				}
			}

			char textureName[kMirrorTexturePathCapacity]{};
			std::uintptr_t baseTextureSetValue = 0;
			if (material && plausiblePointer(material) &&
				shaderType == static_cast<std::int32_t>(RE::BSShader::Type::Lighting)) {
				(void)CopyLightingBaseTexturePathUnsafe(
					material, textureName, sizeof(textureName),
					std::addressof(baseTextureSetValue));
			}
			const bool exactEyeMaterial = materialVtable != 0 &&
				IsHumanEyeBaseTexturePath(textureName);

			const bool eyeLightingTechnique =
				shaderType == static_cast<std::int32_t>(RE::BSShader::Type::Lighting) &&
				((technique >> 24) & 0x3Fu) == kEyeFeature;
			if (exactEyeMaterial) {
				++result->exactEyeMaterialPasses;
				if (classification.player)
					++result->playerExactEyeMaterialPasses;
				if (classification.face)
					++result->faceExactEyeMaterialPasses;
			}
			if (eyeLightingTechnique) {
				++result->eyeLightingTechniquePasses;
				if (classification.player)
					++result->playerEyeLightingTechniquePasses;
				if (classification.face)
					++result->faceEyeLightingTechniquePasses;
			}

			for (std::uint32_t index = 0; index < g_armMirrorPlayerForwardRecordCount &&
				index < kMaximumMirrorPlayerForwardRecords; ++index) {
				result->forward[index].Observe(
					reinterpret_cast<std::uintptr_t>(g_armMirrorPlayerForwardRecords[index].geometry),
					reinterpret_cast<std::uintptr_t>(geometry), geometryGroup, MirrorEyeForwardTechnique(technique),
					reinterpret_cast<std::uintptr_t>(pass), reinterpret_cast<std::uintptr_t>(shader),
					reinterpret_cast<std::uintptr_t>(property), reinterpret_cast<std::uintptr_t>(material), technique);
			}

			if (classification.player || geometryGroup == 4) {
				PlayerFacePassEvidence evidence{};
				evidence.pass = reinterpret_cast<std::uintptr_t>(pass);
				evidence.geometry = reinterpret_cast<std::uintptr_t>(geometry);
				evidence.shader = reinterpret_cast<std::uintptr_t>(shader);
				evidence.shaderVtable = shader && plausiblePointer(shader) ?
					*reinterpret_cast<const std::uintptr_t*>(shader) : 0;
				evidence.property = reinterpret_cast<std::uintptr_t>(property);
				evidence.material = reinterpret_cast<std::uintptr_t>(material);
				evidence.materialVtable = materialVtable;
				evidence.propertyFlags = propertyFlags;
				std::memcpy(evidence.name, geometryName, sizeof(evidence.name));
				std::memcpy(evidence.texturePath, textureName, sizeof(evidence.texturePath));
				evidence.baseTextureSet = baseTextureSetValue;
				if (geometry && plausiblePointer(geometry)) {
					evidence.boundCenter[0] = *reinterpret_cast<const float*>(geometry + 0xb0);
					evidence.boundCenter[1] = *reinterpret_cast<const float*>(geometry + 0xb4);
					evidence.boundCenter[2] = *reinterpret_cast<const float*>(geometry + 0xb8);
					evidence.boundRadius = *reinterpret_cast<const float*>(geometry + 0xbc);
				}
				evidence.technique = technique;
				evidence.shaderType = shaderType;
				evidence.geometryGroup = geometryGroup;
				evidence.batch = batchIndex;
				evidence.category = category;
				evidence.player = classification.player;
				evidence.face = classification.face;
				evidence.exactEyeMaterial = exactEyeMaterial;
				evidence.eyeLightingTechnique = eyeLightingTechnique;
				evidence.eyeName = eyeName;
				evidence.persistentGroup = persistentGroup;
				const bool faceCorrection = classification.player && classification.face &&
					((batchIndex == 4u && geometryGroup == -1 &&
						shaderType == static_cast<std::int32_t>(RE::BSShader::Type::Lighting) &&
						technique == 0x0004101Eu && materialVtable == g_skinTintMaterialVtableAddress) ||
					 (geometryGroup == 4 &&
						((shaderType == static_cast<std::int32_t>(RE::BSShader::Type::Lighting) &&
							(exactEyeMaterial || technique == 0x0000901Fu)) ||
						 (shaderType == static_cast<std::int32_t>(RE::BSShader::Type::Effect) &&
							technique == 0x10000407u))));
				if (faceCorrection)
					result->production.Select(evidence);
				if (result->evidenceCount < kEyeDiagnosticEvidenceCapacity)
					result->evidence[result->evidenceCount++] = evidence;
				else
					++result->droppedEvidence;
			}

		};

		auto scanChain = [&](const std::uint8_t* head, std::uint8_t batchIndex,
			std::int32_t geometryGroup, bool persistentGroup) noexcept {
			auto* pass = head;
			auto* slow = head;
			auto* fast = head;
			std::uint32_t chainPasses = 0;
			while (pass && chainPasses < kMaxPassesPerChain && walkedPasses < kMaxPassesTotal) {
				if (!plausiblePointer(pass)) {
					result->malformed = true;
					break;
				}
				++chainPasses;
				recordPass(pass, batchIndex, geometryGroup, persistentGroup);
				pass = readNext(pass);
				slow = readNext(slow);
				fast = readNext(fast);
				fast = readNext(fast);
				if (slow && slow == fast) {
					++result->truncatedChains;
					break;
				}
			}
			if (pass && (chainPasses >= kMaxPassesPerChain || walkedPasses >= kMaxPassesTotal))
				++result->truncatedChains;
		};

		auto scanBatch = [&](const std::uint8_t* batch, std::int32_t geometryGroup) noexcept {
			if (!plausiblePointer(batch)) {
				result->malformed = true;
				return;
			}
			for (std::uint32_t arrayIndex = 0; arrayIndex < kEyeDiagnosticBatchCount; ++arrayIndex) {
				auto* array = batch + kRenderPassArrayOffset +
					static_cast<std::size_t>(arrayIndex) * kRenderPassArrayStride;
				auto* groups = *reinterpret_cast<const std::uint8_t* const*>(array);
				const std::uint32_t groupCount = *reinterpret_cast<const std::uint32_t*>(array + 0x10);
				if (groupCount > kMaxPassGroups || (groupCount != 0 && !plausiblePointer(groups))) {
					result->malformed = true;
					return;
				}
				for (std::uint32_t groupIndex = 0;
					groupIndex < groupCount && walkedPasses < kMaxPassesTotal;
					++groupIndex) {
					auto* pass = *reinterpret_cast<const std::uint8_t* const*>(
						groups + static_cast<std::size_t>(groupIndex) * kPassGroupStride);
					scanChain(pass, static_cast<std::uint8_t>(arrayIndex), geometryGroup, false);
				}
			}
		};

		auto* batch = reinterpret_cast<const std::uint8_t*>(accumulator) + 0xc8;
		for (std::uint32_t phase = 0; phase != 2; ++phase) {
			collisionPass = phase == 1;
			walkedPasses = 0;
			if (!collisionPass)
				scanBatch(batch, -1);
			
			for (std::uint32_t groupIndex = collisionPass ? 4u : 0u;
				groupIndex < (collisionPass ? 5u : kEyeDiagnosticGeometryGroupCount) && walkedPasses < kMaxPassesTotal;
				++groupIndex) {
				auto* geometryGroup = *reinterpret_cast<const std::uint8_t* const*>(
					batch + kGeometryGroupsOffset + static_cast<std::size_t>(groupIndex) * sizeof(void*));
				if (!geometryGroup)
					continue;
				if (!plausiblePointer(geometryGroup)) {
					result->malformed = true;
					continue;
				}
				const bool persistent = (*reinterpret_cast<const std::uint8_t*>(
					geometryGroup + kGeometryGroupFlags) & 1u) != 0;
				const std::uint32_t declaredCount = *reinterpret_cast<const std::uint32_t*>(
					geometryGroup + kGeometryGroupCount);
				if (persistent) {
					auto* pass = *reinterpret_cast<const std::uint8_t* const*>(
						geometryGroup + kGeometryGroupPersistentHead);
					if (declaredCount != 0 && !pass)
						result->malformed = true;
					scanChain(pass, 0xFF, static_cast<std::int32_t>(groupIndex), true);
				} else {
					auto* childBatch = *reinterpret_cast<const std::uint8_t* const*>(
						geometryGroup + kGeometryGroupBatch);
					if (declaredCount != 0 && !childBatch) {
						result->malformed = true;
						continue;
					}
					if (childBatch)
						scanBatch(childBatch, static_cast<std::int32_t>(groupIndex));
				}
			}
		}
	}

	void InspectPlayerFacePassInventory(
		void* accumulator,
		const std::uint8_t* playerRoot,
		const std::uint8_t* faceRoot,
		PlayerFacePassInventory* result) noexcept
	{
		if (!result)
			return;
		std::memset(result, 0, sizeof(*result));
		__try {
			InspectPlayerFacePassInventoryUnsafe(accumulator, playerRoot, faceRoot, result);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			std::memset(result, 0, sizeof(*result));
			result->malformed = true;
			result->faulted = true;
		}
	}

	struct MirrorPlayerForwardValidation
	{
		std::uint32_t expected{ 0 };
		std::uint32_t matched{ 0 };
		std::uint32_t wrongGroup{ 0 };
		std::uint32_t wrongTechnique{ 0 };
		std::uint32_t firstWrongTechnique{ 0 };
		std::uint32_t firstWrongGroup{ 0 };
		std::uint32_t ambiguous{ 0 };
		bool overflow{ false };
		bool malformed{ false };
		bool valid{ false };
	};

	MirrorPlayerForwardValidation ValidateMirrorPlayerForwardRemaps(
		const PlayerFacePassInventory& inventory) noexcept
	{
		MirrorPlayerForwardValidation validation{};
		validation.expected = g_armMirrorPlayerForwardRecordCount;
		validation.overflow = g_armMirrorPlayerForwardOverflow;
		validation.malformed = inventory.malformed || inventory.faulted;
		for (std::uint32_t recordIndex = 0;
			recordIndex < g_armMirrorPlayerForwardRecordCount &&
			recordIndex < kMaximumMirrorPlayerForwardRecords;
			++recordIndex) {
			auto& record = g_armMirrorPlayerForwardRecords[recordIndex];
			const auto& proof = inventory.forward[recordIndex];
			if (proof.Matched()) {
				record.pass = reinterpret_cast<const RE::BSRenderPass*>(proof.pass);
				record.shader = reinterpret_cast<const void*>(proof.shader);
				record.property = reinterpret_cast<const void*>(proof.property);
				record.material = reinterpret_cast<const void*>(proof.material);
				record.technique = proof.technique;
				++validation.matched;
			} else if (proof.matches > 1u) {
				++validation.ambiguous;
			}
			if (proof.wrongGroup) {
				++validation.wrongGroup;
				validation.firstWrongGroup = static_cast<std::uint32_t>(proof.firstWrongGroup);
			}
			if (proof.matches == 0u && proof.wrongTechnique) {
				++validation.wrongTechnique;
				validation.firstWrongTechnique = proof.firstWrongTechnique;
			}
		}

		validation.valid = !validation.overflow &&
			validation.matched == validation.expected &&
			validation.wrongGroup == 0 && validation.wrongTechnique == 0 &&
			validation.ambiguous == 0;
		return validation;
	}

	constexpr std::uint32_t kEyeMissingDeferredTechnique = 0x0000101Fu;
	constexpr std::uint32_t kEyeReplacementDeferredTechnique = 0x0000101Eu;

	constexpr std::uint32_t kSkinTintMissingDeferredTechnique = 0x0004101Eu;
	constexpr std::uint32_t kSkinTintReplacementDeferredTechnique = 0x0000101Eu;
	constexpr std::uint32_t kMaximumEyeTechniqueRewrites = 12;
	struct EyeTechniqueRewrite
	{
		std::uint8_t* pass;
		std::uint32_t original;
		const void* material;  

	};
	EyeTechniqueRewrite g_eyeTechniqueRewrites[kMaximumEyeTechniqueRewrites]{};
	std::uint32_t g_eyeTechniqueRewriteCount = 0;
	std::uint32_t g_lastSkinTintRewrites = 0;

	std::atomic<bool> g_eyeAlbedoOverrideActive{ false };

	constexpr std::uint32_t kClothingDeferredTechnique = 0x0000101Eu;
	constexpr std::uint32_t kMaximumClothingDepthBiasPasses = 2;
	struct ClothingDepthBiasPass
	{
		std::uint8_t* pass;
		const void* material;
	};
	static_assert(std::is_trivially_copyable_v<ClothingDepthBiasPass>);
	ClothingDepthBiasPass g_clothingDepthBiasPasses[kMaximumClothingDepthBiasPasses]{};
	std::uint32_t g_clothingDepthBiasPassCount = 0;
	bool g_clothingDepthBiasCollectionFaulted = false;

	constexpr std::uint32_t kMaximumSkinTintZPrepassTargets = 12;
	constexpr std::uint32_t kMaximumSkinTintZPrepassRemovals = 64;
	struct SkinTintZPrepassTarget
	{
		const RE::BSGeometry* geometry;
		const void* rendererData;
	};
	struct ArmedSkinTintZPrepassRemoval
	{
		std::uint8_t listIndex;
		MirrorSceneRenderer::ZPrepassFilterDetail::RemovedRecord record;
	};
	static_assert(std::is_trivially_copyable_v<SkinTintZPrepassTarget>);
	static_assert(std::is_trivially_copyable_v<ArmedSkinTintZPrepassRemoval>);
	SkinTintZPrepassTarget g_skinTintZPrepassTargets[kMaximumSkinTintZPrepassTargets]{};
	ArmedSkinTintZPrepassRemoval g_armSkinTintZPrepassRemovals[kMaximumSkinTintZPrepassRemovals]{};
	std::uint32_t g_skinTintZPrepassTargetCount = 0;
	std::uint32_t g_armSkinTintZPrepassRemovalCount = 0;
	std::uint32_t g_armSkinTintZPrepassOriginalCounts[6]{};
	std::uint32_t g_armSkinTintZPrepassActiveCounts[6]{};
	std::uint32_t g_lastSkinTintZPrepassListRemovals[6]{};
	bool g_armSkinTintZPrepassFilter = false;

	bool SkinTintZPrepassPointerPlausible(const void* pointer) noexcept
	{
		const auto address = reinterpret_cast<std::uintptr_t>(pointer);
		return address > 0x10000 && address <= 0x00007FFFFFFFFFFFULL && (address & 7u) == 0;
	}

	void ClearClothingDepthBiasPasses() noexcept
	{
		std::memset(g_clothingDepthBiasPasses, 0, sizeof(g_clothingDepthBiasPasses));
		g_clothingDepthBiasPassCount = 0;
	}

	std::uint32_t CollectClothingDepthBiasPassesUnsafe(
		void* accumulator,
		const std::uint8_t* playerRoot,
		const std::uint8_t* faceRoot) noexcept
	{
		ClearClothingDepthBiasPasses();
		g_clothingDepthBiasCollectionFaulted = false;
		if (!SkinTintZPrepassPointerPlausible(accumulator) ||
			!SkinTintZPrepassPointerPlausible(playerRoot) ||
			!SkinTintZPrepassPointerPlausible(faceRoot) ||
			g_clothingMaterialVtableAddress == 0)
			return 0;

		constexpr std::size_t kRenderPassArrayOffset = 0x8;
		constexpr std::size_t kRenderPassArrayStride = 0x18;
		constexpr std::size_t kPassGroupStride = 0x10;
		constexpr std::size_t kPassProperty = 0x10;
		constexpr std::size_t kPassGeometry = 0x18;
		constexpr std::size_t kPassNextSibling = 0x40;
		constexpr std::size_t kPassTechnique = 0x48;
		constexpr std::size_t kPropertyMaterial = 0x58;
		constexpr std::uint32_t kMaxPassGroups = 0x10000;
		constexpr std::uint32_t kMaxPassesPerChain = 0x20000;
		constexpr std::uint64_t kSkinnedFlag = 1ull << 1;
		constexpr std::uint64_t kRequiredDepthFlags = (1ull << 31) | (1ull << 32);
		constexpr std::uint64_t kDecalFlags = 0x0C00'0000ull;
		constexpr std::uint64_t kAlphaTestFlag = std::uint64_t{ 1 } << 57;

		auto failCollection = []() noexcept -> std::uint32_t {
			ClearClothingDepthBiasPasses();
			g_clothingDepthBiasCollectionFaulted = true;
			return 0;
		};

		// Only the main batch's shader-type-4 array. Grouped/persistent passes and the face subtree are outside
		
		auto* batch = reinterpret_cast<std::uint8_t*>(accumulator) + 0xc8;
		auto* array = batch + kRenderPassArrayOffset + 4u * kRenderPassArrayStride;
		auto* groups = *reinterpret_cast<std::uint8_t* const*>(array);
		const std::uint32_t groupCount = *reinterpret_cast<const std::uint32_t*>(array + 0x10);
		if (groupCount == 0)
			return 0;
		if (groupCount > kMaxPassGroups || !SkinTintZPrepassPointerPlausible(groups))
			return failCollection();

		const auto* playerRootObject = reinterpret_cast<const RE::NiAVObject*>(playerRoot);
		const auto* faceRootObject = reinterpret_cast<const RE::NiAVObject*>(faceRoot);
		for (std::uint32_t groupIndex = 0; groupIndex < groupCount; ++groupIndex) {
			auto* pass = *reinterpret_cast<std::uint8_t* const*>(
				groups + static_cast<std::size_t>(groupIndex) * kPassGroupStride);
			auto* slow = pass;
			auto* fast = pass;
			std::uint32_t chainPasses = 0;
			while (pass && chainPasses++ < kMaxPassesPerChain) {
				if (!SkinTintZPrepassPointerPlausible(pass))
					return failCollection();
				const auto technique = *reinterpret_cast<const std::uint32_t*>(pass + kPassTechnique);
				if (technique == kClothingDeferredTechnique) {
					auto* property = *reinterpret_cast<const std::uint8_t* const*>(pass + kPassProperty);
					auto* geometry = *reinterpret_cast<RE::BSGeometry* const*>(pass + kPassGeometry);
					if (SkinTintZPrepassPointerPlausible(property) &&
						SkinTintZPrepassPointerPlausible(geometry)) {
						auto* material = *reinterpret_cast<const std::uint8_t* const*>(
							property + kPropertyMaterial);
						const auto propertyFlags = *reinterpret_cast<const std::uint64_t*>(property + 0x30);
						const auto materialVtable = SkinTintZPrepassPointerPlausible(material) ?
							*reinterpret_cast<const std::uintptr_t*>(material) : 0;
						char baseTexturePath[kMaxPrivatePlayerGeometryNameLength]{};
						const bool authoredPrewarTShirt =
							materialVtable == g_clothingMaterialVtableAddress &&
							CopyLightingBaseTexturePathUnsafe(
								material, baseTexturePath, sizeof(baseTexturePath), nullptr) &&
							IsPrewarTShirtBaseTexturePath(baseTexturePath);
						const auto* alphaProperty =
							netimmerse_cast<RE::NiAlphaProperty*>(geometry->properties[0].get());
						const bool alphaBlendingEnabled =
							alphaProperty && (alphaProperty->flags.flags & 1u) != 0;
						const bool exactClothing = authoredPrewarTShirt &&
							(propertyFlags & kSkinnedFlag) != 0 &&
							(propertyFlags & kRequiredDepthFlags) == kRequiredDepthFlags &&
							(propertyFlags & (kDecalFlags | kAlphaTestFlag)) == 0 &&
							!alphaBlendingEnabled &&
							IsGeometryUnderRootSEH(geometry, playerRootObject) &&
							!IsGeometryUnderRootSEH(geometry, faceRootObject);
						if (exactClothing) {
							bool duplicate = false;
							for (std::uint32_t index = 0; index < g_clothingDepthBiasPassCount; ++index) {
								if (g_clothingDepthBiasPasses[index].pass == pass) {
									duplicate = true;
									break;
								}
							}
							if (!duplicate) {
								if (g_clothingDepthBiasPassCount >= kMaximumClothingDepthBiasPasses)
									return failCollection();
								g_clothingDepthBiasPasses[g_clothingDepthBiasPassCount++] = { pass, material };
							}
						}
					}
				}
				auto readNext = [](std::uint8_t* at) noexcept -> std::uint8_t* {
					if (!SkinTintZPrepassPointerPlausible(at))
						return nullptr;
					auto* next = *reinterpret_cast<std::uint8_t* const*>(at + kPassNextSibling);
					return next && SkinTintZPrepassPointerPlausible(next) ? next : nullptr;
				};
				pass = readNext(pass);
				slow = readNext(slow);
				fast = readNext(readNext(fast));
				if (slow && slow == fast)
					return failCollection();
			}
			if (pass)
				return failCollection();
		}
		return g_clothingDepthBiasPassCount;
	}

	std::uint32_t CollectClothingDepthBiasPasses(
		void* accumulator,
		const std::uint8_t* playerRoot,
		const std::uint8_t* faceRoot) noexcept
	{
		std::uint32_t count = 0;
		__try {
			count = CollectClothingDepthBiasPassesUnsafe(accumulator, playerRoot, faceRoot);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			ClearClothingDepthBiasPasses();
			g_clothingDepthBiasCollectionFaulted = true;
			count = 0;
		}
		return count;
	}

	bool RestoreSkinTintZPrepassFilterUnsafe() noexcept
	{
		if (!g_armSkinTintZPrepassFilter)
			return true;
		for (std::size_t listIndex = 0; listIndex < kZPrepassListLayouts.size(); ++listIndex) {
			const auto& layout = kZPrepassListLayouts[listIndex];
			auto* count = reinterpret_cast<std::uint32_t*>(REL::Offset(ReflectionRuntime::Rva(layout.countRVA)).address());
			if (*count != g_armSkinTintZPrepassActiveCounts[listIndex])
				return false;
		}

		while (g_armSkinTintZPrepassRemovalCount != 0) {
			const auto removalIndex = g_armSkinTintZPrepassRemovalCount - 1u;
			const auto& armed = g_armSkinTintZPrepassRemovals[removalIndex];
			if (armed.listIndex >= kZPrepassListLayouts.size())
				return false;
			const auto& layout = kZPrepassListLayouts[armed.listIndex];
			auto* count = reinterpret_cast<std::uint32_t*>(REL::Offset(ReflectionRuntime::Rva(layout.countRVA)).address());
			auto* records = reinterpret_cast<std::byte*>(REL::Offset(ReflectionRuntime::Rva(layout.recordsRVA)).address());
			std::uint32_t activeCount = *count;
			if (!MirrorSceneRenderer::ZPrepassFilterDetail::StableRestoreRecord(
					records, activeCount, kZPrepassListCapacity, layout.stride, armed.record))
				return false;
			InterlockedExchange(reinterpret_cast<volatile LONG*>(count), static_cast<LONG>(activeCount));
			g_armSkinTintZPrepassActiveCounts[armed.listIndex] = activeCount;
			--g_armSkinTintZPrepassRemovalCount;
		}
		for (std::size_t listIndex = 0; listIndex < kZPrepassListLayouts.size(); ++listIndex) {
			const auto& layout = kZPrepassListLayouts[listIndex];
			auto* count = reinterpret_cast<std::uint32_t*>(REL::Offset(ReflectionRuntime::Rva(layout.countRVA)).address());
			InterlockedExchange(
				reinterpret_cast<volatile LONG*>(count),
				static_cast<LONG>(g_armSkinTintZPrepassOriginalCounts[listIndex]));
		}
		g_armSkinTintZPrepassFilter = false;
		return true;
	}

	bool RestoreSkinTintZPrepassFilter() noexcept
	{
		bool restored = false;
		__try {
			restored = RestoreSkinTintZPrepassFilterUnsafe();
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			restored = false;
		}
		return restored;
	}

	struct ZPrepassSnapshot
	{
		std::array<std::uint32_t, kZPrepassListLayouts.size()> counts{};
		std::array<std::vector<std::byte>, kZPrepassListLayouts.size()> records{};
		bool armed = false;
		std::uint64_t drives = 0, leftoverDrives = 0, gameRecordDrives = 0;
		std::uint32_t logs = 0;
	};
	ZPrepassSnapshot g_armZPrepassSnapshot;

	std::uint32_t* ZPrepassCountAddress(const ZPrepassListLayout& layout) noexcept
	{
		const auto mapped = ReflectionRuntime::Rva(layout.countRVA);
		return mapped ? reinterpret_cast<std::uint32_t*>(REL::Offset(mapped).address()) : nullptr;
	}
	std::byte* ZPrepassRecordsAddress(const ZPrepassListLayout& layout) noexcept
	{
		const auto mapped = ReflectionRuntime::Rva(layout.recordsRVA);
		return mapped ? reinterpret_cast<std::byte*>(REL::Offset(mapped).address()) : nullptr;
	}

	bool ReadZPrepassCountsUnsafe(std::uint32_t* counts) noexcept
	{
		__try {
			for (std::size_t i = 0; i < kZPrepassListLayouts.size(); ++i) {
				const auto* count = ZPrepassCountAddress(kZPrepassListLayouts[i]);
				if (!count)
					return false;
				counts[i] = *count;
				if (counts[i] > kZPrepassListCapacity)
					return false;
			}
			return true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return false;
		}
	}

	bool CopyZPrepassRecordsUnsafe(std::byte* destination, const std::byte* source, std::size_t bytes) noexcept
	{
		if (bytes && (!destination || !source))
			return false;
		__try {
			if (bytes)
				std::memcpy(destination, source, bytes);
			return true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return false;
		}
	}

	bool WriteZPrepassCountUnsafe(std::uint32_t* count, std::uint32_t value, std::uint32_t& previous) noexcept
	{
		__try {
			previous = static_cast<std::uint32_t>(
				InterlockedExchange(reinterpret_cast<volatile LONG*>(count), static_cast<LONG>(value)));
			return true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return false;
		}
	}

	bool ArmZPrepassSnapshot() noexcept
	{
		auto& snapshot = g_armZPrepassSnapshot;
		if (snapshot.armed)
			return true;  
		const auto fail = [&snapshot]() noexcept {
			if (snapshot.logs < 8u) {
				++snapshot.logs;
				logger::warn("[PlanarMirrors] ZPREPASS lists could not be saved; capture skipped");
			}
			return false;
		};
		if (!ReadZPrepassCountsUnsafe(snapshot.counts.data()))
			return fail();
		bool gameRecords = false;
		for (std::size_t i = 0; i < kZPrepassListLayouts.size(); ++i) {
			const auto bytes = static_cast<std::size_t>(snapshot.counts[i]) * kZPrepassListLayouts[i].stride;
			try {
				if (snapshot.records[i].size() < bytes)
					snapshot.records[i].resize(bytes);
			} catch (...) {
				return fail();
			}
			if (!CopyZPrepassRecordsUnsafe(snapshot.records[i].data(), ZPrepassRecordsAddress(kZPrepassListLayouts[i]), bytes))
				return fail();
			gameRecords = gameRecords || snapshot.counts[i] != 0;
		}
		++snapshot.drives;
		if (gameRecords)
			++snapshot.gameRecordDrives;
		snapshot.armed = true;
		return true;
	}

	void RestoreZPrepassSnapshotArmed() noexcept
	{
		auto& snapshot = g_armZPrepassSnapshot;
		if (!snapshot.armed)
			return;
		snapshot.armed = false;
		bool restored = true;
		bool leftovers = false;
		std::array<std::uint32_t, kZPrepassListLayouts.size()> after{};
		for (std::size_t i = 0; i < kZPrepassListLayouts.size(); ++i) {
			const auto& layout = kZPrepassListLayouts[i];
			const auto bytes = static_cast<std::size_t>(snapshot.counts[i]) * layout.stride;
			restored = CopyZPrepassRecordsUnsafe(ZPrepassRecordsAddress(layout), snapshot.records[i].data(), bytes) && restored;
			restored = WriteZPrepassCountUnsafe(ZPrepassCountAddress(layout), snapshot.counts[i], after[i]) && restored;
			leftovers = leftovers || after[i] != snapshot.counts[i];
		}
		if (leftovers)
			++snapshot.leftoverDrives;
		if (!restored) {
			g_faulted = true;
			logger::error("[MirrorSceneRenderer] ZPREPASS restore faulted; private rendering disabled");
			return;
		}
		if (leftovers && (snapshot.logs < 8u || (snapshot.leftoverDrives % 3000u) == 0u)) {
			++snapshot.logs;
			logger::info(
				"[PlanarMirrors] ZPREPASS private records removed after a capture: before={}/{}/{}/{}/{}/{} after={}/{}/{}/{}/{}/{} "
				"(drives={} withLeftovers={} gameRecordsAtStart={})",
				snapshot.counts[0], snapshot.counts[1], snapshot.counts[2], snapshot.counts[3], snapshot.counts[4],
				snapshot.counts[5], after[0], after[1], after[2], after[3], after[4], after[5], snapshot.drives,
				snapshot.leftoverDrives, snapshot.gameRecordDrives);
		}
	}

	bool ResetPrivateZPrePass(void* renderer) noexcept
	{
		if (!renderer)
			return false;
		const auto resetAddress = REL::Offset(ReflectionRuntime::Rva(kRVA_ResetZPrePass)).address();
		if (resetAddress <= 0x10000 ||
			std::memcmp(
				reinterpret_cast<const void*>(resetAddress),
				ReflectionRuntime::Prologue(kRVA_ResetZPrePass, kResetZPrePassPrologue).data(), kResetZPrePassPrologue.size()) != 0)
			return false;

		bool reset = false;
		__try {
			auto fnResetZPrePass = reinterpret_cast<Group1_t>(resetAddress);
			fnResetZPrePass(renderer);
			reset = true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			reset = false;
		}
		return reset;
	}

	bool RestoreEyeDeferredTechniquesUnsafe() noexcept
	{
		if (g_eyeTechniqueRewriteCount > kMaximumEyeTechniqueRewrites)
			return false;
		while (g_eyeTechniqueRewriteCount != 0) {
			auto& rewrite = g_eyeTechniqueRewrites[g_eyeTechniqueRewriteCount - 1u];
			auto* pass = rewrite.pass;
			const std::uint32_t original = rewrite.original;

			if (pass)
				*reinterpret_cast<std::uint32_t*>(pass + 0x48) = original;
			rewrite = {};
			--g_eyeTechniqueRewriteCount;
		}
		return true;
	}

