	D3D11_RASTERIZER_DESC DefaultClothingRasterizerDescription() noexcept
	{
		D3D11_RASTERIZER_DESC description{};
		description.FillMode = D3D11_FILL_SOLID;
		description.CullMode = D3D11_CULL_BACK;
		description.FrontCounterClockwise = FALSE;
		description.DepthBias = 0;
		description.DepthBiasClamp = 0.0f;
		description.SlopeScaledDepthBias = 0.0f;
		description.DepthClipEnable = TRUE;
		description.ScissorEnable = FALSE;
		description.MultisampleEnable = FALSE;
		description.AntialiasedLineEnable = FALSE;
		return description;
	}

	D3D11_DEPTH_STENCIL_DESC DefaultClothingDepthStencilDescription() noexcept
	{
		D3D11_DEPTH_STENCIL_DESC description{};
		description.DepthEnable = TRUE;
		description.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ALL;
		description.DepthFunc = D3D11_COMPARISON_LESS;
		description.StencilEnable = FALSE;
		description.StencilReadMask = D3D11_DEFAULT_STENCIL_READ_MASK;
		description.StencilWriteMask = D3D11_DEFAULT_STENCIL_WRITE_MASK;
		description.FrontFace.StencilFailOp = D3D11_STENCIL_OP_KEEP;
		description.FrontFace.StencilDepthFailOp = D3D11_STENCIL_OP_KEEP;
		description.FrontFace.StencilPassOp = D3D11_STENCIL_OP_KEEP;
		description.FrontFace.StencilFunc = D3D11_COMPARISON_ALWAYS;
		description.BackFace = description.FrontFace;
		return description;
	}

	bool ResolveClothingBiasStatesUnsafe(
		ID3D11Device* device,
		ID3D11RasterizerState* sourceRasterizer,
		ID3D11DepthStencilState* sourceDepthStencil,
		ID3D11RasterizerState** biasedRasterizer,
		ID3D11DepthStencilState** biasedDepthStencil) noexcept
	{
		if (!device || !biasedRasterizer || !biasedDepthStencil)
			return false;
		*biasedRasterizer = nullptr;
		*biasedDepthStencil = nullptr;

		auto& cache = g_clothingBiasStateCache;
		if (cache.device.Get() != device) {
			cache.entries = {};
			cache.device.Reset();
			cache.device = device;
		}
		for (auto& entry : cache.entries) {
			if (!entry.used)
				continue;
			const bool rasterizerMatches = sourceRasterizer ?
				entry.sourceRasterizer.Get() == sourceRasterizer : entry.sourceRasterizerIsDefault;
			const bool depthStencilMatches = sourceDepthStencil ?
				entry.sourceDepthStencil.Get() == sourceDepthStencil : entry.sourceDepthStencilIsDefault;
			if (rasterizerMatches && depthStencilMatches) {
				*biasedRasterizer = entry.biasedRasterizer.Get();
				*biasedDepthStencil = entry.biasedDepthStencil.Get();
				return *biasedRasterizer && *biasedDepthStencil;
			}
		}

		auto slot = cache.entries.end();
		for (auto at = cache.entries.begin(); at != cache.entries.end(); ++at) {
			if (!at->used) {
				slot = at;
				break;
			}
		}
		if (slot == cache.entries.end())
			return false;

		auto rasterizerDescription = DefaultClothingRasterizerDescription();
		if (sourceRasterizer)
			sourceRasterizer->GetDesc(std::addressof(rasterizerDescription));
		rasterizerDescription.DepthBias = kClothingReplayDepthBias;
		rasterizerDescription.DepthBiasClamp = 0.0f;
		rasterizerDescription.SlopeScaledDepthBias = 0.0f;

		auto depthStencilDescription = DefaultClothingDepthStencilDescription();
		if (sourceDepthStencil)
			sourceDepthStencil->GetDesc(std::addressof(depthStencilDescription));
		depthStencilDescription.DepthEnable = TRUE;
		depthStencilDescription.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ALL;
		depthStencilDescription.DepthFunc = D3D11_COMPARISON_LESS_EQUAL;

		Microsoft::WRL::ComPtr<ID3D11RasterizerState> newRasterizer;
		Microsoft::WRL::ComPtr<ID3D11DepthStencilState> newDepthStencil;
		if (FAILED(device->CreateRasterizerState(
				std::addressof(rasterizerDescription), newRasterizer.GetAddressOf())) ||
			!newRasterizer.Get() ||
			FAILED(device->CreateDepthStencilState(
				std::addressof(depthStencilDescription), newDepthStencil.GetAddressOf())) ||
			!newDepthStencil.Get())
			return false;

		slot->sourceRasterizer = sourceRasterizer;
		slot->sourceDepthStencil = sourceDepthStencil;
		slot->biasedRasterizer = std::move(newRasterizer);
		slot->biasedDepthStencil = std::move(newDepthStencil);
		slot->sourceRasterizerIsDefault = sourceRasterizer == nullptr;
		slot->sourceDepthStencilIsDefault = sourceDepthStencil == nullptr;
		slot->used = true;
		*biasedRasterizer = slot->biasedRasterizer.Get();
		*biasedDepthStencil = slot->biasedDepthStencil.Get();
		return true;
	}

	bool ApplyClothingDepthBiasPostSetDirtyUnsafe(
		ID3D11Device* device,
		ID3D11DeviceContext* context) noexcept
	{
		auto& cleanup = g_clothingRedrawCleanup;
		if (!cleanup.overrideActive)
			return true;
		if (!device || !context || context != cleanup.context || !cleanup.activeMaterial)
			return false;
		const auto* currentMaterial = *reinterpret_cast<const void* const*>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassMaterial)).address());
		if (currentMaterial != cleanup.activeMaterial)
			return true;

		if (cleanup.stateApplied) {
			context->RSSetState(cleanup.biasedRasterizer);
			context->OMSetDepthStencilState(cleanup.biasedDepthStencil, cleanup.previousStencilReference);
			return true;
		}

		cleanup.stateCaptured = true;
		context->RSGetState(std::addressof(cleanup.previousRasterizer));
		context->OMGetDepthStencilState(
			std::addressof(cleanup.previousDepthStencil), std::addressof(cleanup.previousStencilReference));
		if (!ResolveClothingBiasStatesUnsafe(
				device, cleanup.previousRasterizer, cleanup.previousDepthStencil,
				std::addressof(cleanup.biasedRasterizer), std::addressof(cleanup.biasedDepthStencil)))
			return false;

		context->RSSetState(cleanup.biasedRasterizer);
		context->OMSetDepthStencilState(cleanup.biasedDepthStencil, cleanup.previousStencilReference);
		cleanup.stateApplied = true;
		return true;
	}

	void ApplyClothingDepthBiasPostSetDirty() noexcept
	{
		if (!g_clothingRedrawCleanup.overrideActive)
			return;
		bool succeeded = false;
		__try {
			succeeded = ApplyClothingDepthBiasPostSetDirtyUnsafe(
				globals::d3d::device, globals::d3d::context);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			succeeded = false;
		}
		if (!succeeded) {
			
			g_clothingRedrawCleanup.overrideActive = false;
			g_clothingRedrawCleanup.stateFaulted = true;
		}
	}

	bool InvalidateCurrentRenderPassCacheNoexcept() noexcept
	{
		void** shaderSlot = nullptr;
		std::uint32_t* techniqueSlot = nullptr;
		void** materialSlot = nullptr;
		void* previousShader = nullptr;
		std::uint32_t previousTechnique = 0u;
		void* previousMaterial = nullptr;
		bool snapshotComplete = false;
		bool mutationStarted = false;
		bool succeeded = false;
		__try {
			shaderSlot = reinterpret_cast<void**>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassShader)).address());
			techniqueSlot = reinterpret_cast<std::uint32_t*>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassTechnique)).address());
			materialSlot = reinterpret_cast<void**>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassMaterial)).address());
			previousShader = *shaderSlot;
			previousTechnique = *techniqueSlot;
			previousMaterial = *materialSlot;
			snapshotComplete = true;
			mutationStarted = true;
			*shaderSlot = nullptr;
			*techniqueSlot = 0u;
			*materialSlot = nullptr;
			succeeded = true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			succeeded = false;
		}
		if (!succeeded && snapshotComplete && mutationStarted) {

			__try {
				*materialSlot = previousMaterial;
				*techniqueSlot = previousTechnique;
				*shaderSlot = previousShader;
			} __except (EXCEPTION_EXECUTE_HANDLER) {
			}
		}
		return succeeded;
	}

