	bool EyeGroup4TextureViewsShareResource(
		ID3D11ShaderResourceView* left,
		ID3D11ShaderResourceView* right,
		std::uintptr_t* leftResourceIdentity = nullptr,
		std::uintptr_t* rightResourceIdentity = nullptr) noexcept
	{
		if (leftResourceIdentity)
			*leftResourceIdentity = 0;
		if (rightResourceIdentity)
			*rightResourceIdentity = 0;
		if (!left || !right)
			return false;

		Microsoft::WRL::ComPtr<ID3D11Resource> leftResource;
		Microsoft::WRL::ComPtr<ID3D11Resource> rightResource;
		left->GetResource(leftResource.GetAddressOf());
		right->GetResource(rightResource.GetAddressOf());
		if (leftResourceIdentity)
			*leftResourceIdentity = reinterpret_cast<std::uintptr_t>(leftResource.Get());
		if (rightResourceIdentity)
			*rightResourceIdentity = reinterpret_cast<std::uintptr_t>(rightResource.Get());
		return leftResource && rightResource && leftResource.Get() == rightResource.Get();
	}

	bool AcquireEyeGroup4ExpectedDiffuseSRVUnsafe(
		const void* materialPointer,
		std::uintptr_t expectedTextureSet,
		ID3D11Device* device,
		ID3D11ShaderResourceView** expectedView) noexcept
	{
		if (expectedView)
			*expectedView = nullptr;
		if (!materialPointer || expectedTextureSet == 0 || !device || !expectedView)
			return false;

		const auto* lighting = reinterpret_cast<const RE::BSLightingShaderMaterialBase*>(materialPointer);
		if (reinterpret_cast<std::uintptr_t>(lighting->textureSet.get()) != expectedTextureSet)
			return false;
		auto* diffuseTexture = lighting->diffuseTexture.get();
		auto* rendererTexture = diffuseTexture ? diffuseTexture->rendererTexture : nullptr;
		if (!rendererTexture)
			return false;
		auto* view = *reinterpret_cast<ID3D11ShaderResourceView* const*>(rendererTexture);
		if (!view || !DeviceChildUsesDevice(view, device))
			return false;

		D3D11_SHADER_RESOURCE_VIEW_DESC viewDescription{};
		view->GetDesc(std::addressof(viewDescription));
		if (viewDescription.ViewDimension != D3D11_SRV_DIMENSION_TEXTURE2D)
			return false;
		Microsoft::WRL::ComPtr<ID3D11Resource> resource;
		view->GetResource(resource.GetAddressOf());
		if (!resource || !DeviceChildUsesDevice(resource.Get(), device))
			return false;
		D3D11_RESOURCE_DIMENSION resourceDimension = D3D11_RESOURCE_DIMENSION_UNKNOWN;
		resource->GetType(std::addressof(resourceDimension));
		if (resourceDimension != D3D11_RESOURCE_DIMENSION_TEXTURE2D)
			return false;

		view->AddRef();
		*expectedView = view;
		return true;
	}

	constexpr std::uint32_t kExactEyeGroup4NativeVertexDescriptor = 0x0000001Eu;
	constexpr std::uint32_t kExactEyeGroup4NativePixelDescriptor = 0x00018806u;

	bool AcquireExactEyeGroup4NativeVSUnsafe(
		const void* shaderPointer,
		ID3D11Device* device,
		ID3D11VertexShader** nativeShader) noexcept
	{
		if (nativeShader)
			*nativeShader = nullptr;
		if (!shaderPointer || !device || !nativeShader)
			return false;

		auto* shader = reinterpret_cast<RE::BSShader*>(const_cast<void*>(shaderPointer));
		RE::BSGraphics::VertexShader probe{};
		probe.id = kExactEyeGroup4NativeVertexDescriptor;
		auto* key = std::addressof(probe);
		auto& vertexShaders = BSShaderTables::VertexShaders(shader);
		const auto found = vertexShaders.find(key);
		if (found == vertexShaders.end() || !*found || !(*found)->shader)
			return false;
		auto* physical = reinterpret_cast<ID3D11VertexShader*>((*found)->shader);
		if (!DeviceChildUsesDevice(physical, device))
			return false;
		physical->AddRef();
		*nativeShader = physical;
		return true;
	}

	bool AcquireExactEyeGroup4NativePSUnsafe(
		const void* shaderPointer,
		ID3D11Device* device,
		ID3D11PixelShader** nativeShader) noexcept
	{
		if (nativeShader)
			*nativeShader = nullptr;
		if (!shaderPointer || !device || !nativeShader)
			return false;

		auto* shader = reinterpret_cast<RE::BSShader*>(const_cast<void*>(shaderPointer));
		RE::BSGraphics::PixelShader probe{};
		probe.id = kExactEyeGroup4NativePixelDescriptor;
		auto* key = std::addressof(probe);
		auto& pixelShaders = BSShaderTables::PixelShaders(shader);
		const auto found = pixelShaders.find(key);
		if (found == pixelShaders.end() || !*found || !(*found)->shader)
			return false;
		auto* physical = reinterpret_cast<ID3D11PixelShader*>((*found)->shader);
		if (!DeviceChildUsesDevice(physical, device))
			return false;
		physical->AddRef();
		*nativeShader = physical;
		return true;
	}

