	bool RestoreMirrorEyeGroup8WindingStateNoexcept(
		MirrorEyeGroup8WindingOverrideState& state) noexcept
	{
		if (!state.lighting.active && !state.overrideArmed && !state.pixelShaderOverrideArmed &&
			!state.authoredBlendOverrideArmed && !state.baseTextureOverrideArmed)
			return true;
		if (!state.context)
			return false;
		const bool lightingRestored = state.lighting.Restore();
		(void)state.sunlight.Restore();
		bool baseTextureRestored = !state.baseTextureOverrideArmed;
		if (state.baseTextureOverrideArmed) {

			baseTextureRestored = SetMirrorEyeBaseTexture0VerifiedNoexcept(
				state.context, state.nativeBaseTexture);
		}
		ID3D11RasterizerState* restoredRasterizer = nullptr;
		ID3D11PixelShader* restoredPixelShader = nullptr;
		ID3D11BlendState* restoredBlendState = nullptr;
		std::array<float, 4> restoredBlendFactor{};
		UINT restoredSampleMask = 0;
		bool rasterizerRestored = !state.overrideArmed;
		bool pixelShaderRestored = !state.pixelShaderOverrideArmed;
		bool blendRestored = !state.authoredBlendOverrideArmed;
		__try {
			if (state.overrideArmed) {
				state.context->RSSetState(state.nativeRasterizer);
				state.context->RSGetState(std::addressof(restoredRasterizer));
				rasterizerRestored = restoredRasterizer == state.nativeRasterizer;
			}
			if (state.pixelShaderOverrideArmed) {
				state.context->PSSetShader(state.nativePixelShader, nullptr, 0);
				state.context->PSGetShader(std::addressof(restoredPixelShader), nullptr, nullptr);
				pixelShaderRestored = restoredPixelShader == state.nativePixelShader;
			}
			if (state.authoredBlendOverrideArmed) {
				state.context->OMSetBlendState(
					state.nativeBlendState, state.nativeBlendFactor.data(), state.nativeSampleMask);
				state.context->OMGetBlendState(
					std::addressof(restoredBlendState), restoredBlendFactor.data(),
					std::addressof(restoredSampleMask));
				blendRestored = restoredBlendState == state.nativeBlendState &&
					restoredSampleMask == state.nativeSampleMask &&
					std::equal(
						restoredBlendFactor.begin(), restoredBlendFactor.end(),
						state.nativeBlendFactor.begin());
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			rasterizerRestored = false;
			pixelShaderRestored = false;
			blendRestored = false;
		}
		bool released = true;
		released = ReleaseMirrorEyeGroup8COMNoexcept(restoredRasterizer) && released;
		released = ReleaseMirrorEyeGroup8COMNoexcept(restoredPixelShader) && released;
		released = ReleaseMirrorEyeGroup8COMNoexcept(restoredBlendState) && released;
		const bool exactRestored = released && rasterizerRestored && pixelShaderRestored &&
			blendRestored && baseTextureRestored && lightingRestored;

		if (!exactRestored) {
			bool shadowMarked = false;
			__try {
				auto* renderState = g_rsPtr;
				if (renderState && reinterpret_cast<std::uintptr_t>(renderState) > 0x10000u) {
					if (!rasterizerRestored)
						*reinterpret_cast<std::uint32_t*>(renderState + kRS_DirtyFlags) |= 0x2u;
					if (!blendRestored)
						*reinterpret_cast<std::uint32_t*>(renderState + kRS_DirtyFlags) |= 0x4u;
					if (!baseTextureRestored)
						*reinterpret_cast<std::uint32_t*>(renderState + kRS_TextureDirtyMask) |= 0x1u;
					shadowMarked = true;
				}
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				shadowMarked = false;
			}
			if (!pixelShaderRestored || !shadowMarked)
				(void)InvalidateCurrentRenderPassCacheNoexcept();
		}
		return exactRestored;
	}

	bool FinishMirrorEyeGroup8DrawOverrideInternal(bool drawCompleted) noexcept
	{
		auto& state = g_mirrorEyeGroup8WindingOverrideState;
		if (!state.active || !state.drawLeaseActive)
			return false;

		auto drawState = state;
		state.drawLeaseActive = false;
		state.context = drawState.context;
		state.lighting = {};
		state.nativeRasterizer = nullptr;
		state.overrideRasterizer = nullptr;
		state.nativePixelShader = nullptr;
		state.overridePixelShader = nullptr;
		state.nativeBlendState = nullptr;
		state.overrideBlendState = nullptr;
		state.nativeBaseTexture = nullptr;
		state.overrideBaseTexture = nullptr;
		state.nativeBaseSampler = nullptr;
		state.nativeBlendFactor = {};
		state.nativeSampleMask = (std::numeric_limits<UINT>::max)();
		state.stateCaptured = false;
		state.overrideArmed = false;
		state.pixelShaderOverrideArmed = false;
		state.authoredBlendOverrideArmed = false;
		state.baseTextureOverrideArmed = false;

		const bool restored = RestoreMirrorEyeGroup8WindingStateNoexcept(drawState);
		bool released = true;
		released = ReleaseMirrorEyeGroup8COMNoexcept(drawState.nativeRasterizer) && released;
		released = ReleaseMirrorEyeGroup8COMNoexcept(drawState.overrideRasterizer) && released;
		released = ReleaseMirrorEyeGroup8COMNoexcept(drawState.nativePixelShader) && released;
		released = ReleaseMirrorEyeGroup8COMNoexcept(drawState.overridePixelShader) && released;
		released = ReleaseMirrorEyeGroup8COMNoexcept(drawState.nativeBlendState) && released;
		released = ReleaseMirrorEyeGroup8COMNoexcept(drawState.overrideBlendState) && released;
		released = ReleaseMirrorEyeGroup8COMNoexcept(drawState.nativeBaseTexture) && released;
		released = ReleaseMirrorEyeGroup8COMNoexcept(drawState.nativeBaseSampler) && released;

		if (drawCompleted)
			++state.completedDrawCalls;
		if (restored && released)
			++state.restoredDrawCalls;
		state.drawReleaseFaulted = state.drawReleaseFaulted || !released;
		if (!drawCompleted || !restored || !released)
			state.faulted = true;
		return restored && released;
	}

	bool EndMirrorEyeGroup8WindingOverrideInternal(
		bool nativeCompleted = false,
		bool accepted = false) noexcept
	{
		if (!g_mirrorEyeGroup8WindingOverrideState.active)
			return false;

		if (g_mirrorEyeGroup8WindingOverrideState.drawLeaseActive)
			(void)FinishMirrorEyeGroup8DrawOverrideInternal(false);
		
		const auto state = g_mirrorEyeGroup8WindingOverrideState;
		g_mirrorEyeGroup8WindingOverrideState = {};
		const bool drawLifecycleProven = state.drawCalls != 0u &&
			state.completedDrawCalls == state.drawCalls;
		const bool applyProven = state.drawCalls != 0u && state.applyCalls == state.drawCalls &&
			state.outputIdentityAttested &&
			state.rasterizerApplied && state.expectedPixelShaderApplied &&
			state.expectedBlendApplied && state.authoredColorOverrideRequired &&
			state.baseTextureRequired && state.playerBaseTextureApplied &&
			state.baseSamplerAttested && !state.baseTextureFaulted && !state.faulted;
		const bool released = !state.drawReleaseFaulted;
		const bool restoreProven = state.drawCalls != 0u &&
			state.restoredDrawCalls == state.drawCalls && released;
		const bool intervalSucceeded = drawLifecycleProven && applyProven && restoreProven &&
			nativeCompleted && accepted;
		RecordMirrorEyeGroup8PublicationInterval(
			applyProven, restoreProven, nativeCompleted, accepted, !intervalSucceeded);
		static std::uint32_t s_group8WindingLogs = 0;
		if (s_group8WindingLogs++ < 16u || !intervalSucceeded) {
			logger::info(
				"[MirrorSceneRenderer] EYEGROUP8AUTHORED exact eye interval: pass={} geometry={} material={} "
				"drawCalls={} completedDrawCalls={} applyCalls={} restoredDrawCalls={} outputExact={} "
				"rasterizerApplied={} expectedPS={} expectedBlend={} authoredColor={} "
				"playerT0Required={} playerT0Applied={} s0Exact={} playerT0Faulted={} nativeCull={} nativeCCW={} "
				"faulted={} restored={} released={} completed={} accepted={} "
				"publicationProof={}",
				static_cast<const void*>(state.pass), static_cast<const void*>(state.geometry),
				state.material, state.drawCalls, state.completedDrawCalls, state.applyCalls,
				state.restoredDrawCalls, state.outputIdentityAttested,
				state.rasterizerApplied, state.expectedPixelShaderApplied,
				state.expectedBlendApplied, state.authoredColorOverrideRequired,
				state.baseTextureRequired,
				state.playerBaseTextureApplied, state.baseSamplerAttested,
				state.baseTextureFaulted, state.nativeCullMode,
				state.nativeFrontCounterClockwise, state.faulted, restoreProven, released,
				nativeCompleted, accepted, intervalSucceeded);
		}
		return intervalSucceeded;
	}

