	bool PrepareEyeGroup4AlbedoPSOverrideInternal(ID3D11DeviceContext* context) noexcept
	{
		auto& cleanup = g_eyeGroup4AlbedoCleanup;
		if (!cleanup.transactionActive)
			return true;  
		if (cleanup.applyFaulted)
			return false;
		const bool exactFinalDraw = cleanup.finalDrawActive &&
			cleanup.finalDrawPass == cleanup.targetPass;
		const bool exactLightingDraw = cleanup.drawActive &&
			cleanup.activePass == cleanup.targetPass;
		if (!context || !exactFinalDraw || !exactLightingDraw ||
			!CurrentDrawMatchesEyeGroup4AlbedoTargetUnsafe(cleanup))
			return false;

		if (cleanup.stateCaptured)
			return cleanup.context == context;

		cleanup.context = context;
		cleanup.context->AddRef();

		cleanup.stateCaptured = true;
		context->VSGetShader(std::addressof(cleanup.nativeVS), nullptr, nullptr);
		context->PSGetShader(std::addressof(cleanup.nativePS), nullptr, nullptr);
		context->PSGetShaderResources(0, 1, std::addressof(cleanup.nativeTexture0));
		context->PSGetShaderResources(1, 1, std::addressof(cleanup.nativeTexture1));
		context->PSGetShaderResources(2, 1, std::addressof(cleanup.nativeTexture2));
		context->PSGetSamplers(0, 1, std::addressof(cleanup.nativeSampler0));
		context->PSGetSamplers(1, 1, std::addressof(cleanup.nativeSampler1));
		context->PSGetSamplers(2, 1, std::addressof(cleanup.nativeSampler2));
		context->VSGetConstantBuffers(1, 1, std::addressof(cleanup.nativeVSConstantBuffer1));
		context->VSGetConstantBuffers(9, 1, std::addressof(cleanup.nativeVSConstantBuffer9));
		context->VSGetConstantBuffers(10, 1, std::addressof(cleanup.nativeVSConstantBuffer10));
		context->VSGetConstantBuffers(12, 1, std::addressof(cleanup.nativeVSConstantBuffer12));
		context->PSGetConstantBuffers(2, 1, std::addressof(cleanup.nativePSConstantBuffer2));
		context->PSGetConstantBuffers(12, 1, std::addressof(cleanup.nativePSConstantBuffer12));
		context->IAGetInputLayout(std::addressof(cleanup.nativeInputLayout));
		context->IAGetVertexBuffers(
			0, static_cast<UINT>(cleanup.nativeVertexBuffers.size()),
			cleanup.nativeVertexBuffers.data(), cleanup.nativeVertexStrides.data(),
			cleanup.nativeVertexOffsets.data());
		context->IAGetIndexBuffer(
			std::addressof(cleanup.nativeIndexBuffer),
			std::addressof(cleanup.nativeIndexFormat),
			std::addressof(cleanup.nativeIndexOffset));
		context->OMGetRenderTargets(
			static_cast<UINT>(cleanup.nativeRenderTargets.size()),
			cleanup.nativeRenderTargets.data(), std::addressof(cleanup.nativeDepthTarget));
		context->OMGetDepthStencilState(
			std::addressof(cleanup.nativeDepthStencilState),
			std::addressof(cleanup.nativeStencilReference));
		context->RSGetState(std::addressof(cleanup.nativeRasterizerState));
		context->OMGetBlendState(
			std::addressof(cleanup.nativeBlendState), cleanup.nativeBlendFactor.data(),
			std::addressof(cleanup.nativeSampleMask));
		if (!AcquireExactEyeGroup4NativeVSUnsafe(
				cleanup.targetShader, globals::d3d::device,
				std::addressof(cleanup.descriptorNativeVS)))
			return false;
		if (!AcquireExactEyeGroup4NativePSUnsafe(
				cleanup.targetShader, globals::d3d::device,
				std::addressof(cleanup.descriptorNativePS)))
			return false;
		auto* privateAlbedoPS = globals::GetProductionEyeAlbedoPS();
		auto* privateBlendState = globals::GetProductionMirrorEyeAuthoredAlphaBlend();
		if (!privateAlbedoPS || !privateBlendState ||
			!DeviceChildUsesDevice(privateAlbedoPS, globals::d3d::device) ||
			!DeviceChildUsesDevice(privateBlendState, globals::d3d::device))
			return false;
		privateAlbedoPS->AddRef();
		cleanup.privateAlbedoPS = privateAlbedoPS;
		privateBlendState->AddRef();
		cleanup.privateBlendState = privateBlendState;
		const bool materialTextureResolved = AcquireEyeGroup4ExpectedDiffuseSRVUnsafe(
			cleanup.targetMaterial, cleanup.targetBaseTextureSet, globals::d3d::device,
			std::addressof(cleanup.materialTexture0));

		if (!cleanup.nativeVS || cleanup.nativeVS != cleanup.descriptorNativeVS ||
			!cleanup.nativePS || cleanup.nativePS != cleanup.descriptorNativePS ||
			!cleanup.nativeTexture0 || !cleanup.nativeTexture1 || !cleanup.nativeTexture2 ||
			!cleanup.nativeSampler0 || !cleanup.nativeSampler1 || !cleanup.nativeSampler2 ||
			!cleanup.nativeVSConstantBuffer1 || !cleanup.nativeVSConstantBuffer9 ||
			!cleanup.nativeVSConstantBuffer10 || !cleanup.nativeVSConstantBuffer12 ||
			!cleanup.nativePSConstantBuffer2 || !cleanup.nativePSConstantBuffer12 ||
			!cleanup.nativeInputLayout ||
			!cleanup.nativeVertexBuffers[0] || !cleanup.nativeIndexBuffer ||
			!cleanup.nativeRenderTargets[0] || !cleanup.nativeRenderTargets[1] ||
			!cleanup.nativeDepthTarget)
			return false;

		std::uintptr_t nativeResource = 0;
		std::uintptr_t materialResource = 0;
		const bool materialResourceMatch = EyeGroup4TextureViewsShareResource(
			cleanup.nativeTexture0, cleanup.materialTexture0,
			std::addressof(nativeResource), std::addressof(materialResource));
		const bool materialViewMatch = cleanup.nativeTexture0 == cleanup.materialTexture0;
		static std::atomic<std::uint32_t> s_nativeTextureLogs{ 0 };
		const auto logOrdinal = s_nativeTextureLogs.fetch_add(1u, std::memory_order_relaxed) + 1u;
		if (logOrdinal <= 16u) {
			logger::info(
				"[MirrorSceneRenderer] EYEALBEDOINPUT post-SetDirty snapshot: ordinal={}/16 vsDescriptor=0x{:08X} nativeVS={} descriptorVS={} psDescriptor=0x{:08X} nativePS={} descriptorPS={} privatePS={} physicalT0={} materialT0={} materialResolved={} physicalResource=0x{:X} materialResource=0x{:X} materialViewMatch={} materialResourceMatch={} diagnosticOnly=false captureOnly=true",
				logOrdinal, kExactEyeGroup4NativeVertexDescriptor,
				static_cast<void*>(cleanup.nativeVS), static_cast<void*>(cleanup.descriptorNativeVS),
				kExactEyeGroup4NativePixelDescriptor,
				static_cast<void*>(cleanup.nativePS), static_cast<void*>(cleanup.descriptorNativePS),
				static_cast<void*>(cleanup.privateAlbedoPS),
				static_cast<void*>(cleanup.nativeTexture0), static_cast<void*>(cleanup.materialTexture0),
				materialTextureResolved,
				nativeResource, materialResource, materialViewMatch, materialResourceMatch);
		}

		CaptureMirrorEyeColorTextureSourceNoexcept(context, cleanup);
		return true;
	}

	void RecordEyeGroup4AlbedoPSOverrideAppliedInternal() noexcept
	{
		auto& cleanup = g_eyeGroup4AlbedoCleanup;
		if (!cleanup.transactionActive || cleanup.applyFaulted)
			return;
		if (!cleanup.stateCaptured)
			return;  
		const bool exactFinalDraw = cleanup.finalDrawActive &&
			cleanup.finalDrawPass == cleanup.targetPass;
		const bool exactLightingDraw = cleanup.drawActive &&
			cleanup.activePass == cleanup.targetPass;
		if (!exactFinalDraw || !exactLightingDraw ||
			!CurrentDrawMatchesEyeGroup4AlbedoTargetUnsafe(cleanup)) {
			cleanup.applyFaulted = true;
			g_eyeAlbedoOverrideActive.store(false, std::memory_order_release);
			return;
		}
		if (!cleanup.context || !cleanup.privateAlbedoPS || !cleanup.privateBlendState ||
			cleanup.privatePSArmed || cleanup.privateBlendArmed) {
			cleanup.applyFaulted = true;
			g_eyeAlbedoOverrideActive.store(false, std::memory_order_release);
			return;
		}

		cleanup.privatePSArmed = true;
		cleanup.context->PSSetShader(cleanup.privateAlbedoPS, nullptr, 0);
		cleanup.privateBlendArmed = true;
		cleanup.context->OMSetBlendState(
			cleanup.privateBlendState, nullptr, cleanup.nativeSampleMask);

		EyeGroup4DrawStateEvidence evidence{};
		const bool captured = CaptureEyeGroup4DrawStateEvidenceInternal(cleanup.context, evidence);
		auto& queryState = g_eyeGroup4OcclusionQueryState;
		if (queryState.activeSlot < queryState.slots.size())
			queryState.slots[queryState.activeSlot].drawState = evidence;
		const bool exactNativeState = captured &&
			EyeGroup4DrawStatePreservesNativeConsumerContract(evidence);
		if (!exactNativeState) {
			static std::atomic<std::uint32_t> s_eyeNativeStateRejectLogs{ 0u };
			if (s_eyeNativeStateRejectLogs.fetch_add(1u, std::memory_order_relaxed) < 8u) {
				const bool shaderState = evidence.physicalVSMatchesSavedNative &&
					evidence.savedNativeVSMatchesDescriptor && evidence.physicalPSMatchesPrivateAlbedo &&
					evidence.savedNativePSMatchesDescriptor;
				const bool textureSamplerState = evidence.texture0MatchesSavedNative &&
					evidence.texture0ResourceMatchesSavedNative && evidence.texture1Bound &&
					evidence.texture1MatchesSavedNative && evidence.texture2Bound &&
					evidence.texture2MatchesSavedNative && evidence.sampler0Bound &&
					evidence.sampler0MatchesSavedNative && evidence.sampler1Bound &&
					evidence.sampler1MatchesSavedNative && evidence.sampler2Bound &&
					evidence.sampler2MatchesSavedNative;
				const bool constantBufferState = evidence.vertexCB1MatchesSavedNative &&
					evidence.vertexCB9MatchesSavedNative && evidence.vertexCB10MatchesSavedNative &&
					evidence.vertexCB12MatchesSavedNative && evidence.perGeometryCB2MatchesSavedNative &&
					evidence.perFrameCB12MatchesSavedNative;
				const bool inputState = evidence.inputLayoutMatchesSavedNative &&
					evidence.vertexBuffer0MatchesSavedNative && evidence.vertexBuffersMatchSavedNative &&
					evidence.indexBufferMatchesSavedNative &&
					evidence.primitiveTopology == D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST;
				const bool outputState =
					(evidence.expectedPlanarRenderTargetCount == 2u ||
						evidence.expectedPlanarRenderTargetCount == 3u ||
						evidence.expectedPlanarRenderTargetCount == 4u) &&
					evidence.renderTargetCount == evidence.expectedPlanarRenderTargetCount &&
					evidence.renderTargetsMatchSavedNative &&
					evidence.depthTargetMatchesSavedNative &&
					evidence.renderTargetsMatchActivePlanarTarget &&
					evidence.depthTargetMatchesActivePlanarTarget;
				const bool depthState = evidence.depthStateMatchesSavedNative &&
					evidence.stencilReferenceMatchesSavedNative && evidence.depthEnable &&
					evidence.depthFunction != D3D11_COMPARISON_NEVER;
				const bool rasterState = evidence.rasterizerStateMatchesSavedNative &&
					evidence.depthClipEnable;
				const bool rasterExtent = evidence.viewportCount == 1u &&
					evidence.viewportTopLeftX == 0.0f && evidence.viewportTopLeftY == 0.0f &&
					evidence.viewportWidth == static_cast<float>(evidence.expectedPlanarWidth) &&
					evidence.viewportHeight == static_cast<float>(evidence.expectedPlanarHeight) &&
					evidence.viewportMinDepth == 0.0f && evidence.viewportMaxDepth == 1.0f &&
					(!evidence.scissorEnable || (evidence.scissorCount == 1u &&
						evidence.scissorLeft <= 0 && evidence.scissorTop <= 0 &&
						evidence.scissorRight >= static_cast<std::int32_t>(evidence.expectedPlanarWidth) &&
						evidence.scissorBottom >= static_cast<std::int32_t>(evidence.expectedPlanarHeight)));
				const bool blendState = evidence.privateBlendLeaseExact &&
					evidence.blendStateExplicit && !evidence.alphaToCoverageEnable &&
					!evidence.independentBlend &&
					EyeGroup4BlendTargetIsStraightAlpha(evidence.renderTarget0Blend) &&
					EyeGroup4BlendTargetIsStraightAlpha(evidence.renderTarget1Blend);
				logger::warn(
					"[MirrorSceneRenderer] EYENATIVESTATE rejected: observed={} shader={} textures={} cb={} input={} "
					"outputs={} depth={} raster={} extent={} blend={} rt={}/{} expected={} savedRT={} activeRT={} "
					"savedDS={} activeDS={} cull={} ccw={} viewport={}x{} expectedExtent={}x{} "
					"cbBytes={}/{}/{}/{}/{}/{} writeMasks={}/{} rtBound={}/{}/{}",
					evidence.observed, shaderState, textureSamplerState, constantBufferState, inputState,
					outputState, depthState, rasterState, rasterExtent, blendState,
					evidence.renderTargetCount, evidence.renderTarget2Bound,
					evidence.expectedPlanarRenderTargetCount, evidence.renderTargetsMatchSavedNative,
					evidence.renderTargetsMatchActivePlanarTarget, evidence.depthTargetMatchesSavedNative,
					evidence.depthTargetMatchesActivePlanarTarget, evidence.cullMode,
					evidence.frontCounterClockwise, evidence.viewportWidth, evidence.viewportHeight,
					evidence.expectedPlanarWidth, evidence.expectedPlanarHeight,
					evidence.vertexCB1Bytes, evidence.vertexCB9Bytes, evidence.vertexCB10Bytes,
					evidence.vertexCB12Bytes, evidence.perGeometryCB2Bytes,
					evidence.perFrameCB12Bytes, evidence.renderTarget0Blend.writeMask,
					evidence.renderTarget1Blend.writeMask, evidence.renderTarget0Bound,
					evidence.renderTarget1Bound, evidence.renderTarget2Bound);
			}

			(void)RestoreEyeGroup4AlbedoPSBeforeSetDirtyInternal(cleanup.context);
			cleanup.applyFaulted = true;
			g_eyeAlbedoOverrideActive.store(false, std::memory_order_release);
			return;
		}
		cleanup.nativeControlVerified = true;
		++cleanup.applications;
		++cleanup.nativeStateVerifications;
		if (exactFinalDraw)
			++cleanup.finalDrawApplications;
	}

	constexpr std::size_t kMaximumEyeNoWriteDepthStates = 8;
	struct EyeNoWriteDepthStateCacheEntry
	{
		Microsoft::WRL::ComPtr<ID3D11DepthStencilState> source;
		Microsoft::WRL::ComPtr<ID3D11DepthStencilState> noWrite;
		bool sourceIsDefault{ false };
		bool used{ false };
	};
	struct EyeNoWriteDepthStateCache
	{
		Microsoft::WRL::ComPtr<ID3D11Device> device;
		std::array<EyeNoWriteDepthStateCacheEntry, kMaximumEyeNoWriteDepthStates> entries{};
	};
	
	auto& g_eyeNoWriteDepthStateCache = *new EyeNoWriteDepthStateCache();

	bool ResolveEyeNoWriteDepthStateUnsafe(
		ID3D11Device* device,
		ID3D11DepthStencilState* source,
		ID3D11DepthStencilState** noWrite) noexcept
	{
		if (!device || !noWrite)
			return false;
		*noWrite = nullptr;
		auto& cache = g_eyeNoWriteDepthStateCache;
		if (cache.device.Get() != device) {
			cache.entries = {};
			cache.device.Reset();
			cache.device = device;
		}
		for (auto& entry : cache.entries) {
			if (!entry.used)
				continue;
			const bool matches = source ? entry.source.Get() == source : entry.sourceIsDefault;
			if (matches) {
				*noWrite = entry.noWrite.Get();
				return *noWrite != nullptr;
			}
		}
		auto slot = cache.entries.end();
		for (auto at = cache.entries.begin(); at != cache.entries.end(); ++at) {
			if (!at->used) {
				slot = at;
				break;
			}
		}
		if (slot == cache.entries.end())
			return false;
		auto description = DefaultClothingDepthStencilDescription();
		if (source)
			source->GetDesc(std::addressof(description));

		description.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ZERO;
		Microsoft::WRL::ComPtr<ID3D11DepthStencilState> created;
		if (FAILED(device->CreateDepthStencilState(std::addressof(description), created.GetAddressOf())) ||
			!created)
			return false;
		slot->source = source;
		slot->noWrite = std::move(created);
		slot->sourceIsDefault = source == nullptr;
		slot->used = true;
		*noWrite = slot->noWrite.Get();
		return true;
	}

	struct EyeGroup4NoPixelKey
	{
		const RE::BSRenderPass* pass{ nullptr };
		const void* shader{ nullptr };
		const void* material{ nullptr };
		std::uint32_t technique{ 0 };
		std::uint32_t kind{ 0 };
	};
	enum class EyeGroup4NoPixelKind : std::uint32_t
	{
		kEyeAO = 0,

		kEyeWet = 1
	};
	enum class EyeGroup4NoPixelBeginStatus : std::uint32_t
	{
		kNoTargets = 0,
		kArmed = 1,
		kRejected = 2
	};
	constexpr std::uint32_t kMaximumEyeGroup4NoPixelKeys = 1;
	constexpr std::uint32_t kRequiredEyeGroup4NoPixelKindMask =
		(1u << static_cast<std::uint32_t>(EyeGroup4NoPixelKind::kEyeAO));
	struct EyeGroup4NoPixelCleanupState
	{
		ID3D11DeviceContext* context{ nullptr };
		ID3D11PixelShader* previousPS{ nullptr };
		ID3D11DepthStencilState* previousDepthStencil{ nullptr };
		UINT previousStencilReference{ 0 };
		std::array<EyeGroup4NoPixelKey, kMaximumEyeGroup4NoPixelKeys> keys{};
		std::uint32_t keyCount{ 0 };
		std::uint32_t nullPSBinds{ 0 };
		std::uint32_t matchedDraws{ 0 };
		std::uint32_t expectedDraws{ 0 };
		std::uint32_t requiredKeyMask{ 0 };
		std::uint32_t matchedKeyMask{ 0 };
		std::uint32_t collisionCount{ 0 };
		std::uint32_t depthWriteSuppressions{ 0 };
		const RE::BSRenderPass* activePass{ nullptr };
		bool transactionActive{ false };
		bool overrideActive{ false };
		bool stateCaptured{ false };
		bool applyFaulted{ false };
		bool suppressAllDiagnostic{ false };
	};
	thread_local EyeGroup4NoPixelCleanupState g_eyeGroup4NoPixelCleanup{};

	bool EyeGroup4NoPixelCommandBufferRecordContainsTargetUnsafe(
		std::int32_t instanceIndex,
		std::uint32_t technique,
		const void* batchRecord) noexcept
	{

		const auto& cleanup = g_eyeGroup4NoPixelCleanup;
		if (instanceIndex != 4 || !cleanup.transactionActive || !cleanup.overrideActive ||
			cleanup.applyFaulted || cleanup.suppressAllDiagnostic ||
			!SkinTintZPrepassPointerPlausible(batchRecord))
			return false;

		const EyeGroup4NoPixelKey* target = nullptr;
		for (std::uint32_t index = 0; index < cleanup.keyCount; ++index) {
			const auto& key = cleanup.keys[index];
			if (key.kind == static_cast<std::uint32_t>(EyeGroup4NoPixelKind::kEyeWet) &&
				key.technique == technique) {
				if (target)
					return false;
				target = std::addressof(key);
			}
		}
		if (!target || !target->pass || !target->shader || !target->material)
			return false;

		constexpr std::size_t kPassShader = 0x08;
		constexpr std::size_t kPassProperty = 0x10;
		constexpr std::size_t kPassGeometry = 0x18;
		constexpr std::size_t kPassNextSibling = 0x40;
		constexpr std::size_t kPassTechnique = 0x48;
		constexpr std::size_t kPropertyMaterial = 0x58;
		constexpr std::uint32_t kMaximumChainPasses = 0x20000;
		auto readNext = [](const std::uint8_t* pass) noexcept -> const std::uint8_t* {
			if (!SkinTintZPrepassPointerPlausible(pass))
				return nullptr;
			auto* next = *reinterpret_cast<const std::uint8_t* const*>(pass + kPassNextSibling);
			return SkinTintZPrepassPointerPlausible(next) ? next : nullptr;
		};

		auto* pass = *reinterpret_cast<const std::uint8_t* const*>(batchRecord);
		auto* slow = pass;
		auto* fast = pass;
		for (std::uint32_t walked = 0; pass && walked < kMaximumChainPasses; ++walked) {
			if (!SkinTintZPrepassPointerPlausible(pass))
				return false;
			if (reinterpret_cast<const RE::BSRenderPass*>(pass) == target->pass) {
				auto* shader = *reinterpret_cast<const void* const*>(pass + kPassShader);
				auto* property = *reinterpret_cast<const std::uint8_t* const*>(pass + kPassProperty);
				auto* geometry = *reinterpret_cast<const void* const*>(pass + kPassGeometry);
				if (!SkinTintZPrepassPointerPlausible(property) ||
					!SkinTintZPrepassPointerPlausible(geometry))
					return false;
				auto* material = *reinterpret_cast<const void* const*>(property + kPropertyMaterial);
				const auto passTechnique =
					*reinterpret_cast<const std::uint32_t*>(pass + kPassTechnique);
				return shader == target->shader && material == target->material &&
					passTechnique == target->technique;
			}

			pass = readNext(pass);
			slow = readNext(slow);
			fast = readNext(readNext(fast));
			if (slow && slow == fast)
				return false;
		}
		return false;
	}

	struct EyeGroup4NoPixelFinishResult
	{
		std::uint32_t nullPSBinds{ 0 };
		std::uint32_t keyCount{ 0 };
		std::uint32_t matchedDraws{ 0 };
		std::uint32_t expectedDraws{ 0 };
		std::uint32_t requiredKeyMask{ 0 };
		std::uint32_t matchedKeyMask{ 0 };
		std::uint32_t collisionCount{ 0 };
		std::uint32_t depthWriteSuppressions{ 0 };
		bool hadTransaction{ false };
		bool physicalPSRestored{ true };
		bool physicalDepthRestored{ true };
		bool cacheInvalidated{ true };
		bool coverageComplete{ true };
		bool stateSafe{ true };
		bool succeeded{ true };
	};

	bool RestoreEyeGroup4NoPixelPSBeforeSetDirtyInternal(
		ID3D11DeviceContext* context) noexcept
	{
		auto& cleanup = g_eyeGroup4NoPixelCleanup;
		if (!cleanup.stateCaptured && !cleanup.previousPS && !cleanup.previousDepthStencil)
			return true;

		auto* previousPS = cleanup.previousPS;
		auto* previousDepthStencil = cleanup.previousDepthStencil;
		const UINT previousStencilReference = cleanup.previousStencilReference;
		cleanup.previousPS = nullptr;
		cleanup.previousDepthStencil = nullptr;
		cleanup.previousStencilReference = 0;
		cleanup.stateCaptured = false;
		bool restored = context && context == cleanup.context;
		if (restored) {
			__try {
				context->PSSetShader(previousPS, nullptr, 0);
				context->OMSetDepthStencilState(previousDepthStencil, previousStencilReference);
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				restored = false;
			}
		}
		if (previousPS) {
			__try {
				previousPS->Release();
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				restored = false;
			}
		}
		if (previousDepthStencil) {
			__try {
				previousDepthStencil->Release();
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				restored = false;
			}
		}
		if (!restored) {
			cleanup.overrideActive = false;
			cleanup.applyFaulted = true;
		}
		return restored;
	}

	EyeGroup4NoPixelFinishResult FinishEyeGroup4NoPixelSuppression() noexcept
	{
		auto& cleanup = g_eyeGroup4NoPixelCleanup;
		EyeGroup4NoPixelFinishResult result{};
		result.nullPSBinds = cleanup.nullPSBinds;
		result.keyCount = cleanup.keyCount;
		result.matchedDraws = cleanup.matchedDraws;
		result.expectedDraws = cleanup.expectedDraws;
		result.requiredKeyMask = cleanup.requiredKeyMask;
		result.matchedKeyMask = cleanup.matchedKeyMask;
		result.collisionCount = cleanup.collisionCount;
		result.depthWriteSuppressions = cleanup.depthWriteSuppressions;
		result.hadTransaction = cleanup.transactionActive || cleanup.overrideActive ||
			cleanup.stateCaptured || cleanup.context || cleanup.previousPS || cleanup.previousDepthStencil;
		const bool physicalPSRestored = RestoreEyeGroup4NoPixelPSBeforeSetDirtyInternal(cleanup.context);
		const bool applyFaulted = cleanup.applyFaulted;

		cleanup.overrideActive = false;
		cleanup.transactionActive = false;
		cleanup.context = nullptr;
		cleanup.keys = {};
		cleanup.keyCount = 0;
		cleanup.nullPSBinds = 0;
		cleanup.matchedDraws = 0;
		cleanup.expectedDraws = 0;
		cleanup.requiredKeyMask = 0;
		cleanup.matchedKeyMask = 0;
		cleanup.collisionCount = 0;
		cleanup.depthWriteSuppressions = 0;
		cleanup.activePass = nullptr;
		cleanup.stateCaptured = false;
		cleanup.applyFaulted = false;
		cleanup.suppressAllDiagnostic = false;
		result.physicalPSRestored = physicalPSRestored;
		result.physicalDepthRestored = physicalPSRestored;
		if (result.hadTransaction)
			result.cacheInvalidated = InvalidateCurrentRenderPassCacheNoexcept();
		const bool coverageComplete = !result.hadTransaction ||
			(result.expectedDraws != 0 && result.matchedDraws == result.expectedDraws &&
				result.nullPSBinds == result.expectedDraws &&
				result.depthWriteSuppressions == result.expectedDraws &&
				result.matchedKeyMask == result.requiredKeyMask);
		result.coverageComplete = coverageComplete && !applyFaulted;

		result.stateSafe = result.physicalPSRestored && result.physicalDepthRestored &&
			result.cacheInvalidated;
		result.succeeded = result.stateSafe && result.coverageComplete;
		return result;
	}

	bool IsExactEyeGroup4NoPixelTarget(
		const PlayerFacePassEvidence& evidence,
		EyeGroup4NoPixelKind* kind) noexcept
	{
		if (!evidence.player || !evidence.face || evidence.geometryGroup != 4 ||
			evidence.shader == 0 || evidence.material == 0)
			return false;
		const bool eyeAO = evidence.shaderType ==
				static_cast<std::int32_t>(RE::BSShader::Type::Effect) &&
			evidence.technique == 0x10000407u &&
			evidence.materialVtable == g_effectMaterialVtableAddress;
		if (!eyeAO)
			return false;
		if (kind)
			*kind = EyeGroup4NoPixelKind::kEyeAO;
		return true;
	}

	bool HasPlayerFaceEyeAORawCandidate(const PlayerFacePassInventory& inventory) noexcept
	{

		for (std::uint32_t index = 0;
			index < inventory.production.count;
			++index) {
			const auto& evidence = inventory.production.evidence[index];
			if (evidence.player && evidence.face && evidence.geometryGroup == 4 &&
				evidence.shaderType == static_cast<std::int32_t>(RE::BSShader::Type::Effect) &&
				evidence.technique == 0x10000407u)
				return true;
		}
		return false;
	}

	bool HasPlayerFaceEyeWetRawCandidate(const PlayerFacePassInventory& inventory) noexcept
	{

		for (std::uint32_t index = 0;
			index < inventory.production.count;
			++index) {
			const auto& evidence = inventory.production.evidence[index];
			if (evidence.player && evidence.face && evidence.geometryGroup == 4 &&
				evidence.shaderType == static_cast<std::int32_t>(RE::BSShader::Type::Lighting) &&
				evidence.technique == 0x0000901Fu)
				return true;
		}
		return false;
	}

	EyeGroup4NoPixelBeginStatus BeginEyeGroup4NoPixelSuppression(
		ID3D11DeviceContext* context,
		const PlayerFacePassInventory& inventory) noexcept
	{
		if (!context)
			return EyeGroup4NoPixelBeginStatus::kRejected;

		const auto stale = FinishEyeGroup4NoPixelSuppression();
		if (!stale.stateSafe) {
			g_faulted = true;
			static std::uint32_t s_staleCleanupFaultLogs = 0;
			if (s_staleCleanupFaultLogs++ < 4u)
				logger::error(
					"[MirrorSceneRenderer] EYEGROUP4NOPIXEL stale transaction cleanup failed; capture disabled");
			return EyeGroup4NoPixelBeginStatus::kRejected;
		}
		if (!stale.coverageComplete) {
			static std::uint32_t s_staleCoverageLogs = 0;
			if (s_staleCoverageLogs++ < 4u)
				logger::warn(
					"[MirrorSceneRenderer] EYEGROUP4NOPIXEL stale optional suffix was incomplete; physical rollback proven and the new transaction remains eligible");
		}

		if (inventory.malformed || inventory.faulted || inventory.production.overflow ||
			inventory.truncatedChains != 0 || inventory.truncatedParentWalks != 0)
			return EyeGroup4NoPixelBeginStatus::kRejected;

		auto& cleanup = g_eyeGroup4NoPixelCleanup;
		cleanup.context = context;
		cleanup.keys = {};
		cleanup.keyCount = 0;
		cleanup.nullPSBinds = 0;
		cleanup.matchedDraws = 0;
		cleanup.expectedDraws = 0;
		cleanup.requiredKeyMask = 0;
		cleanup.matchedKeyMask = 0;
		cleanup.collisionCount = 0;
		cleanup.depthWriteSuppressions = 0;
		cleanup.suppressAllDiagnostic = g_eyeGroup4NoPixel;
		std::uint32_t admittedKindMask = 0;

		for (std::uint32_t index = 0;
			index < inventory.production.count;
			++index) {
			const auto& evidence = inventory.production.evidence[index];
			EyeGroup4NoPixelKind kind{};
			if (!IsExactEyeGroup4NoPixelTarget(evidence, std::addressof(kind)))
				continue;

			const EyeGroup4NoPixelKey key{
				reinterpret_cast<const RE::BSRenderPass*>(evidence.pass),
				reinterpret_cast<const void*>(evidence.shader),
				reinterpret_cast<const void*>(evidence.material),
				evidence.technique,
				static_cast<std::uint32_t>(kind)
			};
			bool duplicate = false;
			for (std::uint32_t keyIndex = 0; keyIndex < cleanup.keyCount; ++keyIndex) {
				const auto& existing = cleanup.keys[keyIndex];
				duplicate = existing.pass == key.pass && existing.shader == key.shader && existing.material == key.material &&
					existing.technique == key.technique;
				if (duplicate)
					break;
			}
			if (duplicate)
				continue;
			if (cleanup.keyCount >= kMaximumEyeGroup4NoPixelKeys) {
				cleanup = {};
				return EyeGroup4NoPixelBeginStatus::kRejected;
			}
			cleanup.keys[cleanup.keyCount++] = key;
			admittedKindMask |= 1u << static_cast<std::uint32_t>(kind);
		}
		if (!cleanup.suppressAllDiagnostic &&
			admittedKindMask != kRequiredEyeGroup4NoPixelKindMask) {
			cleanup = {};
			return admittedKindMask == 0 ? EyeGroup4NoPixelBeginStatus::kNoTargets :
				EyeGroup4NoPixelBeginStatus::kRejected;
		}

		for (std::uint32_t keyIndex = 0; keyIndex < cleanup.keyCount; ++keyIndex) {
			const auto key = cleanup.keys[keyIndex];
			std::uint32_t totalOccurrences = 0;
			std::uint32_t targetOccurrences = 0;
			for (std::uint32_t index = 0;
				index < inventory.production.count;
				++index) {
				const auto& evidence = inventory.production.evidence[index];
				if (evidence.geometryGroup != 4 ||
					reinterpret_cast<const void*>(evidence.shader) != key.shader ||
					reinterpret_cast<const void*>(evidence.material) != key.material ||
					evidence.technique != key.technique)
					continue;
				totalOccurrences = inventory.production.tripleOccurrences[index];
				EyeGroup4NoPixelKind occurrenceKind{};
				if (IsExactEyeGroup4NoPixelTarget(evidence, std::addressof(occurrenceKind)) &&
					static_cast<std::uint32_t>(occurrenceKind) == key.kind)
					++targetOccurrences;
			}
			if (totalOccurrences == 0 || totalOccurrences != targetOccurrences) {

				const std::uint32_t collisions = cleanup.collisionCount + 1u;
				cleanup = {};
				cleanup.collisionCount = collisions;
				return EyeGroup4NoPixelBeginStatus::kRejected;
			}
			cleanup.expectedDraws += totalOccurrences;
			cleanup.requiredKeyMask |= (1u << keyIndex);
		}

		if (cleanup.suppressAllDiagnostic) {
			cleanup.expectedDraws = inventory.production.group4Passes;
			cleanup.requiredKeyMask = 0;
			if (cleanup.expectedDraws == 0) {
				cleanup = {};
				return EyeGroup4NoPixelBeginStatus::kNoTargets;
			}
		}
		cleanup.transactionActive = true;
		cleanup.overrideActive = true;
		cleanup.applyFaulted = false;
		return EyeGroup4NoPixelBeginStatus::kArmed;
	}

	bool EyeGroup4NoPixelOverrideArmed() noexcept
	{
		return g_eyeGroup4NoPixelCleanup.overrideActive;
	}

	bool ApplyEyeGroup4NoPixelPSInternal(ID3D11DeviceContext* context) noexcept
	{
		auto& cleanup = g_eyeGroup4NoPixelCleanup;
		if (!cleanup.overrideActive)
			return false;

		if (!cleanup.suppressAllDiagnostic && !cleanup.activePass)
			return true;
		bool applied = false;
		__try {
			const auto* currentShader = *reinterpret_cast<const void* const*>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassShader)).address());
			const auto* currentMaterial = *reinterpret_cast<const void* const*>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassMaterial)).address());
			const auto currentTechnique = *reinterpret_cast<const std::uint32_t*>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassTechnique)).address());
			bool selected = cleanup.suppressAllDiagnostic;
			std::uint32_t selectedKey = kMaximumEyeGroup4NoPixelKeys;
			for (std::uint32_t index = 0; !selected && index < cleanup.keyCount; ++index) {
				const auto& key = cleanup.keys[index];
				selected = key.pass == cleanup.activePass &&
					key.shader == currentShader && key.material == currentMaterial &&
					key.technique == currentTechnique;
				if (selected)
					selectedKey = index;
			}
			if (!selected)
				return true;
			if (cleanup.stateCaptured || cleanup.previousPS || cleanup.previousDepthStencil) {

				auto* stalePS = cleanup.previousPS;
				auto* staleDepthStencil = cleanup.previousDepthStencil;
				cleanup.previousPS = nullptr;
				cleanup.previousDepthStencil = nullptr;
				cleanup.previousStencilReference = 0;
				cleanup.stateCaptured = false;
				if (stalePS)
					stalePS->Release();
				if (staleDepthStencil)
					staleDepthStencil->Release();
				cleanup.overrideActive = false;
				cleanup.applyFaulted = true;
				return false;
			}
			if (context && context == cleanup.context) {
				ID3D11PixelShader* previousPS = nullptr;
				ID3D11DepthStencilState* previousDepthStencil = nullptr;
				UINT previousStencilReference = 0;
				context->PSGetShader(std::addressof(previousPS), nullptr, nullptr);
				context->OMGetDepthStencilState(
					std::addressof(previousDepthStencil), std::addressof(previousStencilReference));
				ID3D11DepthStencilState* noWriteDepthStencil = nullptr;
				if (!ResolveEyeNoWriteDepthStateUnsafe(
						globals::d3d::device, previousDepthStencil,
						std::addressof(noWriteDepthStencil))) {
					if (previousPS)
						previousPS->Release();
					if (previousDepthStencil)
						previousDepthStencil->Release();
					return false;
				}
				cleanup.previousPS = previousPS;
				cleanup.previousDepthStencil = previousDepthStencil;
				cleanup.previousStencilReference = previousStencilReference;
				cleanup.stateCaptured = true;
				context->OMSetDepthStencilState(noWriteDepthStencil, previousStencilReference);
				context->PSSetShader(nullptr, nullptr, 0);
				++cleanup.nullPSBinds;
				++cleanup.depthWriteSuppressions;
				++cleanup.matchedDraws;
				if (selectedKey < kMaximumEyeGroup4NoPixelKeys)
					cleanup.matchedKeyMask |= (1u << selectedKey);
				applied = true;
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			applied = false;
		}
		if (!applied) {
			
			cleanup.overrideActive = false;
			cleanup.applyFaulted = true;
		}
		return applied;
	}

	void BeginEyeGroup4NoPixelEffectDrawInternal(RE::BSRenderPass* pass) noexcept
	{
		auto& cleanup = g_eyeGroup4NoPixelCleanup;
		cleanup.activePass = nullptr;
		if (!cleanup.overrideActive || cleanup.suppressAllDiagnostic || !pass)
			return;
		for (std::uint32_t index = 0; index < cleanup.keyCount; ++index) {
			if (cleanup.keys[index].pass == pass) {
				cleanup.activePass = pass;
				return;
			}
		}
	}

	void EndEyeGroup4NoPixelEffectDrawInternal(RE::BSRenderPass* pass) noexcept
	{
		auto& cleanup = g_eyeGroup4NoPixelCleanup;
		if (!pass || cleanup.activePass != pass)
			return;
		const bool restored = RestoreEyeGroup4NoPixelPSBeforeSetDirtyInternal(cleanup.context);
		cleanup.activePass = nullptr;
		if (!restored) {
			cleanup.overrideActive = false;
			cleanup.applyFaulted = true;
		}
	}

	bool FinishClothingRedrawPass() noexcept
	{
		auto& cleanup = g_clothingRedrawCleanup;
		const bool hadTransaction = cleanup.overrideActive || cleanup.passOpen || cleanup.stateCaptured ||
			cleanup.context || cleanup.activeMaterial;
		const bool stateWasApplied = cleanup.stateApplied;
		const bool stateFaulted = cleanup.stateFaulted;
		const bool passAccepted = cleanup.passAccepted;
		bool succeeded = true;

		cleanup.overrideActive = false;
		cleanup.activeMaterial = nullptr;
		if (cleanup.passOpen) {
			cleanup.passOpen = false;
			if (!EndImmediatePassSequenceNoexcept())
				succeeded = false;
		}

		auto* context = cleanup.context;
		auto* previousRasterizer = cleanup.previousRasterizer;
		auto* previousDepthStencil = cleanup.previousDepthStencil;
		const UINT previousStencilReference = cleanup.previousStencilReference;
		const bool stateCaptured = cleanup.stateCaptured;
		cleanup.context = nullptr;
		cleanup.previousRasterizer = nullptr;
		cleanup.previousDepthStencil = nullptr;
		cleanup.biasedRasterizer = nullptr;
		cleanup.biasedDepthStencil = nullptr;
		cleanup.previousStencilReference = 0;
		cleanup.stateCaptured = false;
		cleanup.stateApplied = false;
		cleanup.stateFaulted = false;
		cleanup.passAccepted = false;

		if (stateCaptured) {
			if (!context) {
				succeeded = false;
			} else {
				__try {
					context->RSSetState(previousRasterizer);
				} __except (EXCEPTION_EXECUTE_HANDLER) {
					succeeded = false;
				}
				__try {
					context->OMSetDepthStencilState(previousDepthStencil, previousStencilReference);
				} __except (EXCEPTION_EXECUTE_HANDLER) {
					succeeded = false;
				}
			}
		}
		if (previousRasterizer) {
			__try {
				previousRasterizer->Release();
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				succeeded = false;
			}
		}
		if (previousDepthStencil) {
			__try {
				previousDepthStencil->Release();
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				succeeded = false;
			}
		}
		if (hadTransaction && !InvalidateCurrentRenderPassCacheNoexcept())
			succeeded = false;
		if (stateFaulted || (passAccepted && !stateWasApplied))
			succeeded = false;
		return succeeded;
	}

	struct ClothingDepthBiasReplayResult
	{
		std::uint32_t attempted{ 0 };
		std::uint32_t accepted{ 0 };
		bool succeeded{ true };
	};

	bool RedrawClothingDepthBiasPassesUnsafe(ID3D11DeviceContext* context) noexcept
	{
		g_clothingRedrawAttempted = 0;
		g_clothingRedrawAccepted = 0;
		if (!FinishClothingRedrawPass())
			return false;
		if (g_clothingDepthBiasPassCount == 0)
			return true;
		if (!context || !globals::d3d::device ||
			g_clothingDepthBiasPassCount > kMaximumClothingDepthBiasPasses)
			return false;

		if (!g_renderPassImmediatelyEntryAttested) {
			static bool s_loggedEntryMismatch = false;
			if (!s_loggedEntryMismatch) {
				s_loggedEntryMismatch = true;
				logger::error(
					"[MirrorSceneRenderer] CLOTHINGREDRAW disabled: RenderPassImmediately entry bytes mismatch");
			}
			return false;
		}

		using RenderPassImmediately_t = bool (*)(std::uint8_t*, std::uint32_t, bool);
		auto renderPassImmediately = reinterpret_cast<RenderPassImmediately_t>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_RenderPassImmediately)).address());
		for (std::uint32_t index = 0; index < g_clothingDepthBiasPassCount; ++index) {
			const auto& record = g_clothingDepthBiasPasses[index];
			if (!SkinTintZPrepassPointerPlausible(record.pass) ||
				!SkinTintZPrepassPointerPlausible(record.material) ||
				*reinterpret_cast<const std::uint32_t*>(record.pass + 0x48) != kClothingDeferredTechnique)
				return false;

			g_clothingRedrawCleanup = {};
			g_clothingRedrawCleanup.context = context;
			g_clothingRedrawCleanup.activeMaterial = record.material;
			g_clothingRedrawCleanup.overrideActive = true;
			g_clothingRedrawCleanup.passOpen = true;
			++g_clothingRedrawAttempted;
			const bool accepted = renderPassImmediately(
				record.pass, kClothingDeferredTechnique, false);
			g_clothingRedrawCleanup.passAccepted = accepted;
			if (accepted)
				++g_clothingRedrawAccepted;
			if (!FinishClothingRedrawPass())
				return false;
		}
		return true;
	}

	ClothingDepthBiasReplayResult RedrawClothingDepthBiasPasses(
		ID3D11DeviceContext* context) noexcept
	{
		ClothingDepthBiasReplayResult result{};
		const auto expected = g_clothingDepthBiasPassCount;
		bool drawSucceeded = false;
		bool drawFaulted = false;
		__try {
			drawSucceeded = RedrawClothingDepthBiasPassesUnsafe(context);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			drawSucceeded = false;
			drawFaulted = true;
		}
		const bool cleanupSucceeded = FinishClothingRedrawPass();
		result.attempted = g_clothingRedrawAttempted;
		result.accepted = g_clothingRedrawAccepted;
		result.succeeded = !g_clothingDepthBiasCollectionFaulted &&
			drawSucceeded && cleanupSucceeded && !drawFaulted &&
			result.attempted == expected && result.accepted == result.attempted;
		g_clothingRedrawAttempted = 0;
		g_clothingRedrawAccepted = 0;
		ClearClothingDepthBiasPasses();
		if (!result.succeeded) {
			g_faulted = true;
			static std::uint32_t s_clothingRedrawFaultLogs = 0;
			if (s_clothingRedrawFaultLogs++ < 4u) {
				logger::error(
					"[MirrorSceneRenderer] CLOTHINGREDRAW faulted (draw={}, seh={}, cleanup={}); aborting private capture",
					drawSucceeded, drawFaulted, cleanupSucceeded);
			}
		}
		return result;
	}

