	bool PreparePrivatePlayerGraphsForDestruction(PrivatePlayerBodyResources* resources) noexcept
	{
		__try {
			auto* manager = resources->holder ? resources->holder->Manager() : nullptr;
			if (!manager) return true;
			if (manager == resources->sourceManager.get() || manager->graph.size() > 8) return false;

			for (const auto& graph : manager->graph) {
				if (graph && (graph.get() == resources->sourceGraph0 ||
					!PrepareCloneSubgraphsForDestruction(graph.get()))) return false;
			}
			return true;
		} __except (EXCEPTION_EXECUTE_HANDLER) { return false; }
	}

	void DestroyPrivatePlayerBodyResources(PrivatePlayerBodyResources* resources) noexcept
	{
		if (!resources) return;
		RetireCompletedPlayerPoses(resources);
		if (resources->subgraphOwnershipUncertain ||
			(resources->clothSimulation && resources->clothSimulation->Faulted()) || MirrorSceneRenderer::LoadBlocked()) {
			QuarantinePrivatePlayerBodyResources(resources);
			return;
		}
		const bool inheritedLease = g_playerGraphUpdatePoseLeaseHeld;
		if (!inheritedLease) {
			g_playerRetargetWaiters.fetch_add(1, std::memory_order_release);
			AcquireSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
			g_playerRetargetWaiters.fetch_sub(1, std::memory_order_acq_rel);
			g_playerGraphUpdatePoseLeaseHeld = true;
		}
		__try {
			if (!PreparePrivatePlayerGraphsForDestruction(resources))
				QuarantinePrivatePlayerBodyResources(resources);
			else
				DeletePrivatePlayerBodyResources(resources);
		} __finally {
			if (!inheritedLease) {
				g_playerGraphUpdatePoseLeaseHeld = false;
				ReleaseSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
			}
		}
	}

	void QuarantinePrivatePlayerBodyResources(PrivatePlayerBodyResources* resources) noexcept
	{
		if (!resources)
			return;
		RetireCompletedPlayerPoses(resources);

		if (g_privatePlayerBodyQuarantineCount < g_processLifetimePrivatePlayerBodyQuarantine.size())
			g_processLifetimePrivatePlayerBodyQuarantine[g_privatePlayerBodyQuarantineCount++] = resources;
		g_privatePlayerBodyQuarantineOwnedBytes += sizeof(PrivatePlayerBodyResources);
		logger::warn(
			"[ReflectionPlayerBody] retired graph quarantined: generations={}/{} knownOwnerBytes={} "
			"(native graph/texture allocations excluded); buildCapacity={}",
			g_privatePlayerBodyQuarantineCount, kPrivatePlayerBodyResourceBudget,
			g_privatePlayerBodyQuarantineOwnedBytes, g_privatePlayerBodyResourceBudget.Available());
		if (!g_privatePlayerBodyResourceBudget.Available())
			logger::error("[ReflectionPlayerBody] graph lifetime budget exhausted; fresh player captures suspended, last coherent images retained until game restart");
	}

	void TeardownPrivatePlayerBodyOnGameThread() noexcept
	{
		g_privatePlayerBodyTeardownRequested.store(false, std::memory_order_release);
		const bool loadTransitionQuarantine = MirrorSceneRenderer::LoadBlocked();
		
		g_subgraphMirrorArmed = false;
		g_subgraphMirrorResolved = false;
		g_subgraphMirrorRetryPending = false;
		g_subgraphMirrorDriveAttempts = 0;
		g_subgraphMirrorRetryCounter = 0;

		AcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		g_privatePlayerBody.status = PrivatePlayerBodyStatus::kEmpty;
		++g_privatePlayerBody.buildTicket;  
		g_privatePlayerBody.retryAfterMs = 0;
		g_privatePlayerBodyGeneration.fetch_add(1, std::memory_order_acq_rel);
		ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));

		g_playerRetargetWaiters.fetch_add(1, std::memory_order_release);
		AcquireSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
		g_playerRetargetWaiters.fetch_sub(1, std::memory_order_acq_rel);
		g_playerNaturalPoseSnapshot.valid = false;
		ReleaseSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));

		AcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		auto* retired = std::exchange(g_privatePlayerBody.resources, nullptr);
		ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		auto* materialOwner =
			g_materialAccumulatorQuarantinedPlayerResources.load(std::memory_order_acquire);
		const bool materialOwnershipQuarantine = retired && retired == materialOwner;
		const bool faultQuarantine =
			g_privatePlayerBodyFaultedThisSession.load(std::memory_order_acquire);
		if (loadTransitionQuarantine || materialOwnershipQuarantine || faultQuarantine ||
			(retired && retired->subgraphOwnershipUncertain)) {

			QuarantinePrivatePlayerBodyResources(retired);
			if (materialOwnershipQuarantine) {
				(void)g_materialAccumulatorQuarantinedPlayerResources.compare_exchange_strong(
					materialOwner, nullptr, std::memory_order_acq_rel, std::memory_order_acquire);
			}
		} else {
			DestroyPrivatePlayerBodyResources(retired);
		}

		g_privatePlayerBodyTeardownTaskQueued.store(false, std::memory_order_release);
		if (g_privatePlayerBodyTeardownRequested.load(std::memory_order_acquire))
			QueuePrivatePlayerBodyTeardown();
	}

	void RequestPrivatePlayerBodyTeardown(bool queueTask) noexcept
	{
		g_privatePlayerBodyTeardownRequested.store(true, std::memory_order_release);
		if (queueTask)
			QueuePrivatePlayerBodyTeardown();
	}

	void QueuePrivatePlayerBodyTeardown() noexcept
	{
		if (!g_privatePlayerBodyTeardownRequested.load(std::memory_order_acquire))
			return;
		bool expected = false;
		if (!g_privatePlayerBodyTeardownTaskQueued.compare_exchange_strong(
				expected, true, std::memory_order_acq_rel))
			return;
		auto* taskInterface = F4SE::GetTaskInterface();
		if (!taskInterface) {
			g_privatePlayerBodyTeardownTaskQueued.store(false, std::memory_order_release);
			return;
		}
		try {
			taskInterface->AddTask([]() { TeardownPrivatePlayerBodyOnGameThread(); });
		} catch (...) {
			g_privatePlayerBodyTeardownTaskQueued.store(false, std::memory_order_release);
		}
	}

	bool ReadPrivatePlayerBodySource(
		RE::PlayerCharacter*& player,
		RE::BSTSmartPointer<RE::BSAnimationGraphManager>& manager,
		RE::NiAVObject*& firstPersonRoot,
		RE::NiAVObject*& thirdPersonRoot,
		RE::BShkbAnimationGraph*& graph0) noexcept
	{
		player = RE::PlayerCharacter::GetSingleton();
		manager.reset();
		firstPersonRoot = nullptr;
		thirdPersonRoot = nullptr;
		graph0 = nullptr;
		if (!player || MirrorSceneRenderer::LoadBlocked())
			return false;
		if (!static_cast<const RE::IAnimationGraphManagerHolder*>(player)
				->GetAnimationGraphManagerImpl(manager) ||
			!manager || manager->graph.size() != 2)
			return false;
		firstPersonRoot = player->firstPerson3D.get();
		thirdPersonRoot = player->Get3D(false);
		graph0 = manager->graph[0].get();
		return firstPersonRoot && thirdPersonRoot && graph0;
	}

	bool ReadPrivatePlayerFaceRoots(
		const RE::PlayerCharacter* player,
		RE::NiAVObject*& faceRoot,
		RE::NiAVObject*& headRoot) noexcept
	{
		faceRoot = nullptr;
		headRoot = nullptr;
		if (!player || !player->currentProcess || !player->currentProcess->middleHigh)
			return false;
		faceRoot = reinterpret_cast<RE::NiAVObject*>(
			player->currentProcess->middleHigh->faceNodeSkinned);
		headRoot = player->currentProcess->middleHigh->headNode;

		return true;
	}

	bool PrivatePlayerNodeDescendsFromNoexcept(
		const RE::NiAVObject* object,
		const RE::NiAVObject* root) noexcept
	{
		if (!object || !root)
			return false;
		bool descends = false;
		__try {
			const RE::NiAVObject* cursor = object;
			for (std::uint32_t depth = 0; depth < kMaxPlayerDiagnosticAncestry; ++depth) {
				if (!PlausiblePlayerDiagnosticPointer(cursor))
					break;
				if (cursor == root) {
					descends = true;
					break;
				}
				cursor = cursor->parent;
				if (!cursor)
					break;
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			descends = false;
		}
		return descends;
	}

	void FinishPrivatePlayerBodyBuildFailure(std::uint64_t ticket, const char* reason) noexcept
	{
		std::uint32_t failures = 0;
		AcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		if (g_privatePlayerBody.buildTicket == ticket &&
			g_privatePlayerBody.status == PrivatePlayerBodyStatus::kBuildQueued) {
			g_privatePlayerBody.status = PrivatePlayerBodyStatus::kFailed;
			g_privatePlayerBody.retryAfterMs = GetTickCount64() + 2000u;
			failures = ++g_privatePlayerBody.failureCount;
		}
		ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		if (failures != 0 && (failures <= 8 || (failures % 30u) == 0u)) {
			logger::warn(
				"[ReflectionPlayerBody] private holderID-0 build failed: reason={} failures={} ticket={}",
				reason ? reason : "unknown", failures, ticket);
		}
	}

	bool HashFlattenedBoneTreeNameOrder(
		const void* tree,
		std::uint32_t count,
		std::uint64_t& hash) noexcept
	{
		if (!tree || count == 0 || count > kMaxPlayerNaturalPoseBones ||
			FlattenedBoneTreeEntryCount(tree) != count)
			return false;
		auto* treeBytes = reinterpret_cast<const std::byte*>(tree);
		auto* entries = *reinterpret_cast<const std::byte* const*>(treeBytes + 0x148);
		if (!entries || reinterpret_cast<std::uintptr_t>(entries) <= 0x10000)
			return false;

		hash = kPlayerDiagnosticFnvOffset;
		for (std::uint32_t index = 0; index < count; ++index) {
			HashPlayerDiagnosticBytes(std::addressof(hash), std::addressof(index), sizeof(index));
			auto* entry = entries + static_cast<std::uintptr_t>(index) * 0xA0u;
			auto* object = *reinterpret_cast<RE::NiAVObject* const*>(entry + 0x88);
			const std::uint8_t hasObject = object != nullptr ? 1u : 0u;
			HashPlayerDiagnosticBytes(std::addressof(hash), std::addressof(hasObject), sizeof(hasObject));
			if (!object)
				continue;
			if (!PlausiblePlayerDiagnosticPointer(object))
				return false;

			const char* name = object->name.c_str();
			if (!name)
				continue;
			const auto nameAddress = reinterpret_cast<std::uintptr_t>(name);
			if (nameAddress <= 0x10000 || nameAddress > 0x00007FFFFFFFFFFFULL)
				return false;
			std::size_t length = 0;
			while (length < 128 && name[length] != '\0')
				++length;
			if (length == 128)
				return false;
			HashPlayerDiagnosticBytes(std::addressof(hash), name, length);
			const std::uint8_t terminator = 0;
			HashPlayerDiagnosticBytes(std::addressof(hash), std::addressof(terminator), sizeof(terminator));
		}
		return hash != 0;
	}

	struct SubgraphMirrorOutcome
	{
		std::uint32_t liveCount;
		std::uint32_t liveActive;
		std::uint32_t mirrored;
		std::uint32_t duplicates;
		std::uint32_t failed;
		std::uintptr_t cloneAnchor;
		bool addVerified;
		bool containersValid;
		bool ownershipUncertain;
	};

	void DescribeSubgraphContainerUnsafe(const std::uint8_t* container, char* buffer, std::size_t capacity) noexcept
	{
		if (!buffer || capacity == 0)
			return;
		buffer[0] = '\0';
		auto plausiblePointer = [](const void* pointer) noexcept {
			const auto address = reinterpret_cast<std::uintptr_t>(pointer);
			return address > 0x10000 && address <= 0x00007FFFFFFFFFFFULL && (address & 7u) == 0;
		};
		if (!plausiblePointer(container)) {
			(void)std::snprintf(buffer, capacity, "container=implausible");
			return;
		}
		const std::uint32_t count = *reinterpret_cast<const std::uint32_t*>(container + kSubgraphContainerCountOffset);
		auto* entries = *reinterpret_cast<const std::uint8_t* const*>(container + kSubgraphContainerEntriesOffset);
		int written = std::snprintf(buffer, capacity, "count=%u", count);
		if (written < 0 || count == 0 || count > 64u || !plausiblePointer(entries))
			return;
		for (std::uint32_t index = 0; index < count && static_cast<std::size_t>(written) + 48u < capacity; ++index) {
			const auto* entry = entries + static_cast<std::size_t>(index) * kSubgraphEntryStride;
			const auto handle = *reinterpret_cast<const std::uint64_t*>(entry);
			const auto loaded = *reinterpret_cast<const std::uintptr_t*>(entry + kSubgraphEntryLoadedDataOffset);
			const auto refcount = *reinterpret_cast<const std::uint8_t*>(entry + kSubgraphEntryRefcountOffset);
			const int step = std::snprintf(buffer + written, capacity - static_cast<std::size_t>(written),
				" [h=%llx loaded=%d ref=%u]", static_cast<unsigned long long>(handle), loaded != 0 ? 1 : 0,
				static_cast<unsigned>(refcount));
			if (step < 0)
				break;
			written += step;
		}
	}

	void LockSubgraph(void* lock) { static_cast<RE::BSSpinLock*>(lock)->lock(); }
	void UnlockSubgraph(void* lock) { static_cast<RE::BSSpinLock*>(lock)->unlock(); }

	bool SubgraphOwnershipEngine(MirrorSubgraphOwnership::Engine& engine) noexcept
	{
		if (REL::Module::IsVR())
			return false; 
		const auto getRva = ReflectionRuntime::Rva(kRVA_SubBehavior_GetDataIfLoaded);
		const auto removeRva = ReflectionRuntime::Rva(kRVA_SubBehavior_RemoveSubGraph);
		const auto singletonRva = ReflectionRuntime::Rva(kRVA_SubBehaviorSingleton_InstancePtr);
		if (!getRva || !removeRva || !singletonRva)
			return false;
		const auto base = REL::Module::get().base();
		static const bool verified = [&] {
			return std::memcmp(reinterpret_cast<const void*>(base + getRva),
				ReflectionRuntime::Prologue(kRVA_SubBehavior_GetDataIfLoaded, kSubBehaviorGetPrologue).data(),
				kSubBehaviorGetPrologue.size()) == 0 &&
				std::memcmp(reinterpret_cast<const void*>(base + removeRva),
					ReflectionRuntime::Prologue(kRVA_SubBehavior_RemoveSubGraph, kSubBehaviorRemovePrologue).data(),
					kSubBehaviorRemovePrologue.size()) == 0 &&
				(ReflectionRuntime::IsPort240() || std::memcmp(
					reinterpret_cast<const void*>(base + kRVA_SubgraphContainer_Add),
					kSubgraphAddPrologue.data(), kSubgraphAddPrologue.size()) == 0);
		}();
		if (!verified)
			return false;
		engine = { *reinterpret_cast<void* const*>(base + singletonRva),
			reinterpret_cast<decltype(engine.getLoaded)>(base + getRva),
			reinterpret_cast<decltype(engine.remove)>(base + removeRva),
			ReflectionRuntime::IsPort240() ? &SubgraphContainerAdd240 :
				reinterpret_cast<decltype(engine.add)>(base + kRVA_SubgraphContainer_Add),
			&LockSubgraph, &UnlockSubgraph };
		return MirrorSubgraphOwnership::Plausible(engine.singleton);
	}

	bool MirrorLiveSubgraphContainerUnsafe(const std::uint8_t* liveGraph,
		std::uint8_t* cloneGraph, SubgraphMirrorOutcome* outcome) noexcept
	{
		using namespace MirrorSubgraphOwnership;
		if (!Plausible(liveGraph) || !Plausible(cloneGraph))
			return false;
		auto* liveContainer = *reinterpret_cast<std::uint8_t* const*>(liveGraph + kSubgraphContainerOffset);
		auto* cloneContainer = *reinterpret_cast<std::uint8_t* const*>(cloneGraph + kSubgraphContainerOffset);
		if (!Plausible(liveContainer) || !Plausible(cloneContainer))
			return false;
		outcome->containersValid = true;
		outcome->cloneAnchor = *reinterpret_cast<const std::uintptr_t*>(cloneContainer + kSubgraphContainerAnchorOffset);
		Engine engine{};
		outcome->addVerified = SubgraphOwnershipEngine(engine);
		if (!outcome->addVerified)
			return false;
		Snapshot snapshot{};
		const bool valid = ReadSnapshot(engine, liveContainer, snapshot);
		outcome->liveCount = snapshot.total;
		outcome->liveActive = snapshot.count;
		if (!valid || !snapshot.ready || !snapshot.count)
			return false; 
		for (std::uint32_t i = 0; i < snapshot.count; ++i) {
			const auto& entry = snapshot.entries[i];
			const auto receipt = MirrorEntry(engine, cloneContainer, entry);
			if (receipt.result == Result::kAdded)
				++outcome->mirrored;
			else if (receipt.result == Result::kDuplicate)
				++outcome->duplicates;
			else
				++outcome->failed;
			logger::info("[ReflectionPlayerBody] SUBGRAPHREF handle={:x} result={} use={}->{}",
				entry.handle, static_cast<unsigned>(receipt.result), receipt.before, receipt.after);
			if (receipt.result == Result::kUncertain) {
				outcome->ownershipUncertain = true;
				return false;
			}
		}
		return outcome->failed == 0 && outcome->mirrored + outcome->duplicates == snapshot.count;
	}

	bool MirrorLiveSubgraphContainer(
		const RE::BShkbAnimationGraph* liveGraph,
		RE::BShkbAnimationGraph* cloneGraph,
		SubgraphMirrorOutcome* outcome) noexcept
	{
		*outcome = {};
		bool mirrored = false;
		__try {
			mirrored = MirrorLiveSubgraphContainerUnsafe(
				reinterpret_cast<const std::uint8_t*>(liveGraph),
				reinterpret_cast<std::uint8_t*>(cloneGraph),
				outcome);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			outcome->ownershipUncertain = true;
			mirrored = false;
		}
		return mirrored;
	}

	bool CloneSubgraphEntriesResolvedUnsafe(const std::uint8_t* cloneGraph) noexcept
	{
		auto plausiblePointer = [](const void* pointer) noexcept {
			const auto address = reinterpret_cast<std::uintptr_t>(pointer);
			return address > 0x10000 && address <= 0x00007FFFFFFFFFFFULL && (address & 7u) == 0;
		};
		if (!plausiblePointer(cloneGraph))
			return false;
		auto* container = *reinterpret_cast<std::uint8_t* const*>(cloneGraph + kSubgraphContainerOffset);
		if (!plausiblePointer(container))
			return false;
		const std::uint32_t count = *reinterpret_cast<const std::uint32_t*>(
			container + kSubgraphContainerCountOffset);
		auto* entries = *reinterpret_cast<const std::uint8_t* const*>(
			container + kSubgraphContainerEntriesOffset);
		if (count == 0 || count > 64u || !plausiblePointer(entries))
			return false;
		for (std::uint32_t index = 0; index < count; ++index) {
			const auto* entry = entries + static_cast<std::size_t>(index) * kSubgraphEntryStride;
			if (*reinterpret_cast<const std::uint8_t*>(entry + kSubgraphEntryRefcountOffset) != 0 &&
				*reinterpret_cast<const std::uintptr_t*>(entry + kSubgraphEntryLoadedDataOffset) == 0)
				return false;
		}
		return true;
	}

	void PrepareCloneSubgraphsForDestructionLockedUnsafe(std::uint8_t* cloneGraph) noexcept
	{
		auto* container = *reinterpret_cast<std::uint8_t**>(cloneGraph + kSubgraphContainerOffset);
		if (!MirrorSubgraphOwnership::PrepareForDestruction(container))
			RaiseException(EXCEPTION_ACCESS_VIOLATION, 0, 0, nullptr);
	}

	void PrepareCloneSubgraphsForDestructionUnsafe(std::uint8_t* cloneGraph) noexcept
	{
		if (!MirrorSubgraphOwnership::Plausible(cloneGraph)) return;
		auto* container = *reinterpret_cast<std::uint8_t**>(cloneGraph + kSubgraphContainerOffset);
		if (!MirrorSubgraphOwnership::Plausible(container)) return;
		auto* lock = MirrorSubgraphOwnership::ContainerLock(container);
		if (!MirrorSubgraphOwnership::Plausible(lock))
			RaiseException(EXCEPTION_ACCESS_VIOLATION, 0, 0, nullptr);
		LockSubgraph(lock);
		__try { PrepareCloneSubgraphsForDestructionLockedUnsafe(cloneGraph); }
		__finally { UnlockSubgraph(lock); }
	}

	bool PrepareCloneSubgraphsForDestruction(void* cloneGraph) noexcept
	{
		__try {
			PrepareCloneSubgraphsForDestructionUnsafe(reinterpret_cast<std::uint8_t*>(cloneGraph));
			return true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			logger::warn("[ReflectionPlayerBody] SUBGRAPHMIRROR retirement validation failed; retaining this generation and its owned data");
			return false;
		}
	}

	bool ReadPrivateAnimationWordSEH(const RE::BShkbAnimationGraph* graph, const RE::BSFixedString& name,
		MirrorAnimationInputs::IndexCache& cache, std::uint32_t& value) noexcept
	{
		__try {
			const auto* interned = MirrorAnimationInputs::Read<const void*>(std::addressof(name), 0);
			return MirrorAnimationInputs::ReadWordUnsafe(graph, interned, cache, value);
		} __except (EXCEPTION_EXECUTE_HANDLER) { return false; }
	}

	void SynchronizePrivateAnimationInputsLeased(PrivatePlayerBodyResources* resources) noexcept
	{
		if (!resources || !resources->sourceManager || !resources->privateGraph) return;
		auto* manager = resources->sourceManager.get();
		const auto active = manager->activeGraph;
		if (manager->graph.size() != 2 || active > 1 || manager->graph[0].get() != resources->sourceGraph0) return;
		using SetInt = bool (*)(RE::BShkbAnimationGraph*, const RE::BSFixedString&, std::int32_t);
		using SetFloat = bool (*)(RE::BShkbAnimationGraph*, const RE::BSFixedString&, float);
		auto setInt = reinterpret_cast<SetInt>(REL::Offset(ReflectionRuntime::Rva(kRVA_BShkbAnimationGraph_SetVariableInt)).address());
		auto setFloat = reinterpret_cast<SetFloat>(REL::Offset(ReflectionRuntime::Rva(kRVA_BShkbAnimationGraph_SetVariableFloat)).address());
		static const auto names = [] {
			std::array<RE::BSFixedString, MirrorAnimationInputs::kInputs.size()> result{};
			for (std::size_t i = 0; i < result.size(); ++i) result[i] = MirrorAnimationInputs::kInputs[i].name;
			return result;
		}();
		for (std::size_t i = 0; i < names.size(); ++i) {
			std::uint32_t value = 0, previous = 0;

			if (MirrorAnimationInputs::kInputs[i].thirdPersonIntent) continue;
			const auto type = MirrorAnimationInputs::kInputs[i].type;
			if (!ReadPrivateAnimationWordSEH(manager->graph[active].get(), names[i], resources->animationInputIndices[active][i], value) ||
				!MirrorAnimationInputs::Valid(type, value) ||
				!ReadPrivateAnimationWordSEH(resources->privateGraph, names[i], resources->animationInputIndices[2][i], previous) || previous == value) continue;
			const bool written = type == MirrorAnimationInputs::Type::kInt ?
				setInt(resources->privateGraph, names[i], std::bit_cast<std::int32_t>(value)) :
				setFloat(resources->privateGraph, names[i], std::bit_cast<float>(value));
			if (written) ++resources->animationInputWrites;
		}
	}

	void LogPrivateAnimationStateLeased(PrivatePlayerBodyResources* resources) noexcept
	{
		const auto now = GetTickCount64();
		const auto perspective = resources->sourceManager->activeGraph;

		static unsigned relaxedSamples = 0;
		static ULONGLONG nextRelaxedSample = 0;
		if (perspective == 1 && resources->player && !resources->player->GetWeaponMagicDrawn() &&
			resources->sourceThirdPersonRoot && resources->cloneRoot && relaxedSamples < 240u && now >= nextRelaxedSample) {
			nextRelaxedSample = now + 250u;
			++relaxedSamples;
			std::array<float, 12> liveRotation{}, privateRotation{};
			static_assert(sizeof(RE::NiMatrix3) == sizeof(liveRotation));
			std::memcpy(liveRotation.data(), &resources->sourceThirdPersonRoot->world.rotate, sizeof(liveRotation));
			std::memcpy(privateRotation.data(), &resources->cloneRoot->world.rotate, sizeof(privateRotation));
			static const RE::BSFixedString directionName("Direction");
			static const RE::BSFixedString speedName("Speed");
			std::uint32_t direction{}, speed{};
			const bool directionValid = ReadPrivateAnimationWordSEH(resources->privateGraph, directionName,
				resources->animationStateIndices[7], direction);
			const bool speedValid = ReadPrivateAnimationWordSEH(resources->privateGraph, speedName,
				resources->animationStateIndices[0], speed);
			logger::info("[ReflectionPlayerBody] RELAXEDSTRAFE sample={} actorYaw={} liveXY={},{},{},{} privateXY={},{},{},{} direction={} speed={} valid={}/{}",
				relaxedSamples, resources->player->data.angle.z,
				liveRotation[0], liveRotation[1], liveRotation[4], liveRotation[5],
				privateRotation[0], privateRotation[1], privateRotation[4], privateRotation[5],
				std::bit_cast<float>(direction), std::bit_cast<float>(speed), directionValid, speedValid);
		}
		if (resources->animationStateLogs >= 90u ||
			(now < resources->animationStateLogAfterMs && perspective == resources->animationStatePerspective)) return;
		resources->animationStatePerspective = perspective;
		resources->animationStateLogAfterMs = now + (now - resources->weaponEventMs < 2000u ? 500u : 10000u);
		++resources->animationStateLogs;
		static const std::array<RE::BSFixedString, 12> names{
			RE::BSFixedString("Speed"), RE::BSFixedString("weaponSpeedMult"),
			RE::BSFixedString("bIsInMT"), RE::BSFixedString("RifleDrawnCurrentState"),
			RE::BSFixedString("IsAttackReady"), RE::BSFixedString("iSyncSightedState"), RE::BSFixedString("bAimActive"),
			RE::BSFixedString("Direction"), RE::BSFixedString("iLocomotionSpeedState"), RE::BSFixedString("iSyncRunDirection"),
			RE::BSFixedString("fLocomotionRunPlaybackSpeed"), RE::BSFixedString("fLocomotionWalkPlaybackSpeed")};
		std::array<std::uint32_t, 12> values{};
		std::uint32_t valid = 0;
		for (std::size_t i = 0; i < names.size(); ++i)
			if (ReadPrivateAnimationWordSEH(resources->privateGraph, names[i], resources->animationStateIndices[i], values[i])) valid |= 1u << i;
		std::array<std::uint64_t,2> weaponLocal{}, weaponWorld{};
		for (std::size_t i = 0; i < resources->cloneWeaponBones.size(); ++i) {
			if (const auto* bone = resources->cloneWeaponBones[i].get()) {
				weaponLocal[i] = weaponWorld[i] = kPlayerDiagnosticFnvOffset;
				HashPlayerSemanticTransform(&weaponLocal[i], &bone->local);
				HashPlayerSemanticTransform(&weaponWorld[i], &bone->world);
			}
		}
		logger::info("[ReflectionPlayerBody] ANIMSTATE active={} valid=0x{:X} speed={} weaponSpeed={} inMT={} rifleState={} attackReady={} sighted={} aimActive={} inputWrites={} generation={} privateEvalWeaponLocal={:X}/{:X} privateEvalWeaponWorld={:X}/{:X} direction={} gait={} runDirection={} runRate={} walkRate={}",
			resources->sourceManager->activeGraph, valid, std::bit_cast<float>(values[0]), std::bit_cast<float>(values[1]),
			values[2], values[3], values[4], values[5], values[6], resources->animationInputWrites, resources->stateGeneration,
			weaponLocal[0], weaponLocal[1], weaponWorld[0], weaponWorld[1], std::bit_cast<float>(values[7]), values[8], values[9],
			std::bit_cast<float>(values[10]), std::bit_cast<float>(values[11]));
	}

	void ReplayCloneWeaponState(RE::BSAnimationGraphManager* cloneManager, RE::BShkbAnimationGraph* cloneGraph) noexcept;
	bool ReplayCloneBootstrapEvent(RE::BSAnimationGraphManager* cloneManager, RE::BShkbAnimationGraph* cloneGraph) noexcept
	{

		if (!cloneManager)
			return false;
		using ProcessGraphEvent_t = std::uint32_t (*)(RE::BSAnimationGraphManager*, const RE::BSFixedString&);
		auto processGraphEvent = reinterpret_cast<ProcessGraphEvent_t>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_ProcessGraphEvent)).address());
		const RE::BSFixedString bootstrapEvent("g_archetypeBaseStateStartInstant");
		const bool accepted = processGraphEvent(cloneManager, bootstrapEvent) != 0;
		logger::info(
			"[ReflectionPlayerBody] SUBGRAPHMIRROR post-splice bootstrap accepted={}", accepted);
		if (accepted)
			ReplayCloneWeaponState(cloneManager, cloneGraph);
		return accepted;
	}

	int ReplayCloneWeaponStateSEH(RE::BSAnimationGraphManager* manager, RE::BShkbAnimationGraph* graph,
		std::uint32_t (*event)(RE::BSAnimationGraphManager*, const RE::BSFixedString&),
		bool (*variable)(RE::BShkbAnimationGraph*, const RE::BSFixedString&, std::int32_t),
		const RE::BSFixedString& sightedName, const RE::BSFixedString& instant,
		const RE::BSFixedString& fallback, bool sighted, int* results) noexcept
	{
		__try {
			results[0] = variable(graph, sightedName, sighted ? 1 : 0);
			results[1] = event(manager, instant) != 0;
			if (!results[1]) results[2] = event(manager, fallback) != 0;
			return 1;
		} __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
	}

	void ReplayCloneWeaponState(RE::BSAnimationGraphManager* manager, RE::BShkbAnimationGraph* graph) noexcept
	{
		static const bool disabled = [] {
			std::error_code error;
			return std::filesystem::exists(L"Data\\dynref_noweaponreplay", error);
		}();
		auto* player = RE::PlayerCharacter::GetSingleton();
		if (disabled || !manager || !graph || !player || !player->GetWeaponMagicDrawn()) return;
		using Event = std::uint32_t (*)(RE::BSAnimationGraphManager*, const RE::BSFixedString&);
		using Variable = bool (*)(RE::BShkbAnimationGraph*, const RE::BSFixedString&, std::int32_t);
		auto event = reinterpret_cast<Event>(REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_ProcessGraphEvent)).address());
		auto variable = reinterpret_cast<Variable>(REL::Offset(ReflectionRuntime::Rva(kRVA_BShkbAnimationGraph_SetVariableInt)).address());
		const RE::BSFixedString sightedName("iSyncSightedState"), instant("g_weapForceEquipInstant"), fallback("weapForceEquip");
		const bool sighted = player->gunState == RE::GUN_STATE::kSighted || player->gunState == RE::GUN_STATE::kFireSighted;
		int results[3]{};
		const int outcome = ReplayCloneWeaponStateSEH(manager, graph, event, variable, sightedName, instant, fallback, sighted, results);
		logger::info("[ReflectionPlayerBody] WEAPONSTATE bootstrap outcome={} sighted={} variable={} instant={} fallback={}",
			outcome, sighted, results[0], results[1], results[2]);
	}

	void ReconcileCloneWeaponState(PrivatePlayerBodyResources* resources) noexcept
	{
		auto* player = resources->player;
		if (!player || !resources->holder || !resources->privateGraph) return;
		const bool drawn = player->GetWeaponMagicDrawn();
		const bool sighted = drawn && (player->gunState == RE::GUN_STATE::kSighted || player->gunState == RE::GUN_STATE::kFireSighted);
		if (resources->weaponStateInitialized && GetTickCount64() - resources->weaponEventMs >= 250u) {
			using Event = std::uint32_t (*)(RE::BSAnimationGraphManager*, const RE::BSFixedString&);
			using Variable = bool (*)(RE::BShkbAnimationGraph*, const RE::BSFixedString&, std::int32_t);
			auto event = reinterpret_cast<Event>(REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_ProcessGraphEvent)).address());
			auto variable = reinterpret_cast<Variable>(REL::Offset(ReflectionRuntime::Rva(kRVA_BShkbAnimationGraph_SetVariableInt)).address());
			if (drawn != resources->weaponStateDrawn) {
				if (drawn) ReplayCloneWeaponState(resources->holder->Manager(), resources->privateGraph);
				else {
					const RE::BSFixedString name("Unequip");
					(void)event(resources->holder->Manager(), name);
				}
			}
			if (drawn && sighted != resources->weaponStateSighted) {
				const RE::BSFixedString variableName("iSyncSightedState");
				const RE::BSFixedString eventName(sighted ? "rifleSightedStart" : "rifleSightedEnd");
				const bool seeded = variable(resources->privateGraph, variableName, sighted ? 1 : 0);
				const bool accepted = event(resources->holder->Manager(), eventName) != 0;
				logger::info("[ReflectionPlayerBody] WEAPONSTATE reconcile sighted={} seeded={} accepted={}", sighted, seeded, accepted);
			}
		} else if (resources->weaponStateInitialized) return;
		resources->weaponStateInitialized = true;
		resources->weaponStateDrawn = drawn;
		resources->weaponStateSighted = sighted;
	}

	void ReconcileCloneWeaponPosture(PrivatePlayerBodyResources* resources) noexcept
	{
		if (!resources->player || !resources->holder || !resources->privateGraph || !resources->sourceManager)
			return;
		if (resources->sourceManager->activeGraph != 1 || !resources->player->GetWeaponMagicDrawn()) {
			resources->weaponPosture = 0;
			return;
		}
		const auto now = GetTickCount64();
		if (now < resources->weaponPostureCheckAfterMs) return;
		resources->weaponPostureCheckAfterMs = now + 100u;

		static const RE::BSFixedString gunDownName("iSyncGunDown");
		std::uint32_t gunDownBits = 0;
		if (!ReadPrivateAnimationWordSEH(resources->privateGraph, gunDownName,
				resources->weaponPostureGunDownIndex, gunDownBits))
			return;
		const bool lowered = gunDownBits != 0;
		const std::uint8_t wanted = lowered ? 1u : 2u;
		if (wanted == resources->weaponPosture) return;
		using Event = std::uint32_t (*)(RE::BSAnimationGraphManager*, const RE::BSFixedString&);
		auto event = reinterpret_cast<Event>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_ProcessGraphEvent)).address());
		const char* request = lowered ? "RelaxedStateStart" : "ReadyStateStart";
		const bool accepted = event(resources->holder->Manager(), RE::BSFixedString(request)) != 0;

		resources->weaponPosture = wanted;
		if (resources->weaponPostureLogs < 24u) {
			++resources->weaponPostureLogs;
			logger::info("[ReflectionPlayerBody] WEAPONPOSTURE firstPerson request={} accepted={} gunDown={}",
				request, accepted, lowered);
		}
	}

	bool SneakMoveSynthesisDisabled() noexcept
	{
		static const bool disabled = [] {
			std::error_code error;
			return std::filesystem::exists(L"Data\\dynref_nosneakmove", error);
		}();
		return disabled;
	}

	void ReconcileCloneSneakLocomotion(PrivatePlayerBodyResources* resources) noexcept
	{
		if (SneakMoveSynthesisDisabled() || !resources->player || !resources->holder || !resources->privateGraph ||
			!resources->sourceManager)
			return;
		const auto now = GetTickCount64();
		if (now < resources->sneakMoveCheckAfterMs) return;
		resources->sneakMoveCheckAfterMs = now + 100u;
		const bool firstPersonSneak = resources->sourceManager->activeGraph == 1 && resources->player->IsSneaking();
		if (!firstPersonSneak) return;
		static const RE::BSFixedString speedName("Speed");
		std::uint32_t speedBits = 0;
		if (!ReadPrivateAnimationWordSEH(resources->privateGraph, speedName, resources->sneakSpeedIndex, speedBits)) return;
		const float speed = std::bit_cast<float>(speedBits);
		if (!std::isfinite(speed)) return;
		const bool moving = speed > 1.0f;
		if (moving == resources->sneakMoveActive) return;
		using Event = std::uint32_t (*)(RE::BSAnimationGraphManager*, const RE::BSFixedString&);
		auto event = reinterpret_cast<Event>(REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_ProcessGraphEvent)).address());
		auto* manager = resources->holder->Manager();
		const char* sent = moving ? "MoveStart" : "MoveStop";
		bool accepted = event(manager, RE::BSFixedString(sent)) != 0;
		if (!accepted && moving) {
			sent = "moveStartAnimated";
			accepted = event(manager, RE::BSFixedString(sent)) != 0;
		}
		resources->sneakMoveActive = moving;
		if (resources->sneakMoveLogs < 40u) {
			++resources->sneakMoveLogs;
			logger::info("[ReflectionPlayerBody] SNEAKMOVE synthesized {} accepted={} speed={:.1f} (first-person sneak; 1P graph sends no move edges)",
				sent, accepted, speed);
		}
	}

	std::uint64_t g_subgraphRebuildAfterMs = 0;
	bool CloneSubgraphSetChanged(PrivatePlayerBodyResources* resources) noexcept
	{
		const auto now = GetTickCount64();
		if (now < resources->subgraphCheckAfterMs) return false;
		resources->subgraphCheckAfterMs = now + 250u;
		MirrorSubgraphOwnership::Engine engine{};
		if (!SubgraphOwnershipEngine(engine)) return false;
		MirrorSubgraphOwnership::Snapshot live{}, clone{};
		auto* liveContainer = *reinterpret_cast<std::uint8_t* const*>(reinterpret_cast<const std::uint8_t*>(resources->sourceGraph0) + kSubgraphContainerOffset);
		auto* cloneContainer = *reinterpret_cast<std::uint8_t* const*>(reinterpret_cast<const std::uint8_t*>(resources->privateGraph) + kSubgraphContainerOffset);
		if (!MirrorSubgraphOwnership::ReadSnapshot(engine, liveContainer, live) || !live.ready || !live.count ||
			!MirrorSubgraphOwnership::ReadSnapshot(engine, cloneContainer, clone)) return false;
		if (MirrorSubgraphOwnership::SameHandles(live, clone)) {
			resources->subgraphMismatchSinceMs = 0;
			return false;
		}
		if (!resources->subgraphMismatchSinceMs) resources->subgraphMismatchSinceMs = now;
		if (now - resources->subgraphMismatchSinceMs < 750u || now < g_subgraphRebuildAfterMs) return false;
		g_subgraphRebuildAfterMs = now + 5000u;
		logger::warn("[ReflectionPlayerBody] SUBGRAPHDIVERGE live={} clone={} stableForMs={}; rebuilding the owned private graph",
			live.count, clone.count, now - resources->subgraphMismatchSinceMs);
		return true;
	}

	bool DriveCloneSubgraphProcessing(RE::BSAnimationGraphManager* cloneManager,
		RE::BShkbAnimationGraph* cloneGraph, const RE::BShkbAnimationGraph* liveGraph) noexcept
	{
		if (!cloneManager || !cloneGraph)
			return false;

		if (!g_subgraphMirrorArmed) {
			if (!g_subgraphMirrorRetryPending || !liveGraph)
				return false;
			++g_subgraphMirrorRetryCounter;
			if ((g_subgraphMirrorRetryCounter % 120u) != 0u)
				return false;
			if (g_subgraphMirrorRetryCounter > 120u * 20u) {
				g_subgraphMirrorRetryPending = false;
				logger::warn(
					"[ReflectionPlayerBody] SUBGRAPHMIRROR retry budget exhausted; mirror stays off this build");
				return false;
			}
			SubgraphMirrorOutcome retryOutcome{};
			const bool mirrored = MirrorLiveSubgraphContainer(
				liveGraph, cloneGraph, std::addressof(retryOutcome));
			if (retryOutcome.ownershipUncertain) {
				if (g_privatePlayerBody.resources)
					g_privatePlayerBody.resources->subgraphOwnershipUncertain = true;
				g_subgraphMirrorRetryPending = false;
				g_privatePlayerBodyTeardownRequested.store(true, std::memory_order_release);
				return false;
			}
			logger::info(
				"[ReflectionPlayerBody] SUBGRAPHMIRROR retry #{}: live={}/{} mirrored={} duplicates={} failed={} armed={}",
				g_subgraphMirrorRetryCounter / 120u, retryOutcome.liveActive, retryOutcome.liveCount,
				retryOutcome.mirrored, retryOutcome.duplicates, retryOutcome.failed, mirrored);
			if (mirrored) {
				g_subgraphMirrorArmed = true;
				g_subgraphMirrorRetryPending = false;
				g_subgraphMirrorResolved = false;
				g_subgraphMirrorDriveAttempts = 0;
			}
			return false;
		}
		if (g_subgraphMirrorResolved)
			return true;
		if (g_subgraphMirrorDriveAttempts >= kMaxSubgraphDriveAttempts)
			return false;
		++g_subgraphMirrorDriveAttempts;
		auto* singleton = *reinterpret_cast<void* const*>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_SwapSingleton_InstancePtr)).address());
		if (!singleton)
			return false;
		using UpdateForManager_t = void (*)(void*, RE::BSAnimationGraphManager*);
		auto updateForManager = reinterpret_cast<UpdateForManager_t>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_SwapSingleton_UpdateForManager)).address());
		if (g_subgraphMirrorDriveAttempts == 1u) {

			logger::info("[ReflectionPlayerBody] SUBGRAPHMIRROR drive begin (UpdateForManager on clone manager)");
			spdlog::default_logger_raw()->flush();
		}
		bool resolved = false;
		__try {
			updateForManager(singleton, cloneManager);
			resolved = CloneSubgraphEntriesResolvedUnsafe(
				reinterpret_cast<const std::uint8_t*>(cloneGraph));
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			g_subgraphMirrorArmed = false;
			logger::error("[ReflectionPlayerBody] SUBGRAPHMIRROR drive faulted; mirror disabled for this build");
			return false;
		}
		if (resolved) {
			logger::info(
				"[ReflectionPlayerBody] SUBGRAPHMIRROR resolved after {} drive attempts: clone subgraphs are "
				"loaded and spliced (locomotion listeners installed)",
				g_subgraphMirrorDriveAttempts);

			g_subgraphMirrorResolved = ReplayCloneBootstrapEvent(cloneManager, cloneGraph);
		} else if (g_subgraphMirrorDriveAttempts == kSubgraphBootstrapStallAttempts ||
			g_subgraphMirrorDriveAttempts == kMaxSubgraphDriveAttempts) {
			char cloneDescription[512];
			DescribeSubgraphContainerUnsafe(
				*reinterpret_cast<std::uint8_t* const*>(
					reinterpret_cast<const std::uint8_t*>(cloneGraph) + kSubgraphContainerOffset),
				cloneDescription, sizeof(cloneDescription));
			logger::warn(
				"[ReflectionPlayerBody] SUBGRAPHMIRROR unresolved after {} attempts: entries appended but the "
				"processor never loaded them (check swap anchor / sub-behavior availability); clone {}",
				g_subgraphMirrorDriveAttempts, cloneDescription);
		}
		return g_subgraphMirrorResolved;
	}

	bool CloneSubgraphBootstrapStalled() noexcept
	{
		return g_subgraphMirrorArmed && !g_subgraphMirrorResolved &&
			g_subgraphMirrorDriveAttempts >= kSubgraphBootstrapStallAttempts;
	}

	bool StallRetireEnabled() noexcept
	{
		static const bool enabled = [] {
			std::error_code error;
			const bool present = std::filesystem::exists(L"Data\\dynref_stallretire", error);
			logger::info("[ReflectionPlayerBody] stalled-clone automatic retire: {}", present ? "ENABLED (Data\\dynref_stallretire)" : "off");
			return present;
		}();
		return enabled;
	}

	bool FlushPrivateLocomotionRequests(const RE::BSAnimationGraphManager* manager,
		const MirrorLocomotion::Requests& requests, MirrorLocomotion::Requests* previous)
	{
		if (!manager || manager->graph.size() != 1 || !manager->graph[0] || !previous || !requests.valid) return false;
		auto* graph = manager->graph[0].get();
		using SetInt = bool (*)(RE::BShkbAnimationGraph*, const RE::BSFixedString&, std::int32_t);
		using SetFloat = bool (*)(RE::BShkbAnimationGraph*, const RE::BSFixedString&, float);
		using Event = std::uint32_t (*)(RE::BSAnimationGraphManager*, const RE::BSFixedString&);
		auto setInt = reinterpret_cast<SetInt>(REL::Offset(ReflectionRuntime::Rva(kRVA_BShkbAnimationGraph_SetVariableInt)).address());
		auto setFloat = reinterpret_cast<SetFloat>(REL::Offset(ReflectionRuntime::Rva(kRVA_BShkbAnimationGraph_SetVariableFloat)).address());
		auto event = reinterpret_cast<Event>(REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_ProcessGraphEvent)).address());
		return requests.ApplyTo(*previous, [&](const MirrorLocomotion::Request& request, bool sameState) {
			const RE::BSFixedString name(request.name.data());
			bool applied = true;
			if (request.variable) {
				MirrorAnimationInputs::IndexCache cache{}; std::uint32_t current = 0;
				if (!ReadPrivateAnimationWordSEH(graph, name, cache, current) || current != request.value)
					applied = request.type == 0 ? setInt(graph, name, std::bit_cast<std::int32_t>(request.value)) :
						setFloat(graph, name, std::bit_cast<float>(request.value));
			} else applied = event(const_cast<RE::BSAnimationGraphManager*>(manager), name) != 0;
			static std::uint32_t logs = 0;
			if (!sameState && logs < 48u) {
				++logs;
				logger::info("[ReflectionPlayerBody] GAITREQUEST name={} variable={} type={} valueBits=0x{:X} accepted={}; private graph only",
					request.name.data(), request.variable, request.type, request.value, applied);
			}
			return applied;
		});
	}

	struct PrivateLocomotionEvaluation
	{
		const RE::BSAnimationGraphManager* manager;
		const MirrorLocomotion::Requests* requests;
		MirrorLocomotion::Requests* previous;
		static bool Flush(void* data) {
			const auto& state=*static_cast<PrivateLocomotionEvaluation*>(data);
			return FlushPrivateLocomotionRequests(state.manager,*state.requests,state.previous);
		}
	};

	bool SafePrivateGraphUpdate(
		PrivateGraphUpdate_t update,
		const RE::IAnimationGraphManagerHolder* holder,
		const RE::BSAnimationGraphManager* manager,
		const RE::BShkbAnimationGraph* sourceGraph,
		MirrorLocomotion::Requests* previousRequests,
		void* data) noexcept
	{
		if (!update || !holder || !data)
			return false;
		const auto previousTarget = MirrorAnimationTarget::current;
		MirrorAnimationTarget::current = {
			manager && manager->graph.size() == 1u ? manager->graph[0].get() : nullptr,
			sourceGraph, RE::PlayerCharacter::GetSingleton() };
		MirrorLocomotion::Requests requests{};
		const auto previous = MirrorLocomotion::Begin(
			static_cast<const RE::IAnimationGraphManagerHolder*>(RE::PlayerCharacter::GetSingleton()),
			holder, g_privateLocomotionHooksInstalled ? manager : nullptr, &requests, previousRequests);
		PrivateLocomotionEvaluation evaluation{manager,&requests,previousRequests};
		MirrorAnimationEvaluation::Callback callback;
		callback.state=&evaluation;callback.flush=PrivateLocomotionEvaluation::Flush;
		void* savedCallback=MirrorAnimationEvaluation::Install(data,callback);
		__try {
			__try {
				const bool updated = update(holder, data);

				return updated && callback.called && callback.accepted;
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				logger::error(
					"[ReflectionPlayerBody] private clone update faulted; retiring this graph and scheduling bounded recovery after cooldown; last coherent mirror publication retained");
				g_subgraphMirrorArmed = false;
				g_subgraphMirrorResolved = false;
				g_privatePlayerBodyFaultedThisSession.store(true, std::memory_order_release);
				g_privatePlayerBodyFaultCount.fetch_add(1u, std::memory_order_acq_rel);
				g_privatePlayerBodyFaultRetryAfterMs.store(
					GetTickCount64() + kPrivatePlayerBodyFaultCooldownMs, std::memory_order_release);
				return false;
			}
		} __finally {
			MirrorAnimationEvaluation::Restore(data,savedCallback);
			MirrorLocomotion::Restore(previous);
			MirrorAnimationTarget::current = previousTarget;
		}
	}

	struct PrivateGraphGateSample
	{
		const void* graph;
		const void* field240;
		const void* field240_20;
		const void* field378;
		std::uint32_t flag378_1AA;
		std::uint32_t byte3C8;
		std::uint32_t byte3C9;
		std::uint32_t word3C0;
		std::uint32_t word3C5;
		float timer350;
		float timer354;

		const void* subgraphContainer;  
		std::uint32_t subgraphCount;    
		std::uint32_t subgraphFlags[4]; 
		bool read;
	};

	void SamplePrivateGraphGates(
		const RE::BShkbAnimationGraph* graph,
		PrivateGraphGateSample* out) noexcept
	{
		if (!out)
			return;
		*out = {};
		const auto address = reinterpret_cast<std::uintptr_t>(graph);
		if (address <= 0x10000 || address > 0x00007FFFFFFFFFFFULL || (address & 7u) != 0)
			return;
		out->graph = graph;
		__try {
			const auto* bytes = reinterpret_cast<const std::uint8_t*>(graph);
			auto plausible = [](const void* pointer) noexcept {
				const auto value = reinterpret_cast<std::uintptr_t>(pointer);
				return value > 0x10000 && value <= 0x00007FFFFFFFFFFFULL && (value & 7u) == 0;
			};
			out->field240 = *reinterpret_cast<void* const*>(bytes + 0x240);
			if (plausible(out->field240)) {
				out->field240_20 = *reinterpret_cast<void* const*>(
					reinterpret_cast<const std::uint8_t*>(out->field240) + 0x20);
			}
			out->field378 = *reinterpret_cast<void* const*>(bytes + 0x378);
			out->flag378_1AA = plausible(out->field378) ?
				*(reinterpret_cast<const std::uint8_t*>(out->field378) + 0x1AA) : 0xFFu;
			out->byte3C8 = bytes[0x3C8];
			out->byte3C9 = bytes[0x3C9];
			out->word3C0 = *reinterpret_cast<const std::uint16_t*>(bytes + 0x3C0);
			out->word3C5 = *reinterpret_cast<const std::uint16_t*>(bytes + 0x3C5);
			out->timer350 = *reinterpret_cast<const float*>(bytes + 0x350);
			out->timer354 = *reinterpret_cast<const float*>(bytes + 0x354);
			out->subgraphFlags[0] = out->subgraphFlags[1] =
				out->subgraphFlags[2] = out->subgraphFlags[3] = 0xFFFFFFFFu;
			out->subgraphContainer = *reinterpret_cast<void* const*>(bytes + 0x3A0);
			if (plausible(out->subgraphContainer)) {
				const auto* container =
					reinterpret_cast<const std::uint8_t*>(out->subgraphContainer);
				out->subgraphCount = *reinterpret_cast<const std::uint32_t*>(container + 0x10);
				const auto* entries = *reinterpret_cast<const std::uint8_t* const*>(container);
				if (entries && out->subgraphCount != 0 && out->subgraphCount <= 64u) {
					const auto sampleCount = (std::min)(out->subgraphCount, 4u);
					for (std::uint32_t entry = 0; entry < sampleCount; ++entry) {
						const auto* record = entries + static_cast<std::size_t>(entry) * 0x48u;
						out->subgraphFlags[entry] =
							static_cast<std::uint32_t>(record[0x40]) |
							(static_cast<std::uint32_t>(record[0x41]) << 8);
					}
				}
			}
			out->read = true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			out->read = false;
		}
	}

	void LogPrivateGraphGates(
		const char* stage,
		const RE::BShkbAnimationGraph* privateGraph,
		const RE::BShkbAnimationGraph* sourceGraph,
		const RE::BSAnimationGraphManager* privateManager,
		const RE::BSAnimationGraphManager* sourceManager) noexcept
	{
		PrivateGraphGateSample privateSample{};
		PrivateGraphGateSample sourceSample{};
		SamplePrivateGraphGates(privateGraph, std::addressof(privateSample));
		SamplePrivateGraphGates(sourceGraph, std::addressof(sourceSample));

		std::uint32_t privateActive = 0xFFFFFFFFu;
		std::uint32_t privateGraphs = 0xFFFFFFFFu;
		std::uint32_t sourceActive = 0xFFFFFFFFu;
		std::uint32_t sourceGraphs = 0xFFFFFFFFu;
		__try {
			if (privateManager) {
				privateActive = privateManager->activeGraph;
				privateGraphs = static_cast<std::uint32_t>(privateManager->graph.size());
			}
			if (sourceManager) {
				sourceActive = sourceManager->activeGraph;
				sourceGraphs = static_cast<std::uint32_t>(sourceManager->graph.size());
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
		}
		logger::info(
			"[ReflectionPlayerBody] GRAPHGATE {} private: read={} graph={} activeGraph={} graphs={} f240={} "
			"f240_20={} f378={} f378_1AA={} b3C8={} b3C9={} w3C0={} w3C5={} timers=({:.4f}/{:.4f}) "
			"subgraphs={} count={} flags=[{:04X},{:04X},{:04X},{:04X}]",
			stage, privateSample.read, privateSample.graph, privateActive, privateGraphs,
			privateSample.field240, privateSample.field240_20,
			privateSample.field378, privateSample.flag378_1AA, privateSample.byte3C8, privateSample.byte3C9,
			privateSample.word3C0, privateSample.word3C5, privateSample.timer350, privateSample.timer354,
			privateSample.subgraphContainer, privateSample.subgraphCount,
			privateSample.subgraphFlags[0], privateSample.subgraphFlags[1],
			privateSample.subgraphFlags[2], privateSample.subgraphFlags[3]);
		logger::info(
			"[ReflectionPlayerBody] GRAPHGATE {} source0: read={} graph={} activeGraph={} graphs={} f240={} "
			"f240_20={} f378={} f378_1AA={} b3C8={} b3C9={} w3C0={} w3C5={} timers=({:.4f}/{:.4f}) "
			"subgraphs={} count={} flags=[{:04X},{:04X},{:04X},{:04X}]",
			stage, sourceSample.read, sourceSample.graph, sourceActive, sourceGraphs,
			sourceSample.field240, sourceSample.field240_20,
			sourceSample.field378, sourceSample.flag378_1AA, sourceSample.byte3C8, sourceSample.byte3C9,
			sourceSample.word3C0, sourceSample.word3C5, sourceSample.timer350, sourceSample.timer354,
			sourceSample.subgraphContainer, sourceSample.subgraphCount,
			sourceSample.subgraphFlags[0], sourceSample.subgraphFlags[1],
			sourceSample.subgraphFlags[2], sourceSample.subgraphFlags[3]);
	}

	bool ReadLiveFaceGenSnapshotNoexcept(const void* animation, MirrorFaceGenSnapshot* snapshot) noexcept
	{
		if (!animation || !snapshot)
			return false;
		auto* lock = reinterpret_cast<RE::BSSpinLock*>(
			reinterpret_cast<std::uintptr_t>(animation) + 0x2B4u);
		bool acquired = false;
		bool read = false;
		__try {
			__try {
				lock->lock();
				acquired = true;
				read = snapshot->Read(animation);
			} __finally {
				if (acquired)
					lock->unlock();
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			read = false;
		}
		return read;
	}

	bool SynchronizePrivatePlayerFaceNoexcept(PrivatePlayerBodyResources* resources) noexcept
	{
		if (resources && !resources->sourceFaceRoot && !resources->cloneFaceRoot)
			return true;
		const auto* recovery = ReflectionRuntime::Recovery();
		if (!recovery || !recovery->faceAnimationCtor)
			return false;
		if (!resources || !resources->sourceFaceRoot || !resources->cloneFaceRoot ||
			!resources->privateFaceAnimation)
			return false;
		__try {
			const auto* source = reinterpret_cast<const std::byte*>(resources->sourceFaceRoot.get());
			auto* clone = reinterpret_cast<std::byte*>(resources->cloneFaceRoot.get());
			const auto* liveAnimation = *reinterpret_cast<const void* const*>(source + 0x170);
			auto* privateAnimation = resources->privateFaceAnimation.get();
			if (!liveAnimation || liveAnimation == privateAnimation ||
				*reinterpret_cast<const void* const*>(clone + 0x170) != privateAnimation ||
				*reinterpret_cast<const std::uintptr_t*>(liveAnimation) !=
					REL::Offset(recovery->faceAnimationVtable).address())
				return false;
			MirrorFaceGenSnapshot snapshot;
			if (!ReadLiveFaceGenSnapshotNoexcept(liveAnimation, std::addressof(snapshot)))
				return false;
			snapshot.Apply(privateAnimation, *reinterpret_cast<std::uint16_t*>(clone + 0x17C));
			return true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return false;
		}
	}

	bool IsolatePrivatePlayerFaceAnimation(PrivatePlayerBodyResources* resources)
	{
		if (resources && !resources->sourceFaceRoot && !resources->cloneFaceRoot)
			return true;
		const auto* recovery = ReflectionRuntime::Recovery();
		if (!recovery || !recovery->faceAnimationCtor)
			return false;
		const auto constructor = REL::Offset(recovery->faceAnimationCtor).address();
		const auto& expected = recovery->faceAnimationCtorEntry;
		if (!resources || !resources->cloneFaceRoot || !resources->sourceFaceRoot ||
			constructor <= 0x10000u || std::memcmp(reinterpret_cast<const void*>(constructor),
				expected.data(), expected.size()) != 0)
			return false;
		auto* clone = reinterpret_cast<std::byte*>(resources->cloneFaceRoot.get());
		const auto faceVtable = REL::Offset(recovery->faceNodeVtable).address();
		if (*reinterpret_cast<const std::uintptr_t*>(clone) != faceVtable ||
			*reinterpret_cast<const std::uintptr_t*>(resources->sourceFaceRoot.get()) != faceVtable)
			return false;
		auto* storage = RE::malloc(0x2E8u);
		if (!storage)
			return false;
		using Constructor = RE::NiObject* (*)(void*);
		auto* animation = reinterpret_cast<Constructor>(constructor)(storage);
		resources->privateFaceAnimation.reset(animation);

		auto* animationSlot = reinterpret_cast<RE::NiPointer<RE::NiObject>*>(clone + 0x170);
		animationSlot->reset(animation);
		const bool synchronized = SynchronizePrivatePlayerFaceNoexcept(resources);
		logger::info("[ReflectionPlayerBody] detached FaceGen animation isolated: liveFace={} cloneFace={} privateAnimation={} synchronized={}; live blink/dialogue driver remains sole writer",
			static_cast<void*>(resources->sourceFaceRoot.get()), static_cast<void*>(resources->cloneFaceRoot.get()),
			static_cast<void*>(animation), synchronized);
		return synchronized;
	}

	RE::NiObject* ClonePlayerVisualTree(RE::NiAVObject* source, RE::NiCloningProcess* process)
	{
		try {
			std::size_t detached = 0;
			auto* clone = MirrorCloneControllers::WithoutControllers(*source,
				[](RE::NiAVObject& object, auto&& enqueue) {
					if (auto* node = object.IsNode()) {
						for (const auto& child : node->GetRuntimeData().children) enqueue(child.get());
					}
				},
				[source, process] {
					auto* result = static_cast<RE::NiAVObject*>(NiVirtualDispatch::CreateClone(source, *process));
					if (result) NiVirtualDispatch::ProcessClone(source, *process);
					return result;
				}, &detached);
			static std::atomic<std::uint32_t> samples{ 0 };
			if (samples.fetch_add(1, std::memory_order_relaxed) < 6u)
				logger::info("[ReflectionPlayerBody] visual clone: {} live controller chains excluded and restored; private behavior created separately", detached);
			return clone;
		} catch (const std::exception& error) {
			logger::warn("[ReflectionPlayerBody] visual clone preparation/creation failed: {}", error.what());
			return nullptr;
		}
	}

	RE::NiObject* ClonePlayerVisualTreeLeased(RE::NiAVObject* source, RE::NiCloningProcess* process)
	{

		AcquireSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
		__try { return ClonePlayerVisualTree(source, process); }
		__finally { ReleaseSRWLockExclusive(std::addressof(g_playerNaturalPoseLock)); }
	}

	void HidePrivateCloneForeignRigs(RE::NiAVObject* cloneRoot, RE::NiAVObject* faceRoot,
		RE::NiAVObject* headRoot) noexcept
	{
		try {
			const auto branches = MirrorForeignRig::Branches<RE::NiAVObject>(cloneRoot, faceRoot, headRoot,
				[](RE::NiAVObject* node, auto&& visit) {
					if (auto* asNode = node->IsNode()) {
						for (const auto& child : asNode->GetRuntimeData().children)
							visit(child.get());
					}
				},
				[](RE::NiAVObject* node) -> RE::NiAVObject* { return node->parent; },
				[](RE::NiAVObject* node) {
					const char* name = node->name.c_str();
					return name && _stricmp(name, "TFP_ShadowTwin") == 0;
				});
			for (auto* branch : branches) {
				if (branch->GetAppCulled())
					continue;
				NiVirtualDispatch::SetAppCulled(branch, true);
				static std::atomic<std::uint32_t> s_hiddenRigLogs{ 0 };
				if (s_hiddenRigLogs.fetch_add(1, std::memory_order_relaxed) < 16u) {
					const char* name = branch->name.c_str();
					logger::info(
						"[ReflectionPlayerBody] foreign rig hidden in the private clone: branch='{}' "
						"(True First Person's explicitly tagged shadow twin)",
						name ? name : "");
				}
			}
		} catch (...) {
		}
	}

#include "FlatMirrorClothPose.inl"
#include "FlatMirrorCompletedPoseBuild.inl"

	void BuildPrivatePlayerBodyOnGameThread(std::uint64_t ticket) noexcept
	{
		if (!g_privatePlayerBodyDemand.Needed(GetTickCount64())) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "no-visible-mirror-demand");
			return;
		}
		auto reservation = g_privatePlayerBodyResourceBudget.Acquire();
		if (!reservation) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "graph-lifetime-budget-exhausted");
			return;
		}
		if (MirrorSceneRenderer::LoadBlocked()) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "load-blocked");
			return;
		}

		RE::PlayerCharacter* player = nullptr;
		RE::BSTSmartPointer<RE::BSAnimationGraphManager> sourceManager;
		RE::NiAVObject* firstPersonRoot = nullptr;
		RE::NiAVObject* thirdPersonRoot = nullptr;
		RE::BShkbAnimationGraph* sourceGraph0 = nullptr;
		if (!ReadPrivatePlayerBodySource(
				player, sourceManager, firstPersonRoot, thirdPersonRoot, sourceGraph0)) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "source-unavailable");
			return;
		}
		const auto generation = MirrorSceneRenderer::LoadGeneration();

		std::unique_ptr<PrivatePlayerBodyResources, decltype(&DestroyPrivatePlayerBodyResources)>
			candidate(nullptr, &DestroyPrivatePlayerBodyResources);
		try {
			candidate.reset(new PrivatePlayerBodyResources());
			candidate->retirementLease = std::move(reservation);
			candidate->holder = std::make_unique<PrivatePlayerAnimationHolder>(player);
		} catch (...) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "private-resource-allocation");
			return;
		}
		candidate->player = player;
		candidate->loadGeneration = generation;
		candidate->sourceManager = sourceManager;
		candidate->sourceGraph0 = sourceGraph0;
		g_privateSourceGraph0.store(sourceGraph0, std::memory_order_release);
		candidate->sourceFirstPersonRoot.reset(firstPersonRoot);
		candidate->sourceThirdPersonRoot.reset(thirdPersonRoot);
		RE::NiAVObject* sourceFaceRoot = nullptr;
		RE::NiAVObject* sourceHeadRoot = nullptr;
		if (!ReadPrivatePlayerFaceRoots(player, sourceFaceRoot, sourceHeadRoot)) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "face-head-unavailable");
			return;
		}
		candidate->sourceFaceRoot.reset(sourceFaceRoot);
		candidate->sourceHeadRoot.reset(sourceHeadRoot);

		RE::NiObject* clonedObject = nullptr;
		RE::NiAVObject* cloneFaceRoot = nullptr;
		RE::NiAVObject* cloneHeadRoot = nullptr;
		std::uint32_t sourceGeometryCount = 0;
		std::uint32_t cloneGeometryCount = 0;
		{
			RE::NiCloningProcess cloningProcess{};
			cloningProcess.copyType = RE::NiCloningProcess::CopyType::kCopyUnique;
			cloningProcess.scale = RE::NiPoint3{ 1.0F, 1.0F, 1.0F };
			clonedObject = ClonePlayerVisualTreeLeased(thirdPersonRoot, std::addressof(cloningProcess));
			if (clonedObject) BuildMirrorClothPose(candidate.get(), cloningProcess);
			if (const auto faceIt = cloningProcess.cloneMap.find(sourceFaceRoot);
				faceIt != cloningProcess.cloneMap.end()) {
				cloneFaceRoot = netimmerse_cast<RE::NiAVObject*>(faceIt->second);
			}
			if (const auto headIt = cloningProcess.cloneMap.find(sourceHeadRoot);
				headIt != cloningProcess.cloneMap.end()) {
				cloneHeadRoot = netimmerse_cast<RE::NiAVObject*>(headIt->second);
			}

			for (const auto& cloneEntry : cloningProcess.cloneMap) {
				if (!netimmerse_cast<RE::BSGeometry*>(cloneEntry.first))
					continue;
				++sourceGeometryCount;
				if (netimmerse_cast<RE::BSGeometry*>(cloneEntry.second))
					++cloneGeometryCount;
			}

			std::uint32_t hiddenSourceGeometry = 0;
			std::uint32_t hiddenGoreCaps = 0;
			for (const auto& cloneEntry : cloningProcess.cloneMap) {
				auto* sourceGeometry = netimmerse_cast<RE::BSGeometry*>(cloneEntry.first);
				auto* clonedGeometry = netimmerse_cast<RE::BSGeometry*>(cloneEntry.second);
				if (!sourceGeometry || !clonedGeometry)
					continue;
				if (PrivatePlayerSourceGeometryAppCulled(sourceGeometry)) {
					NiVirtualDispatch::SetAppCulled(clonedGeometry, true);
					++hiddenSourceGeometry;
					continue;
				}
				if (PrivatePlayerGeometryIsDismembermentCap(sourceGeometry)) {
					NiVirtualDispatch::SetAppCulled(clonedGeometry, true);
					++hiddenGoreCaps;
				}
			}
			if (hiddenSourceGeometry != 0 || hiddenGoreCaps != 0) {
				static std::uint32_t s_hiddenGeometryLogs = 0;
				if (s_hiddenGeometryLogs++ < 4u)
					logger::info(
						"[ReflectionPlayerBody] private clone visibility carried over: hiddenSourceGeometry={} goreCaps={} of {} geometries",
						hiddenSourceGeometry, hiddenGoreCaps, cloneGeometryCount);
			}
			if (clonedObject && !RemoveInitialPrivatePlayerTransientArt(thirdPersonRoot,
				static_cast<RE::NiAVObject*>(clonedObject), cloningProcess)) {
				candidate->cloneRoot.reset(static_cast<RE::NiAVObject*>(clonedObject));
				FinishPrivatePlayerBodyBuildFailure(ticket, "transient-attachment-detach-failed");
				return;
			}
		}
		if (!clonedObject) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "CreateClone-null");
			return;
		}
		auto* cloneRoot = static_cast<RE::NiAVObject*>(clonedObject);

		NiVirtualDispatch::SetAppCulled(cloneRoot, false);
		candidate->cloneRoot.reset(cloneRoot);
		candidate->cloneFaceRoot.reset(cloneFaceRoot);
		candidate->cloneHeadRoot.reset(cloneHeadRoot);
		if (bool(sourceFaceRoot) != bool(cloneFaceRoot) || bool(sourceHeadRoot) != bool(cloneHeadRoot) || sourceGeometryCount == 0 ||
			cloneGeometryCount != sourceGeometryCount ||
			(cloneFaceRoot && !PrivatePlayerNodeDescendsFromNoexcept(cloneFaceRoot, cloneRoot)) ||
			(cloneHeadRoot && !PrivatePlayerNodeDescendsFromNoexcept(cloneHeadRoot, cloneRoot))) {
			logger::warn(
				"[ReflectionPlayerBody] detached clone rejected: sourceGeometry={} cloneGeometry={} "
				"faceMapped={} headMapped={} faceDescends={} headDescends={}",
				sourceGeometryCount, cloneGeometryCount, cloneFaceRoot != nullptr, cloneHeadRoot != nullptr,
				PrivatePlayerNodeDescendsFromNoexcept(cloneFaceRoot, cloneRoot),
				PrivatePlayerNodeDescendsFromNoexcept(cloneHeadRoot, cloneRoot));
			FinishPrivatePlayerBodyBuildFailure(ticket, "clone-render-subtree-incomplete");
			return;
		}
		HidePrivateCloneForeignRigs(cloneRoot, cloneFaceRoot, cloneHeadRoot);
		PrivatePlayerGeometryMaterialCensus sourceMaterialCensus{};
		PrivatePlayerGeometryMaterialCensus cloneMaterialCensus{};
		if (!IsolatePrivatePlayerFaceAnimation(candidate.get())) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "face-animation-isolation-unavailable");
			return;
		}
		const bool sourceMaterialReady = ReadPrivatePlayerGeometryMaterialCensus(
			thirdPersonRoot, sourceFaceRoot, sourceHeadRoot,
			std::addressof(sourceMaterialCensus));
		const bool cloneMaterialReady = ReadPrivatePlayerGeometryMaterialCensus(
			cloneRoot, cloneFaceRoot, cloneHeadRoot, std::addressof(cloneMaterialCensus), candidate.get());
		const bool materialIdentityReady = sourceMaterialReady && cloneMaterialReady &&
			PrivatePlayerMaterialCensusMatchesCloneMap(
				sourceMaterialCensus, cloneMaterialCensus, sourceGeometryCount, cloneGeometryCount);
		if (!materialIdentityReady) {
			logger::warn(
				"[ReflectionPlayerBody] detached clone material census rejected: "
				"source(count/material/face/eye/hash)={}/{}/{}/{}/0x{:X} "
				"clone={}/{}/{}/{}/0x{:X} map={}/{} truncated={}/{}",
				sourceMaterialCensus.geometryCount, sourceMaterialCensus.materialGeometryCount,
				sourceMaterialCensus.faceMaterialGeometryCount,
				sourceMaterialCensus.authoredEyeGeometryCount,
				sourceMaterialCensus.semanticHash, cloneMaterialCensus.geometryCount,
				cloneMaterialCensus.materialGeometryCount,
				cloneMaterialCensus.faceMaterialGeometryCount,
				cloneMaterialCensus.authoredEyeGeometryCount,
				cloneMaterialCensus.semanticHash, sourceGeometryCount, cloneGeometryCount,
				sourceMaterialCensus.truncated, cloneMaterialCensus.truncated);

			static bool s_faceInventoryLogged = false;
			if (!s_faceInventoryLogged && !sourceMaterialCensus.complete) {
				s_faceInventoryLogged = true;
				static thread_local std::array<PrivatePlayerGeometrySample, kMaxPrivatePlayerGeometrySamples> faceSamples{};
				std::uint32_t visited = 0;
				bool truncatedInventory = false;
				const auto inventoryCount = CollectPrivatePlayerGeometryInventory(
					thirdPersonRoot, sourceFaceRoot, sourceHeadRoot, faceSamples.data(),
					static_cast<std::uint32_t>(faceSamples.size()), std::addressof(visited),
					std::addressof(truncatedInventory));
				logger::warn(
					"[ReflectionPlayerBody] FACEINVENTORY source census incomplete: geometries={} visited={} truncated={} material={} face={} faceMaterial={} eye={} nonFaceMaterial={}",
					inventoryCount, visited, truncatedInventory, sourceMaterialCensus.materialGeometryCount,
					sourceMaterialCensus.faceGeometryCount, sourceMaterialCensus.faceMaterialGeometryCount,
					sourceMaterialCensus.authoredEyeGeometryCount, sourceMaterialCensus.nonFaceMaterialGeometryCount);
				std::uint32_t logged = 0;
				for (std::uint32_t index = 0; index < inventoryCount && logged < 24u; ++index) {
					const auto& sample = faceSamples[index];
					++logged;
					logger::warn(
						"[ReflectionPlayerBody] FACEINVENTORY [{}] name='{}' texture='{}' underFace={} underHead={} material={} feature={} culled={} eyeMatch={}",
						index, sample.name, sample.texturePath, sample.underFace, sample.underHead,
						sample.material != nullptr, sample.feature, sample.appCulled,
						sample.material && IsHumanEyeBaseTexturePath(sample.texturePath));
				}
			}
			FinishPrivatePlayerBodyBuildFailure(ticket, "clone-material-identity-incomplete");
			return;
		}
		
		candidate->sourceGeometryCount = sourceMaterialCensus.geometryCount;
		candidate->cloneGeometryCount = cloneMaterialCensus.geometryCount;
		candidate->geometryMaterialHash = cloneMaterialCensus.semanticHash;
		candidate->drawRequirements = cloneMaterialCensus.drawRequirements;
		{
			static thread_local PrivatePlayerGeometrySample headSamples[kMaxPrivatePlayerGeometrySamples]{};
			bool truncated = false;
			const auto count = CollectPrivatePlayerGeometryInventory(cloneRoot, cloneFaceRoot, cloneHeadRoot,
				headSamples, kMaxPrivatePlayerGeometrySamples, nullptr, &truncated);
			if (truncated) {
				FinishPrivatePlayerBodyBuildFailure(ticket, "pane-clearance-census");
				return;
			}
			for (std::uint32_t i = 0; i < count; ++i) {
				const auto& sample = headSamples[i];

				if (candidate->paneClearanceGeometryCount >= candidate->paneClearanceGeometry.size()) {
					FinishPrivatePlayerBodyBuildFailure(ticket, "pane-clearance-capacity");
					return;
				}
				candidate->paneClearanceGeometry[candidate->paneClearanceGeometryCount++] =
					const_cast<RE::BSGeometry*>(static_cast<const RE::BSGeometry*>(sample.geometry));
			}
		}
		candidate->materialGeometryCount = cloneMaterialCensus.materialGeometryCount;

		using GetProjectName_t = const RE::BSFixedString* (*)(const RE::BShkbAnimationGraph*);
		auto getProjectName = reinterpret_cast<GetProjectName_t>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_BShkbAnimationGraph_GetProjectName)).address());
		const auto* projectName = getProjectName(sourceGraph0);
		if (!projectName || projectName->empty()) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "graph0-project-empty");
			return;
		}
		candidate->projectHash = kPlayerDiagnosticFnvOffset;
		HashPlayerDiagnosticBytes(
			std::addressof(candidate->projectHash), projectName->c_str(), projectName->length());

		using AnimationProjectName = RE::BSStaticStringT<260>;
		using AnimationProjectList = RE::BSScrapArray<AnimationProjectName>;
		static_assert(sizeof(AnimationProjectName) == 0x118);
		static_assert(sizeof(AnimationProjectList) == 0x20);
		AnimationProjectList projectFilenames;
		if (!player->PopulateGraphProjectsToLoad(thirdPersonRoot, projectFilenames) ||
			projectFilenames.empty() || projectFilenames[0].empty()) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "graph-project-populate");
			return;
		}

		using CreateManager_t = bool (*)(RE::IAnimationGraphManagerHolder*, const char*);
		using SetTargets_t = bool (*)(RE::IAnimationGraphManagerHolder*, RE::NiAVObject*, bool);
		auto createManager = reinterpret_cast<CreateManager_t>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_AnimationGraphManagerHolder_CreateSingleProject)).address());
		auto setTargets = reinterpret_cast<SetTargets_t>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_AnimationGraphManagerHolder_SetTargets)).address());
		bool managerCreated = false;
		bool targetsBound = false;
		{
			ScopedPrivatePlayerBodyMutation mutationScope;
			managerCreated = createManager(candidate->holder.get(), projectFilenames[0].c_str());
			if (managerCreated)
				targetsBound = setTargets(candidate->holder.get(), cloneRoot, true);
		}
		if (!managerCreated || !targetsBound || !candidate->holder->Manager()) {
			FinishPrivatePlayerBodyBuildFailure(
				ticket, !managerCreated ? "manager-create" : "clone-target-bind");
			return;
		}

		auto* privateManager = candidate->holder->Manager();
		const auto channelCount = candidate->holder->ChannelCount();
		const auto privateBoundChannelCount = privateManager->boundChannel.size();
		const auto sourceBoundChannelCount = sourceManager->boundChannel.size();
		const bool privateBoundChannelNull = privateBoundChannelCount != 0 &&
			std::any_of(
				privateManager->boundChannel.begin(), privateManager->boundChannel.end(),
				[](const auto& channel) noexcept { return channel.get() == nullptr; });

		if (channelCount == 0 || privateBoundChannelCount == 0 ||
			privateBoundChannelCount > channelCount || privateBoundChannelNull ||
			privateManager->graph.size() != 1 ||
			privateManager->activeGraph != 0 || !privateManager->graph[0]) {
			logger::warn(
				"[ReflectionPlayerBody] private manager rejected: channels={} privateBound={} sourceBound={} "
				"graphs={} active={} graph0={} privateBumped={} sourceBumped={}",
				channelCount, privateBoundChannelCount, sourceBoundChannelCount,
				privateManager->graph.size(), privateManager->activeGraph,
				privateManager->graph.size() == 0 ? nullptr : static_cast<void*>(privateManager->graph[0].get()),
				privateManager->bumpedChannel.size(), sourceManager->bumpedChannel.size());
			FinishPrivatePlayerBodyBuildFailure(ticket, "manager-shape-or-channel-subset");
			return;
		}

		static const bool setActiveGraphEntryMatches = [] {
			const auto address = REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_SetActiveGraph)).address();
			return address > 0x10000 &&
				std::memcmp(
					reinterpret_cast<const void*>(address),
					ReflectionRuntime::Prologue(kRVA_BSAnimationGraphManager_SetActiveGraph, kSetActiveGraphPrologue).data(),
					kSetActiveGraphPrologue.size()) == 0;
		}();
		if (!setActiveGraphEntryMatches) {
			logger::error(
				"[ReflectionPlayerBody] SetActiveGraph entry-byte mismatch at {}: clone graph left inert",
				reinterpret_cast<void*>(REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_SetActiveGraph)).address()));
		} else {
			using SetActiveGraph_t = bool (*)(RE::BSAnimationGraphManager*, std::uint32_t);
			auto setActiveGraph = reinterpret_cast<SetActiveGraph_t>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_SetActiveGraph)).address());
			bool graphActivated = false;
			{
				ScopedPrivatePlayerBodyMutation mutationScope;
				graphActivated = setActiveGraph(privateManager, 0);
			}
			if (graphActivated) {
				logger::info(
					"[ReflectionPlayerBody] clone graph ACTIVATED via SetActiveGraph(0): project={}",
					projectName->c_str());

				using ProcessGraphEvent_t = std::uint32_t (*)(
					RE::BSAnimationGraphManager*, const RE::BSFixedString&);
				auto processGraphEvent = reinterpret_cast<ProcessGraphEvent_t>(
					REL::Offset(ReflectionRuntime::Rva(kRVA_BSAnimationGraphManager_ProcessGraphEvent)).address());
				const RE::BSFixedString bootstrapEvent("g_archetypeBaseStateStartInstant");
				bool bootstrapAccepted = false;
				{

					ScopedPrivatePlayerBodyMutation mutationScope;
					bootstrapAccepted = processGraphEvent(privateManager, bootstrapEvent) != 0;
				}
				logger::info(
					"[ReflectionPlayerBody] clone bootstrap g_archetypeBaseStateStartInstant accepted={}",
					bootstrapAccepted);
			} else {
				logger::warn(
					"[ReflectionPlayerBody] SetActiveGraph(0) refused: clone graph stays in its start state");
			}
		}

		{
			SubgraphMirrorOutcome mirrorOutcome{};
			ScopedPrivatePlayerBodyMutation mutationScope;

			logger::info("[ReflectionPlayerBody] SUBGRAPHMIRROR begin");
			spdlog::default_logger_raw()->flush();
			const bool mirrored = MirrorLiveSubgraphContainer(
				sourceGraph0, privateManager->graph[0].get(), std::addressof(mirrorOutcome));
			if (mirrorOutcome.ownershipUncertain) {
				candidate->subgraphOwnershipUncertain = true;
				QuarantinePrivatePlayerBodyResources(candidate.release());
				FinishPrivatePlayerBodyBuildFailure(ticket, "subgraph-ownership-uncertain");
				return;
			}
			g_subgraphMirrorArmed = mirrored;
			g_subgraphMirrorResolved = false;
			g_subgraphMirrorDriveAttempts = 0;
			g_subgraphMirrorRetryCounter = 0;

			g_subgraphMirrorRetryPending = !mirrored && mirrorOutcome.containersValid &&
				mirrorOutcome.addVerified;
			logger::info(
				"[ReflectionPlayerBody] SUBGRAPHMIRROR live={}/{} mirrored={} duplicates={} failed={} "
				"cloneAnchor={} addVerified={} containers={} armed={}",
				mirrorOutcome.liveActive, mirrorOutcome.liveCount, mirrorOutcome.mirrored,
				mirrorOutcome.duplicates, mirrorOutcome.failed,
				reinterpret_cast<const void*>(mirrorOutcome.cloneAnchor), mirrorOutcome.addVerified,
				mirrorOutcome.containersValid, g_subgraphMirrorArmed);
			if (mirrorOutcome.cloneAnchor == 0 && mirrored)
				logger::warn(
					"[ReflectionPlayerBody] SUBGRAPHMIRROR clone swap-state-machine anchor is NULL: entries will "
					"load but cannot splice (locomotion events would still be refused)");
		}
		candidate->privateGraph = privateManager->graph[0].get();
		const auto* privateProjectName = getProjectName(candidate->privateGraph);
		std::uint64_t privateProjectHash = kPlayerDiagnosticFnvOffset;
		if (!privateProjectName || privateProjectName->empty()) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "private-project-empty");
			return;
		}
		HashPlayerDiagnosticBytes(
			std::addressof(privateProjectHash),
			privateProjectName->c_str(),
			privateProjectName->length());
		if (privateProjectHash != candidate->projectHash) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "private-project-mismatch");
			return;
		}
		candidate->cloneTree = FindFlattenedBoneTreeFlat(cloneRoot);
		void* liveThirdPersonTree = FindFlattenedBoneTreeFlat(thirdPersonRoot);
		const auto cloneCount = FlattenedBoneTreeEntryCount(candidate->cloneTree);
		const auto liveCount = FlattenedBoneTreeEntryCount(liveThirdPersonTree);
		std::uint64_t cloneOrderHash = 0;
		std::uint64_t liveOrderHash = 0;
		if (!candidate->cloneTree || candidate->cloneTree == cloneRoot || !liveThirdPersonTree ||
			cloneCount == 0 || cloneCount != liveCount || cloneCount > kMaxPlayerNaturalPoseBones ||
			!HashFlattenedBoneTreeNameOrder(candidate->cloneTree, cloneCount, cloneOrderHash) ||
			!HashFlattenedBoneTreeNameOrder(liveThirdPersonTree, liveCount, liveOrderHash) ||
			cloneOrderHash != liveOrderHash) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "clone-tree-mismatch");
			return;
		}
		candidate->skeletonOrderHash = cloneOrderHash;
		if (!REL::Module::IsVR()) {
			try {
				candidate->clothSimulation=std::make_unique<MirrorPrivateCloth::Simulation>();
				candidate->clothSimulation->Prepare(cloneRoot,player);
			} catch (...) {logger::warn("[MirrorClothSimulation] allocation unavailable; character remains visible");}
		}
		if (!BuildCompletedPlayerPosePool(candidate.get())) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "completed-visual-slots");
			return;
		}

		RE::PlayerCharacter* currentPlayer = nullptr;
		RE::BSTSmartPointer<RE::BSAnimationGraphManager> currentManager;
		RE::NiAVObject* currentFirstPersonRoot = nullptr;
		RE::NiAVObject* currentThirdPersonRoot = nullptr;
		RE::BShkbAnimationGraph* currentGraph0 = nullptr;

		if (MirrorSceneRenderer::LoadBlocked() || MirrorSceneRenderer::LoadGeneration() != generation ||
			!ReadPrivatePlayerBodySource(
				currentPlayer, currentManager, currentFirstPersonRoot, currentThirdPersonRoot, currentGraph0) ||
			currentPlayer != player || currentManager.get() != sourceManager.get() ||
			currentFirstPersonRoot != firstPersonRoot || currentThirdPersonRoot != thirdPersonRoot ||
			currentGraph0 != sourceGraph0) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "source-changed-during-build");
			return;
		}

		PrivatePlayerBodyResources* retired = nullptr;
		bool published = false;
		AcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		if (g_privatePlayerBody.buildTicket == ticket &&
			g_privatePlayerBody.status == PrivatePlayerBodyStatus::kBuildQueued) {
			candidate->stateGeneration =
				g_privatePlayerBodyGeneration.fetch_add(1, std::memory_order_acq_rel) + 1;
			g_completedPlayerPoses.store(candidate->completedPoses, std::memory_order_release);
			retired = std::exchange(g_privatePlayerBody.resources, candidate.release());
			g_privatePlayerBody.status = PrivatePlayerBodyStatus::kReady;
			g_privatePlayerBody.retryAfterMs = 0;
			published = true;
			
			g_privatePlayerPoseFrozen.store(false, std::memory_order_release);
		}
		ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		DestroyPrivatePlayerBodyResources(retired);

		if (published) {
			auto* ready = g_privatePlayerBody.resources;
			logger::info(
				"[ReflectionPlayerBody] private holderID-0 shadow ready: project={} resource={} candidates={} channels={} graph={} "
				"cloneTree={} entries={} cloneFace={} cloneHead={} geometry={}/{} boundChannels={} bumpedChannels={} "
				"generation={} (ID4 disabled)",
				projectName->c_str(), projectFilenames[0].c_str(), projectFilenames.size(),
				ready->holder->ChannelCount(), static_cast<void*>(ready->privateGraph),
				ready->cloneTree, cloneCount, static_cast<void*>(ready->cloneFaceRoot.get()),
				static_cast<void*>(ready->cloneHeadRoot.get()), ready->cloneGeometryCount,
				ready->sourceGeometryCount, ready->holder->Manager()->boundChannel.size(),
				ready->holder->Manager()->bumpedChannel.size(), generation);
			LogPrivateGraphGates(
				"post-build", ready->privateGraph, ready->sourceGraph0,
				ready->holder->Manager(), ready->sourceManager.get());
		}
	}

	void QueuePrivatePlayerBodyBuild(const char* reason) noexcept
	{
		if (!g_privatePlayerBodyDemand.Needed(GetTickCount64()) ||
			!g_privatePlayerBodyResourceBudget.Available() ||
			stl::hookInstallationFailed.load(std::memory_order_acquire))
			return;
		if (g_privatePlayerBodyFaultedThisSession.load(std::memory_order_acquire)) {
			const auto faults = g_privatePlayerBodyFaultCount.load(std::memory_order_acquire);
			const bool budgetSpent = faults >= kPrivatePlayerBodyFaultBudget;
			const bool coolingDown =
				GetTickCount64() < g_privatePlayerBodyFaultRetryAfterMs.load(std::memory_order_acquire);
			if (budgetSpent || coolingDown) {
				static std::uint32_t s_faultedBuildRefusals = 0;
				if (s_faultedBuildRefusals++ < 6u)
					logger::warn(
						"[ReflectionPlayerBody] private clone build refused after a fault (reason={} faults={}/{} coolingDown={})",
						reason, faults, kPrivatePlayerBodyFaultBudget, coolingDown);
				return;
			}
			static std::uint32_t s_faultRetryLogs = 0;
			if (s_faultRetryLogs++ < 6u)
				logger::info("[ReflectionPlayerBody] private clone rebuild after fault cooldown (reason={} faults={}/{})",
					reason, faults, kPrivatePlayerBodyFaultBudget);
		}
		if (!g_privatePlayerBodyIngressHooksInstalled || MirrorSceneRenderer::LoadBlocked() ||
			MirrorSceneRenderer::ShutdownRequested() ||
			g_privatePlayerBodyTeardownRequested.load(std::memory_order_acquire) ||
			g_privatePlayerBodyTeardownTaskQueued.load(std::memory_order_acquire))
			return;
		std::uint64_t ticket = 0;
		AcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		const auto now = GetTickCount64();
		if (g_privatePlayerBody.status != PrivatePlayerBodyStatus::kReady &&
			g_privatePlayerBody.status != PrivatePlayerBodyStatus::kBuildQueued &&
			now >= g_privatePlayerBody.retryAfterMs) {
			g_privatePlayerBody.status = PrivatePlayerBodyStatus::kBuildQueued;
			ticket = ++g_privatePlayerBody.buildTicket;
		}
		ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		if (ticket == 0)
			return;

		auto* taskInterface = F4SE::GetTaskInterface();
		if (!taskInterface) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "task-interface-null");
			return;
		}
		try {
			taskInterface->AddTask([ticket]() { BuildPrivatePlayerBodyOnGameThread(ticket); });
			logger::info(
				"[ReflectionPlayerBody] queued private holderID-0 shadow build: reason={} ticket={}",
				reason ? reason : "unspecified", ticket);
		} catch (...) {
			FinishPrivatePlayerBodyBuildFailure(ticket, "AddTask-exception");
		}
	}

	bool FinitePrivatePlayerTransform(const RE::NiTransform& transform) noexcept
	{
		const auto* components = reinterpret_cast<const float*>(std::addressof(transform));
		for (std::size_t index = 0; index < sizeof(transform) / sizeof(float); ++index) {
			if (!std::isfinite(components[index]))
				return false;
		}
		return true;
	}

	bool ReadPrivatePlayerPoseContentHashUnsafe(
		void* poseTree,
		const RE::NiAVObject* cloneRoot,
		std::uint32_t expectedCount,
		std::uint64_t* hashOut) noexcept
	{
		if (hashOut)
			*hashOut = 0;
		if (!poseTree || !cloneRoot || !hashOut || expectedCount == 0u ||
			expectedCount > kMaxPlayerNaturalPoseBones ||
			FlattenedBoneTreeEntryCount(poseTree) != expectedCount)
			return false;

		std::uint64_t hash = kPlayerDiagnosticFnvOffset;
		for (std::uint32_t index = 0; index < expectedCount; ++index) {
			auto* local = ResolveFlattenedBoneLocal(poseTree, static_cast<std::int32_t>(index));
			if (!local || local == std::addressof(cloneRoot->local) ||
				!FinitePrivatePlayerTransform(*local))
				return false;
			const auto targetIndex = static_cast<std::int32_t>(index);
			HashPlayerDiagnosticBytes(
				std::addressof(hash), std::addressof(targetIndex), sizeof(targetIndex));
			HashPlayerSemanticTransform(std::addressof(hash), local);
		}
		*hashOut = hash;
		return hash != 0u;
	}

	bool ReadPrivatePlayerPoseContentHashNoexcept(
		void* poseTree,
		const RE::NiAVObject* cloneRoot,
		std::uint32_t expectedCount,
		std::uint64_t* hashOut) noexcept
	{
		bool valid = false;
		__try {
			valid = ReadPrivatePlayerPoseContentHashUnsafe(
				poseTree, cloneRoot, expectedCount, hashOut);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			if (hashOut)
				*hashOut = 0;
			valid = false;
		}
		return valid;
	}

	constexpr bool UsesNativeThirdPersonPose(bool thirdPersonShown, std::uint32_t activeGraph) noexcept
	{
		return thirdPersonShown && activeGraph == 0u;
	}

	bool CopyThirdPersonPoseToPrivateCloneUnsafe(
		bool thirdPersonShown,
		std::uint32_t activeGraph,
		RE::NiAVObject* sourceRoot,
		RE::NiAVObject* cloneRoot,
		void* cloneTree,
		std::uint64_t expectedOrderHash,
		RE::NiUpdateData& update) noexcept
	{
		if (!UsesNativeThirdPersonPose(thirdPersonShown, activeGraph) || !sourceRoot || !cloneRoot ||
			sourceRoot == cloneRoot || !cloneTree || expectedOrderHash == 0u)
			return false;
		auto* sourceTree = FindFlattenedBoneTreeFlat(sourceRoot);
		if (!sourceTree || sourceTree == cloneTree)
			return false;
		const auto count = FlattenedBoneTreeEntryCount(sourceTree);
		if (count == 0u ||
			count > kMaxPlayerNaturalPoseBones || FlattenedBoneTreeEntryCount(cloneTree) != count)
			return false;
		std::uint64_t sourceOrderHash = 0u, cloneOrderHash = 0u;
		if (!HashFlattenedBoneTreeNameOrder(sourceTree, count, sourceOrderHash) ||
			!HashFlattenedBoneTreeNameOrder(cloneTree, count, cloneOrderHash) ||
			sourceOrderHash != expectedOrderHash || cloneOrderHash != expectedOrderHash)
			return false;

		std::array<const RE::NiTransform*, kMaxPlayerNaturalPoseBones> sources{};
		std::array<RE::NiTransform*, kMaxPlayerNaturalPoseBones> targets{};
		for (std::uint32_t index = 0u; index < count; ++index) {
			sources[index] = ResolveFlattenedBoneLocal(sourceTree, static_cast<std::int32_t>(index));
			targets[index] = ResolveFlattenedBoneLocal(cloneTree, static_cast<std::int32_t>(index));
			if (!sources[index] || !targets[index] || sources[index] == targets[index] ||
				sources[index] == std::addressof(sourceRoot->local) ||
				targets[index] == std::addressof(cloneRoot->local) ||
				!FinitePrivatePlayerTransform(*sources[index]))
				return false;
		}
		for (std::uint32_t index = 0u; index < count; ++index)
			std::memcpy(targets[index], sources[index], sizeof(RE::NiTransform));
		NiVirtualDispatch::UpdateDownwardPass(cloneRoot, update, 0);
		return true;
	}

	bool CopyThirdPersonPoseToPrivateCloneNoexcept(
		bool thirdPersonShown,
		std::uint32_t activeGraph,
		RE::NiAVObject* sourceRoot,
		RE::NiAVObject* cloneRoot,
		void* cloneTree,
		std::uint64_t expectedOrderHash,
		RE::NiUpdateData& update) noexcept
	{
		__try {
			return CopyThirdPersonPoseToPrivateCloneUnsafe(thirdPersonShown, activeGraph,
				sourceRoot, cloneRoot, cloneTree, expectedOrderHash, update);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return false;
		}
	}

	bool CapturePrivatePlayerNaturalPoseUnsafe(
		PrivatePlayerBodyResources* resources,
		RE::BSAnimationGraphManager* currentSourceManager,
		RE::NiAVObject* currentFirstPersonRoot,
		RE::NiAVObject* currentThirdPersonRoot,
		std::uint64_t sourceUpdateSerial, float animationDelta, std::uint64_t demandGeneration,
		PlayerNaturalPoseSnapshot* out,
		std::uint32_t& changedBones) noexcept
	{
		std::memset(out, 0, sizeof(*out));
		changedBones = 0;
		if (!resources || !currentSourceManager || !currentFirstPersonRoot || !currentThirdPersonRoot ||
			!resources->cloneRoot || !resources->cloneTree || !resources->holder ||
			resources->holder->Manager() == nullptr || resources->privateGraph == nullptr ||
			resources->stateGeneration == 0 || resources->projectHash == 0 ||
			resources->skeletonOrderHash == 0)
			return false;

		void* firstPersonTree = FindFlattenedBoneTreeFlat(currentFirstPersonRoot);
		void* thirdPersonTree = FindFlattenedBoneTreeFlat(currentThirdPersonRoot);
		if (!firstPersonTree || !thirdPersonTree || thirdPersonTree == currentThirdPersonRoot)
			return false;
		const auto targetCount = FlattenedBoneTreeEntryCount(thirdPersonTree);
		if (targetCount == 0 || targetCount > kMaxPlayerNaturalPoseBones ||
			FlattenedBoneTreeEntryCount(resources->cloneTree) != targetCount)
			return false;

		std::uint32_t mappingCount = 0;
		std::uint64_t mappingHash = 0;
		if (!ReadPlayerPoseMappingProvenanceUnsafe(
				resources->player, firstPersonTree, thirdPersonTree,
				std::addressof(mappingCount), std::addressof(mappingHash)))
			return false;

		if (!g_poseBridgeDisabled && resources->player && !PlayerPoseFromThirdPersonGraph(resources->player)) {
			if (!resources->bridgeHeadMaskBuilt) {
				const RE::NiAVObject* cloneHeadNode = nullptr;
				if (!REL::Module::IsVR()) {  
					if (auto* process = resources->player->currentProcess) {
						if (auto* middleHigh = process->middleHigh)
							cloneHeadNode = middleHigh->headNode;
					}
				}

				BuildPlayerPoseBridgeHeadMaskNoexcept(
					resources->cloneTree,
					g_poseBridgeIncludeHead ? nullptr : ResolveCloneHeadNodeNoexcept(resources, cloneHeadNode),
					resources->bridgeHeadMask.data(),
					std::addressof(resources->bridgeHeadMaskMarked));
				resources->bridgeHeadMaskBuilt = true;
			}
			PlayerPoseBridgeResult bridge{};
			const bool bridgeOk = ApplyPlayerPoseBridgeNoexcept(
				resources->player,
				firstPersonTree,
				resources->cloneTree,
				std::addressof(resources->cloneRoot->local),
				resources->bridgeHeadMask.data(),
				std::addressof(bridge));
			if (!bridgeOk || bridge.faulted) {
				static std::uint32_t s_bridgeFaults = 0;
				if (++s_bridgeFaults >= 8u && !g_poseBridgeDisabled) {
					g_poseBridgeDisabled = true;
					logger::error(
						"[ReflectionPlayerBody] pose bridge disabled for the session after {} faults", s_bridgeFaults);
				}
			}
			static bool s_bridgeLogged = false;
			if (!s_bridgeLogged && bridge.mappingCount != 0) {
				s_bridgeLogged = true;
				logger::info(
					"[ReflectionPlayerBody] POSEBRIDGE mappingCount={} bridged={} skippedHeadChain={} "
					"skippedNonFinite={} skippedUnresolved={} headMaskMarked={} cloneBones={} faulted={}",
					bridge.mappingCount, bridge.bridged, bridge.skippedHeadChain, bridge.skippedNonFinite,
					bridge.skippedUnresolved, resources->bridgeHeadMaskMarked, targetCount, bridge.faulted);
			}
		}

		const bool nativeThirdPerson=UsesNativeThirdPersonPose(
			PlayerThirdPersonModelShown(resources->player),currentSourceManager->activeGraph);
		if (resources->clothSimulation && resources->clothSimulation->Ready()) {
			// Resolve animation/bridge inputs before simulation; publish only the
			// completed private result. All mirrors consume this same immutable pose.
			RE::NiUpdateData update{};
			NiVirtualDispatch::UpdateDownwardPass(resources->cloneRoot,update,0);
			if (!resources->clothSimulation->Update(animationDelta,sourceUpdateSerial,demandGeneration,nativeThirdPerson))
				ApplyMirrorClothPose(resources,nativeThirdPerson);
			NiVirtualDispatch::UpdateDownwardPass(resources->cloneRoot,update,0);
		} else {
			ApplyMirrorClothPose(resources,nativeThirdPerson);
		}
		out->sourceKind = PlayerNaturalPoseSource::kPrivateHolder0Shadow;
		out->loadGeneration = resources->loadGeneration;
		out->captureFrame = GetRenderFrame();
		out->threadId = GetCurrentThreadId();
		out->sourceUpdateSerial = sourceUpdateSerial;
		out->privateStateGeneration = resources->stateGeneration;
		out->privateProjectHash = resources->projectHash;
		out->privateSkeletonOrderHash = resources->skeletonOrderHash;
		out->privatePoseCount = targetCount;
		out->player = resources->player;
		out->firstPersonRoot = currentFirstPersonRoot;
		out->thirdPersonRoot = currentThirdPersonRoot;
		out->animationGraphManager = currentSourceManager;
		out->privateAnimationGraphManager = resources->holder->Manager();
		out->privateAnimationGraph = resources->privateGraph;
		out->sourceTree = firstPersonTree;
		out->targetTree = thirdPersonTree;
		out->privatePoseTree = resources->cloneTree;
		out->mappingCount = mappingCount;
		out->mappingHash = mappingHash;
		std::uint64_t poseContentHash = kPlayerDiagnosticFnvOffset;
		for (std::uint32_t targetIndex = 0; targetIndex < targetCount; ++targetIndex) {
			auto* cloneLocal = ResolveFlattenedBoneLocal(
				resources->cloneTree, static_cast<std::int32_t>(targetIndex));
			auto* liveLocal = ResolveFlattenedBoneLocal(
				thirdPersonTree, static_cast<std::int32_t>(targetIndex));
			if (!cloneLocal || !liveLocal || cloneLocal == std::addressof(resources->cloneRoot->local) ||
				liveLocal == std::addressof(currentThirdPersonRoot->local) ||
				!FinitePrivatePlayerTransform(*cloneLocal))
				return false;

			auto& captured = out->bones[out->count++];
			captured.targetIndex = static_cast<std::int32_t>(targetIndex);
			std::memcpy(std::addressof(captured.naturalLocal), cloneLocal, sizeof(RE::NiTransform));
			HashPlayerDiagnosticBytes(
				std::addressof(poseContentHash), std::addressof(captured.targetIndex),
				sizeof(captured.targetIndex));
			HashPlayerSemanticTransform(
				std::addressof(poseContentHash), std::addressof(captured.naturalLocal));
			std::uint64_t boneHash = kPlayerDiagnosticFnvOffset;
			HashPlayerSemanticTransform(
				std::addressof(boneHash), std::addressof(captured.naturalLocal));
			if (resources->havePreviousBoneHashes &&
				resources->previousBoneHashes[targetIndex] != boneHash)
				++changedBones;
			resources->previousBoneHashes[targetIndex] = boneHash;
		}
		resources->havePreviousBoneHashes = true;
		out->privatePoseContentHash = poseContentHash;
		out->valid = out->count == targetCount;
		return out->valid;
	}

	int ResolvePrivatePlayerNodeByNameSEH(
		RE::NiAVObject* root, const RE::BSFixedString& name, RE::NiAVObject** out) noexcept
	{
		__try {
			*out = root ? NiVirtualDispatch::GetObjectByName(root, name) : nullptr;
			return *out ? 1 : 0;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			*out = nullptr;
			return -1;
		}
	}

#include "FlatMirrorLandingTrace.inl"

	int SynchronizePrivatePlayerNodeCullSEH(RE::NiAVObject* live, RE::NiAVObject* clone) noexcept
	{
		__try {
			if (!live || !clone)
				return 0;
			const bool liveCulled = live->GetAppCulled();
			if (clone->GetAppCulled() == liveCulled)
				return 0;
			NiVirtualDispatch::SetAppCulled(clone, liveCulled);
			return 1;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return -1;
		}
	}

	void SynchronizePrivatePlayerWeaponBoneCull(PrivatePlayerBodyResources* resources) noexcept
	{
		if (!resources || !resources->cloneRoot || !resources->sourceThirdPersonRoot)
			return;
		static const std::array<RE::BSFixedString, 2> kWeaponBoneNames{
			RE::BSFixedString("Weapon"), RE::BSFixedString("WeaponLeft")
		};
		if (!resources->weaponBonesResolved) {
			resources->weaponBonesResolved = true;
			std::array<int, 2> found{ 0, 0 };
			for (std::size_t index = 0; index < kWeaponBoneNames.size(); ++index) {
				RE::NiAVObject* live = nullptr;
				RE::NiAVObject* clone = nullptr;
				if (ResolvePrivatePlayerNodeByNameSEH(
						resources->sourceThirdPersonRoot.get(), kWeaponBoneNames[index], std::addressof(live)) == 1 &&
					ResolvePrivatePlayerNodeByNameSEH(
						resources->cloneRoot.get(), kWeaponBoneNames[index], std::addressof(clone)) == 1) {
					resources->sourceWeaponBones[index].reset(live);
					resources->cloneWeaponBones[index].reset(clone);
					found[index] = 1;
				}
			}
			static std::uint32_t s_weaponBoneResolveLogs = 0;
			if (s_weaponBoneResolveLogs++ < 6u) {
				logger::info(
					"[ReflectionPlayerBody] clone weapon bones resolved: Weapon={} WeaponLeft={} (live cull bits {}/{})",
					found[0], found[1],
					resources->sourceWeaponBones[0] ? (resources->sourceWeaponBones[0]->GetAppCulled() ? 1 : 0) : -1,
					resources->sourceWeaponBones[1] ? (resources->sourceWeaponBones[1]->GetAppCulled() ? 1 : 0) : -1);
			}
		}
		for (std::size_t index = 0; index < kWeaponBoneNames.size(); ++index) {
			const int result = SynchronizePrivatePlayerNodeCullSEH(
				resources->sourceWeaponBones[index].get(), resources->cloneWeaponBones[index].get());
			if (result == 0)
				continue;
			static std::uint32_t s_weaponBoneSyncLogs = 0;
			if (++s_weaponBoneSyncLogs <= 12u || (s_weaponBoneSyncLogs % 60u) == 0u) {
				logger::info(
					"[ReflectionPlayerBody] clone weapon bone '{}' cull synchronized: culled={} result={}",
					index == 0 ? "Weapon" : "WeaponLeft",
					resources->sourceWeaponBones[index] ? (resources->sourceWeaponBones[index]->GetAppCulled() ? 1 : 0) : -1,
					result);
			}
			if (result < 0) {
				
				resources->sourceWeaponBones[index].reset();
				resources->cloneWeaponBones[index].reset();
			}
		}
	}

	struct PlayerMuzzleFlashState
	{
		const void* muzzleFlash{ nullptr };
		RE::NiAVObject* art{ nullptr };
		RE::NiAVObject* fireNode{ nullptr };
		bool active{ false };
	};

	int ReadPlayerMuzzleFlashSEH(RE::PlayerCharacter* player, PlayerMuzzleFlashState* out) noexcept
	{
		__try {
			*out = {};
			if (!player || !player->currentProcess || !player->currentProcess->middleHigh)
				return 0;
			auto& items = player->currentProcess->middleHigh->equippedItems;
			for (const auto& item : items) {
				auto* form = item.item.object;
				if (!form || form->GetFormType() != RE::ENUM_FORM_ID::kWEAP || !item.data)
					continue;
				const auto* data = reinterpret_cast<const std::uint8_t*>(item.data.get());
				const auto* muzzleFlash = *reinterpret_cast<const std::uint8_t* const*>(data + 0x28);
				out->muzzleFlash = muzzleFlash;
				if (!muzzleFlash)
					return 1;
				out->active = muzzleFlash[0] != 0;
				out->art = *reinterpret_cast<RE::NiAVObject* const*>(muzzleFlash + 0x10);
				out->fireNode = *reinterpret_cast<RE::NiAVObject* const*>(muzzleFlash + 0x18);
				return 1;
			}
			return 0;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			*out = {};
			return -1;
		}
	}

	int CloneMuzzleFlashArtSEH(RE::NiAVObject* art, RE::NiCloningProcess* process, RE::NiObject** out) noexcept
	{
		__try {
			*out = NiVirtualDispatch::CreateClone(art, *process);
			if (*out)
				NiVirtualDispatch::ProcessClone(art, *process);
			return *out ? 1 : 0;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			*out = nullptr;
			return -1;
		}
	}

	int AttachMuzzleFlashCloneSEH(RE::NiAVObject* parent, RE::NiAVObject* child) noexcept
	{
		__try {
			auto* node = parent ? parent->IsNode() : nullptr;
			if (!node || !child)
				return 0;
			child->local.MakeIdentity();  
			node->AttachChild(child, true);
			return child->parent == node ? 1 : 0;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return -1;
		}
	}

	int DetachMuzzleFlashCloneSEH(RE::NiAVObject* parent, RE::NiAVObject* child,
		RE::NiAVObject** detachedOut) noexcept
	{
		__try {
			auto* node = parent ? parent->IsNode() : nullptr;
			if (!node || !child || child->parent != node)
				return 0;
			auto** vtable = *reinterpret_cast<void***>(node);
			if (!vtable)
				return 0;
			using DetachChild_t = void (*)(RE::NiNode*, RE::NiAVObject*, RE::NiAVObject**);
			const std::size_t slot = REL::Module::IsVR() ? 0x40u : 0x3Cu;
			reinterpret_cast<DetachChild_t>(vtable[slot])(node, child, detachedOut);
			return 1;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return -1;
		}
	}

	int ReadNodeNameSEH(const RE::NiAVObject* object, char* buffer, std::size_t capacity) noexcept
	{
		__try {
			buffer[0] = '\0';
			if (!object)
				return 0;
			const auto* name = object->name.c_str();
			const auto address = reinterpret_cast<std::uintptr_t>(name);
			if (address <= 0x10000 || address > 0x00007FFFFFFFFFFFULL)
				return 0;
			std::size_t copied = 0;
			while (copied + 1 < capacity && name[copied] != '\0') {
				const auto character = static_cast<unsigned char>(name[copied]);
				if (character < 0x20 || character > 0x7E)
					return 0;
				buffer[copied] = name[copied];
				++copied;
			}
			buffer[copied] = '\0';
			return copied != 0 && name[copied] == '\0' ? 1 : 0;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			buffer[0] = '\0';
			return -1;
		}
	}

#include "FlatMirrorPlayerAttachments.inl"

	void ReleasePrivatePlayerMuzzleFlash(PrivatePlayerBodyResources* resources, const char* reason) noexcept
	{
		if (!resources)
			return;
		if (resources->muzzleFlashCloneArt) {
			RE::NiPointer<RE::NiAVObject> detached;  
			(void)DetachMuzzleFlashCloneSEH(resources->muzzleFlashCloneParent.get(), resources->muzzleFlashCloneArt.get(),
				reinterpret_cast<RE::NiAVObject**>(std::addressof(detached)));
			if (resources->muzzleFlashLogs++ < 12u)
				logger::info("[ReflectionPlayerBody] MUZZLEFLASH clone detached ({})", reason);
		}
		resources->muzzleFlashCloneArt.reset();
		resources->muzzleFlashCloneParent.reset();
		resources->muzzleFlashLiveArt.reset();
	}

	void SynchronizePrivatePlayerMuzzleFlash(PrivatePlayerBodyResources* resources) noexcept
	{
		if (!resources || !resources->cloneRoot || REL::Module::IsVR() || resources->muzzleFlashFailures >= 8u)
			return;
		PlayerMuzzleFlashState state{};
		const int read = ReadPlayerMuzzleFlashSEH(resources->player, std::addressof(state));
		if (read < 0) {
			++resources->muzzleFlashFailures;
			ReleasePrivatePlayerMuzzleFlash(resources, "read fault");
			return;
		}
		const bool liveVisible = state.active && state.art && state.art->parent != nullptr;
		if (!liveVisible) {
			if (resources->muzzleFlashCloneArt)
				ReleasePrivatePlayerMuzzleFlash(resources, "flash ended");
			return;
		}
		if (resources->muzzleFlashCloneArt && resources->muzzleFlashLiveArt.get() == state.art)
			return;  
		ReleasePrivatePlayerMuzzleFlash(resources, "flash instance changed");

		char fireNodeName[64]{};
		RE::NiAVObject* cloneFireNode = nullptr;
		if (ReadNodeNameSEH(state.fireNode, fireNodeName, sizeof(fireNodeName)) == 1) {
			const RE::BSFixedString fireName(fireNodeName);
			for (const auto& weaponBone : resources->cloneWeaponBones) {
				if (weaponBone &&
					ResolvePrivatePlayerNodeByNameSEH(weaponBone.get(), fireName, std::addressof(cloneFireNode)) == 1)
					break;
				cloneFireNode = nullptr;
			}
			if (!cloneFireNode)
				(void)ResolvePrivatePlayerNodeByNameSEH(resources->cloneRoot.get(), fireName, std::addressof(cloneFireNode));
		}
		if (!cloneFireNode)
			cloneFireNode = resources->cloneWeaponBones[0].get();
		if (!cloneFireNode || !cloneFireNode->IsNode()) {
			if (resources->muzzleFlashLogs++ < 12u)
				logger::warn("[ReflectionPlayerBody] MUZZLEFLASH no clone fire node for '{}' (weapon bone resolved={})",
					fireNodeName, resources->cloneWeaponBones[0] != nullptr);
			++resources->muzzleFlashFailures;
			return;
		}

		RE::NiObject* cloned = nullptr;
		{
			RE::NiCloningProcess cloningProcess{};
			cloningProcess.copyType = RE::NiCloningProcess::CopyType::kCopyUnique;
			cloningProcess.scale = RE::NiPoint3{ 1.0F, 1.0F, 1.0F };
			if (CloneMuzzleFlashArtSEH(state.art, std::addressof(cloningProcess), std::addressof(cloned)) != 1 || !cloned) {
				++resources->muzzleFlashFailures;
				if (resources->muzzleFlashLogs++ < 12u)
					logger::warn("[ReflectionPlayerBody] MUZZLEFLASH art clone failed");
				return;
			}
		}
		auto* cloneArt = static_cast<RE::NiAVObject*>(cloned);
		RE::NiPointer<RE::NiAVObject> owner(cloneArt);
		cloneArt->name = RE::BSFixedString(kMirrorMuzzleFlashCloneName);
		if (AttachMuzzleFlashCloneSEH(cloneFireNode, cloneArt) != 1) {
			++resources->muzzleFlashFailures;
			if (resources->muzzleFlashLogs++ < 12u)
				logger::warn("[ReflectionPlayerBody] MUZZLEFLASH attach failed under '{}'", fireNodeName);
			return;
		}
		NiVirtualDispatch::SetAppCulled(cloneArt, false);
		resources->muzzleFlashCloneArt = owner;
		resources->muzzleFlashCloneParent.reset(cloneFireNode);
		resources->muzzleFlashLiveArt.reset(state.art);
		if (resources->muzzleFlashLogs++ < 12u) {
			char artName[64]{};
			(void)ReadNodeNameSEH(state.art, artName, sizeof(artName));
			logger::info("[ReflectionPlayerBody] MUZZLEFLASH clone attached: art='{}' fireNode='{}' liveParent={} cloneParent={}",
				artName, fireNodeName, static_cast<const void*>(state.art->parent), static_cast<const void*>(cloneFireNode));
		}
	}

