	using PrivatePlayerActorScaleGetter = float (*)(RE::TESObjectREFR*);

	bool CallPrivatePlayerActorScaleNoexcept(PrivatePlayerActorScaleGetter getScale,
		RE::PlayerCharacter* player, float& scale) noexcept
	{
		
		__try {
			scale = getScale(player);
			return true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return false;
		}
	}

	bool ReadPrivatePlayerActorScale(RE::PlayerCharacter* player, float& scale) noexcept
	{

		static const auto getScale = []() -> PrivatePlayerActorScaleGetter {
			if (!ReflectionRuntime::Supported() || REL::Module::IsVR()) return nullptr;
			return reinterpret_cast<PrivatePlayerActorScaleGetter>(ReflectionRuntime::Address(0x3F8540u));
		}();
		if (!player || !getScale) return false;
		return CallPrivatePlayerActorScaleNoexcept(getScale, player, scale);
	}

	void UpdatePrivatePlayerBodyAfterNativePlayer(
		const RE::IAnimationGraphManagerHolder* holder,
		void* animationUpdateData,
		PrivateGraphUpdate_t originalUpdate,
		std::uint64_t sourceUpdateSerial) noexcept
	{
		auto* player = RE::PlayerCharacter::GetSingleton();
		if (!player || holder != static_cast<const RE::IAnimationGraphManagerHolder*>(player) ||
			!animationUpdateData || !originalUpdate)
			return;
		if (MirrorSceneRenderer::LoadBlocked()) {
			RequestPrivatePlayerBodyTeardown();
			return;
		}
		
		if (!MirrorToggle::Active())
			return;

		const bool captureDemand = g_privatePlayerBodyDemand.Needed(GetTickCount64());
		if (!captureDemand) {

			return;
		}
		MirrorPerformance::AnimationSample animationTiming;
		const auto demandGeneration = g_privatePlayerBodyDemand.Generation();

		RE::BSTSmartPointer<RE::BSAnimationGraphManager> currentManager;
		if (!static_cast<const RE::IAnimationGraphManagerHolder*>(player)
				->GetAnimationGraphManagerImpl(currentManager) ||
			!currentManager || currentManager->graph.size() != 2) {
			QueuePrivatePlayerBodyBuild("source-manager-unavailable");
			return;
		}
		auto* firstPersonRoot = player->firstPerson3D.get();
		auto* thirdPersonRoot = PlayerThirdPersonRoot(player);
		auto* currentGraph0 = currentManager->graph[0].get();
		RE::NiAVObject* currentFaceRoot = nullptr;
		RE::NiAVObject* currentHeadRoot = nullptr;
		const bool currentFaceRootsAvailable =
			ReadPrivatePlayerFaceRoots(player, currentFaceRoot, currentHeadRoot);
		const auto generation = MirrorSceneRenderer::LoadGeneration();

		PrivateAnimationUpdateDataCopy updateDataCopy{};
		std::memcpy(updateDataCopy.bytes.data(), animationUpdateData, updateDataCopy.bytes.size());

		*reinterpret_cast<void**>(updateDataCopy.bytes.data() + 0x10) = nullptr;

		bool needBuild = false;
		bool teardownNeeded = false;
		bool captured = false;
		bool privateUpdateResult = false;
		bool poseFromThirdPerson = false;
		std::uint32_t changedBones = 0;
		std::uint64_t privateSerial = 0;
		std::uint64_t publishCount = 0;
		std::uint64_t changedPublishCount = 0;
		std::uint64_t consecutiveUnchangedPublishes = 0;
		std::uint64_t mirroredEvents = 0;
		std::uint64_t attemptedEvents = 0;
		std::uint64_t mirroredVariables = 0;
		bool subgraphBootstrapReady = false;
		bool frozenLatched = false;
		bool jumpRecoveryWatch = false;
		bool jumpLandingPending = false;
		auto* candidate = std::addressof(g_privatePlayerNaturalPoseCaptureStaging);
		AcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		auto* resources = g_privatePlayerBody.resources;
		const bool identitiesMatch = g_privatePlayerBody.status == PrivatePlayerBodyStatus::kReady &&
			resources &&
			resources->player == player && resources->loadGeneration == generation &&
			resources->sourceManager.get() == currentManager.get() && resources->sourceGraph0 == currentGraph0 &&
			resources->sourceFirstPersonRoot.get() == firstPersonRoot &&
			resources->sourceThirdPersonRoot.get() == thirdPersonRoot && currentFaceRootsAvailable &&
			resources->sourceFaceRoot.get() == currentFaceRoot &&
			resources->sourceHeadRoot.get() == currentHeadRoot && resources->cloneRoot &&
			bool(resources->cloneFaceRoot) == bool(resources->sourceFaceRoot) &&
			bool(resources->cloneHeadRoot) == bool(resources->sourceHeadRoot) &&
			resources->geometryMaterialHash != 0 && resources->materialGeometryCount != 0 &&
			resources->sourceGeometryCount != 0 &&
			resources->sourceGeometryCount == resources->cloneGeometryCount && resources->holder &&
			resources->holder->Manager() && resources->holder->Manager()->graph.size() == 1 &&
			resources->holder->Manager()->activeGraph == 0 &&
			resources->holder->Manager()->graph[0].get() == resources->privateGraph;
		if (!identitiesMatch) {
			if (g_privatePlayerBody.status == PrivatePlayerBodyStatus::kReady) {
				g_privatePlayerBody.status = PrivatePlayerBodyStatus::kEmpty;
				g_privatePlayerBodyGeneration.fetch_add(1, std::memory_order_acq_rel);
				teardownNeeded = resources != nullptr;
			}
			needBuild = g_privatePlayerBody.status != PrivatePlayerBodyStatus::kBuildQueued;
		} else {
			ScopedPrivatePlayerBodyMutation mutationScope;
			if (!SynchronizePrivatePlayerFaceNoexcept(resources)) {
				
				ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
				return;
			}
			
			SynchronizePrivatePlayerWeaponBoneCull(resources);
			SynchronizePrivatePlayerMuzzleFlash(resources);
			SynchronizePrivateAnimationInputsLeased(resources);

			subgraphBootstrapReady = DriveCloneSubgraphProcessing(
				resources->holder ? resources->holder->Manager() : nullptr, resources->privateGraph,
				resources->sourceGraph0);
			if (CloneSubgraphSetChanged(resources)) {
				g_privatePlayerBodyTeardownRequested.store(true, std::memory_order_release);
				ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
				return;
			}
			if (subgraphBootstrapReady) ReconcileCloneWeaponState(resources);
			if (subgraphBootstrapReady) ReconcileCloneWeaponPosture(resources);
			if (subgraphBootstrapReady) ReconcileCloneSneakLocomotion(resources);

			std::memcpy(
				std::addressof(resources->cloneRoot->local),
				std::addressof(thirdPersonRoot->local),
				sizeof(RE::NiTransform));
			std::memcpy(
				std::addressof(resources->cloneRoot->world),
				std::addressof(thirdPersonRoot->world),
				sizeof(RE::NiTransform));

			if (!REL::Module::IsVR()) {
				MirrorBodyPlacement::AnchorFirstPerson(currentManager->activeGraph == 1,
					!resources->cloneRoot->parent, player->data.location,
					resources->cloneRoot->local, resources->cloneRoot->world);

				static const bool tfpLoaded = GetModuleHandleW(L"TrueFirstPerson.dll") != nullptr;
				MirrorBodyPlacement::RestoreFirstPersonScale(currentManager->activeGraph == 1,
					!resources->cloneRoot->parent, tfpLoaded,
					[player](float& scale) noexcept { return ReadPrivatePlayerActorScale(player, scale); },
					resources->cloneRoot->local, resources->cloneRoot->world);
			}

			if (!REL::Module::IsVR() && !resources->cloneRoot->parent &&
				MirrorLocomotion::AlignRelaxedHeading(currentManager->activeGraph == 1,
					player->GetWeaponMagicDrawn(), player->data.angle.z, resources->cloneRoot->world.rotate))
				resources->cloneRoot->local.rotate = resources->cloneRoot->world.rotate;
			RE::NiUpdateData clonePlacementUpdate{};
			std::memcpy(
				std::addressof(clonePlacementUpdate.time),
				updateDataCopy.bytes.data(),
				sizeof(clonePlacementUpdate.time));
			NiVirtualDispatch::UpdateDownwardPass(resources->cloneRoot, clonePlacementUpdate, 0);

			g_playerLiveActiveGraph.store(currentManager->activeGraph, std::memory_order_release);
			poseFromThirdPerson = UsesNativeThirdPersonPose(PlayerThirdPersonModelShown(player), currentManager->activeGraph);

			privateUpdateResult = SafePrivateGraphUpdate(
				originalUpdate, resources->holder.get(), resources->holder->Manager(), resources->sourceGraph0,
				&resources->locomotionRequests, updateDataCopy.bytes.data());
			if (privateUpdateResult && subgraphBootstrapReady) LogPrivateAnimationStateLeased(resources);
			if (poseFromThirdPerson && privateUpdateResult) {
				privateUpdateResult = CopyThirdPersonPoseToPrivateCloneNoexcept(
					true, currentManager->activeGraph, thirdPersonRoot, resources->cloneRoot.get(),
					resources->cloneTree, resources->skeletonOrderHash, clonePlacementUpdate);

				subgraphBootstrapReady = true;
			}
			if (privateUpdateResult && subgraphBootstrapReady) {
				captured = CapturePrivatePlayerNaturalPoseUnsafe(
					resources, currentManager.get(), firstPersonRoot, thirdPersonRoot,
					sourceUpdateSerial, clonePlacementUpdate.time, demandGeneration, candidate, changedBones);
			}
			if (captured) {

				candidate->serial =
					g_playerNaturalPoseSerial.fetch_add(1, std::memory_order_relaxed) + 1;
				privateSerial = ++resources->updateSerial;
				resources->demandGeneration = demandGeneration;
				resources->poseSerial = candidate->serial;
				resources->sourceUpdateSerial = sourceUpdateSerial;
				resources->poseContentHash = candidate->privatePoseContentHash;
				resources->poseBoneCount = candidate->privatePoseCount;
				resources->poseFromThirdPerson = poseFromThirdPerson;
				PublishCompletedPlayerPose(resources);
				TraceMirrorLandingPose(0,resources->cloneRoot.get(),resources->poseSerial,
					resources->sourceUpdateSerial,resources->poseContentHash,-1,false);
				if (poseFromThirdPerson) {
					resources->jumpRecoveryWatch = false;
					resources->jumpLandingPending = false;
					resources->consecutiveUnchangedPublishes = 0;
				}
				++resources->publishCount;
				if (changedBones != 0) {
					++resources->changedPublishCount;
					resources->consecutiveUnchangedPublishes = 0;
					if (resources->jumpLandingPending) {

						resources->jumpLandingPending = false;
						resources->jumpRecoveryWatch = false;
					}
				} else if (resources->jumpRecoveryWatch &&
					resources->consecutiveUnchangedPublishes !=
						(std::numeric_limits<std::uint64_t>::max)()) {
					++resources->consecutiveUnchangedPublishes;
				}
				publishCount = resources->publishCount;
				changedPublishCount = resources->changedPublishCount;
				consecutiveUnchangedPublishes = resources->consecutiveUnchangedPublishes;
				mirroredEvents = resources->mirroredEvents;
				attemptedEvents = resources->attemptedEvents;
				mirroredVariables = resources->mirroredVariables;
				jumpRecoveryWatch = resources->jumpRecoveryWatch;
				jumpLandingPending = resources->jumpLandingPending;

				frozenLatched = resources->jumpRecoveryWatch &&
					consecutiveUnchangedPublishes >= kFrozenPrivatePosePublishProbe;
			} else if (subgraphBootstrapReady) {
				g_privatePlayerBody.status = PrivatePlayerBodyStatus::kFailed;
				g_privatePlayerBodyGeneration.fetch_add(1, std::memory_order_acq_rel);
				g_privatePlayerBody.retryAfterMs = GetTickCount64() + 2000u;
				++g_privatePlayerBody.failureCount;
				needBuild = true;
				teardownNeeded = true;
			} else if (!poseFromThirdPerson && CloneSubgraphBootstrapStalled() &&
				StallRetireEnabled()) {

				const auto failures = ++g_privatePlayerBody.failureCount;
				g_privatePlayerBody.status = PrivatePlayerBodyStatus::kFailed;
				g_privatePlayerBodyGeneration.fetch_add(1, std::memory_order_acq_rel);
				g_privatePlayerBody.retryAfterMs = GetTickCount64() + 2000u +
					1000u * static_cast<std::uint64_t>((std::min)(failures, 10u));
				needBuild = true;
				teardownNeeded = true;
				static std::uint32_t s_bootstrapStallRetirements = 0;
				if (++s_bootstrapStallRetirements <= 8u || (s_bootstrapStallRetirements % 30u) == 0u) {
					logger::warn(
						"[ReflectionPlayerBody] SUBGRAPHMIRROR bootstrap stalled after {} drive attempts; retiring the private "
						"clone for a rebuild from the current live container (failures={} retryAfterMs=+{})",
						g_subgraphMirrorDriveAttempts, failures,
						g_privatePlayerBody.retryAfterMs - GetTickCount64());
				}
			}
		}
		ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));

		if (captured && g_privatePlayerBodyDemand.AcceptsPose(GetTickCount64(), demandGeneration) &&
			!MirrorSceneRenderer::LoadBlocked() &&
			MirrorSceneRenderer::LoadGeneration() == generation &&
			candidate->privateStateGeneration ==
				g_privatePlayerBodyGeneration.load(std::memory_order_acquire) &&
			g_playerNativeUpdateSerial.load(std::memory_order_acquire) == sourceUpdateSerial) {
			g_playerRetargetWaiters.fetch_add(1, std::memory_order_release);
			AcquireSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
			g_playerRetargetWaiters.fetch_sub(1, std::memory_order_acq_rel);
			if (g_privatePlayerBodyDemand.AcceptsPose(GetTickCount64(), demandGeneration) &&
				!MirrorSceneRenderer::LoadBlocked() && MirrorSceneRenderer::LoadGeneration() == generation &&
				candidate->privateStateGeneration ==
					g_privatePlayerBodyGeneration.load(std::memory_order_acquire) &&
				g_playerNativeUpdateSerial.load(std::memory_order_acquire) == sourceUpdateSerial) {
				PublishPlayerNaturalPoseSnapshotLeased(candidate);
				if (changedBones != 0)
					g_playerNaturalPoseChangedSerial.store(candidate->serial, std::memory_order_release);
			} else {
				g_playerNaturalPoseSnapshot.valid = false;
			}
			ReleaseSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));

			if (privateSerial == 1 || (privateSerial % 600u) == 0u) {
				logger::info(
					"[ReflectionPlayerBody] shadow pose published: privateSerial={} snapshotSerial={} "
					"sourceUpdate={} bones={} changed={} result={} generation={} publishes={} changedPublishes={} "
					"events={}/{} eventHookCalls={} variables={} unchanged={} jumpWatch={} landingPending={} frozen={} nativeThirdPerson={}",
					privateSerial, candidate->serial, sourceUpdateSerial, candidate->count,
					changedBones, privateUpdateResult, generation, publishCount, changedPublishCount,
					mirroredEvents, attemptedEvents,
					g_processGraphEventHookCalls.load(std::memory_order_relaxed),
					mirroredVariables, consecutiveUnchangedPublishes,
					jumpRecoveryWatch, jumpLandingPending, frozenLatched, poseFromThirdPerson);
				if (privateSerial == 1 || privateSerial == 600) {
					LogPrivateGraphGates(
						privateSerial == 1 ? "post-first-update" : "steady-state",
						candidate->privateAnimationGraph, currentGraph0,
						candidate->privateAnimationGraphManager, currentManager.get());
				}
			}
			if (const auto remaining = g_fireTraceRemaining.load(std::memory_order_relaxed); remaining != 0u) {
				g_fireTraceRemaining.store(remaining - 1u, std::memory_order_relaxed);
				logger::info(
					"[ReflectionPlayerBody] FIRETRACE after attackStart: remaining={} privateSerial={} changed={} bones={} result={} nativeThirdPerson={} sourceUpdate={}",
					remaining, privateSerial, changedBones, candidate->count, privateUpdateResult,
					poseFromThirdPerson, sourceUpdateSerial);
			}
			if (g_privatePlayerPoseFrozen.load(std::memory_order_acquire) != frozenLatched) {
				g_privatePlayerPoseFrozen.store(frozenLatched, std::memory_order_release);
				static std::uint32_t s_frozenTransitionLogs = 0;
				if (s_frozenTransitionLogs++ < 8u) {
					logger::warn(
						"[ReflectionPlayerBody] private clone pose frozen={}: publishes={} changedPublishes={} "
						"events={}/{} eventHookCalls={} variables={} unchanged={} liveFallback={}",
						frozenLatched, publishCount, changedPublishCount, mirroredEvents, attemptedEvents,
						g_processGraphEventHookCalls.load(std::memory_order_relaxed), mirroredVariables,
						consecutiveUnchangedPublishes, g_livePlayerPoseFallback);
				}
				if (frozenLatched) {

					needBuild = true;
					teardownNeeded = true;
				}
			}
		}
		NotePrivateCloneAvailability(captured);
		if (teardownNeeded)
			RequestPrivatePlayerBodyTeardown();
		if (needBuild && !teardownNeeded)
			QueuePrivatePlayerBodyBuild(captured ? "identity-changed" : "private-update-or-capture-failed");
	}

	constexpr bool PrivatePlayerPoseEpochReady(
		std::uint32_t loadGeneration,
		std::uint64_t stateGeneration,
		std::uint64_t privateUpdateSerial,
		std::uint64_t poseSerial,
		std::uint64_t sourceUpdateSerial,
		std::uint64_t projectHash,
		std::uint64_t skeletonOrderHash,
		std::uint64_t poseContentHash,
		std::uint32_t poseBoneCount,
		std::uint32_t sourceGeometryCount,
		std::uint32_t cloneGeometryCount) noexcept
	{
		(void)loadGeneration;  
		return stateGeneration != 0 && privateUpdateSerial != 0 &&
			poseSerial != 0 && sourceUpdateSerial != 0 && projectHash != 0 &&
			skeletonOrderHash != 0 && poseContentHash != 0 && poseBoneCount != 0 &&
			poseBoneCount <= kMaxPlayerNaturalPoseBones && sourceGeometryCount != 0 &&
			sourceGeometryCount == cloneGeometryCount;
	}

	static_assert(PrivatePlayerPoseEpochReady(
		0u, 1u, 1u, 1u, 1u, 1u, 1u, 1u, 8u, 8u, 8u));
	static_assert(!PrivatePlayerPoseEpochReady(
		1u, 1u, 1u, 0u, 1u, 1u, 1u, 1u, 8u, 8u, 8u));
	static_assert(!PrivatePlayerPoseEpochReady(
		1u, 1u, 1u, 1u, 0u, 1u, 1u, 1u, 8u, 8u, 8u));
	static_assert(!PrivatePlayerPoseEpochReady(
		1u, 1u, 1u, 1u, 1u, 1u, 1u, 0u, 8u, 8u, 8u));
	static_assert(!PrivatePlayerPoseEpochReady(
		1u, 1u, 1u, 1u, 1u, 1u, 1u, 1u, 8u, 8u, 7u));

	struct PrivatePlayerRenderClone
	{
		RE::NiAVObject* root = nullptr;
		RE::NiAVObject* faceRoot = nullptr;
		RE::NiAVObject* headRoot = nullptr;
		std::uint32_t loadGeneration = 0;
		std::uint64_t stateGeneration = 0;
		std::uint64_t privateUpdateSerial = 0;
		std::uint64_t poseSerial = 0;
		std::uint64_t sourceUpdateSerial = 0;
		std::uint64_t projectHash = 0;
		std::uint64_t skeletonOrderHash = 0;
		std::uint64_t poseContentHash = 0;
		std::uint64_t geometryMaterialHash = 0;
		void* poseTree = nullptr;
		std::uint32_t poseBoneCount = 0;
		std::uint32_t materialGeometryCount = 0;
		std::uint32_t sourceGeometryCount = 0;
		std::uint32_t geometryCount = 0;
		bool poseFromThirdPerson = false;
		MirrorPlayerDrawRequirements drawRequirements{};

		std::array<RE::BSGeometry*, kMaxPrivatePlayerGeometrySamples> paneClearanceGeometry{};
		std::uint32_t paneClearanceGeometryCount = 0;
	};

	MirrorPlayerPoseBatch g_privatePlayerPoseBatch; 
	bool g_privatePlayerBodyAdmissionBusy = false; 
	MirrorCaptureSync g_mirrorCaptureSync; 
	PrivatePlayerRenderClone g_mirrorCaptureSyncClone{};
	std::uint64_t g_mirrorCaptureSyncCameraGeneration{};

#include "FlatMirrorPlayerPoseEpoch.inl"

#include "FlatMirrorHeadClearance.inl"
#include "FlatMirrorCompletedPoseRender.inl"

	void ReleasePrivatePlayerBodyRenderLeaseArmed() noexcept
	{
		if (!g_armPrivatePlayerBodyRenderLease)
			return;
		RestorePrivatePaneClearance();
		g_armPrivatePlayerBodyRenderLease = false;
		if (g_armedCompletedPlayerVisual) {
			g_armedCompletedPlayerVisual = nullptr;
			return; 
		}
		ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
	}

	bool TryArmPrivatePlayerBodyRenderClone(
		RE::NiAVObject* liveRoot,
		RE::NiAVObject* liveFaceRoot,
		RE::NiAVObject* liveHeadRoot,
		PrivatePlayerRenderClone* out) noexcept
	{
		if (!out)
			return false;
		std::memset(out, 0, sizeof(*out));

		if (g_mirrorCaptureSync.PlayerRequired()) {
			const auto* resources = ArmedPrivatePlayerResources();
			if (!g_armPrivatePlayerBodyRenderLease || MirrorSceneRenderer::LoadBlocked() ||
				!resources || resources->sourceThirdPersonRoot.get() != liveRoot ||
				resources->sourceFaceRoot.get() != liveFaceRoot ||
				resources->sourceHeadRoot.get() != liveHeadRoot ||
				!PrivatePlayerRenderClonePoseEpochMatchesCurrent(g_mirrorCaptureSyncClone)) return false;
			*out = g_mirrorCaptureSyncClone;
			return true;
		}
		g_privatePlayerBodyAdmissionBusy = false;
		if (!liveRoot || MirrorSceneRenderer::LoadBlocked())
			return false;
		if (!REL::Module::IsVR())
			return TryArmCompletedPlayerPose(liveRoot, liveFaceRoot, liveHeadRoot, out);
		if (g_armPrivatePlayerBodyRenderLease ||
			!TryAcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock))) {
			g_privatePlayerBodyAdmissionBusy = !g_armPrivatePlayerBodyRenderLease;
			static unsigned busyReports = 0;
			if (++busyReports <= 4 || busyReports % 600 == 0)
				logger::info("[ReflectionPlayerBody] render lease busy: frame={} alreadyArmed={}",
					GetRenderFrame(), g_armPrivatePlayerBodyRenderLease);
			return false;
		}

		g_armPrivatePlayerBodyRenderLease = true;
		bool valid = false;
		bool materialIdentityDiverged = false;
		__try {
			auto* resources = g_privatePlayerBody.resources;
			auto* player = RE::PlayerCharacter::GetSingleton();
			RE::NiAVObject* currentFaceRoot = nullptr;
			RE::NiAVObject* currentHeadRoot = nullptr;
			const auto loadGeneration = MirrorSceneRenderer::LoadGeneration();
			const auto poseFrame = GetRenderFrame();
			const auto stateGeneration =
				g_privatePlayerBodyGeneration.load(std::memory_order_acquire);
			const auto publishedPoseSerial =
				g_playerNaturalPosePublishedSerial.load(std::memory_order_acquire);
			const auto sourceUpdateSerial =
				g_playerNativeUpdateSerial.load(std::memory_order_acquire);
			const auto pendingPrivateSource =
				g_playerPrivateUpdatePendingSource.load(std::memory_order_acquire);
			const bool currentRootsMatch = player && player->loadedData && player->loadedData->data3D &&
				player->loadedData->data3D.get() == liveRoot &&
				ReadPrivatePlayerFaceRoots(player, currentFaceRoot, currentHeadRoot) &&
				currentFaceRoot == liveFaceRoot && currentHeadRoot == liveHeadRoot;
			valid = !MirrorSceneRenderer::LoadBlocked() && currentRootsMatch &&
				g_privatePlayerBody.status == PrivatePlayerBodyStatus::kReady && resources &&
				g_privatePlayerBodyDemand.AcceptsPose(GetTickCount64(), resources->demandGeneration) &&
				resources->player == player && resources->loadGeneration == loadGeneration &&
				resources->stateGeneration == stateGeneration &&
				resources->sourceThirdPersonRoot.get() == liveRoot &&
				resources->poseFromThirdPerson == PlayerPoseFromThirdPersonGraph(player) &&
				resources->sourceFaceRoot.get() == liveFaceRoot &&
				resources->sourceHeadRoot.get() == liveHeadRoot && resources->cloneRoot &&
				bool(resources->cloneFaceRoot) == bool(resources->sourceFaceRoot) &&
			bool(resources->cloneHeadRoot) == bool(resources->sourceHeadRoot) && resources->cloneTree &&
				resources->geometryMaterialHash != 0 && resources->materialGeometryCount != 0 &&
				resources->sourceGeometryCount != 0 &&
				resources->sourceGeometryCount == resources->cloneGeometryCount &&
				PrivatePlayerPoseEpochReady(
					resources->loadGeneration, resources->stateGeneration,
					resources->updateSerial, resources->poseSerial,
					resources->sourceUpdateSerial, resources->projectHash,
					resources->skeletonOrderHash, resources->poseContentHash,
					resources->poseBoneCount, resources->sourceGeometryCount,
					resources->cloneGeometryCount) &&
				
				g_privatePlayerPoseBatch.Accepts(poseFrame, loadGeneration,
					{ reinterpret_cast<std::uintptr_t>(resources->cloneRoot.get()), resources->stateGeneration,
						resources->poseSerial, resources->sourceUpdateSerial }, sourceUpdateSerial, pendingPrivateSource) &&
				!resources->cloneRoot->GetAppCulled() &&
				(!resources->cloneFaceRoot.get() || PrivatePlayerNodeDescendsFromNoexcept(
					resources->cloneFaceRoot.get(), resources->cloneRoot.get())) &&
				(!resources->cloneHeadRoot.get() || PrivatePlayerNodeDescendsFromNoexcept(
					resources->cloneHeadRoot.get(), resources->cloneRoot.get()));
			if (!valid && resources) {
				static unsigned admissionReports = 0;
				if (++admissionReports <= 8 || admissionReports % 300 == 0)
					logger::info("[ReflectionPlayerBody] render admission deferred: frame={} pose={}/{} source={}/{} pending={} generation={}/{} roots={} status={}",
						poseFrame, resources->poseSerial, publishedPoseSerial, resources->sourceUpdateSerial,
						sourceUpdateSerial, pendingPrivateSource, resources->stateGeneration, stateGeneration,
						currentRootsMatch, static_cast<unsigned>(g_privatePlayerBody.status));
			}
			std::uint64_t currentPoseContentHash = 0;
			if (valid)
				valid = SynchronizePrivatePlayerFaceNoexcept(resources);
			if (valid) {
				valid = ReadPrivatePlayerPoseContentHashNoexcept(
					resources->cloneTree, resources->cloneRoot.get(), resources->poseBoneCount,
					std::addressof(currentPoseContentHash)) &&
					currentPoseContentHash == resources->poseContentHash;
			}
			PrivatePlayerGeometryMaterialCensus sourceMaterialCensus{};
			PrivatePlayerGeometryMaterialCensus cloneMaterialCensus{};
			if (valid) {
				const bool materialIdentityReady = ReadPrivatePlayerGeometryMaterialCensus(
					liveRoot, liveFaceRoot, liveHeadRoot,
					std::addressof(sourceMaterialCensus)) &&
					ReadPrivatePlayerGeometryMaterialCensus(
						resources->cloneRoot.get(), resources->cloneFaceRoot.get(),
						resources->cloneHeadRoot.get(), std::addressof(cloneMaterialCensus), resources) &&
					PrivatePlayerGeometryMaterialCensusesMatch(
						sourceMaterialCensus, cloneMaterialCensus) &&
					sourceMaterialCensus.geometryCount == resources->sourceGeometryCount &&
					cloneMaterialCensus.geometryCount == resources->cloneGeometryCount &&
					cloneMaterialCensus.materialGeometryCount == resources->materialGeometryCount &&
					cloneMaterialCensus.semanticHash == resources->geometryMaterialHash;
				valid = materialIdentityReady;
				if (!materialIdentityReady) {

					g_privatePlayerBody.status = PrivatePlayerBodyStatus::kEmpty;
					g_privatePlayerBodyGeneration.fetch_add(1, std::memory_order_acq_rel);
					materialIdentityDiverged = true;
				}
			}
			if (valid) {
				out->root = resources->cloneRoot.get();
				out->faceRoot = resources->cloneFaceRoot.get();
				out->headRoot = resources->cloneHeadRoot.get();
				out->loadGeneration = resources->loadGeneration;
				out->stateGeneration = stateGeneration;
				out->privateUpdateSerial = resources->updateSerial;
				out->poseSerial = resources->poseSerial;
				out->sourceUpdateSerial = resources->sourceUpdateSerial;
				out->projectHash = resources->projectHash;
				out->skeletonOrderHash = resources->skeletonOrderHash;
				out->poseContentHash = resources->poseContentHash;
				out->geometryMaterialHash = resources->geometryMaterialHash;
				out->paneClearanceGeometry = resources->paneClearanceGeometry;
				out->paneClearanceGeometryCount = resources->paneClearanceGeometryCount;
				out->poseTree = resources->cloneTree;
				out->poseBoneCount = resources->poseBoneCount;
				out->materialGeometryCount = resources->materialGeometryCount;
				out->drawRequirements = resources->drawRequirements;
				out->sourceGeometryCount = resources->sourceGeometryCount;
				out->geometryCount = resources->cloneGeometryCount;
				out->poseFromThirdPerson = resources->poseFromThirdPerson;
				g_privatePlayerPoseBatch.Remember(poseFrame, loadGeneration,
					{ reinterpret_cast<std::uintptr_t>(out->root), out->stateGeneration, out->poseSerial, out->sourceUpdateSerial },
					sourceUpdateSerial, pendingPrivateSource);
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			valid = false;
		}

		if (!valid) {
			std::memset(out, 0, sizeof(*out));
			ReleasePrivatePlayerBodyRenderLeaseArmed();
			if (materialIdentityDiverged)
				RequestPrivatePlayerBodyTeardown();
		}
		return valid;
	}

	bool UpdatePlayerPoseRootNoexcept(RE::NiAVObject* root, RE::NiCamera* camera) noexcept
	{
		if (!root || !camera)
			return false;
		__try {
			RE::NiUpdateData update{};
			update.camera = camera;
			NiVirtualDispatch::UpdateDownwardPass(root, update, 0);
			return true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return false;
		}
	}

	void RestorePlayerPoseArmedWithEvidence(
		bool faultPath,
		PlayerPoseTransformEvidence* beforeDownward,
		PlayerPoseTransformEvidence* afterDownward) noexcept;

	void RestorePlayerPoseArmedWithEvidence(
		bool faultPath,
		PlayerPoseTransformEvidence* beforeDownward,
		PlayerPoseTransformEvidence* afterDownward) noexcept
	{
		const bool releaseLease = g_armPlayerPoseLease;
		auto* root = g_armPlayerPoseRoot;
		auto* camera = g_armPlayerPoseRestoreCamera;
		auto* targetTree = g_armPlayerPoseTargetTree;
		const auto count = g_armPlayerPoseCount;

		g_armPlayerPoseRoot = nullptr;
		g_armPlayerPoseRestoreCamera = nullptr;
		g_armPlayerPoseTargetTree = nullptr;
		g_armPlayerPoseCount = 0;
		g_armPlayerPoseLease = false;
		if (count == 0) {
			if (releaseLease)
				ReleaseSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
			return;
		}

		bool localsRestored = false;
		__try {
			for (std::uint32_t reverse = count; reverse != 0; --reverse) {
				auto& armed = g_armPlayerPoseBones[reverse - 1];
				auto* effectiveLocal = ResolveFlattenedBoneLocal(targetTree, armed.targetIndex);
				if (!effectiveLocal)
					__leave;
				std::memcpy(
					effectiveLocal,
					std::addressof(armed.gameplayLocal),
					sizeof(RE::NiTransform));
			}
			localsRestored = true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			localsRestored = false;
		}
		if (localsRestored && beforeDownward)
			CompareArmedGameplayPoseNoexcept(targetTree, count, beforeDownward);
		const bool treeRestored = localsRestored && UpdatePlayerPoseRootNoexcept(root, camera);
		if (treeRestored && afterDownward)
			CompareArmedGameplayPoseNoexcept(targetTree, count, afterDownward);
		for (std::uint32_t index = 0; index < count && index < kMaxPlayerNaturalPoseBones; ++index) {
			g_armPlayerPoseBones[index].targetIndex = -1;
			g_armPlayerPoseBones[index].installedLocal = nullptr;
		}
		
		if (releaseLease)
			ReleaseSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
		if (!treeRestored) {
			g_faulted = true;
			static int s_restoreFaultLogs = 0;
			if (s_restoreFaultLogs < 4) {
				++s_restoreFaultLogs;
				logger::error(
					"[MirrorSceneRenderer] player natural-pose restore failed (faultPath={}, locals={}, count={})",
					faultPath, localsRestored, count);
			}
		}
	}

	[[nodiscard]] bool MaterialPlayerCleanupLeaseMatches(
		RE::NiAVObject* cloneRoot, std::uint64_t stateGeneration) noexcept
	{
		if (!g_armPrivatePlayerBodyRenderLease || !cloneRoot || !stateGeneration) return false;
		const auto* resources = ArmedPrivatePlayerResources();
		if (g_armedCompletedPlayerVisual &&
			(!g_selectedPlayerPoses || g_selectedPlayerPoseSlot < 0 ||
				g_selectedPlayerPoseSlot >= MirrorPoseExchange::Slots ||
				g_selectedPlayerPoses->slots[g_selectedPlayerPoseSlot].visual.get() != resources))
			return false;

		return resources && resources->cloneRoot.get() == cloneRoot &&
			resources->stateGeneration == stateGeneration;
	}

	[[nodiscard]] bool ArmMaterialPlayerFlattenedPassCleanup(
		RE::NiAVObject* cloneRoot, std::uint64_t stateGeneration) noexcept
	{
		g_armMaterialPlayerFlattenedRoot = nullptr;
		g_armMaterialPlayerStateGeneration = 0u;
		g_armMaterialPlayerFlattenedGeometryCount = 0u;
		g_armMaterialPlayerFlattenedPropertyCount = 0u;
		std::memset(
			g_armMaterialPlayerFlattenedRepresentatives, 0,
			sizeof(g_armMaterialPlayerFlattenedRepresentatives));
		std::memset(
			g_armMaterialPlayerFlattenedProperties, 0,
			sizeof(g_armMaterialPlayerFlattenedProperties));
		if (!MaterialPlayerCleanupLeaseMatches(cloneRoot, stateGeneration))
			return false;

		bool ready = false;
		__try {
			auto* fadeNode = netimmerse_cast<RE::BSFadeNode*>(cloneRoot);
			const auto geometryCount = fadeNode ?
				static_cast<std::uint32_t>(fadeNode->GetFadeNodeRuntimeData().geomArray.size()) : 0u;
			ready = fadeNode && geometryCount != 0u &&
				geometryCount <= kMaximumMaterialPlayerFlattenedProperties;
			if (ready) {
				auto& geometries = fadeNode->GetFadeNodeRuntimeData().geomArray;
				for (std::uint32_t geometryIndex = 0u; geometryIndex < geometryCount;
					++geometryIndex) {
					auto* geometry = geometries[geometryIndex].geometry.get();
					auto* property = geometry ? geometry->properties[1].get() : nullptr;
					if (!geometry || !property)
						continue;
					bool duplicateProperty = false;
					for (std::uint32_t propertyIndex = 0u;
						propertyIndex < g_armMaterialPlayerFlattenedPropertyCount;
						++propertyIndex) {
						if (g_armMaterialPlayerFlattenedProperties[propertyIndex] == property) {
							duplicateProperty = true;
							break;
						}
					}
					if (duplicateProperty)
						continue;
					const auto propertyIndex = g_armMaterialPlayerFlattenedPropertyCount++;
					g_armMaterialPlayerFlattenedRepresentatives[propertyIndex] = geometry;
					g_armMaterialPlayerFlattenedProperties[propertyIndex] = property;
				}
				ready = ready && g_armMaterialPlayerFlattenedPropertyCount != 0u;
			}
			if (ready) {
				g_armMaterialPlayerFlattenedRoot = cloneRoot;
				g_armMaterialPlayerStateGeneration = stateGeneration;
				g_armMaterialPlayerFlattenedGeometryCount = geometryCount;
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			ready = false;
		}
		if (!ready) {
			g_armMaterialPlayerFlattenedRoot = nullptr;
			g_armMaterialPlayerStateGeneration = 0u;
			g_armMaterialPlayerFlattenedGeometryCount = 0u;
			g_armMaterialPlayerFlattenedPropertyCount = 0u;
			std::memset(
				g_armMaterialPlayerFlattenedRepresentatives, 0,
				sizeof(g_armMaterialPlayerFlattenedRepresentatives));
			std::memset(
				g_armMaterialPlayerFlattenedProperties, 0,
				sizeof(g_armMaterialPlayerFlattenedProperties));
		}
		return ready;
	}

	void DisarmMaterialPlayerFlattenedPassCleanup() noexcept
	{
		g_armMaterialPlayerFlattenedRoot = nullptr;
		g_armMaterialPlayerStateGeneration = 0u;
		g_armMaterialPlayerFlattenedGeometryCount = 0u;
		g_armMaterialPlayerFlattenedPropertyCount = 0u;
		std::memset(
			g_armMaterialPlayerFlattenedRepresentatives, 0,
			sizeof(g_armMaterialPlayerFlattenedRepresentatives));
		std::memset(
			g_armMaterialPlayerFlattenedProperties, 0,
			sizeof(g_armMaterialPlayerFlattenedProperties));
	}

	void PermanentlyQuarantineMaterialAccumulator() noexcept
	{
		g_faulted = true;
		g_materialAccumulatorPermanentlyQuarantined = true;
		if (!g_armPrivatePlayerBodyRenderLease || !g_armMaterialPlayerFlattenedRoot ||
			g_armMaterialPlayerStateGeneration == 0u)
			return;
		if (g_armedCompletedPlayerVisual) {
			
			g_materialQuarantinedCompletedPoses = g_selectedPlayerPoses;
			return;
		}
		auto* resources = g_privatePlayerBody.resources;
		if (resources && resources->cloneRoot.get() == g_armMaterialPlayerFlattenedRoot &&
			resources->stateGeneration == g_armMaterialPlayerStateGeneration) {
			g_materialAccumulatorQuarantinedPlayerResources.store(
				resources, std::memory_order_release);
		}
	}

	void FinishMaterialAccumulatorPassesArmed() noexcept
	{
		if (!g_armMaterialPasses || !g_armMaterialAccumulator)
			return;

		auto clearActivePasses = reinterpret_cast<ClearActivePasses_t>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_ClearActivePasses)).address());
		auto finishAccumulating = reinterpret_cast<Group1_t>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_FinishAccumulatingPostResolveDepth)).address());

		g_armMaterialCleanupInFlight = true;
		g_armMaterialPasses = false;

		bool propertyPassesCleared = !IsMirrorPlanarDrive(g_activeDriveKind);
		if (!propertyPassesCleared) {
			const auto clearRenderPassesAddress =
				REL::Offset(ReflectionRuntime::Rva(kRVA_BSShaderUtil_ClearRenderPasses)).address();
			const auto submittedRootCount = g_privateGroupSubmittedRootCount;
			const bool entryAttested = clearRenderPassesAddress > 0x10000u &&
				std::memcmp(
					reinterpret_cast<const void*>(clearRenderPassesAddress),
					ReflectionRuntime::Prologue(kRVA_BSShaderUtil_ClearRenderPasses, kBSShaderUtilClearRenderPassesBody).data(),
					kBSShaderUtilClearRenderPassesBody.size()) == 0;
			const bool rootSetAttested = entryAttested && submittedRootCount != 0u &&
				submittedRootCount <= kMaximumPrivateGroupSubmissions &&
				!g_privateGroupSubmissionRecordFaulted &&
				PrivateGroupSubmissionsPairwiseSubtreeDisjoint();
			std::uint32_t attemptedRootCount = 0u;
			std::uint32_t clearedRootCount = 0u;
			std::uint32_t expectedFlattenedPropertyCount = 0u;
			std::uint32_t attemptedFlattenedPropertyCount = 0u;
			std::uint32_t clearedFlattenedPropertyCount = 0u;
			std::uint32_t propertyClearFaultCount = 0u;
			const bool flattenedCleanupExpected =
				g_armMaterialPlayerFlattenedRoot != nullptr;
			bool flattenedSetAttested = !flattenedCleanupExpected;
			if (flattenedCleanupExpected) {
				__try {
					auto* fadeNode = MaterialPlayerCleanupLeaseMatches(g_armMaterialPlayerFlattenedRoot,
						g_armMaterialPlayerStateGeneration) ?
						netimmerse_cast<RE::BSFadeNode*>(g_armMaterialPlayerFlattenedRoot) : nullptr;
					expectedFlattenedPropertyCount = g_armMaterialPlayerFlattenedPropertyCount;
					flattenedSetAttested = fadeNode &&
						expectedFlattenedPropertyCount != 0u &&
						expectedFlattenedPropertyCount <=
							kMaximumMaterialPlayerFlattenedProperties;
					auto* geometries = flattenedSetAttested ?
						std::addressof(fadeNode->GetFadeNodeRuntimeData().geomArray) : nullptr;
					flattenedSetAttested = geometries &&
						geometries->size() == g_armMaterialPlayerFlattenedGeometryCount;
					const void* currentProperties[kMaximumMaterialPlayerFlattenedProperties]{};
					std::uint32_t currentPropertyCount = 0u;
					for (std::uint32_t geometryIndex = 0u;
						flattenedSetAttested &&
							geometryIndex < g_armMaterialPlayerFlattenedGeometryCount;
						++geometryIndex) {
						auto* geometry = (*geometries)[geometryIndex].geometry.get();
						auto* property = geometry ? geometry->properties[1].get() : nullptr;
						if (!property)
							continue;
						bool duplicateProperty = false;
						for (std::uint32_t currentIndex = 0u;
							currentIndex < currentPropertyCount; ++currentIndex) {
							if (currentProperties[currentIndex] == property) {
								duplicateProperty = true;
								break;
							}
						}
						if (!duplicateProperty)
							currentProperties[currentPropertyCount++] = property;
					}
					flattenedSetAttested = flattenedSetAttested &&
						currentPropertyCount == expectedFlattenedPropertyCount;
					for (std::uint32_t currentIndex = 0u;
						flattenedSetAttested && currentIndex < currentPropertyCount;
						++currentIndex) {
						bool propertyWasArmed = false;
						for (std::uint32_t armedIndex = 0u;
							armedIndex < expectedFlattenedPropertyCount; ++armedIndex) {
							if (g_armMaterialPlayerFlattenedProperties[armedIndex] ==
								currentProperties[currentIndex]) {
								propertyWasArmed = true;
								break;
							}
						}
						flattenedSetAttested = propertyWasArmed;
					}
					for (std::uint32_t propertyIndex = 0u;
						flattenedSetAttested &&
							propertyIndex < expectedFlattenedPropertyCount;
						++propertyIndex) {
						auto* representative =
							g_armMaterialPlayerFlattenedRepresentatives[propertyIndex];
						auto* expectedProperty =
							g_armMaterialPlayerFlattenedProperties[propertyIndex];
						bool representativeStillFlattened = false;
						if (representative && expectedProperty) {
							for (std::uint32_t geometryIndex = 0u;
								geometryIndex < g_armMaterialPlayerFlattenedGeometryCount;
								++geometryIndex) {
								if ((*geometries)[geometryIndex].geometry.get() == representative) {
									representativeStillFlattened = true;
									break;
								}
							}
						}
						const bool propertyIdentityMatches = representativeStillFlattened &&
							representative->properties[1].get() == expectedProperty;
						flattenedSetAttested = propertyIdentityMatches;
					}
				} __except (EXCEPTION_EXECUTE_HANDLER) {
					flattenedSetAttested = false;
				}
			}
			if (rootSetAttested && flattenedSetAttested) {
				using ClearRenderPasses_t = void (*)(RE::NiAVObject*);
				auto clearRenderPasses = reinterpret_cast<ClearRenderPasses_t>(
					clearRenderPassesAddress);
				for (std::uint32_t rootIndex = 0u; rootIndex < submittedRootCount; ++rootIndex) {
					auto* root = g_privateGroupSubmittedRoots[rootIndex];
					++attemptedRootCount;
					bool rootCleared = false;
					__try {
						clearRenderPasses(root);
						rootCleared = true;
					} __except (EXCEPTION_EXECUTE_HANDLER) {
					}
					if (rootCleared)
						++clearedRootCount;
					else {
						++propertyClearFaultCount;
						break;
					}
				}

				for (std::uint32_t propertyIndex = 0u;
					propertyClearFaultCount == 0u &&
						propertyIndex < expectedFlattenedPropertyCount;
					++propertyIndex) {
					auto* representative = g_armMaterialPlayerFlattenedRepresentatives[
						propertyIndex];
					++attemptedFlattenedPropertyCount;
					bool propertyCleared = false;
					__try {
						clearRenderPasses(representative);
						propertyCleared = true;
					} __except (EXCEPTION_EXECUTE_HANDLER) {
					}
					if (propertyCleared)
						++clearedFlattenedPropertyCount;
					else {
						++propertyClearFaultCount;
						break;
					}
				}
			}
			propertyPassesCleared = rootSetAttested && flattenedSetAttested &&
				attemptedRootCount == submittedRootCount &&
				clearedRootCount == submittedRootCount &&
				attemptedFlattenedPropertyCount == expectedFlattenedPropertyCount &&
				clearedFlattenedPropertyCount == expectedFlattenedPropertyCount &&
				propertyClearFaultCount == 0u;
			if (propertyPassesCleared) {
				static std::uint64_t s_rootCacheClearCount = 0u;
				const auto occurrence = ++s_rootCacheClearCount;
				if (occurrence <= 4u || (occurrence % 600u) == 0u) {
					logger::info(
						"[MirrorSceneRenderer] coherent mirror property pass caches cleared: roots={} "
						"flattenedProperties={} "
						"(occurrence {})",
						submittedRootCount, clearedFlattenedPropertyCount, occurrence);
				}
			} else {
				PermanentlyQuarantineMaterialAccumulator();
				static std::uint32_t s_rootCacheClearFailures = 0u;
				if (s_rootCacheClearFailures++ < 4u) {
					logger::error(
						"[MirrorSceneRenderer] coherent mirror property pass-cache teardown failed: "
						"entry={} rootsAttested={} roots={} attempted={} cleared={} "
						"flattenedAttested={} flattened={}/{} faults={} recordFaulted={}; "
						"private accumulator quarantined and capture disabled",
						entryAttested, rootSetAttested, submittedRootCount, attemptedRootCount,
						clearedRootCount, flattenedSetAttested,
						clearedFlattenedPropertyCount, expectedFlattenedPropertyCount,
						propertyClearFaultCount, g_privateGroupSubmissionRecordFaulted);
				}

				return;
			}
		}

		clearActivePasses(g_armMaterialAccumulator, true);
		finishAccumulating(g_armMaterialAccumulator);

		constexpr std::uintptr_t kMaximumUserAddress = 0x00007FFFFFFFFFFFULL;
		auto plausiblePointer = [](const void* pointer) noexcept {
			const auto address = reinterpret_cast<std::uintptr_t>(pointer);
			return pointer == nullptr ||
				(address > 0x10000u && address <= kMaximumUserAddress &&
					(address & (alignof(void*) - 1u)) == 0u);
		};
		bool sortedRecordValidated = false;
		bool sortedRecordRepaired = false;
		std::uint32_t leakedSortedPassCount = 0u;
		auto* batch = g_armMaterialAccumulator + 0xc8;
		__try {
			auto* record = *reinterpret_cast<std::uint8_t**>(batch + 0x410);
			if (!record) {
				sortedRecordValidated = true;
				sortedRecordRepaired = true;
			} else if (plausiblePointer(record)) {
				auto* head = *reinterpret_cast<void**>(record + 0x08);
				auto* tail = *reinterpret_cast<void**>(record + 0x10);
				const auto flags = *reinterpret_cast<std::uint8_t*>(record + 0x20);
				leakedSortedPassCount = *reinterpret_cast<std::uint32_t*>(record + 0x1c);
				sortedRecordValidated = (flags & 1u) != 0u &&
					plausiblePointer(head) && plausiblePointer(tail);
				if (sortedRecordValidated) {
					*reinterpret_cast<std::uint8_t**>(record + 0x08) = nullptr;
					*reinterpret_cast<std::uint8_t**>(record + 0x10) = nullptr;
					*reinterpret_cast<std::uint32_t*>(record + 0x1c) = 0;
					sortedRecordRepaired =
						*reinterpret_cast<std::uint8_t**>(batch + 0x410) == record &&
						*reinterpret_cast<void**>(record + 0x08) == nullptr &&
						*reinterpret_cast<void**>(record + 0x10) == nullptr &&
						*reinterpret_cast<std::uint32_t*>(record + 0x1c) == 0u &&
						(*reinterpret_cast<std::uint8_t*>(record + 0x20) & 1u) != 0u;
				}
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
		}
		if (!sortedRecordValidated || !sortedRecordRepaired) {
			PermanentlyQuarantineMaterialAccumulator();
			static std::uint32_t s_sortedRecordRepairFailures = 0u;
			if (s_sortedRecordRepairFailures++ < 4u) {
				logger::error(
					"[MirrorSceneRenderer] mode-0x18 sorted-record repair unproven: validated={} repaired={}; "
					"private accumulator quarantined and restart required",
					sortedRecordValidated, sortedRecordRepaired);
			}

			return;
		}
		g_armMaterialCleanupInFlight = false;
		if (leakedSortedPassCount != 0u) {
			static std::uint32_t s_leakClears = 0u;
			const auto clears = ++s_leakClears;
			if (clears <= 4u || (clears % 600u) == 0u) {
				logger::info(
					"[MirrorSceneRenderer] mode-0x18 sorted-record leak cleared: count={} (occurrence {})",
					leakedSortedPassCount, clears);
			}
		}
	}

	void RestoreMaterialAccumulatorState() noexcept
	{

		EndMirrorEyeGroup8WindingOverrideInternal();

		const auto eyeGroup4AlbedoCleanup = FinishEyeGroup4AlbedoOverride();
		if (!eyeGroup4AlbedoCleanup.stateSafe) {
			static std::uint32_t s_eyeGroup4AlbedoFaultCleanupLogs = 0;
			if (s_eyeGroup4AlbedoFaultCleanupLogs++ < 4u)
				logger::error(
					"[MirrorSceneRenderer] EYEGROUP4ALBEDO fault-path PS restoration failed; capture disabled");
			g_faulted = true;
		}

		const auto eyeGroup4NoPixelCleanup = FinishEyeGroup4NoPixelSuppression();
		if (!eyeGroup4NoPixelCleanup.stateSafe) {
			static std::uint32_t s_eyeGroup4NoPixelFaultCleanupLogs = 0;
			if (s_eyeGroup4NoPixelFaultCleanupLogs++ < 4u)
				logger::error(
					"[MirrorSceneRenderer] EYEGROUP4NOPIXEL fault-path PS restoration failed; capture disabled");
			g_faulted = true;
		}

		if (!FinishClothingRedrawPass()) {
			static std::uint32_t s_clothingFaultRestoreLogs = 0;
			if (s_clothingFaultRestoreLogs++ < 4u)
				logger::error("[MirrorSceneRenderer] CLOTHINGREDRAW fault-path cleanup failed; capture disabled");
			g_faulted = true;
		}
		ClearClothingDepthBiasPasses();

		if (!RestoreSkinTintZPrepassFilter()) {
			static std::uint32_t s_skinZFaultRestoreLogs = 0;
			if (s_skinZFaultRestoreLogs++ < 4u)
				logger::error("[MirrorSceneRenderer] SKINZFILTER fault-path restore failed; capture disabled");
			g_faulted = true;
		}

		{
			__try {
				*reinterpret_cast<void**>(REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassShader)).address()) = nullptr;
				*reinterpret_cast<std::uint32_t*>(
					REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassTechnique)).address()) = 0u;
				*reinterpret_cast<void**>(REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassMaterial)).address()) = nullptr;
			} __except (EXCEPTION_EXECUTE_HANDLER) {
			}
		}

		DisarmMirrorEyeForwardRemap();
		ResetMirrorPlayerForwardRemapEvidence();
		
		RestoreEyeDeferredTechniques();
		g_armMirrorEyeHookCount = 0;
		g_armMirrorEyeMode18Count = 0;
		g_armMirrorEyeExactMaterialCount = 0;
		g_armMirrorEyeReflectFlagCount = 0;
		g_armMirrorEyeUnderPlayerCount = 0;
		g_armMirrorEyeFaultCount = 0;
		g_armMirrorEyeRemapCount = 0;
		g_armMirrorEyeFlagOnlyCount = 0;

		bool materialCleanupFaulted = false;
		__try {
			FinishMaterialAccumulatorPassesArmed();
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			materialCleanupFaulted = true;
		}
		const bool materialCleanupIncomplete =
			std::exchange(g_armMaterialCleanupInFlight, false);
		if (materialCleanupFaulted || materialCleanupIncomplete) {
			PermanentlyQuarantineMaterialAccumulator();
			static std::uint32_t s_materialCleanupFaultLogs = 0;
			if (s_materialCleanupFaultLogs++ < 4u) {
				logger::error(
					"[MirrorSceneRenderer] material accumulator native cleanup unsafe: exception={} incomplete={}; "
					"capture disabled and load auto-rearm forbidden",
					materialCleanupFaulted, materialCleanupIncomplete);
			}
		}
		DisarmMaterialPlayerFlattenedPassCleanup();
		if (g_armMaterialAccumulator) {
			*reinterpret_cast<std::uint32_t*>(g_armMaterialAccumulator + 0x560) =
				g_armMaterialAccumulatorModeSaved;
			*(g_armMaterialAccumulator + 0xb1) = g_armMaterialAccumulatorDeferredSaved;
			g_armMaterialAccumulator = nullptr;
		}
		if (g_armMaterialAccumulatorSSN) {
			*g_armMaterialAccumulatorSSN = g_armMaterialAccumulatorSSNSaved;
			g_armMaterialAccumulatorSSN = nullptr;
			g_armMaterialAccumulatorSSNSaved = nullptr;
		}
		if (g_armCurrentAccumulatorPtr) {
			*g_armCurrentAccumulatorPtr = g_armCurrentAccumulatorSaved;
			g_armCurrentAccumulatorPtr = nullptr;
			g_armCurrentAccumulatorSaved = nullptr;
		}
	}

