	void DestroyReflectedLightCullerArmed() noexcept
	{
		void* culler = g_cullProc;
		g_cullProc = nullptr;  
		if (!culler)
			return;
		__try {
			reinterpret_cast<CullProcDtor_t>(REL::Offset(ReflectionRuntime::Rva(kRVA_CullProc_dtor)).address())(culler);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			g_faulted = true;
		}
	}

	void RestoreEngineStateArmed() noexcept
	{

		RestorePrivatePassPoolLeaseArmed();
		RestorePrivateSunDepth();

		g_suppressReflectionMTA = false;
		DestroyReflectedLightCullerArmed();

		RestoreMaterialAccumulatorState();

		g_mirrorRenderActive = false;
		PlanarMirrors::EndCameraOverride();
		CloseFaceCaptureState();
		if (g_planarTarget.Bound())
			g_planarTarget.End(globals::d3d::context);
		if (g_sidePlanarTarget.Bound())
			g_sidePlanarTarget.End(globals::d3d::context);
		if (g_extraPlanarTarget.Bound())
			g_extraPlanarTarget.End(globals::d3d::context);
		if (g_planarRasterizerSaved) {
			if (globals::d3d::context)
				globals::d3d::context->RSSetState(g_planarSavedRasterizer);
			if (g_planarSavedRasterizer)
				g_planarSavedRasterizer->Release();
			g_planarSavedRasterizer = nullptr;
			g_planarRasterizerSaved = false;
		}

		RestoreVisibilityQueryArmed();
		RestoreNativeWorldLivePlayerExclusions();
		if (g_armMirrorRootFlags) {
			*g_armMirrorRootFlags = g_armMirrorRootFlagsSaved;
			g_armMirrorRootFlags = nullptr;
		}
		RestorePrivateAppCullOverrides();
		RestoreFaceGenEyeCullArmed();

		ReleasePrivatePlayerBodyRenderLeaseArmed();

		if (g_rsDirty && g_rsPtr) {
			*reinterpret_cast<std::uint32_t*>(g_rsPtr + kRS_DirtyFlags) |= 4;
			*reinterpret_cast<std::uint32_t*>(g_rsPtr + kRS_ColorMode) = g_rsSavedColor;
			*reinterpret_cast<std::uint32_t*>(g_rsPtr + kRS_DirtyFlags) |= 8;
			*reinterpret_cast<std::uint32_t*>(g_rsPtr + kRS_DepthMode) = g_rsSavedDepth;
			*reinterpret_cast<std::uint32_t*>(g_rsPtr + kRS_DirtyFlags) |= 0x10;
			*reinterpret_cast<std::uint32_t*>(g_rsPtr + kRS_ForwardColorMode) = g_rsSavedForwardColor;
			*reinterpret_cast<std::uint32_t*>(g_rsPtr + kRS_DirtyFlags) |= 8;
			*reinterpret_cast<std::uint32_t*>(g_rsPtr + kRS_ForwardDepthMode) = g_rsSavedForwardDepth;
			auto fnFlush = reinterpret_cast<void (*)(void*)>(REL::Offset(ReflectionRuntime::Rva(kRVA_RendererFlush)).address());
			fnFlush(reinterpret_cast<void*>(REL::Offset(ReflectionRuntime::Rva(kRVA_Renderer)).address()));
			g_rsDirty = false;
		}

		if (g_armOM) {
			if (auto* ctx = globals::d3d::context) {
				ctx->OMSetRenderTargets(8, g_armRTV, g_armDSV);
				if (g_armVPn)
					ctx->RSSetViewports(g_armVPn, g_armVP);
			}
			for (auto& r : g_armRTV) {
				if (r) {
					r->Release();
					r = nullptr;
				}
			}
			if (g_armDSV) {
				g_armDSV->Release();
				g_armDSV = nullptr;
			}
			g_armOM = false;
		}
		
		if (g_armIsMainPtr) {
			*g_armIsMainPtr = g_armIsMainSaved;
			g_armIsMainPtr = nullptr;
		}
		if (g_armCullCamPtr) {
			*g_armCullCamPtr = g_armCullCamSaved;
			g_armCullCamPtr = nullptr;
		}
		
		if (g_armSSNDisablePtr) {
			*g_armSSNDisablePtr = g_armSSNDisableSaved;
			g_armSSNDisablePtr = nullptr;
		}
		
		if (g_armStateObj) {
			if ((g_armStateFlagsSaved & 0x800ull) == 0)
				*reinterpret_cast<std::uint64_t*>(g_armStateObj + 0x108) &= ~0x800ull;
			g_armStateObj = nullptr;
		}
		
		if (g_armClearColor) {
			auto fnRestoreClear = reinterpret_cast<RestoreClear_t>(REL::Offset(ReflectionRuntime::Rva(kRVA_RestoreClear)).address());
			fnRestoreClear(reinterpret_cast<void*>(REL::Offset(ReflectionRuntime::Rva(kRVA_Renderer)).address()));
			g_armClearColor = false;
		}
		
		ReleaseCullList();

		if (g_planarMainCamera) {
			auto* mainCamera = g_planarMainCamera;
			const float cameraFlush = g_planarMainCameraFlush;
			
			g_planarMainCamera = nullptr;
			g_planarMainCameraFlush = 0.0f;
			if (std::isfinite(cameraFlush) && cameraFlush > 0.0f) {
				auto fnCameraData = reinterpret_cast<SetCameraData_t>(
					REL::Offset(ReflectionRuntime::Rva(kRVA_State_SetCameraData)).address());
				fnCameraData(
					reinterpret_cast<void*>(REL::Offset(ReflectionRuntime::Rva(kRVA_GfxState)).address()),
					mainCamera,
					true,
					0.0f,
					cameraFlush);
			}
		}

		g_privateInWorldArmed = false;
		g_privateRenderActive = false;
		
		MirrorSceneRenderer::ReconcileEngineShadowAfterDrive();
		
		RestoreZPrepassSnapshotArmed();
	}
           
