	[[nodiscard]] bool InitializePersistentReflectionCameraLeaf() noexcept
	{
		__try {
			if (g_cam || g_camLifetimePinned)
				return g_cam && g_camLifetimePinned;
			auto fnNew = reinterpret_cast<NiAVObject_new_t>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_NiAVObject_new)).address());
			auto fnCtor = reinterpret_cast<NativeCameraCtor_t>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_NativeCameraCtor)).address());
			void* memory = fnNew(0x1e0);
			if (!memory)
				return false;
			void* constructed = fnCtor(memory, nullptr, nullptr);
			if (!constructed || constructed != memory)
				return false;

			reinterpret_cast<RE::NiRefObject*>(constructed)->IncRefCount();
			g_cam = constructed;
			g_camLifetimePinned = true;
			return true;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return false;
		}
	}

	[[nodiscard]] bool EnsurePersistentReflectionCamera() noexcept
	{
		const bool initializedNow = !g_cam && !g_camLifetimePinned;
		if (!InitializePersistentReflectionCameraLeaf()) {
			static std::uint32_t failureLogs = 0;
			if (++failureLogs <= 8u || (failureLogs % 120u) == 0u) {
				logger::warn(
					"[PlanarMirrors] persistent reflected-camera initialization deferred; native hero prewarm not entered");
			}
			return false;
		}
		if (initializedNow) {
			logger::info(
				"[PlanarMirrors] persistent reflected camera initialized before native hero prewarm");
		}
		return true;
	}

