	constexpr std::uint8_t IncrementNativePlayerInvalidRendererFailures(
		std::uint8_t failures) noexcept
	{
		return failures < kNativePlayerInvalidRendererFailureLimit ?
		           static_cast<std::uint8_t>(failures + 1u) :
		           failures;
	}

	static_assert(IncrementNativePlayerInvalidRendererFailures(0u) == 1u);
	static_assert(IncrementNativePlayerInvalidRendererFailures(1u) == 2u);
	static_assert(IncrementNativePlayerInvalidRendererFailures(2u) == 2u);
	constexpr bool NativePlayerStagePolicyAllows(
		bool ownerUnavailable, bool producerLatched) noexcept
	{
		return !ownerUnavailable && !producerLatched;
	}
	static_assert(NativePlayerStagePolicyAllows(false, false));
	static_assert(!NativePlayerStagePolicyAllows(true, false));
	static_assert(!NativePlayerStagePolicyAllows(false, true));
	static_assert(!NativePlayerStagePolicyAllows(true, true));

	void DisableNativePlayerOwnerForSession(
		DriveKind observedKind, const char* reason, std::uint32_t ownerStatus,
		std::uint32_t captureStatus) noexcept
	{
		if (g_nativePlayerOwnerSession.unavailable)
			return;
		g_nativePlayerOwnerSession.observedKind = observedKind;
		g_nativePlayerOwnerSession.ownerStatus = ownerStatus;
		g_nativePlayerOwnerSession.captureStatus = captureStatus;
		g_nativePlayerOwnerSession.unavailable = true;
		logger::error(
			"[MirrorSceneRenderer] shared native player owner SESSION UNAVAILABLE: observedKind={} reason={} "
			"ownerStatus={} captureStatus={}; every environment drive remains schedulable",
			DriveKindName(observedKind), reason ? reason : "unknown", ownerStatus, captureStatus);
	}

	void RecordNativePlayerOwnerAcquireFailure(
		DriveKind kind, FlatReflectionRendererOwner::Status status) noexcept
	{
		if (status == FlatReflectionRendererOwner::Status::kReleaseFailed) {

			DisableNativePlayerOwnerForSession(
				kind, "owner-release-failed-or-prior-quarantine-observed",
				static_cast<std::uint32_t>(status), 0u);
		}
	}

	void InvalidateFlatNativePlanarStateOnRenderThread(const char* reason) noexcept
	{
		g_flatCameraCacheWarmup = {};
		g_flatCameraCacheWarmupFailureLogs = 0;
		if (!REL::Module::IsVR())
			FlatReflectionRendererOwner::Invalidate(GetCurrentThreadId());
		logger::info("[PlanarMirrors] invalidated flat native player state: {}",
			reason ? reason : "unspecified transition");
	}

	[[nodiscard]] bool EnsureFlatCameraCacheWarm(
		RE::NiCamera* captureCamera, RE::NiCamera*& restoreCamera) noexcept
	{
		restoreCamera = nullptr;
		if (!captureCamera || REL::Module::IsVR() ||
			MirrorSceneRenderer::LoadBlocked() || !globals::d3d::device)
			return false;
		const auto renderThreadId = GetCurrentThreadId();

		restoreCamera = FlatDeferredPlayerCapture::CurrentShaderCamera(renderThreadId);
		if (!restoreCamera || restoreCamera == captureCamera) {
			restoreCamera = nullptr;
			return false;
		}
		const auto loadGeneration = MirrorSceneRenderer::LoadGeneration();
		const auto& cached = g_flatCameraCacheWarmup;
		if (static_cast<bool>(cached.proof) && cached.device == globals::d3d::device &&
			cached.captureCamera == captureCamera && cached.restoreCamera == restoreCamera &&
			cached.loadGeneration == loadGeneration && cached.renderThreadId == renderThreadId)
			return true;

		auto proof = FlatDeferredPlayerCapture::PrewarmCameraCache(
			captureCamera, restoreCamera, renderThreadId);
		if (!static_cast<bool>(proof)) {
			g_flatCameraCacheWarmup = {};
			if (g_flatCameraCacheWarmupFailureLogs++ < 8) {
				spdlog::warn(
					"[DynRefl RTC] native flat camera-cache warmup withheld status={} capture={:p} restore={:p} "
					"runtime={} exe={} bodies={} restoreCurrent={} captureReady={} restoreReady={} "
					"republished={} metadataStable={} entryShader={:p} entryReference={:p} "
					"afterShader={:p} afterReference={:p} verifiedShader={:p} verifiedReference={:p} "
					"cache={:p} capacity={}/{} size={}/{} thread={}",
					static_cast<std::uint32_t>(proof.status), static_cast<void*>(captureCamera),
					static_cast<void*>(restoreCamera), proof.runtimeAttested,
					proof.executableHashAttested, proof.bodyHashesAttested,
					proof.restoreWasCurrentOnEntry, proof.captureEntryReady,
					proof.restoreEntryReady, proof.restoreRepublished,
					proof.metadataStableAfterRepublish,
					reinterpret_cast<void*>(proof.entryShaderCamera),
					reinterpret_cast<void*>(proof.entryStateReferenceCamera),
					reinterpret_cast<void*>(proof.afterShaderCamera),
					reinterpret_cast<void*>(proof.afterStateReferenceCamera),
					reinterpret_cast<void*>(proof.verifiedShaderCamera),
					reinterpret_cast<void*>(proof.verifiedStateReferenceCamera),
					reinterpret_cast<void*>(proof.cacheData), proof.cacheCapacity,
					proof.verifiedCacheCapacity, proof.cacheSize, proof.verifiedCacheSize,
					proof.renderThreadId);
			}
			return false;
		}
		g_flatCameraCacheWarmup.proof = proof;
		g_flatCameraCacheWarmup.device = globals::d3d::device;
		g_flatCameraCacheWarmup.captureCamera = captureCamera;
		g_flatCameraCacheWarmup.restoreCamera = restoreCamera;
		g_flatCameraCacheWarmup.loadGeneration = loadGeneration;
		g_flatCameraCacheWarmup.renderThreadId = renderThreadId;
		return true;
	}
