	[[nodiscard]] bool ObserveNativeHeroWorldPasses(
		void* opaqueContext,
		const FlatDeferredPlayerCapture::NativeWorldPassAccumulationView& view,
		std::uint32_t* failureCode) noexcept
	{
		if (failureCode)
			*failureCode = 0u;
		auto fail = [failureCode](std::uint32_t code) noexcept {
			if (failureCode)
				*failureCode = code;
			return false;
		};
		auto* context = static_cast<NativeHeroDriveContext*>(opaqueContext);
		if (!context || !context->ownerAcquired || context->ownerFinished ||
			context->passAccumulationCompleted || context->passCensusAttested)
			return fail(1u);
		if (!context->passAccumulatorIdentity || !view.cullingProcess ||
			!g_armMaterialPasses || view.exclusiveAccumulator != context->passAccumulatorIdentity)
			return fail(2u);
		if (view.captureCamera != context->request.captureCamera.get() ||
			view.privateShadowSceneNode != context->ownerLease.shadowSceneNode.get() ||
			view.ownerIdentitySerial != context->ownerGeneration ||
			view.preparedAccumulatorSerial != context->preparedAccumulatorSerial ||
			view.frameSerial != context->frameSerial)
			return fail(3u);

		for (std::uint32_t index = 0; index < context->callback.submittedRootCount; ++index) {
			if (!context->callback.submittedRoots[index])
				return fail(9u);
		}
		context->passAccumulationCompleted = true;

		RestorePrivateAppCullOverrides();
		g_suppressReflectionMTA = false;
		DisarmMirrorEyeForwardRemap();

		context->accumulatedPassStats = InspectPlayerPassChains(
			view.exclusiveAccumulator, context->passPlayerRoot, context->passFaceRoot,
			context->passExactRugRoot, context->passReceiverRoot);

		const auto& stats = context->accumulatedPassStats;
		if (!context->passEnvironmentScopeReady || stats.malformed || stats.receiverPasses != 0u ||
			stats.truncatedChains != 0u)
			return fail(4u);
		if (stats.environmentPasses == 0u)
			return fail(5u);
		if (context->passPlayerRequired &&
			(!context->passPlayerSubmitted || !context->passDrawRequirements.Covered(
				stats.playerPasses, stats.facePasses, stats.nonFacePlayerPasses,
				stats.faceSkinMaterialPasses, stats.faceSkinMaterialPasses)))
			return fail(6u);
		if (!PrivateGroupSubmissionsPairwiseSubtreeDisjoint())
			return fail(7u);
		context->passCensusAttested = true;
		return true;
	}

