	struct PendingMirrorAttachEvent
	{
		RE::ObjectRefHandle handle{};
		RE::TESFormID formID{ 0 };
		bool attached{ false };
	};

	constexpr std::size_t kMaximumPendingMirrorAttachEvents = 65536;
	constexpr std::size_t kMaximumAttachedRegisteredMirrors = 4096;
	SRWLOCK g_mirrorAttachQueueLock = SRWLOCK_INIT;
	std::vector<PendingMirrorAttachEvent> g_pendingMirrorAttachEvents;
	std::atomic<std::uint32_t> g_droppedMirrorAttachEvents{ 0 };

	void QueueRegisteredMirrorAttachEvent(PendingMirrorAttachEvent pending) noexcept
	{
		if (pending.formID == 0 || (pending.attached && !pending.handle))
			return;

		AcquireSRWLockExclusive(std::addressof(g_mirrorAttachQueueLock));
		try {

			const std::size_t recentCount = (std::min)(g_pendingMirrorAttachEvents.size(), std::size_t{ 128 });
			auto recentBegin = g_pendingMirrorAttachEvents.end() - static_cast<std::ptrdiff_t>(recentCount);
			auto existing = std::find_if(
				recentBegin, g_pendingMirrorAttachEvents.end(),
				[&](const auto& queued) noexcept { return queued.formID == pending.formID; });
			if (existing != g_pendingMirrorAttachEvents.end()) {
				*existing = std::move(pending);
			} else if (g_pendingMirrorAttachEvents.size() < kMaximumPendingMirrorAttachEvents) {
				g_pendingMirrorAttachEvents.push_back(std::move(pending));
			} else {
				g_droppedMirrorAttachEvents.fetch_add(1, std::memory_order_relaxed);
			}
		} catch (...) {
			g_droppedMirrorAttachEvents.fetch_add(1, std::memory_order_relaxed);
		}
		ReleaseSRWLockExclusive(std::addressof(g_mirrorAttachQueueLock));
	}

	std::atomic<std::uint64_t> g_sceneReferenceGeneration{ 1 };
	class RegisteredMirrorAttachSink final : public RE::BSTEventSink<RE::TESCellAttachDetachEvent>
	{
	public:
		RE::BSEventNotifyControl ProcessEvent(
			const RE::TESCellAttachDetachEvent& event,
			RE::BSTEventSource<RE::TESCellAttachDetachEvent>*) override
		{
			g_sceneReferenceGeneration.fetch_add(1u, std::memory_order_relaxed);
			auto* reference = event.reference.get();
			if (!reference)
				return RE::BSEventNotifyControl::kContinue;
			PendingMirrorAttachEvent pending{
				reference->GetHandle(), reference->GetFormID(), event.attached
			};

			if (pending.formID == 0 || (pending.attached && !pending.handle))
				return RE::BSEventNotifyControl::kContinue;
			QueueRegisteredMirrorAttachEvent(std::move(pending));
			return RE::BSEventNotifyControl::kContinue;
		}
	};

