	bool MirrorHybridPlanesMatch(
		const PlanarMirrorMath::Plane& left,
		const PlanarMirrorMath::Plane& right) noexcept
	{
		return std::isfinite(left.distance) && std::isfinite(right.distance) &&
			std::fabs(left.normal.x - right.normal.x) <= 1.0e-5f &&
			std::fabs(left.normal.y - right.normal.y) <= 1.0e-5f &&
			std::fabs(left.normal.z - right.normal.z) <= 1.0e-5f &&
			std::fabs(left.distance - right.distance) <= 0.01f;
	}

	bool MirrorHybridRoutesMatch(const MirrorRouteState& left, const MirrorRouteState& right) noexcept
	{
		if (!left.valid || !right.valid || left.firstVertex != right.firstVertex ||
			left.vertexCount != right.vertexCount || left.authoredContour != right.authoredContour)
			return false;
		const auto nearlyEqual = [](float a, float b) noexcept {
			return std::isfinite(a) && std::isfinite(b) && std::fabs(a - b) <= 1.0e-4f;
		};
		return nearlyEqual(left.center.x, right.center.x) && nearlyEqual(left.center.y, right.center.y) &&
			nearlyEqual(left.center.z, right.center.z) && nearlyEqual(left.normal.x, right.normal.x) &&
			nearlyEqual(left.normal.y, right.normal.y) && nearlyEqual(left.normal.z, right.normal.z) &&
			nearlyEqual(left.halfThickness, right.halfThickness) &&
			nearlyEqual(left.halfWidth, right.halfWidth) &&
			nearlyEqual(left.halfHeight, right.halfHeight) &&
			nearlyEqual(left.ellipseMask, right.ellipseMask);
	}

	void InvalidateMirrorHybridTransaction(DriveKind kind, const char* reason) noexcept
	{
		if (!IsMirrorPlanarDrive(kind))
			return;
		if (IsBathroomMirrorPlanarDrive(kind))
			g_planarPlayerRefreshPending = false;
		auto& transaction = ActiveMirrorHybridTransaction(kind);
		if (transaction.valid && transaction.purpose == MirrorHybridTransactionPurpose::kPendingCoverage &&
			transaction.coverageProofSerial != 0) {
			(void)ActivePlanarTarget(kind).DiscardRetainedMaterialCoverageProof(
				transaction.coverageProofSerial);
		}
		if (transaction.valid && reason) {
			logger::info(
				"[PlanarMirrors] HYBRID transaction {} invalidated: kind={} {}; committed image retained",
				transaction.serial, DriveKindName(kind), reason);
		}
		transaction = {};
	}

	void InvalidateAllMirrorHybridTransactions(const char* reason) noexcept
	{
		InvalidateMirrorHybridTransaction(DriveKind::kPlanarMirror, reason);
		InvalidateMirrorHybridTransaction(DriveKind::kPlanarSideMirror, reason);
		InvalidateMirrorHybridTransaction(DriveKind::kPlanarExtraMirror, reason);
	}

