	CameraRefreshSample CaptureCameraRefreshSample(const RE::NiPoint3& fallbackEye) noexcept
	{
		CameraRefreshSample result{};
		result.eye = fallbackEye;
		auto* playerCamera = RE::PlayerCamera::GetSingleton();
		auto* cameraRoot = playerCamera ? playerCamera->cameraRoot.get() : nullptr;
		if (!cameraRoot)
			return result;
		result.eye = cameraRoot->world.translate;
		const auto& rotate = cameraRoot->world.rotate;

		result.basis = {
			rotate.entry[0].z, rotate.entry[1].z, rotate.entry[2].z,
			rotate.entry[0].y, rotate.entry[1].y, rotate.entry[2].y,
			rotate.entry[0].x, rotate.entry[1].x, rotate.entry[2].x
		};
		result.valid = std::isfinite(result.eye.x) && std::isfinite(result.eye.y) &&
			std::isfinite(result.eye.z);
		for (const float coefficient : result.basis)
			result.valid = result.valid && std::isfinite(coefficient);
		return result;
	}

	bool CameraRefreshSampleChanged(
		const CameraRefreshSample& current, const CameraRefreshSample& previous,
		float positionThreshold, float basisDeltaSqThreshold) noexcept
	{
		if (!current.valid || !previous.valid)
			return current.valid != previous.valid;
		if (current.eye.GetSquaredDistance(previous.eye) > positionThreshold * positionThreshold)
			return true;
		float basisDeltaSq = 0.0f;
		for (std::size_t index = 0; index < current.basis.size(); ++index) {
			const float delta = current.basis[index] - previous.basis[index];
			basisDeltaSq += delta * delta;
		}
		return basisDeltaSq > basisDeltaSqThreshold;
	}

	constexpr bool ContinuousMirrorRefreshReady(
		bool dirty, bool queuePending, std::uint64_t nowMs,
		std::uint64_t lastArmMs, std::uint64_t intervalMs) noexcept
	{
		return dirty && !queuePending &&
			(lastArmMs == 0u || nowMs - lastArmMs >= intervalMs);
	}

	constexpr bool IdleMirrorRefreshReady(
		bool active, bool queuePending, std::uint64_t nowMs,
		std::uint64_t lastPublicationMs, std::uint64_t lastArmMs,
		std::uint64_t intervalMs) noexcept
	{

		return active && !queuePending && lastPublicationMs != 0u &&
			lastPublicationMs >= lastArmMs && nowMs - lastPublicationMs >= intervalMs;
	}

	static_assert(!ContinuousMirrorRefreshReady(true, true, 1167u, 1000u, 167u));
	static_assert(!ContinuousMirrorRefreshReady(true, false, 1166u, 1000u, 167u));
	static_assert(ContinuousMirrorRefreshReady(true, false, 1167u, 1000u, 167u));
	static_assert(!IdleMirrorRefreshReady(true, false, 1500u, 0u, 1000u, 500u));
	static_assert(!IdleMirrorRefreshReady(true, false, 1500u, 999u, 1000u, 500u));
	static_assert(!IdleMirrorRefreshReady(true, false, 1499u, 1000u, 1000u, 500u));
	static_assert(IdleMirrorRefreshReady(true, false, 1500u, 1000u, 1000u, 500u));

	bool ObserveContinuousMirrorCameraRefresh(
		SettledCameraRefreshState& state, const CameraRefreshSample& current,
		float positionThreshold, bool queuePending, std::uint64_t nowMs,
		std::uint64_t intervalMs) noexcept
	{
		if (!current.valid) {
			state.sampleValid = false;
			state.dirty = false;
			return false;
		}
		if (!state.sampleValid) {
			state.sample = current;
			state.sampleValid = true;
			return false;
		}
		if (CameraRefreshSampleChanged(
				current, state.sample, positionThreshold, kPlanarCameraBasisDeltaSq)) {
			state.sample = current;
			state.dirty = true;
		}
		if (!ContinuousMirrorRefreshReady(
				state.dirty, queuePending, nowMs, state.lastArmTickMs, intervalMs))
			return false;
		state.dirty = false;
		state.stableFrames = 0;
		state.dirtySinceTickMs = 0;
		state.lastArmTickMs = nowMs;
		return true;
	}

