	constexpr std::uint8_t Mode18CaptureAttemptLimit(DriveKind kind) noexcept
	{
		if (IsBathroomMirrorPlanarDrive(kind))
			return kMode18HeroMirrorAttemptLimit;
		if (IsAuxiliaryMirrorPlanarDrive(kind))
			return kMode18AuxiliaryMirrorAttemptLimit;
		return 0u;
	}

	bool IsBoundedMode18Drive(DriveKind kind) noexcept
	{
		return IsMirrorPlanarDrive(kind);
	}

	std::uint8_t& Mode18CaptureAttemptCount(DriveKind kind) noexcept
	{
		if (IsBathroomMirrorPlanarDrive(kind))
			return g_mode18CaptureBudget.heroMirrorAttempts;
		if (IsSideMirrorPlanarDrive(kind))
			return g_mode18CaptureBudget.sideMirrorAttempts;
		if (IsExtraMirrorPlanarDrive(kind))
			return g_mode18CaptureBudget.extraMirrorAttempts;
		return g_mode18CaptureBudget.heroMirrorAttempts;
	}

	bool Mode18CaptureAttemptAvailable(DriveKind kind) noexcept
	{
		if (!IsBoundedMode18Drive(kind))
			return true;
		if (IsBathroomMirrorPlanarDrive(kind) &&
			g_mode18CaptureBudget.heroMirrorPlayerDeferrals >= kMode18MirrorPlayerDeferralLimit)
			return false;
		if (IsSideMirrorPlanarDrive(kind) &&
			g_mode18CaptureBudget.sideMirrorPlayerDeferrals >= kMode18MirrorPlayerDeferralLimit)
			return false;
		if (IsExtraMirrorPlanarDrive(kind) &&
			g_mode18CaptureBudget.extraMirrorPlayerDeferrals >= kMode18MirrorPlayerDeferralLimit)
			return false;
		return Mode18CaptureAttemptCount(kind) < Mode18CaptureAttemptLimit(kind);
	}

	void OpenMode18CaptureGeneration(const char* reason) noexcept
	{
		for (auto& mirrorGeneration : g_mirrorHybridProducerGenerations)
			++mirrorGeneration;
		InvalidateAllMirrorHybridTransactions(reason ? reason : "global producer generation reopened");
		++g_mode18CaptureBudget.generation;
		g_mode18CaptureBudget.heroMirrorAttempts = 0;
		g_mode18CaptureBudget.sideMirrorAttempts = 0;
		g_mode18CaptureBudget.extraMirrorAttempts = 0;
		g_mode18CaptureBudget.heroMirrorPlayerDeferrals = 0;
		g_mode18CaptureBudget.sideMirrorPlayerDeferrals = 0;
		g_mode18CaptureBudget.extraMirrorPlayerDeferrals = 0;
		logger::info(
			"[PlanarMirrors] bounded generation {} opened by {} (hero={} side={} extra={})",
			g_mode18CaptureBudget.generation, reason ? reason : "unknown",
			static_cast<std::uint32_t>(kMode18HeroMirrorAttemptLimit),
			static_cast<std::uint32_t>(kMode18AuxiliaryMirrorAttemptLimit),
			static_cast<std::uint32_t>(kMode18AuxiliaryMirrorAttemptLimit));
	}

	void OpenMode18CaptureProducerGeneration(
		DriveKind kind, const char* reason, RE::TESFormID receiverFormID = 0) noexcept
	{
		if (IsMirrorPlanarDrive(kind)) {
			++ActiveMirrorHybridProducerGeneration(kind);
			InvalidateMirrorHybridTransaction(kind, reason ? reason : "producer generation reopened");
		}
		const bool exactEyeProofBudgetRearmed = IsMirrorPlanarDrive(kind) &&
			EyeGroup4AutomaticProofRetrySuppressed();

		if (exactEyeProofBudgetRearmed) {
			g_eyeGroup4AutomaticProofBudget.attempts = 0;
		}
		++g_mode18CaptureBudget.generation;
		if (IsBathroomMirrorPlanarDrive(kind)) {
			g_mode18CaptureBudget.heroMirrorAttempts = 0;
			g_mode18CaptureBudget.heroMirrorPlayerDeferrals = 0;
		} else if (IsSideMirrorPlanarDrive(kind)) {
			g_mode18CaptureBudget.sideMirrorAttempts = 0;
			g_mode18CaptureBudget.sideMirrorPlayerDeferrals = 0;
		} else if (IsExtraMirrorPlanarDrive(kind)) {
			g_mode18CaptureBudget.extraMirrorAttempts = 0;
			g_mode18CaptureBudget.extraMirrorPlayerDeferrals = 0;
		} else {
			return;
		}
		bool logProducerReopen = true;
		if (reason &&
			(std::strcmp(reason, "continuous camera pose movement") == 0 ||
				std::strcmp(reason, "bounded idle player animation") == 0 ||
				std::strcmp(reason, "mirror reference changed") == 0 ||
				std::strcmp(reason, "receiver refresh deadline") == 0 ||
				std::strcmp(reason, "mirror visibility/plane change") == 0 ||
				std::strcmp(reason, "standard mirror 0 visibility/plane change") == 0 ||
				std::strcmp(reason, "standard mirror 1 visibility/plane change") == 0)) {
			static std::uint64_t s_heroCadenceReopenEvents = 0;
			logProducerReopen = ShouldLogHeroMirrorCadenceEvent(++s_heroCadenceReopenEvents);
		}
		if (logProducerReopen) {
			logger::info(
				"[PlanarMirrors] mode-0x18 producer generation {} reopened: kind={} reason={}",
				g_mode18CaptureBudget.generation, DriveKindName(kind), reason ? reason : "unknown");
		}
		if (exactEyeProofBudgetRearmed && logProducerReopen) {
			logger::info(
				"[PlanarMirrors] bounded exact-eye proof budget rearmed: generation={} kind={} queries={}; "
				"prior committed image retained",
				g_mode18CaptureBudget.generation, DriveKindName(kind),
				static_cast<std::uint32_t>(kEyeGroup4AutomaticProofQueryLimit));
		}
	}

	bool ClaimMode18CaptureAttempt(DriveKind kind) noexcept
	{
		if (!IsBoundedMode18Drive(kind))
			return true;
		auto& attempts = Mode18CaptureAttemptCount(kind);
		const auto limit = Mode18CaptureAttemptLimit(kind);
		if (attempts >= limit)
			return false;
		++attempts;
		const std::uint64_t generation = g_mode18CaptureBudget.generation;
		static std::uint64_t s_mirrorCadenceAttemptEvents = 0;
		const bool logAttempt = ShouldLogHeroMirrorCadenceEvent(++s_mirrorCadenceAttemptEvents);
		if (logAttempt) {
			logger::info(
				"[MirrorSceneRenderer] mode-0x18 bounded attempt: generation={} kind={} attempt={}/{}",
				generation, static_cast<unsigned>(kind), attempts, limit);
		}
		return true;
	}

	std::uint32_t g_mirrorYieldUntilFrame = 0;
	constexpr std::uint32_t kPreflightDeferralYieldFrames = 8u;

	constexpr bool MirrorPlayerPublicationReady(
		bool playerRequired, int facesRendered, int playerSubmitted,
		std::uint8_t playerRootPassFaceMask) noexcept
	{
		return !playerRequired || (facesRendered > 0 && playerSubmitted != 0 &&
			playerRootPassFaceMask != 0u);
	}

	constexpr bool MirrorEyePublicationReady(
		int exactEyeCommitWithheld, std::uint32_t albedoRejectReason) noexcept
	{
		return exactEyeCommitWithheld == 0 &&
			albedoRejectReason == static_cast<std::uint32_t>(EyeGroup4AlbedoRejectReason::kNone);
	}

	static_assert(MirrorEyePublicationReady(
		0, static_cast<std::uint32_t>(EyeGroup4AlbedoRejectReason::kNone)));
	static_assert(!MirrorEyePublicationReady(
		1, static_cast<std::uint32_t>(EyeGroup4AlbedoRejectReason::kNone)));
	static_assert(!MirrorEyePublicationReady(
		1, static_cast<std::uint32_t>(EyeGroup4AlbedoRejectReason::kAmbiguousExactTarget)));

	std::uint8_t& Mode18MirrorPlayerDeferralCount(DriveKind kind) noexcept
	{
		if (IsSideMirrorPlanarDrive(kind))
			return g_mode18CaptureBudget.sideMirrorPlayerDeferrals;
		if (IsExtraMirrorPlanarDrive(kind))
			return g_mode18CaptureBudget.extraMirrorPlayerDeferrals;
		return g_mode18CaptureBudget.heroMirrorPlayerDeferrals;
	}

	bool RecordMode18MirrorPlayerDeferral(
		DriveKind kind, bool playerRequired, int facesRendered,
		int playerSubmitted, std::uint8_t playerRootPassFaceMask,
		int eyeExactProofWarmup, int eyeExactCommitWithheld,
		std::uint32_t eyeAlbedoRejectReason,
		std::uint32_t nativePlayerCaptureStatus) noexcept
	{
		const bool missingRequiredPlayer = !MirrorPlayerPublicationReady(
			playerRequired, facesRendered, playerSubmitted, playerRootPassFaceMask);

		const bool exactEyeCommitDeferred =
			eyeExactCommitWithheld != 0 && IsBathroomMirrorPlanarDrive(kind);
		const bool resourcePoolWarmingDeferred = playerRequired && facesRendered <= 0 &&
			nativePlayerCaptureStatus == static_cast<std::uint32_t>(
				FlatDeferredPlayerCapture::Status::kResourcePoolWarming);
		if (!IsMirrorPlanarDrive(kind) ||
			(!missingRequiredPlayer && !exactEyeCommitDeferred && !resourcePoolWarmingDeferred))
			return false;

		if (facesRendered <= 0 && !exactEyeCommitDeferred && !resourcePoolWarmingDeferred)
			return false;
		auto& attempts = Mode18CaptureAttemptCount(kind);
		if (attempts > 0)
			--attempts;
		auto& deferrals = Mode18MirrorPlayerDeferralCount(kind);
		if (deferrals < kMode18MirrorPlayerDeferralLimit)
			++deferrals;
		if (resourcePoolWarmingDeferred)
			g_mirrorYieldUntilFrame = GetRenderFrame() + kPreflightDeferralYieldFrames;
		const auto rejectReason = static_cast<EyeGroup4AlbedoRejectReason>(eyeAlbedoRejectReason);
		const char* deferralReason = rejectReason != EyeGroup4AlbedoRejectReason::kNone ?
			EyeGroup4AlbedoRejectReasonName(rejectReason) :
			(resourcePoolWarmingDeferred ? "resource-pool-warming" :
			(exactEyeCommitDeferred ?
				(eyeExactProofWarmup != 0 ? "eye-proof" : "eye-commit") : "missing-player"));
		logger::info(
			"[PlanarMirrors] bounded publication retry retained prior image: kind={} reason={} deferral={}/{} "
			"faces={} submitted={} playerRootMask=0x{:02X} eyeCommit={} eyeRejectReason={}({})",
			DriveKindName(kind), deferralReason,
			static_cast<std::uint32_t>(deferrals),
			static_cast<std::uint32_t>(kMode18MirrorPlayerDeferralLimit), facesRendered,
			playerSubmitted, static_cast<unsigned>(playerRootPassFaceMask),
			exactEyeCommitDeferred ? "withheld" : "ready", eyeAlbedoRejectReason,
			EyeGroup4AlbedoRejectReasonName(rejectReason));
		return true;
	}

	void ReturnUntouchedMode18MirrorAttempt(DriveKind kind) noexcept
	{
		if (!IsMirrorPlanarDrive(kind))
			return;
		auto& attempts = Mode18CaptureAttemptCount(kind);
		if (attempts > 0)
			--attempts;
		static std::uint64_t returnedAttempts = 0;
		if (ShouldLogHeroMirrorCadenceEvent(++returnedAttempts))
			logger::info(
				"[PlanarMirrors] untouched environment preflight returned unused mode-0x18 attempt: kind={} attempts={}/{} total={}",
				DriveKindName(kind), attempts, Mode18CaptureAttemptLimit(kind), returnedAttempts);
	}

	static_assert(MirrorPlayerPublicationReady(false, 1, 0, 0u));
	static_assert(!MirrorPlayerPublicationReady(true, 1, 0, 0u));
	static_assert(!MirrorPlayerPublicationReady(true, 1, 1, 0u));
	static_assert(MirrorPlayerPublicationReady(true, 1, 1, 0x04u));

	void CloseExhaustedMode18Queue(DriveKind kind) noexcept
	{
		if (IsMirrorPlanarDrive(kind)) {
			const auto& transaction = ActiveMirrorHybridTransaction(kind);
			if (transaction.valid &&
				transaction.purpose == MirrorHybridTransactionPurpose::kPendingCoverage)
				return;
		}
		if (!IsBoundedMode18Drive(kind) || Mode18CaptureAttemptAvailable(kind))
			return;
		if (IsBathroomMirrorPlanarDrive(kind))
			g_planarRefreshPending = false;
		else if (IsSideMirrorPlanarDrive(kind))
			g_sidePlanarRefreshPending = false;
		else if (IsExtraMirrorPlanarDrive(kind))
			g_extraPlanarRefreshPending = false;
	}

