	constexpr bool SideMirrorViewPassesHysteresis(
		bool wasVisible,
		float facingCosine,
		float absolutePlaneDistance,
		float halfThickness) noexcept
	{
		(void)halfThickness;
		return wasVisible ?
			(facingCosine >= kSideMirrorFacingExit &&
				absolutePlaneDistance > kSideMirrorDepthExitGuard) :
			(facingCosine >= kSideMirrorFacingEnter &&
				absolutePlaneDistance > kSideMirrorDepthEnterGuard);
	}

