	static_assert(SideMirrorViewPassesHysteresis(false, 0.0011f, 0.011f, 0.924f));
	static_assert(SideMirrorViewPassesHysteresis(true, 0.0006f, 0.006f, 0.924f));
	static_assert(!SideMirrorViewPassesHysteresis(true, 0.0004f, 20.0f, 0.924f));
