	[[nodiscard]] bool TemporalConsumerPresent() noexcept
	{
		static std::uint64_t s_lastPollTick = 0u;
		static bool s_present = false;
		const auto now = GetTickCount64();
		if (s_lastPollTick == 0u || now - s_lastPollTick >= 2000u) {
			s_lastPollTick = now;
			if (GetFileAttributesW(L"Data\\dynref_nopanepin") != INVALID_FILE_ATTRIBUTES) {
				s_present = false;
			} else {
				static constexpr const wchar_t* kTemporalModules[]{
					L"amd_fidelityfx_framegeneration_dx12.dll", L"sl.dlss_g.dll", L"nvngx_dlssg.dll",
					L"amd_fidelityfx_upscaler_dx12.dll", L"sl.dlss.dll", L"nvngx_dlss.dll",
					L"sl.interposer.dll" };
				s_present = GetFileAttributesW(L"Data\\dynref_panepin") != INVALID_FILE_ATTRIBUTES;
				for (const auto* name : kTemporalModules)
					s_present = s_present || GetModuleHandleW(name) != nullptr;
			}
		}
		return s_present;
	}

