	constexpr std::uint32_t kPlanarMirrorRectangleVertexCount = 6;
	constexpr std::array<PlanarMirrorPresentationVertex, kPlanarMirrorRectangleVertexCount>
		kPlanarMirrorRectangleVertices{ {
			{ -1.0f, -1.0f },
			{ 1.0f, -1.0f },
			{ -1.0f, 1.0f },
			{ -1.0f, 1.0f },
			{ 1.0f, -1.0f },
			{ 1.0f, 1.0f }
		} };
	constexpr std::size_t kPlanarMirrorAuthoredVertexCount =
		PlanarMirrorSilhouetteData::kTriangleCount * 3u;
	constexpr std::size_t kPlanarMirrorPresentationVertexCount =
		kPlanarMirrorRectangleVertexCount + kPlanarMirrorAuthoredVertexCount;

	constexpr auto BuildPlanarMirrorPresentationVertices() noexcept
	{
		std::array<PlanarMirrorPresentationVertex, kPlanarMirrorPresentationVertexCount> vertices{};
		for (std::size_t index = 0; index < kPlanarMirrorRectangleVertices.size(); ++index)
			vertices[index] = kPlanarMirrorRectangleVertices[index];
		std::size_t destination = kPlanarMirrorRectangleVertexCount;
		for (const auto& triangle : PlanarMirrorSilhouetteData::kTriangles) {
			vertices[destination++] = triangle.a;
			vertices[destination++] = triangle.b;
			vertices[destination++] = triangle.c;
		}
		return vertices;
	}

	inline constexpr auto kPlanarMirrorPresentationVertices = BuildPlanarMirrorPresentationVertices();
	static_assert(kPlanarMirrorPresentationVertices.size() == 17811u);

	const char* DriveKindName(DriveKind kind) noexcept
	{
		switch (kind) {
		case DriveKind::kPlanarMirror:
			return "mirror";
		case DriveKind::kPlanarSideMirror:
			return "standard mirror 0";
		case DriveKind::kPlanarExtraMirror:
			return "standard mirror 1";
		default:
			return "normal";
		}
	}

	PlanarMirrors::RenderTarget& ActivePlanarTarget(DriveKind kind) noexcept
	{
		if (IsSideMirrorPlanarDrive(kind))
			return g_sidePlanarTarget;
		if (IsExtraMirrorPlanarDrive(kind))
			return g_extraPlanarTarget;
		return g_planarTarget;
	}

	bool EnsurePlanarMaterialResolveShader() noexcept
	{
		auto* device = globals::d3d::device;
		if (!device)
			return false;
		if (device != g_planarMaterialResolveDevice) {
			if (g_planarMaterialResolveCS)
				g_planarMaterialResolveCS->Release();
			g_planarMaterialResolveCS = nullptr;
			g_planarMaterialResolveDevice = device;
			g_planarMaterialResolveCompileAttempted = false;
			g_planarMaterialResolveRetryNotBeforeMs = 0;
		}
		if (g_planarMaterialResolveCS)
			return true;
		const std::uint64_t nowMs = GetTickCount64();
		if (g_planarMaterialResolveCompileAttempted) {
			if (nowMs < g_planarMaterialResolveRetryNotBeforeMs)
				return false;
			g_planarMaterialResolveCompileAttempted = false;
		}

		g_planarMaterialResolveCompileAttempted = true;
		g_planarMaterialResolveRetryNotBeforeMs = nowMs + 1000u;
		g_planarMaterialResolveCS = static_cast<ID3D11ComputeShader*>(
			Util::CompileShader(
				L"Data\\Shaders\\MirrorsOfFallout\\PlanarMaterialResolveCS.hlsl", {}, "cs_5_0"));

		if (device != g_planarMirrorLightTilesDevice) {
			if (g_planarMirrorLightTilesCS) g_planarMirrorLightTilesCS->Release();
			g_planarMirrorLightTilesCS = nullptr;
			g_planarMirrorLightTilesDevice = device;
			g_planarMirrorLightTilesCompileAttempted = false;
		}
		if (!g_planarMirrorLightTilesCS && !g_planarMirrorLightTilesCompileAttempted) {
			g_planarMirrorLightTilesCompileAttempted = true;
			g_planarMirrorLightTilesCS = static_cast<ID3D11ComputeShader*>(
				Util::CompileShader(
					L"Data\\Shaders\\MirrorsOfFallout\\PlanarMirrorLightTilesCS.hlsl", {}, "cs_5_0"));
			logger::info("[MirrorSceneRenderer] per-tile light cull {}",
				g_planarMirrorLightTilesCS ? "compiled" : "unavailable; resolve shades every light per pixel");
		}
		if (!g_planarMaterialResolveCS) {
			logger::error("[MirrorSceneRenderer] PlanarMaterialResolveCS compile failed; private material capture disabled");
			return false;
		}
		g_planarMaterialResolveRetryNotBeforeMs = 0;
		logger::info("[PlanarMirrors] compiled private mode-0x18 material resolve shader");
		return true;
	}

	bool EnsurePlanarMirrorPlayerOverlayResolveShader() noexcept
	{
		auto* device = globals::d3d::device;
		if (!device)
			return false;
		if (device != g_planarMirrorPlayerOverlayResolveDevice) {
			if (g_planarMirrorPlayerOverlayResolveCS)
				g_planarMirrorPlayerOverlayResolveCS->Release();
			g_planarMirrorPlayerOverlayResolveCS = nullptr;
			g_planarMirrorPlayerOverlayResolveDevice = device;
			g_planarMirrorPlayerOverlayResolveCompileAttempted = false;
		}
		if (g_planarMirrorPlayerOverlayResolveCS)
			return true;
		if (g_planarMirrorPlayerOverlayResolveCompileAttempted)
			return false;

		g_planarMirrorPlayerOverlayResolveCompileAttempted = true;
		g_planarMirrorPlayerOverlayResolveCS = static_cast<ID3D11ComputeShader*>(
			Util::CompileShader(
				L"Data\\Shaders\\MirrorsOfFallout\\PlanarMirrorPlayerOverlayResolveCS.hlsl", {}, "cs_5_0"));
		if (!g_planarMirrorPlayerOverlayResolveCS) {
			logger::error(
				"[PlanarMirrors] PlanarMirrorPlayerOverlayResolveCS compile failed; retained mirror images remain active");
			return false;
		}
		logger::info(
			"[PlanarMirrors] compiled native-MRT2 immutable-environment player overlay resolve shader");
		return true;
	}

	void ReleasePlanarMirrorOverlayResources(bool releaseCameraSnapshot = true) noexcept
	{
		if (releaseCameraSnapshot) {
			g_mirrorMainViewReadback.Reset();

			g_planarMirrorCameraSnapshotPublishedGeneration.store(0u, std::memory_order_release);
			g_planarMirrorCameraSnapshotValid.store(false, std::memory_order_release);
			g_planarMirrorMainDepthSnapshotValid = false;
		}
		if (g_planarMirrorOverlayDepthStencil)
			g_planarMirrorOverlayDepthStencil->Release();
		if (g_planarMirrorOverlayBlend)
			g_planarMirrorOverlayBlend->Release();
		if (g_planarMirrorOverlayRasterizer)
			g_planarMirrorOverlayRasterizer->Release();
		if (g_planarMirrorOverlaySampler)
			g_planarMirrorOverlaySampler->Release();
		if (releaseCameraSnapshot && g_planarMirrorMainDepthSnapshotSRV)
			g_planarMirrorMainDepthSnapshotSRV->Release();
		if (releaseCameraSnapshot && g_planarMirrorMainDepthSnapshot)
			g_planarMirrorMainDepthSnapshot->Release();
		if (releaseCameraSnapshot && g_planarMirrorCameraSnapshotCB)
			g_planarMirrorCameraSnapshotCB->Release();
		if (releaseCameraSnapshot) {
			if (g_planarMirrorPreviousCameraSnapshotCB)
				g_planarMirrorPreviousCameraSnapshotCB->Release();
			g_planarMirrorPreviousCameraSnapshotCB = nullptr;
			g_planarMirrorPreviousCameraSnapshotValid = false;
		}
		if (g_planarMirrorOverlayMotionBlend)
			g_planarMirrorOverlayMotionBlend->Release();
		g_planarMirrorOverlayMotionBlend = nullptr;
		if (g_planarMirrorOverlayMotionPinBlend)
			g_planarMirrorOverlayMotionPinBlend->Release();
		g_planarMirrorOverlayMotionPinBlend = nullptr;
		g_committedDepthCopies.clear();
		if (g_planarMirrorOverlayCB)
			g_planarMirrorOverlayCB->Release();
		if (g_planarMirrorOverlayVertexSRV)
			g_planarMirrorOverlayVertexSRV->Release();
		if (g_planarMirrorOverlayVertices)
			g_planarMirrorOverlayVertices->Release();
		if (g_planarMirrorOverlayPS)
			g_planarMirrorOverlayPS->Release();
		if (g_planarMirrorVisibilityBlend) g_planarMirrorVisibilityBlend->Release();
		g_planarMirrorVisibilityBlend = nullptr;
		if (g_planarMirrorOverlayVS)
			g_planarMirrorOverlayVS->Release();
		g_planarMirrorOverlayDepthStencil = nullptr;
		g_planarMirrorOverlayBlend = nullptr;
		g_planarMirrorOverlayRasterizer = nullptr;
		g_planarMirrorOverlaySampler = nullptr;
		if (releaseCameraSnapshot) {
			g_planarMirrorMainDepthSnapshotSRV = nullptr;
			g_planarMirrorMainDepthSnapshot = nullptr;
			g_planarMirrorMainDepthSourceDesc = {};
			g_planarMirrorMainDepthSourceViewDesc = {};
			g_planarMirrorMainDepthSourceDescValid = false;
			g_planarMirrorCameraSnapshotCB = nullptr;
		}
		g_planarMirrorOverlayCB = nullptr;
		g_planarMirrorOverlayVertexSRV = nullptr;
		g_planarMirrorOverlayVertices = nullptr;
		g_planarMirrorOverlayPS = nullptr;
		g_planarMirrorOverlayVS = nullptr;
	}

	bool ObservePlanarMirrorOverlayDevice() noexcept
	{
		auto* device = globals::d3d::device;
		if (!device)
			return false;
		if (device != g_planarMirrorOverlayDevice) {
			ReleasePlanarMirrorOverlayResources();
			g_planarMirrorOverlayDevice = device;
			g_planarMirrorOverlayCompileAttempted = false;
			g_planarMirrorOverlayRetryNotBeforeMs = 0;
		}
		return true;
	}

	bool EnsurePlanarMirrorOverlayResources() noexcept
	{
		if (!ObservePlanarMirrorOverlayDevice()) return false;
		auto* device = globals::d3d::device;
		if (g_planarMirrorOverlayVS && g_planarMirrorOverlayPS && g_planarMirrorOverlayVertices &&
			g_planarMirrorOverlayVertexSRV && g_planarMirrorOverlayCB &&
			g_planarMirrorOverlaySampler && g_planarMirrorOverlayRasterizer &&
			g_planarMirrorOverlayBlend && g_planarMirrorVisibilityBlend && g_planarMirrorOverlayDepthStencil)
			return true;
		const std::uint64_t nowMs = GetTickCount64();
		if (g_planarMirrorOverlayCompileAttempted) {
			if (nowMs < g_planarMirrorOverlayRetryNotBeforeMs)
				return false;
			g_planarMirrorOverlayCompileAttempted = false;
		}

		g_planarMirrorOverlayCompileAttempted = true;
		g_planarMirrorOverlayRetryNotBeforeMs = nowMs + 1000u;
		g_planarMirrorOverlayVS = static_cast<ID3D11VertexShader*>(
			Util::CompileShader(
				L"Data\\Shaders\\MirrorsOfFallout\\PlanarMirrorOverlayCS.hlsl", {}, "vs_5_0", "VSMain"));
		g_planarMirrorOverlayPS = static_cast<ID3D11PixelShader*>(
			Util::CompileShader(
				L"Data\\Shaders\\MirrorsOfFallout\\PlanarMirrorOverlayCS.hlsl", {}, "ps_5_0", "PSMain"));
		if (!g_planarMirrorOverlayVS || !g_planarMirrorOverlayPS) {
			logger::error("[PlanarMirrors] presentation VS/PS compile failed; final mirror composite disabled");
			ReleasePlanarMirrorOverlayResources(false);
			return false;
		}

		D3D11_BUFFER_DESC vertexDesc{};
		vertexDesc.ByteWidth = static_cast<UINT>(sizeof(kPlanarMirrorPresentationVertices));
		vertexDesc.Usage = D3D11_USAGE_IMMUTABLE;
		vertexDesc.BindFlags = D3D11_BIND_SHADER_RESOURCE;
		vertexDesc.MiscFlags = D3D11_RESOURCE_MISC_BUFFER_STRUCTURED;
		vertexDesc.StructureByteStride = sizeof(PlanarMirrorPresentationVertex);
		D3D11_SUBRESOURCE_DATA vertexData{};
		vertexData.pSysMem = kPlanarMirrorPresentationVertices.data();
		if (FAILED(device->CreateBuffer(&vertexDesc, &vertexData, &g_planarMirrorOverlayVertices))) {
			logger::error("[PlanarMirrors] failed to create authored silhouette vertex buffer");
			ReleasePlanarMirrorOverlayResources(false);
			return false;
		}
		D3D11_SHADER_RESOURCE_VIEW_DESC vertexViewDesc{};
		vertexViewDesc.Format = DXGI_FORMAT_UNKNOWN;
		vertexViewDesc.ViewDimension = D3D11_SRV_DIMENSION_BUFFER;
		vertexViewDesc.Buffer.FirstElement = 0;
		vertexViewDesc.Buffer.NumElements = static_cast<UINT>(kPlanarMirrorPresentationVertices.size());
		if (FAILED(device->CreateShaderResourceView(
				g_planarMirrorOverlayVertices, &vertexViewDesc, &g_planarMirrorOverlayVertexSRV))) {
			logger::error("[PlanarMirrors] failed to create authored silhouette vertex view");
			ReleasePlanarMirrorOverlayResources(false);
			return false;
		}

		D3D11_BUFFER_DESC cbDesc{};
		cbDesc.ByteWidth = sizeof(PlanarMirrorOverlayCBData);
		cbDesc.Usage = D3D11_USAGE_DEFAULT;
		cbDesc.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
		if (FAILED(device->CreateBuffer(&cbDesc, nullptr, &g_planarMirrorOverlayCB))) {
			logger::error("[PlanarMirrors] failed to create final mirror composite constant buffer");
			ReleasePlanarMirrorOverlayResources(false);
			return false;
		}

		D3D11_SAMPLER_DESC samplerDesc{};

		samplerDesc.Filter = D3D11_FILTER_ANISOTROPIC;
		samplerDesc.MaxAnisotropy = 8u;
		samplerDesc.AddressU = D3D11_TEXTURE_ADDRESS_CLAMP;
		samplerDesc.AddressV = D3D11_TEXTURE_ADDRESS_CLAMP;
		samplerDesc.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
		samplerDesc.MinLOD = 0.0f;
		samplerDesc.MaxLOD = D3D11_FLOAT32_MAX;
		if (FAILED(device->CreateSamplerState(&samplerDesc, &g_planarMirrorOverlaySampler))) {
			logger::error("[PlanarMirrors] failed to create final mirror composite sampler");
			ReleasePlanarMirrorOverlayResources(false);
			return false;
		}

		D3D11_RASTERIZER_DESC rasterizerDesc{};
		rasterizerDesc.FillMode = D3D11_FILL_SOLID;
		rasterizerDesc.CullMode = D3D11_CULL_NONE;
		rasterizerDesc.DepthClipEnable = FALSE;
		if (FAILED(device->CreateRasterizerState(&rasterizerDesc, &g_planarMirrorOverlayRasterizer))) {
			logger::error("[PlanarMirrors] failed to create presentation rasterizer state");
			ReleasePlanarMirrorOverlayResources(false);
			return false;
		}

		D3D11_BLEND_DESC blendDesc{};
		blendDesc.RenderTarget[0].BlendEnable = FALSE;
		blendDesc.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
		if (FAILED(device->CreateBlendState(&blendDesc, &g_planarMirrorOverlayBlend))) {
			logger::error("[PlanarMirrors] failed to create presentation blend state");
			ReleasePlanarMirrorOverlayResources(false);
			return false;
		}

		blendDesc.RenderTarget[0].RenderTargetWriteMask = 0;
		if (FAILED(device->CreateBlendState(&blendDesc, &g_planarMirrorVisibilityBlend))) {
			ReleasePlanarMirrorOverlayResources(false);
			return false;
		}

		D3D11_BLEND_DESC motionBlendDesc{};
		motionBlendDesc.IndependentBlendEnable = TRUE;
		motionBlendDesc.RenderTarget[0].BlendEnable = FALSE;
		motionBlendDesc.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
		motionBlendDesc.RenderTarget[1].BlendEnable = TRUE;
		motionBlendDesc.RenderTarget[1].SrcBlend = D3D11_BLEND_SRC_ALPHA;
		motionBlendDesc.RenderTarget[1].DestBlend = D3D11_BLEND_INV_SRC_ALPHA;
		motionBlendDesc.RenderTarget[1].BlendOp = D3D11_BLEND_OP_ADD;
		motionBlendDesc.RenderTarget[1].SrcBlendAlpha = D3D11_BLEND_ONE;
		motionBlendDesc.RenderTarget[1].DestBlendAlpha = D3D11_BLEND_ZERO;
		motionBlendDesc.RenderTarget[1].BlendOpAlpha = D3D11_BLEND_OP_ADD;
		motionBlendDesc.RenderTarget[1].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_RED | D3D11_COLOR_WRITE_ENABLE_GREEN;
		if (FAILED(device->CreateBlendState(&motionBlendDesc, &g_planarMirrorOverlayMotionBlend))) {
			logger::warn("[PlanarMirrors] pane motion-vector blend state unavailable; panes present without TAA velocity");
			g_planarMirrorOverlayMotionBlend = nullptr;
		}

		motionBlendDesc.RenderTarget[1].SrcBlend = D3D11_BLEND_ZERO;
		motionBlendDesc.RenderTarget[1].DestBlend = D3D11_BLEND_ZERO;
		motionBlendDesc.RenderTarget[1].SrcBlendAlpha = D3D11_BLEND_ZERO;
		motionBlendDesc.RenderTarget[1].DestBlendAlpha = D3D11_BLEND_ZERO;
		if (FAILED(device->CreateBlendState(&motionBlendDesc, &g_planarMirrorOverlayMotionPinBlend))) {
			logger::warn("[PlanarMirrors] pane motion-pin blend state unavailable; frame generation may ghost the pane");
			g_planarMirrorOverlayMotionPinBlend = nullptr;
		}

		D3D11_DEPTH_STENCIL_DESC depthStencilDesc{};
		depthStencilDesc.DepthEnable = FALSE;
		depthStencilDesc.StencilEnable = FALSE;
		if (FAILED(device->CreateDepthStencilState(
				&depthStencilDesc, &g_planarMirrorOverlayDepthStencil))) {
			logger::error("[PlanarMirrors] failed to create presentation depth-stencil state");
			ReleasePlanarMirrorOverlayResources(false);
			return false;
		}

		g_planarMirrorOverlayRetryNotBeforeMs = 0;
		logger::info("[PlanarMirrors] compiled dedicated post-imagespace framebuffer VS/PS");
		return true;
	}

	bool IsPlanarMirrorMainDepthSourceSupported(
		const D3D11_TEXTURE2D_DESC& textureDesc,
		const D3D11_SHADER_RESOURCE_VIEW_DESC& viewDesc) noexcept
	{
		if (textureDesc.Width == 0 || textureDesc.Height == 0 || textureDesc.MipLevels == 0 ||
			textureDesc.ArraySize != 1 || textureDesc.SampleDesc.Count != 1 ||
			(textureDesc.BindFlags & D3D11_BIND_SHADER_RESOURCE) == 0 ||
			viewDesc.Format == DXGI_FORMAT_UNKNOWN ||
			viewDesc.ViewDimension != D3D11_SRV_DIMENSION_TEXTURE2D ||
			viewDesc.Texture2D.MostDetailedMip >= textureDesc.MipLevels)
			return false;

		const UINT viewMipLevels = viewDesc.Texture2D.MipLevels;
		return viewMipLevels == static_cast<UINT>(-1) ||
			(viewMipLevels != 0 &&
				viewMipLevels <= textureDesc.MipLevels - viewDesc.Texture2D.MostDetailedMip);
	}

	bool PlanarMirrorMainDepthSourceDescriptionMatches(
		const D3D11_TEXTURE2D_DESC& textureDesc,
		const D3D11_SHADER_RESOURCE_VIEW_DESC& viewDesc) noexcept
	{
		if (!g_planarMirrorMainDepthSourceDescValid)
			return false;
		const auto& cachedTexture = g_planarMirrorMainDepthSourceDesc;
		const auto& cachedView = g_planarMirrorMainDepthSourceViewDesc;
		return cachedTexture.Width == textureDesc.Width &&
			cachedTexture.Height == textureDesc.Height &&
			cachedTexture.MipLevels == textureDesc.MipLevels &&
			cachedTexture.ArraySize == textureDesc.ArraySize &&
			cachedTexture.Format == textureDesc.Format &&
			cachedTexture.SampleDesc.Count == textureDesc.SampleDesc.Count &&
			cachedTexture.SampleDesc.Quality == textureDesc.SampleDesc.Quality &&
			cachedTexture.Usage == textureDesc.Usage &&
			cachedTexture.BindFlags == textureDesc.BindFlags &&
			cachedTexture.CPUAccessFlags == textureDesc.CPUAccessFlags &&
			cachedTexture.MiscFlags == textureDesc.MiscFlags &&
			cachedView.Format == viewDesc.Format &&
			cachedView.ViewDimension == viewDesc.ViewDimension &&
			cachedView.Texture2D.MostDetailedMip == viewDesc.Texture2D.MostDetailedMip &&
			cachedView.Texture2D.MipLevels == viewDesc.Texture2D.MipLevels;
	}

	bool EnsurePlanarMirrorMainDepthSnapshot(
		const D3D11_TEXTURE2D_DESC& sourceDesc,
		const D3D11_SHADER_RESOURCE_VIEW_DESC& sourceViewDesc) noexcept
	{
		auto* device = globals::d3d::device;
		if (!device || !IsPlanarMirrorMainDepthSourceSupported(sourceDesc, sourceViewDesc))
			return false;
		if (g_planarMirrorMainDepthSnapshot && g_planarMirrorMainDepthSnapshotSRV &&
			PlanarMirrorMainDepthSourceDescriptionMatches(sourceDesc, sourceViewDesc))
			return true;

		D3D11_TEXTURE2D_DESC snapshotDesc = sourceDesc;
		snapshotDesc.Usage = D3D11_USAGE_DEFAULT;
		snapshotDesc.BindFlags = D3D11_BIND_SHADER_RESOURCE;
		snapshotDesc.CPUAccessFlags = 0;
		snapshotDesc.MiscFlags = 0;
		Microsoft::WRL::ComPtr<ID3D11Texture2D> replacementTexture;
		if (FAILED(device->CreateTexture2D(&snapshotDesc, nullptr, &replacementTexture)) ||
			!replacementTexture) {
			logger::error("[PlanarMirrors] failed to create plugin-owned main-world depth snapshot texture");
			return false;
		}
		Microsoft::WRL::ComPtr<ID3D11ShaderResourceView> replacementView;
		if (FAILED(device->CreateShaderResourceView(
				replacementTexture.Get(), &sourceViewDesc, &replacementView)) ||
			!replacementView) {
			logger::error("[PlanarMirrors] failed to create plugin-owned main-world depth snapshot SRV");
			return false;
		}

		if (g_planarMirrorMainDepthSnapshotSRV)
			g_planarMirrorMainDepthSnapshotSRV->Release();
		if (g_planarMirrorMainDepthSnapshot)
			g_planarMirrorMainDepthSnapshot->Release();
		g_planarMirrorMainDepthSnapshot = replacementTexture.Detach();
		g_planarMirrorMainDepthSnapshotSRV = replacementView.Detach();
		g_planarMirrorMainDepthSourceDesc = sourceDesc;
		g_planarMirrorMainDepthSourceViewDesc = sourceViewDesc;
		g_planarMirrorMainDepthSourceDescValid = true;
		logger::info("[PlanarMirrors] plugin-owned main-world depth snapshot ready: {}x{} textureFormat={} SRVformat={}",
			sourceDesc.Width, sourceDesc.Height,
			static_cast<std::uint32_t>(sourceDesc.Format),
			static_cast<std::uint32_t>(sourceViewDesc.Format));
		return true;
	}

	Microsoft::WRL::ComPtr<ID3D11Texture2D> PreparePlanarMirrorMainDepthSnapshot() noexcept
	{
		auto* device = globals::d3d::device;
		auto* renderer = globals::game::renderer;
		if (!device || !renderer)
			return {};

		auto* targetManager = reinterpret_cast<RE::BSGraphics::RenderTargetManager*>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_RTManager)).address());
		if (!targetManager)
			return {};

		const std::uint32_t physicalDepthTarget =
			ReflectionRuntime::DepthStencilTargetIds(targetManager)[kFO4MainWorldDepthLogicalTarget];
		if (physicalDepthTarget >= kFO4PhysicalDepthTargetCount)
			return {};

		auto& mainWorldDepth = renderer->data.depthStencilTargets[physicalDepthTarget];
		auto* sourceDepthSRV = reinterpret_cast<ID3D11ShaderResourceView*>(mainWorldDepth.srViewDepth);
		if (!sourceDepthSRV)
			return {};
		Microsoft::WRL::ComPtr<ID3D11Resource> sourceDepthResource;
		sourceDepthSRV->GetResource(&sourceDepthResource);
		Microsoft::WRL::ComPtr<ID3D11Texture2D> sourceDepthTexture;
		if (!sourceDepthResource || FAILED(sourceDepthResource.As(&sourceDepthTexture)) || !sourceDepthTexture)
			return {};
		Microsoft::WRL::ComPtr<ID3D11Device> sourceDepthDevice;
		sourceDepthTexture->GetDevice(&sourceDepthDevice);
		if (!Util::D3DDevicesMatch(sourceDepthDevice.Get(), device))
			return {};
		D3D11_TEXTURE2D_DESC sourceDepthDesc{};
		sourceDepthTexture->GetDesc(&sourceDepthDesc);
		D3D11_SHADER_RESOURCE_VIEW_DESC sourceDepthViewDesc{};
		sourceDepthSRV->GetDesc(&sourceDepthViewDesc);
		static bool loggedSource = false;
		if (!loggedSource) {
			loggedSource = true;
			logger::info(
				"[PlanarMirrors] main-world logical depth {} maps to physical slot {}",
				kFO4MainWorldDepthLogicalTarget, physicalDepthTarget);
		}
		return EnsurePlanarMirrorMainDepthSnapshot(sourceDepthDesc, sourceDepthViewDesc) ?
			sourceDepthTexture : Microsoft::WRL::ComPtr<ID3D11Texture2D>{};
	}

	constexpr wchar_t kMirrorRawCompositeTriggerPath[] = L"Data\\dynref_mirrorrawcomposite";
	std::uint32_t g_mirrorDepthPoll = 0;
	bool g_mirrorDepthTrigger = false;

	void PollMirrorDepthRejectionTrigger() noexcept
	{
		if ((g_mirrorDepthPoll++ % 60u) != 0u)
			return;
		std::error_code error;
		const bool present = std::filesystem::exists(kMirrorRawCompositeTriggerPath, error) && !error;
		if (present == g_mirrorDepthTrigger)
			return;
		g_mirrorDepthTrigger = present;
		const std::uint32_t mode = present ? 3u : 4u;
		g_planarMirrorDiagnosticMode.store(mode, std::memory_order_release);
		logger::info("[PlanarMirrors] MIRRORDEPTH composite mode {} ({}) via Data\\dynref_mirrorrawcomposite", mode,
			present ? "raw reflection" : "foreground depth rejection");
	}

	void PollMirrorEyeForwardDiagnostic() noexcept
	{

		if (g_mirrorRenderActive || g_privateRenderActive)
			return;
		static std::uint32_t poll = 0;
		if ((poll++ % 60u) != 0u)
			return;
		std::error_code error;
		const bool forceNative = std::filesystem::exists("Data/dynref_noeyeforward", error);
		if (error)
			return;
		const bool forward = !forceNative && std::filesystem::exists("Data/dynref_eyeforward", error);
		if (error)
			return;
		static bool logged = false;
		if (logged && forward == g_eyeForwardRemap)
			return;
		g_eyeForwardRemap = forward;
		logged = true;
		logger::info("[MirrorsOfFallout] EYE_RENDER_PATH={} via standalone PreUI; native eye geometry/material unchanged",
			forward ? "forward-iris" : "native-material-prefix");
	}

	[[nodiscard]] std::uint64_t CapturePlanarMirrorMainCamera(ID3D11DeviceContext* captureContext = nullptr) noexcept
	{

		if (!captureContext) {
			PollMirrorDepthRejectionTrigger();
			PollMirrorEyeForwardDiagnostic();
		}
		const std::uint32_t diagnosticMode =
			g_planarMirrorDiagnosticMode.load(std::memory_order_acquire);

		const bool captureMainDepth = diagnosticMode >= 4u && captureContext != nullptr;

		const bool routeSnapshotRequired = kBathroomMirrorOnlyProducer ||
			(g_heroMirrorPresentationActive && g_activeMirrorRoute.valid) ||
			(g_planarCommittedValid && g_planarCommittedRoute.valid) ||
			(g_sideMirrorCaptureActive && g_activeSideMirrorRoute.valid) ||
			(g_sidePlanarCommittedValid && g_sidePlanarCommittedRoute.valid) ||
			(g_extraMirrorCaptureActive && g_activeExtraMirrorRoute.valid) ||
			(g_extraPlanarCommittedValid && g_extraPlanarCommittedRoute.valid);
		if (diagnosticMode == 0u || !g_enabled || MirrorSceneRenderer::LoadBlocked() ||
			g_mirrorRenderActive || g_privateRenderActive || !g_mirrorReflections ||
			!routeSnapshotRequired)
			return 0u;

		auto* context = captureContext ? captureContext : globals::d3d::context;
		auto* device = globals::d3d::device;
		auto* cameraCB = globals::game::identifiedPerFrameBuffer;
		if (!context || !device || !cameraCB || !ObservePlanarMirrorOverlayDevice())
			return 0u;
		if (!captureContext && g_sceneCameraSnapshotGeneration &&
			g_sceneCameraSnapshotFrame == GetRenderFrame() &&
			g_sceneCameraSnapshotGeneration == g_planarMirrorCameraSnapshotPublishedGeneration.load(std::memory_order_acquire) &&
			g_planarMirrorCameraSnapshotValid && g_planarMirrorCameraSnapshotCB &&
			(!captureMainDepth || g_planarMirrorMainDepthSnapshotValid)) {
			const auto generation = std::exchange(g_sceneCameraSnapshotGeneration, 0u);
			g_mirrorMainViewReadback.Capture(device, context, g_planarMirrorCameraSnapshotCB,
				generation, MirrorSceneRenderer::LoadGeneration());
			return generation;
		}
		
		g_planarMirrorMainDepthSnapshotValid = false;

		D3D11_BUFFER_DESC sourceDesc{};
		cameraCB->GetDesc(&sourceDesc);
		if (sourceDesc.ByteWidth < 41u * sizeof(float) * 4u)
			return 0u;
		bool recreate = !g_planarMirrorCameraSnapshotCB;
		if (!recreate) {
			D3D11_BUFFER_DESC snapshotDesc{};
			g_planarMirrorCameraSnapshotCB->GetDesc(&snapshotDesc);
			recreate = snapshotDesc.ByteWidth != sourceDesc.ByteWidth;
		}
		if (recreate) {
			D3D11_BUFFER_DESC snapshotDesc{};
			snapshotDesc.ByteWidth = sourceDesc.ByteWidth;
			snapshotDesc.Usage = D3D11_USAGE_DEFAULT;
			snapshotDesc.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
			Microsoft::WRL::ComPtr<ID3D11Buffer> replacementBuffer;
			if (FAILED(device->CreateBuffer(&snapshotDesc, nullptr, &replacementBuffer)) ||
				!replacementBuffer) {
				logger::error("[PlanarMirrors] failed to create main-camera constant snapshot");
				return 0u;
			}
			if (g_planarMirrorCameraSnapshotCB)
				g_planarMirrorCameraSnapshotCB->Release();
			g_planarMirrorCameraSnapshotCB = replacementBuffer.Detach();
		}

		Microsoft::WRL::ComPtr<ID3D11Texture2D> sourceDepthTexture;
		if (captureMainDepth)
			sourceDepthTexture = PreparePlanarMirrorMainDepthSnapshot();

		{
			const auto snapshotFrame = GetRenderFrame();
			if (recreate && g_planarMirrorPreviousCameraSnapshotCB) {
				g_planarMirrorPreviousCameraSnapshotCB->Release();
				g_planarMirrorPreviousCameraSnapshotCB = nullptr;
				g_planarMirrorPreviousCameraSnapshotValid = false;
			}
			if (!recreate && g_planarMirrorCameraSnapshotValid.load(std::memory_order_acquire) &&
				snapshotFrame != g_planarMirrorCameraSnapshotFrame) {
				if (!g_planarMirrorPreviousCameraSnapshotCB) {
					D3D11_BUFFER_DESC previousDesc{};
					previousDesc.ByteWidth = sourceDesc.ByteWidth;
					previousDesc.Usage = D3D11_USAGE_DEFAULT;
					previousDesc.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
					if (FAILED(device->CreateBuffer(&previousDesc, nullptr, &g_planarMirrorPreviousCameraSnapshotCB)))
						g_planarMirrorPreviousCameraSnapshotCB = nullptr;
				}
				if (g_planarMirrorPreviousCameraSnapshotCB) {
					context->CopyResource(g_planarMirrorPreviousCameraSnapshotCB, g_planarMirrorCameraSnapshotCB);
					g_planarMirrorPreviousCameraSnapshotFrame = g_planarMirrorCameraSnapshotFrame;
					g_planarMirrorPreviousCameraSnapshotValid = true;
				}
			}
			g_planarMirrorCameraSnapshotFrame = snapshotFrame;
		}
		context->CopyResource(g_planarMirrorCameraSnapshotCB, cameraCB);
		if (captureMainDepth && sourceDepthTexture) {
			context->CopyResource(g_planarMirrorMainDepthSnapshot, sourceDepthTexture.Get());
			g_planarMirrorMainDepthSnapshotValid = true;
		}

		g_planarMirrorCameraSnapshotValid.store(true, std::memory_order_release);
		const auto snapshotGeneration =
			g_planarMirrorCameraSnapshotNextGeneration.fetch_add(
				1u, std::memory_order_acq_rel) + 1u;
		if (!captureContext) 
			g_mirrorMainViewReadback.Capture(device, context, cameraCB,
				snapshotGeneration, MirrorSceneRenderer::LoadGeneration());
		g_planarMirrorCameraSnapshotPublishedGeneration.store(
			snapshotGeneration, std::memory_order_release);
		if (captureContext) {
			g_sceneCameraSnapshotGeneration=snapshotGeneration;
			g_sceneCameraSnapshotFrame=GetRenderFrame();
		} else g_sceneCameraSnapshotGeneration=0;
		static bool loggedSnapshot = false;
		if (!loggedSnapshot) {
			loggedSnapshot = true;
			logger::info(
				"[PlanarMirrors] main-camera constants snapshotted before private reflection drive; mode3DepthCopy=false");
		}
		return snapshotGeneration;
	}

