		Microsoft::WRL::ComPtr<ID3D11Texture2D> candidateThumbnail;
		Microsoft::WRL::ComPtr<ID3D11UnorderedAccessView> candidateThumbnailUAV;
		Microsoft::WRL::ComPtr<ID3D11ShaderResourceView> candidateThumbnailSRV;
		Microsoft::WRL::ComPtr<ID3D11Texture2D> witnessThumbnail;
		Microsoft::WRL::ComPtr<ID3D11UnorderedAccessView> witnessThumbnailUAV;
		Microsoft::WRL::ComPtr<ID3D11ShaderResourceView> witnessThumbnailSRV;
