	bool PublishValidatedHeroMirrorCandidate(
		const HeroMirrorCaptureCandidate& candidate,
		std::uint64_t retainedCoverageProofSerial) noexcept
	{
		if (retainedCoverageProofSerial == 0u ||
			!HeroMirrorPublicationCandidateMatchesCurrent(candidate) ||
			(candidate.observedProofFlags & kHeroProofStateRestored) == 0u ||
			(candidate.requiredProofFlags & kHeroProofEnvironmentPixelCoverage) == 0u ||
			(candidate.observedProofFlags & kHeroProofEnvironmentPixelCoverage) == 0u ||
			candidate.environmentCoveredPixels == 0u ||
			!HeroMirrorProofFlagsReady(
				candidate.producerKind, candidate.requiredProofFlags,
				candidate.observedProofFlags, candidate.playerRequired) ||
			!candidate.sourceTexture || !candidate.sourceSRV ||
			!globals::d3d::device || !globals::d3d::context ||
			g_mirrorRenderActive || g_privateRenderActive ||
			ActivePlanarTarget(candidate.kind).Bound())
			return false;

		auto& target = ActivePlanarTarget(candidate.kind);

		StagedHeroMirrorPresentationReplacement staged{};
		if (!PrepareHeroMirrorPresentationReplacement(
				globals::d3d::device, candidate.sourceTexture, staged) ||
			!StageHeroMirrorPresentationCopy(candidate, staged))
			return false;
		if (!target.ConsumeRetainedMaterialCoverageProof(retainedCoverageProofSerial))
			return false;
		FinalizeHeroMirrorPresentationCommit(candidate, staged);

		g_planarViewProjection = candidate.viewProjection;
		g_planarReflectedEye = candidate.reflectedEye;
		g_planarObliqueApplied = candidate.obliqueApplied;
		g_planarViewProjectionValid = true;
		g_planarSliceValid = true;

		g_planarSliceResident = false;
		g_mirrorLastRefreshFrame = GetRenderFrame();
		g_planarRefreshPending = false;
		g_planarPlayerRefreshPending = false;
		return true;
	}

	struct HeroCommitted2DPublicationContext
	{
		const HeroMirrorCaptureCandidate* candidate{};
		StagedHeroMirrorPresentationReplacement* staged{};
		std::uint64_t publicationTickMs{};
		std::uint64_t publicationSerial{};
		std::uint32_t publicationFrame{};
		bool committed{};
	};
	static_assert(std::is_trivially_destructible_v<HeroCommitted2DPublicationContext>);

	void FinalizeHeroCommitted2DPublication(
		HeroCommitted2DPublicationContext& publication) noexcept
	{

		const auto& candidate = *publication.candidate;
		FinalizeHeroMirrorPresentationCommit(candidate, *publication.staged);
		g_planarViewProjection = candidate.viewProjection;
		g_planarReflectedEye = candidate.reflectedEye;
		g_planarObliqueApplied = candidate.obliqueApplied;
		g_planarViewProjectionValid = true;
		g_planarSliceValid = true;
		
		g_planarSliceResident = false;
		g_heroMirrorPublication.serial = publication.publicationSerial;
		g_heroMirrorPublication.lastPublicationTickMs = publication.publicationTickMs;
		g_mirrorLastRefreshFrame = publication.publicationFrame;
		g_planarRefreshPending = false;
		g_planarPlayerRefreshPending = false;

		publication.committed = true;
	}

