	bool CommitPlanarMirrorPresentation(DriveKind kind, const HeroMirrorCaptureCandidate& candidate) noexcept
	{

		if (!IsAuxiliaryMirrorPlanarDrive(kind) || candidate.kind != kind ||
			!HeroMirrorPublicationCandidateMatchesCurrent(candidate))
			return false;
		auto* device = globals::d3d::device;
		auto* context = globals::d3d::context;
		if (!device || !context || !candidate.sourceTexture ||
			(candidate.observedProofFlags & kHeroProofStateRestored) == 0u ||
			!ActivePlanarViewProjectionValid(kind) || !ActivePlanarMirrorRoute(kind).valid ||
			g_mirrorRenderActive || g_privateRenderActive || ActivePlanarTarget(kind).Bound())
			return false;
		StagedHeroMirrorPresentationReplacement staged{};
		if (!PrepareHeroMirrorPresentationReplacement(device, candidate.sourceTexture, staged, kind) ||
			!StageHeroMirrorPresentationCopy(candidate, staged))
			return false;
		FinalizeHeroMirrorPresentationCommit(candidate, staged);
		return true;
	}

	[[nodiscard]] bool ServiceReadyNativeHeroPublication() noexcept
	{
		auto& state = NativeHeroAsync();
		if (state.phase != NativeHeroAsyncPhase::kReady)
			return false;
		const auto& candidate = state.candidate;
		const bool retainedIdentityReady = state.terminalIdentityCurrent &&
			state.pendingIdentity != 0u && state.loadGeneration == candidate.loadGeneration &&
			state.device.Get() == candidate.device && state.device.Get() == globals::d3d::device &&
			state.context.Get() == globals::d3d::context &&
			state.receiverRoot.get() == candidate.receiverRoot &&
			state.captureCamera && state.restoreCamera && state.result.color.Get() == candidate.sourceTexture &&
			state.result.colorSRV.Get() == candidate.sourceSRV &&
			(!candidate.playerRequired ||
				(state.playerRoot.get() == candidate.playerClone.root &&
					state.faceRoot.get() == candidate.playerClone.faceRoot &&
					state.headRoot.get() == candidate.playerClone.headRoot));
		const bool evidenceReady = HeroMirrorCandidateEvidenceReady(
			candidate.producerKind, candidate.attemptSerial, candidate.completionSerial,
			candidate.requiredProofFlags, candidate.observedProofFlags,
			candidate.playerRequired, candidate.localCellFormID, candidate.localRootCount,
			candidate.environmentPassFaceMask, candidate.playerRootPassFaceMask,
			candidate.faceNodePassFaceMask, candidate.playerSubmitted,
			candidate.playerClone.sourceGeometryCount, candidate.playerClone.geometryCount,
			candidate.exactEyeGeometryCount, candidate.playerClone.drawRequirements.face);
		if (!retainedIdentityReady || !evidenceReady ||
			!HeroMirrorPublicationCandidateMatchesCurrent(candidate)) {
			logger::info(
				"[PlanarMirrors] retired stale native hero terminal candidate; last-good reflection retained and coherent fallback armed");
			ResetNativeHeroAsyncState(false);
			LatchNativeHeroMode18FallbackForCurrentLoad(
				"terminal identity changed",
				FlatDeferredPlayerCapture::Status::kProjectionAttestationFailed);
			return false;
		}

		StagedHeroMirrorPresentationReplacement alternate{};

		const bool preflightReady = candidate.sourceTexture && candidate.sourceSRV &&
			PrepareHeroMirrorPresentationReplacement(
				globals::d3d::device, candidate.sourceTexture, alternate);
		const bool committed2DStaged = preflightReady &&
			StageHeroMirrorPresentationCopy(candidate, alternate);
		HeroCommitted2DPublicationContext publication{};
		publication.candidate = std::addressof(candidate);
		publication.staged = std::addressof(alternate);
		publication.publicationTickMs = GetTickCount64();
		publication.publicationSerial = g_heroMirrorPublication.serial + 1u;
		publication.publicationFrame = GetRenderFrame();
		if (committed2DStaged)
			FinalizeHeroCommitted2DPublication(publication);
		if (!publication.committed) {
			if (state.publicationAttempts !=
				(std::numeric_limits<std::uint32_t>::max)())
				++state.publicationAttempts;
			if (state.publicationAttempts >= 8u) {
				logger::warn(
					"[PlanarMirrors] native hero atomic publication exhausted; retained last-good and armed coherent fallback");
				ResetNativeHeroAsyncState(false);
				LatchNativeHeroMode18FallbackForCurrentLoad(
					"atomic publication", FlatDeferredPlayerCapture::Status::kResultCopyFailed);
				return false;
			}
			static std::uint32_t s_nativePublicationRetryLogs = 0;
			if (++s_nativePublicationRetryLogs <= 8u ||
				(s_nativePublicationRetryLogs % 120u) == 0u) {
				logger::info(
					"[PlanarMirrors] native hero committed-2D publication deferred: preflight={} committed2D={} attempt={}/8; last-good retained",
					preflightReady, publication.committed,
					state.publicationAttempts);
			}
			return true;
		}

		static std::uint64_t nativeCommitLogs = 0;
		if (++nativeCommitLogs <= 4u || (nativeCommitLogs % 120u) == 0u)
			logger::info(
			"[PlanarMirrors] NATIVE HERO PUBLICATION COMMIT: serial={} completion={} owner={} source={}x{} alternate=true player={} pose={}",
			g_heroMirrorPublication.serial, candidate.producerCompletionIdentity,
			candidate.privateOwnerGeneration, candidate.sourceWidth, candidate.sourceHeight,
			candidate.playerSubmitted, candidate.playerClone.poseSerial);
		MarkNativeHeroCorrectnessSampleCommitted();
		ResetNativeHeroAsyncState(false);
		return true;
	}

