	void FinishNativeHeroOwner(
		NativeHeroDriveContext& context, bool forceQuarantine) noexcept
	{
		if (!context.ownerAcquired || context.ownerFinished)
			return;
		const auto disposition = forceQuarantine ||
			(context.captureCalled && context.result.proof.ownerDisposition ==
				FlatDeferredPlayerCapture::NativeWorldOwnerDisposition::kQuarantine) ?
			FlatReflectionRendererOwner::FinishDisposition::kQuarantine :
			FlatReflectionRendererOwner::FinishDisposition::kReusable;
		context.ownerLease.Finish(disposition);
		context.ownerFinished = true;
	}

	void InvokeNativeHeroWorldCapture(NativeHeroDriveContext& context) noexcept
	{
		auto result = FlatDeferredPlayerCapture::CaptureNativeWorld(context.request);
		context.result = std::move(result);
	}

	[[nodiscard]] bool PrewarmNativeHeroDriveContext(
		NativeHeroDriveContext& context,
		DriveKind driveKind,
		RE::NiAVObject* receiverRoot,
		HeroMirrorCaptureCandidate& candidate) noexcept
	{
		BeginHeroMirrorCaptureCandidate(
			driveKind, receiverRoot, std::addressof(candidate));
		if (candidate.attemptSerial == 0u ||
			candidate.kind != DriveKind::kPlanarMirror ||
			candidate.device != globals::d3d::device ||
			!globals::d3d::device || !globals::d3d::context ||
			MirrorSceneRenderer::LoadBlocked())
			return false;

		candidate.producerKind = HeroMirrorProducerKind::kNativeWorldDeferred;
		context.frameSerial = candidate.attemptSerial;
		context.cameraSnapshotGeneration = candidate.cameraSnapshotGeneration;
		if (context.cameraSnapshotGeneration == 0u ||
			context.cameraSnapshotGeneration != g_flatReflectionDriveSnapshotGeneration ||
			context.cameraSnapshotGeneration !=
				g_planarMirrorCameraSnapshotPublishedGeneration.load(std::memory_order_acquire))
			return false;

		if (!EnsurePersistentReflectionCamera())
			return false;
		auto* captureCamera = reinterpret_cast<RE::NiCamera*>(g_cam);
		RE::NiCamera* restoreCamera = nullptr;
		if (!EnsureFlatCameraCacheWarm(captureCamera, restoreCamera))
			return false;
		context.request.restoreCamera.reset(restoreCamera);
		globals::d3d::context->VSGetConstantBuffers(
			12u, 1u, context.cameraConstantBuffer.ReleaseAndGetAddressOf());
		if (!context.cameraConstantBuffer ||
			!DeviceChildUsesDevice(context.cameraConstantBuffer.Get(), globals::d3d::device))
			return false;

		FlatDeferredPlayerCapture::NativeWorldResourcePrewarmRequest prewarmRequest{};
		prewarmRequest.device = globals::d3d::device;
		prewarmRequest.immediateContext = globals::d3d::context;
		prewarmRequest.cameraConstantBuffer = context.cameraConstantBuffer.Get();
		prewarmRequest.renderThreadId = GetCurrentThreadId();
		prewarmRequest.frameSerial = context.frameSerial;

		prewarmRequest.requiredWidth = 0u;
		prewarmRequest.requiredHeight = 0u;
		context.prewarm =
			FlatDeferredPlayerCapture::PrewarmNativeWorldResources(prewarmRequest);
		context.prewarmed = static_cast<bool>(context.prewarm) &&
			context.prewarm.colorWidth != 0u && context.prewarm.colorHeight != 0u &&
			context.prewarm.depthWidth != 0u && context.prewarm.depthHeight != 0u;
		if (!context.prewarmed) {
			RecordNativeHeroPrewarmFailure(context.prewarm.status);
			static std::uint32_t s_nativePrewarmFailures = 0;
			if (++s_nativePrewarmFailures <= 8u ||
				(s_nativePrewarmFailures % 120u) == 0u) {
				logger::info(
					"[PlanarMirrors] native hero prewarm deferred: status={} frame={} cb12={}; last-good retained",
					static_cast<std::uint32_t>(context.prewarm.status), context.frameSerial,
					static_cast<void*>(context.cameraConstantBuffer.Get()));
			}
			return false;
		}
		RecordNativeHeroPrewarmSuccess();

		context.request.device = prewarmRequest.device;
		context.request.immediateContext = prewarmRequest.immediateContext;
		context.request.cameraConstantBuffer = prewarmRequest.cameraConstantBuffer;
		context.request.renderThreadId = prewarmRequest.renderThreadId;
		context.request.frameSerial = prewarmRequest.frameSerial;
		context.request.resourceGenerationIdentity =
			context.prewarm.resourceGenerationIdentity;
		context.request.requiredWidth = prewarmRequest.requiredWidth;
		context.request.requiredHeight = prewarmRequest.requiredHeight;
		context.request.cameraHandedness =
			FlatDeferredPlayerCapture::CameraHandedness::kReflected;
		return true;
	}

	[[nodiscard]] bool AdoptNativeHeroDriveResult(
		NativeHeroDriveContext& context, const DriveDiag& diag, bool driveReturnedNormally) noexcept
	{

		FinishNativeHeroOwner(
			context, context.ownerAcquired &&
				(!driveReturnedNormally || !context.captureCalled));
		if (!context.captureCalled)
			return false;
		if (!context.result.IsPending()) {
			LatchNativeHeroMode18FallbackForCurrentLoad(
				"native capture submission", context.result.status);
			return false;
		}

		auto& state = NativeHeroAsync();
		const auto& proof = context.result.proof;
		const auto& candidate = diag.heroMirrorCandidate;
		const bool playerClonePinsReady = !candidate.playerRequired ||
			(context.playerClonePinsAcquired && context.playerRootPin &&
				context.playerRootPin.get() == candidate.playerClone.root &&
				context.faceRootPin.get() == candidate.playerClone.faceRoot &&
				context.headRootPin.get() == candidate.playerClone.headRoot);
		const bool identityReady = state.phase == NativeHeroAsyncPhase::kIdle &&
			candidate.attemptSerial != 0u &&
			candidate.cameraSnapshotGeneration != 0u &&
			candidate.cameraSnapshotGeneration == context.cameraSnapshotGeneration &&
			candidate.producerKind == HeroMirrorProducerKind::kNativeWorldDeferred &&
			candidate.privateOwnerGeneration == context.ownerGeneration &&
			proof.pendingIdentity != 0u && proof.frameSerial == candidate.attemptSerial &&
			proof.ownerIdentitySerial == context.ownerGeneration &&
			proof.preparedAccumulatorSerial == context.preparedAccumulatorSerial &&
			proof.resourceGenerationIdentity == context.prewarm.resourceGenerationIdentity &&
			context.request.captureCamera && context.request.restoreCamera &&
			context.request.privateShadowSceneNode && playerClonePinsReady;
		if (!identityReady) {

			logger::warn(
				"[PlanarMirrors] native hero pending handoff tuple incomplete; retaining identity only for nonblocking drain");
		}
		const auto pendingIdentity = proof.pendingIdentity;
		const auto renderThreadId = context.request.renderThreadId;

		state = {};
		state.phase = NativeHeroAsyncPhase::kPending;
		state.candidate = candidate;
		state.result = std::move(context.result);
		state.device = context.request.device;
		state.context = context.request.immediateContext;
		state.receiverRoot.reset(candidate.receiverRoot);

		state.playerRoot = std::move(context.playerRootPin);
		state.faceRoot = std::move(context.faceRootPin);
		state.headRoot = std::move(context.headRootPin);
		state.captureCamera = context.request.captureCamera;
		state.restoreCamera = context.request.restoreCamera;
		state.pendingIdentity = pendingIdentity;
		state.renderThreadId = renderThreadId;
		state.loadGeneration = candidate.loadGeneration;
		state.deferredRefresh = !driveReturnedNormally || !identityReady;
		state.terminalIdentityCurrent = false;
		g_planarRefreshPending = false;
		g_planarPlayerRefreshPending = false;
		static std::uint64_t nativePendingLogs = 0;
		if (++nativePendingLogs <= 4u || (nativePendingLogs % 120u) == 0u)
			logger::info(
			"[PlanarMirrors] native hero authority PENDING: identity={} attempt={} owner={} roots={} source={}x{}; last-good retained",
			state.pendingIdentity, candidate.attemptSerial, context.ownerGeneration,
			context.request.submittedRootCount, context.prewarm.colorWidth,
			context.prewarm.colorHeight);
		return true;
	}

	constexpr bool CanCommitDriveResult(int facesRendered) noexcept
	{
		return facesRendered > 0;
	}

	int g_lastFaceBailSite = 0;

	constexpr std::uint32_t AdvanceFaceCursor(std::uint32_t faceBase, int facesRendered) noexcept
	{
		return CanCommitDriveResult(facesRendered) ?
		           (faceBase + static_cast<std::uint32_t>(facesRendered)) % 6u :
		           faceBase;
	}

	constexpr int ConsumeLazyFaces(int facesRemaining, int facesRendered) noexcept
	{
		if (!CanCommitDriveResult(facesRendered))
			return facesRemaining;
		return facesRendered >= facesRemaining ? 0 : facesRemaining - facesRendered;
	}

	static_assert(!CanCommitDriveResult(0));
	static_assert(CanCommitDriveResult(1));
	static_assert(AdvanceFaceCursor(4u, 0) == 4u);
	static_assert(AdvanceFaceCursor(5u, 1) == 0u);
	static_assert(ConsumeLazyFaces(6, 0) == 6);
	static_assert(ConsumeLazyFaces(6, 1) == 5);
	static_assert(ConsumeLazyFaces(1, 2) == 0);

