	std::uint32_t CycleMirrorDiagnosticMode() noexcept
	{
		std::uint32_t current = g_planarMirrorDiagnosticMode.load(std::memory_order_relaxed);
		for (;;) {
			const std::uint32_t next = current == 0u ? 1u : (current == 4u ? 0u : current + 1u);
			if (g_planarMirrorDiagnosticMode.compare_exchange_weak(
					current, next, std::memory_order_release, std::memory_order_relaxed)) {
				logger::info("[PlanarMirrors] F8 diagnostic mode {} ({})",
					next, MirrorDiagnosticModeName(next));
				return next;
			}
		}
	}

