	void RequestCycleMirrorGallery(int direction) noexcept
	{
		auto* taskInterface = F4SE::GetTaskInterface();
		if (!taskInterface) {
			logger::error("[MirrorGallery] cycle rejected: F4SE task interface is unavailable");
			return;
		}
		if (direction == 0)
			return;
		if (LoadBlocked() || REL::Module::IsVR()) {
			logger::warn("[MirrorGallery] cycle request rejected while loading, shutting down, or in VR");
			return;
		}

		MirrorGalleryState observed = g_mirrorGalleryState.load(std::memory_order_acquire);
		if (observed != MirrorGalleryState::kIdle && observed != MirrorGalleryState::kLive)
			return;

		const auto count = static_cast<std::uint32_t>(MirrorDefinitionRegistry::kDefinitionCount);
		std::uint32_t definitionIndex = direction > 0 ? 0u : count - 1u;
		const bool removeFirst = observed == MirrorGalleryState::kLive;
		if (removeFirst) {
			const auto current = g_mirrorGalleryCurrentDefinition.load(std::memory_order_acquire);
			if (current >= count) {
				logger::error("[MirrorGallery] cycle rejected: live state has no current definition");
				return;
			}
			definitionIndex = direction > 0 ? (current + 1u) % count : (current + count - 1u) % count;
		}

		g_mirrorGalleryPendingDefinition.store(definitionIndex, std::memory_order_release);
		const MirrorGalleryState queuedState =
			removeFirst ? MirrorGalleryState::kRemoveQueued : MirrorGalleryState::kSpawnQueued;
		if (!g_mirrorGalleryState.compare_exchange_strong(
				observed, queuedState,
				std::memory_order_acq_rel, std::memory_order_acquire)) {
			g_mirrorGalleryPendingDefinition.store(kNoMirrorGalleryDefinition, std::memory_order_release);
			return;
		}

		const std::uint32_t taskGeneration =
			g_mirrorGalleryTaskGeneration.fetch_add(1, std::memory_order_acq_rel) + 1;
		try {
			taskInterface->AddTask([taskGeneration, definitionIndex, removeFirst]() {
				ReplaceMirrorGalleryOnGameThread(taskGeneration, definitionIndex, removeFirst);
			});
			logger::info(
				"[MirrorGallery] game-thread {} queued for definition {}/{} '{}'",
				removeFirst ? "replacement" : "spawn", definitionIndex + 1u, count,
				MirrorGalleryDefinitionName(definitionIndex));
		} catch (...) {
			if (g_mirrorGalleryTaskGeneration.load(std::memory_order_acquire) == taskGeneration) {
				g_mirrorGalleryPendingDefinition.store(kNoMirrorGalleryDefinition, std::memory_order_release);
				g_mirrorGalleryState.store(
					removeFirst ? MirrorGalleryState::kLive : MirrorGalleryState::kIdle,
					std::memory_order_release);
			}
			logger::error("[MirrorGallery] failed to queue game-thread cycle task");
		}
	}

	void RequestRemoveMirrorGallery() noexcept
	{
		auto* taskInterface = F4SE::GetTaskInterface();
		if (!taskInterface) {
			logger::error("[MirrorGallery] removal rejected: F4SE task interface is unavailable");
			return;
		}

		const auto prior = g_mirrorGalleryState.load(std::memory_order_acquire);
		if (prior == MirrorGalleryState::kIdle)
			return;

		g_mirrorGalleryPendingDefinition.store(kNoMirrorGalleryDefinition, std::memory_order_release);
		const std::uint32_t taskGeneration =
			g_mirrorGalleryTaskGeneration.fetch_add(1, std::memory_order_acq_rel) + 1;
		g_mirrorGalleryState.store(MirrorGalleryState::kRemoveQueued, std::memory_order_release);
		try {
			taskInterface->AddTask([taskGeneration]() {
				if (g_mirrorGalleryTaskGeneration.load(std::memory_order_acquire) == taskGeneration &&
					g_mirrorGalleryState.load(std::memory_order_acquire) == MirrorGalleryState::kRemoveQueued)
					RemoveMirrorGalleryOnGameThread(true);
			});
			logger::info("[MirrorGallery] game-thread removal queued");
		} catch (...) {
			if (g_mirrorGalleryTaskGeneration.load(std::memory_order_acquire) == taskGeneration) {
				const bool hasCurrent = g_mirrorGalleryCurrentDefinition.load(std::memory_order_acquire) <
					MirrorDefinitionRegistry::kDefinitionCount;
				g_mirrorGalleryState.store(
					hasCurrent ? MirrorGalleryState::kLive : MirrorGalleryState::kIdle,
					std::memory_order_release);
			}
			logger::error("[MirrorGallery] failed to queue game-thread removal task");
		}
	}

	MirrorGalleryCleanupReport CleanupMirrorGalleryForLifecycle() noexcept
	{

		g_mirrorGalleryTaskGeneration.fetch_add(1, std::memory_order_acq_rel);
		g_mirrorGalleryPendingDefinition.store(kNoMirrorGalleryDefinition, std::memory_order_release);
		g_mirrorGalleryState.store(MirrorGalleryState::kRemoveQueued, std::memory_order_release);
		return RemoveMirrorGalleryOnGameThread(false);
	}

	void NoteD3DDrawSeamWrapper(bool present) noexcept
	{
		if (g_d3dDrawSeamWrapper.exchange(present, std::memory_order_acq_rel) == present)
			return;
		logger::warn(
			"[PlanarMirrors] d3d11 wrapper {}; mirror capture runs {} the world render (Data\\dynref_preworld forces the early seam)",
			present ? "present" : "absent", present ? "after" : "before");
	}

	std::uint32_t ResetMirrorGalleryTrackingForWorldChange() noexcept
	{

		g_mirrorGalleryTaskGeneration.fetch_add(1, std::memory_order_acq_rel);
		g_mirrorGalleryPendingDefinition.store(kNoMirrorGalleryDefinition, std::memory_order_release);
		g_mirrorGalleryState.store(MirrorGalleryState::kRemoveQueued, std::memory_order_release);
		const std::uint32_t discarded =
			MirrorGalleryTrackingEntryPresent(g_mirrorGalleryReference) ? 1u : 0u;
		ClearMirrorGalleryTrackingOnGameThread();
		g_mirrorGalleryCurrentDefinition.store(kNoMirrorGalleryDefinition, std::memory_order_release);
		g_mirrorGalleryState.store(MirrorGalleryState::kIdle, std::memory_order_release);
		return discarded;
	}

