	bool GetPlanarMirrorRoute(PlanarMirrorRoute& route) noexcept
	{
		route = {};
		if (!PlanarMirrorReadyForRouting())
			return false;
		const auto& source = g_planarCommittedRoute;
		route.sliceReserved = false;
		route.classifierValid = true;
		route.center[0] = source.center.x;
		route.center[1] = source.center.y;
		route.center[2] = source.center.z;
		route.normal[0] = source.normal.x;
		route.normal[1] = source.normal.y;
		route.normal[2] = source.normal.z;
		route.tangent[0] = source.tangent.x;
		route.tangent[1] = source.tangent.y;
		route.tangent[2] = source.tangent.z;
		route.bitangent[0] = source.bitangent.x;
		route.bitangent[1] = source.bitangent.y;
		route.bitangent[2] = source.bitangent.z;
		route.halfThickness = source.halfThickness;
		route.halfWidth = source.halfWidth;
		route.halfHeight = source.halfHeight;
		route.selfDepthMargin = source.selfDepthMargin;
		route.ellipseMask = source.ellipseMask;
		route.firstVertex = source.firstVertex;
		route.vertexCount = source.vertexCount;
		route.authoredContour = source.authoredContour;
		return true;
	}

	bool PrepareVRMirrorCapture(VRMirrorCaptureRequest& request, std::uint32_t slot) noexcept
	{
		request = {};
		if (slot >= kVRMirrorSlotCount || !REL::Module::IsVR() || !g_enabled || g_faulted || !g_mirrorReflections ||
			!PlanarMirrors::SupportsNativeCameraReflection() || !ServiceLoadGateOnRenderThread())
			return false;

		RE::NiPoint3 eye{};
		if (auto* playerCamera = RE::PlayerCamera::GetSingleton()) {
			if (auto* cameraRoot = playerCamera->cameraRoot.get())
				eye = cameraRoot->world.translate;
		}
		if (eye.x == 0.0f && eye.y == 0.0f && eye.z == 0.0f) {
			if (auto* mainCamera = RE::Main::WorldRootCamera())
				eye = mainCamera->world.translate;
		}

		ScanForRegisteredMirrorReferences(eye);
		RE::NiPoint3 captureCenter{};
		PlanarMirrorMath::Plane plane{};
		const DriveKind kind = slot == 0u ? DriveKind::kPlanarMirror :
			(slot == 1u ? DriveKind::kPlanarSideMirror : DriveKind::kPlanarExtraMirror);
		const auto& candidateRoute = slot == 0u ? g_mirrorCandidateRoute :
			(slot == 1u ? g_sideMirrorCandidateRoute : g_extraMirrorCandidateRoute);
		RE::NiPointer<RE::TESObjectREFR> mirrorReference = MirrorReferenceHandle(kind).get();
		const auto* definition = mirrorReference ? GetRegisteredMirrorDefinition(mirrorReference.get()) : nullptr;
		const bool permitted = definition && VRMirrorPolicy::Enabled(definition->family) &&
			g_workshopPlacement.CaptureAllowed(mirrorReference->GetFormID()) &&
			mirrorReference->GetParentCell();
		float ownerViewArea = 0.0f;

		static std::uint64_t s_lastInViewTick = 0;
		const auto viewTick = GetTickCount64();
		const bool projectedInView = permitted && ProjectMirrorRouteIntoMainView(candidateRoute, ownerViewArea);
		if (projectedInView) s_lastInViewTick = viewTick;
		const bool inView = projectedInView ||
			(permitted && s_lastInViewTick != 0 && viewTick - s_lastInViewTick <= 1000u);
		const bool captureGate = inView && (slot == 0u ? TryGetMirrorCapture(eye, captureCenter, plane) :
			(slot == 1u ? TryGetSideMirrorCapture(eye, captureCenter, plane) :
				TryGetExtraMirrorCapture(eye, captureCenter, plane)));
		const bool active = captureGate && candidateRoute.valid;
		if (slot == 0u) {
			
			static bool s_lastActive = false;
			static std::uint32_t s_transitionLogs = 0;
			if (active != s_lastActive) {
				s_lastActive = active;
				if (s_transitionLogs++ < 40u) {
					const char* gate = active ? "active" :
						(!mirrorReference ? "no-hero-reference" :
							(!definition ? "no-definition" :
								(!permitted ? "not-permitted(policy/workshop-held/no-cell)" :
									(!inView ? "pane-outside-both-eyes" :
										(!captureGate ? "capture-gate(candidate-stale/grazing)" : "route-invalid")))));
					logger::info("[PlanarMirrors] VR hero capture {}: gate={} ref={:08X} eye=({:.0f},{:.0f},{:.0f}) viewArea={:.4f}",
						active ? "ON" : "OFF", gate, mirrorReference ? mirrorReference->GetFormID() : 0u,
						eye.x, eye.y, eye.z, ownerViewArea);
				}
			}
		}
		if (slot == 0u) {
			g_mirrorCaptureActive = active;
			g_heroMirrorPresentationActive = active;
		} else if (slot == 1u) {
			g_sideMirrorCaptureActive = active;
		} else {
			g_extraMirrorCaptureActive = active;
		}
		auto& activeRoute = ActivePlanarMirrorRoute(kind);
		if (!active) {
			activeRoute.valid = false;
			return false;
		}

		ActivePlanarPlane(kind) = plane;
		activeRoute = candidateRoute;
		activeRoute.valid = true;
		request.route.classifierValid = true;
		request.route.center[0] = activeRoute.center.x;
		request.route.center[1] = activeRoute.center.y;
		request.route.center[2] = activeRoute.center.z;
		request.route.normal[0] = activeRoute.normal.x;
		request.route.normal[1] = activeRoute.normal.y;
		request.route.normal[2] = activeRoute.normal.z;
		request.route.tangent[0] = activeRoute.tangent.x;
		request.route.tangent[1] = activeRoute.tangent.y;
		request.route.tangent[2] = activeRoute.tangent.z;
		request.route.bitangent[0] = activeRoute.bitangent.x;
		request.route.bitangent[1] = activeRoute.bitangent.y;
		request.route.bitangent[2] = activeRoute.bitangent.z;
		request.route.halfThickness = activeRoute.halfThickness;
		request.route.halfWidth = activeRoute.halfWidth;
		request.route.halfHeight = activeRoute.halfHeight;
		request.route.selfDepthMargin = activeRoute.selfDepthMargin;
		request.route.ellipseMask = activeRoute.ellipseMask;
		request.route.firstVertex = activeRoute.firstVertex;
		request.route.vertexCount = activeRoute.vertexCount;
		request.route.authoredContour = activeRoute.authoredContour;
		request.plane[0] = plane.normal.x;
		request.plane[1] = plane.normal.y;
		request.plane[2] = plane.normal.z;
		request.plane[3] = plane.distance;

		request.receiverFormID = mirrorReference->GetFormID();
		request.loadGeneration = LoadGeneration();
		request.cellFormID = mirrorReference->GetParentCell()->GetFormID();
		if (mirrorReference && mirrorReference->loadedData && mirrorReference->loadedData->data3D)
			request.exclusionRoot = mirrorReference->loadedData->data3D.get();
		return true;
	}

