	constexpr wchar_t kForcePSTextureFlushTriggerPath[] = L"Data\\dynref_forceflush";
	constexpr std::uintptr_t kRS_PSTextureDirtyMask = 0x14;
	constexpr std::uintptr_t kRS_PSSamplerDirtyMask = 0x18;
	bool g_forcePSTextureFlush = false;
	std::uint32_t g_forcePSTextureFlushPoll = 0;
	std::uint32_t g_forcePSTextureFlushApplied = 0;

	void ForcePSTextureRebindNoexcept() noexcept
	{
		__try {
			const std::uint32_t tlsIndex = *reinterpret_cast<const std::uint32_t*>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_GameTlsIndex)).address());
			auto* tlsSlots = *reinterpret_cast<std::uint8_t**>(__readgsqword(0x58));
			std::uint8_t* renderState = nullptr;
			if (tlsSlots) {
				auto* threadBlock = *reinterpret_cast<std::uint8_t**>(tlsSlots + tlsIndex * 8u);
				if (threadBlock)
					renderState = *reinterpret_cast<std::uint8_t**>(threadBlock + 0xb20);
			}
			if (!renderState)
				renderState = *reinterpret_cast<std::uint8_t**>(REL::Offset(ReflectionRuntime::Rva(kRVA_RenderStateFallback)).address());
			if (!renderState)
				return;
			auto* shadow = renderState + kRS_DirtyFlags;  
			*reinterpret_cast<std::uint32_t*>(shadow + kRS_PSTextureDirtyMask) |= 0xFFFFu;
			*reinterpret_cast<std::uint32_t*>(shadow + kRS_PSSamplerDirtyMask) |= 0xFFFFu;
			++g_forcePSTextureFlushApplied;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
		}
	}

	constexpr std::uintptr_t kRS_ShadowVertexShader = 0x688;
	constexpr std::uintptr_t kRS_ShadowDomainShader = 0x690;
	constexpr std::uintptr_t kRS_ShadowHullShader = 0x698;
	constexpr std::uintptr_t kRS_ShadowPixelShader = 0x6A0;
	constexpr std::uint32_t kRS_DirtyDepthStencilBit = 0x4u;
	constexpr std::uint32_t kRS_DirtyRasterizerBit = 0x8u;
	constexpr std::uint32_t kRS_DirtyBlendBit = 0x10u;
	constexpr wchar_t kNoReconcileTriggerPath[] = L"Data\\dynref_noreconcile";
	bool g_reconcileDisabled = false;
	std::uint32_t g_reconcilePoll = 0;
	struct ReconcileCounters
	{
		std::uint32_t commits{ 0 };
		std::uint32_t pixelFixed{ 0 };
		std::uint32_t vertexFixed{ 0 };
		std::uint32_t hullFixed{ 0 };
		std::uint32_t domainFixed{ 0 };
		std::uint32_t faults{ 0 };
	};
	ReconcileCounters g_reconcileDrive{};
	ReconcileCounters g_reconcileTotal{};
	std::uint32_t g_reconcileDrives = 0;
	std::uint32_t g_reconcileDrivesWithFixes = 0;
	std::uint32_t g_reconcileLogs = 0;

	std::uint8_t* ResolveEngineShadowStateNoexcept() noexcept
	{
		__try {
			const std::uint32_t tlsIndex = *reinterpret_cast<const std::uint32_t*>(
				REL::Offset(ReflectionRuntime::Rva(kRVA_GameTlsIndex)).address());
			auto* tlsSlots = *reinterpret_cast<std::uint8_t**>(__readgsqword(0x58));
			std::uint8_t* renderState = nullptr;
			if (tlsSlots) {
				auto* threadBlock = *reinterpret_cast<std::uint8_t**>(tlsSlots + tlsIndex * 8u);
				if (threadBlock)
					renderState = *reinterpret_cast<std::uint8_t**>(threadBlock + 0xb20);
			}
			if (!renderState)
				renderState = *reinterpret_cast<std::uint8_t**>(REL::Offset(ReflectionRuntime::Rva(kRVA_RenderStateFallback)).address());
			return renderState ? renderState + kRS_DirtyFlags : nullptr;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return nullptr;
		}
	}

	void* EngineShaderInterfaceNoexcept(const std::uint8_t* shadow, std::uintptr_t offset) noexcept
	{
		__try {
			const auto* wrapper = *reinterpret_cast<const std::uint8_t* const*>(shadow + offset);
			return wrapper ? *reinterpret_cast<void* const*>(wrapper + 8) : nullptr;
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			return nullptr;
		}
	}

	void ReconcileEngineShadowNoexcept(ID3D11DeviceContext* context, ReconcileCounters& counters) noexcept
	{
		auto* shadow = ResolveEngineShadowStateNoexcept();
		if (!shadow || !context)
			return;
		__try {
			++counters.commits;
			*reinterpret_cast<std::uint32_t*>(shadow) |=
				kRS_DirtyDepthStencilBit | kRS_DirtyRasterizerBit | kRS_DirtyBlendBit;
			*reinterpret_cast<std::uint32_t*>(shadow + kRS_PSTextureDirtyMask) |= 0xFFFFu;
			*reinterpret_cast<std::uint32_t*>(shadow + kRS_PSSamplerDirtyMask) |= 0xFFFFu;

			auto* intendedPS = static_cast<ID3D11PixelShader*>(
				EngineShaderInterfaceNoexcept(shadow, kRS_ShadowPixelShader));
			auto* intendedVS = static_cast<ID3D11VertexShader*>(
				EngineShaderInterfaceNoexcept(shadow, kRS_ShadowVertexShader));
			auto* intendedHS = static_cast<ID3D11HullShader*>(
				EngineShaderInterfaceNoexcept(shadow, kRS_ShadowHullShader));
			auto* intendedDS = static_cast<ID3D11DomainShader*>(
				EngineShaderInterfaceNoexcept(shadow, kRS_ShadowDomainShader));

			ID3D11PixelShader* physicalPS = nullptr;
			ID3D11VertexShader* physicalVS = nullptr;
			ID3D11HullShader* physicalHS = nullptr;
			ID3D11DomainShader* physicalDS = nullptr;
			context->PSGetShader(&physicalPS, nullptr, nullptr);
			context->VSGetShader(&physicalVS, nullptr, nullptr);
			context->HSGetShader(&physicalHS, nullptr, nullptr);
			context->DSGetShader(&physicalDS, nullptr, nullptr);
			if (physicalPS != intendedPS) {
				context->PSSetShader(intendedPS, nullptr, 0);
				++counters.pixelFixed;
			}
			if (physicalVS != intendedVS) {
				context->VSSetShader(intendedVS, nullptr, 0);
				++counters.vertexFixed;
			}
			if (physicalHS != intendedHS) {
				context->HSSetShader(intendedHS, nullptr, 0);
				++counters.hullFixed;
			}
			if (physicalDS != intendedDS) {
				context->DSSetShader(intendedDS, nullptr, 0);
				++counters.domainFixed;
			}
			if (physicalPS)
				physicalPS->Release();
			if (physicalVS)
				physicalVS->Release();
			if (physicalHS)
				physicalHS->Release();
			if (physicalDS)
				physicalDS->Release();
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			++counters.faults;
		}
	}

	void PollNoReconcileTrigger() noexcept
	{
		if ((g_reconcilePoll++ % 256u) != 0u)
			return;
		std::error_code error;
		const bool present = std::filesystem::exists(kNoReconcileTriggerPath, error) && !error;
		if (present != g_reconcileDisabled) {
			g_reconcileDisabled = present;
			logger::warn(
				"[MirrorSceneRenderer] RECONCILE {}: engine shadow-state reconciliation before private-drive commits ({} drives so far, {} with corrections)",
				present ? "DISABLED by Data\\dynref_noreconcile" : "ENABLED", g_reconcileDrives,
				g_reconcileDrivesWithFixes);
		}
	}

	void ReconcileEngineShadowBeforeCommit() noexcept
	{
		if (!g_mirrorRenderActive || !globals::d3d::context)
			return;
		PollNoReconcileTrigger();
		if (g_reconcileDisabled)
			return;
		ReconcileEngineShadowNoexcept(globals::d3d::context, g_reconcileDrive);
	}

	void ReconcileEngineShadowAfterDrive() noexcept
	{
		if (g_reconcileDisabled || !globals::d3d::context)
			return;

		ReconcileCounters tail{};
		ReconcileEngineShadowNoexcept(globals::d3d::context, tail);
		const ReconcileCounters drive = g_reconcileDrive;
		g_reconcileDrive = {};
		if (drive.commits == 0u)
			return;
		++g_reconcileDrives;
		const bool fixed = drive.pixelFixed || drive.vertexFixed || drive.hullFixed || drive.domainFixed ||
			tail.pixelFixed || tail.vertexFixed;
		if (fixed)
			++g_reconcileDrivesWithFixes;
		g_reconcileTotal.commits += drive.commits;
		g_reconcileTotal.pixelFixed += drive.pixelFixed + tail.pixelFixed;
		g_reconcileTotal.vertexFixed += drive.vertexFixed + tail.vertexFixed;
		g_reconcileTotal.hullFixed += drive.hullFixed + tail.hullFixed;
		g_reconcileTotal.domainFixed += drive.domainFixed + tail.domainFixed;
		g_reconcileTotal.faults += drive.faults + tail.faults;
		const bool logNow = (fixed && g_reconcileLogs < 48u) || (g_reconcileDrives % 600u) == 0u;
		if (logNow) {
			++g_reconcileLogs;
			logger::info(
				"[MirrorSceneRenderer] RECONCILE drive={} commits={} fixed(ps/vs/hs/ds)={}/{}/{}/{} afterDrive(ps/vs)={}/{} faults={} | drivesWithFixes={}/{} totals(ps/vs/hs/ds)={}/{}/{}/{}",
				g_reconcileDrives, drive.commits, drive.pixelFixed, drive.vertexFixed, drive.hullFixed,
				drive.domainFixed, tail.pixelFixed, tail.vertexFixed, drive.faults + tail.faults,
				g_reconcileDrivesWithFixes, g_reconcileDrives, g_reconcileTotal.pixelFixed,
				g_reconcileTotal.vertexFixed, g_reconcileTotal.hullFixed, g_reconcileTotal.domainFixed);
		}
	}

	void PollForcePSTextureFlushTrigger() noexcept
	{
		if ((g_forcePSTextureFlushPoll++ % 256u) != 0u)
			return;
		std::error_code error;
		const bool present = std::filesystem::exists(kForcePSTextureFlushTriggerPath, error) && !error;
		if (present != g_forcePSTextureFlush) {
			g_forcePSTextureFlush = present;
			logger::warn(
				"[PlanarMirrors] FORCEFLUSH experiment {}: every private-drive commit {} all PS texture/sampler slots dirty (applied so far={})",
				present ? "ON" : "OFF", present ? "marks" : "no longer marks", g_forcePSTextureFlushApplied);
		}
	}

	constexpr wchar_t kSeamWindingTriggerPath[] = L"Data\\dynref_seamwinding";
	bool g_seamWindingToggle = false;
	std::uint32_t g_seamWindingPoll = 0;

	void PollSeamWindingTrigger() noexcept
	{
		if ((g_seamWindingPoll++ % 256u) != 0u)
			return;
		std::error_code error;
		const bool present = std::filesystem::exists(kSeamWindingTriggerPath, error) && !error;
		if (present != g_seamWindingToggle) {
			g_seamWindingToggle = present;
			logger::warn(
				"[PlanarMirrors] SEAMWINDING legacy post-commit winding toggle {} (Data\\dynref_seamwinding); the engine's own reflected rasterizer table is authoritative when OFF",
				present ? "ON" : "OFF");
		}
	}

	void BindPlanarTarget() noexcept
	{
		if (BindPrivateSunDepth()) return;
		if (!g_mirrorRenderActive || !globals::d3d::device || !globals::d3d::context)
			return;
		PollForcePSTextureFlushTrigger();
		if (g_forcePSTextureFlush)
			ForcePSTextureRebindNoexcept();
		auto& planarTarget = ActivePlanarTarget(g_activeDriveKind);
		if (!IsPlanarDrive(g_activeDriveKind) || !planarTarget.Bound())
			return;
		ID3D11RasterizerState* rasterizerBefore = nullptr;
		ID3D11DepthStencilState* depthStencilBefore = nullptr;
		UINT stencilBefore = 0u;
		if (g_tripwireBindFromDrawSeam) {
			globals::d3d::context->RSGetState(std::addressof(rasterizerBefore));
			globals::d3d::context->OMGetDepthStencilState(std::addressof(depthStencilBefore), std::addressof(stencilBefore));
		}
		planarTarget.Rebind(globals::d3d::context);
		if (g_tripwireBindFromDrawSeam)
			g_tripwireRebindTargetRebinds.fetch_add(1u, std::memory_order_relaxed);

		PollSeamWindingTrigger();
		if (g_seamWindingToggle)
			PlanarMirrorLookup::ApplyReflectedRasterizer(globals::d3d::device, globals::d3d::context);

		ApplyClothingDepthBiasPostSetDirty();
		g_mirrorSkyLease.Apply();
		g_mirrorEffectLease.Apply();
		if (g_tripwireBindFromDrawSeam) {
			ID3D11RasterizerState* rasterizerAfter = nullptr;
			ID3D11DepthStencilState* depthStencilAfter = nullptr;
			UINT stencilAfter = 0u;
			globals::d3d::context->RSGetState(std::addressof(rasterizerAfter));
			globals::d3d::context->OMGetDepthStencilState(std::addressof(depthStencilAfter), std::addressof(stencilAfter));
			if (rasterizerAfter != rasterizerBefore)
				g_tripwireRebindRasterizerChanges.fetch_add(1u, std::memory_order_relaxed);
			if (depthStencilAfter != depthStencilBefore)
				g_tripwireRebindDepthStencilChanges.fetch_add(1u, std::memory_order_relaxed);
			if (rasterizerAfter)
				rasterizerAfter->Release();
			if (depthStencilAfter)
				depthStencilAfter->Release();
		}
		if (rasterizerBefore)
			rasterizerBefore->Release();
		if (depthStencilBefore)
			depthStencilBefore->Release();
	}

