	void ObserveMirrorGeometry(RE::BSRenderPass* pass) noexcept
	{
		auto* geometry = pass ? pass->geometry : nullptr;
		if (LoadBlocked() || !g_mirrorReflections || !g_enabled || !geometry || REL::Module::IsVR())
			return;

		if (g_workshopMenuOpen.load(std::memory_order_acquire))
			return;

		if (!IsMirrorGeometry(geometry))
			return;
		const auto& bound = geometry->worldBound;
		if (!std::isfinite(bound.center.x) || !std::isfinite(bound.center.y) || !std::isfinite(bound.center.z) ||
			!std::isfinite(bound.fRadius) || bound.fRadius < 1.0f || bound.fRadius > 5000.0f)
			return;

		RE::NiPoint3 eye{};
		if (auto* playerCamera = RE::PlayerCamera::GetSingleton()) {
			if (auto* cameraRoot = playerCamera->cameraRoot.get())
				eye = cameraRoot->world.translate;
		}
		const float distanceSq = bound.center.GetSquaredDistance(eye);
		PlanarMirrorMath::PlaneSelectionInput planeInput{};
		planeInput.center = { bound.center.x, bound.center.y, bound.center.z };
		planeInput.eye = { eye.x, eye.y, eye.z };
		
		planeInput.worldAxes = {
			DirectX::XMFLOAT3{ geometry->world.rotate.entry[0].x, geometry->world.rotate.entry[1].x, geometry->world.rotate.entry[2].x },
			DirectX::XMFLOAT3{ geometry->world.rotate.entry[0].y, geometry->world.rotate.entry[1].y, geometry->world.rotate.entry[2].y },
			DirectX::XMFLOAT3{ geometry->world.rotate.entry[0].z, geometry->world.rotate.entry[1].z, geometry->world.rotate.entry[2].z }
		};

		PlanarMirrorMath::PlaneSelection selectedPlane{};
		if (!PlanarMirrorMath::SelectPlaneFromBasis(planeInput, selectedPlane))
			return;

		MirrorRouteState route{};
		route.center = selectedPlane.center;
		route.normal = selectedPlane.plane.normal;
		route.tangent = selectedPlane.tangent;
		route.bitangent = selectedPlane.bitangent;

		route.halfThickness = std::clamp(bound.fRadius * 0.05f, 1.5f, 16.0f);
		route.halfWidth = bound.fRadius;
		route.halfHeight = bound.fRadius;
		route.valid = true;

		PublishMirrorCandidate(bound.center, selectedPlane.plane, route, bound.fRadius, distanceSq, 0u);
		static bool s_loggedFirstMirror = false;
		if (!s_loggedFirstMirror) {
			s_loggedFirstMirror = true;
			logger::info("[PlanarMirrors] visible mirror pane: '{}' center=({:.0f},{:.0f},{:.0f}) "
				"normal=({:.3f},{:.3f},{:.3f}) radius={:.1f} confidence={:.2f}",
				geometry->GetName(), bound.center.x, bound.center.y, bound.center.z,
				selectedPlane.plane.normal.x, selectedPlane.plane.normal.y, selectedPlane.plane.normal.z,
				bound.fRadius, selectedPlane.confidence);
		}
	}

