	int ClassifyCurrentArmedDrawMaterial() noexcept
	{
		if (g_faceSkinTintReplay.transactionActive) {
			bool exactFaceDraw = false;
			__try {
				exactFaceDraw = FaceSkinTintCurrentPassMatchesUnsafe();
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				g_faceSkinTintReplay.applyFaulted = true;
				exactFaceDraw = false;
			}
			return exactFaceDraw ? 3 : 0;
		}
		if (g_eyeAlbedoOverrideActive.load(std::memory_order_acquire)) {
			const auto& eyeGroup4 = g_eyeGroup4AlbedoCleanup;
			if (eyeGroup4.transactionActive) {

				return eyeGroup4.drawActive && eyeGroup4.activePass == eyeGroup4.targetPass &&
					eyeGroup4.finalDrawActive && eyeGroup4.finalDrawPass == eyeGroup4.targetPass ? 1 : 0;
			}
		}
		const void* currentMaterial = *reinterpret_cast<void* const*>(
			REL::Offset(ReflectionRuntime::Rva(kRVA_CurrentRenderPassMaterial)).address());
		if (!currentMaterial)
			return 0;

		if (g_clothingRedrawCleanup.overrideActive && !g_clothingRedrawCleanup.eyePass &&
			g_clothingRedrawCleanup.activeMaterial == currentMaterial)
			return 2;
		if (!g_eyeAlbedoOverrideActive.load(std::memory_order_acquire))
			return 0;
		const auto& eyeGroup4 = g_eyeGroup4AlbedoCleanup;
		if (CurrentDrawMatchesEyeGroup4AlbedoTargetUnsafe(eyeGroup4))
			return 1;
		const std::uint32_t count = (std::min)(g_eyeTechniqueRewriteCount, kMaximumEyeTechniqueRewrites);
		for (std::uint32_t index = 0; index < count; ++index) {
			if (g_eyeTechniqueRewrites[index].material == currentMaterial)
				return g_eyeTechniqueRewrites[index].original == kEyeMissingDeferredTechnique ? 1 : 2;
		}
		return 0;
	}

