	bool BeginFaceSkinTintDrawOverride(ID3D11DeviceContext* context) noexcept
	{
		auto& state = g_faceSkinTintReplay;
		if (!state.transactionActive || !state.finalDrawActive ||
			!context || context != state.context)
			return false;

		if (state.drawLeaseActive)
			return false;
		state.drawLeaseActive = true;
		++state.drawCalls;
		if (state.nativeTechnique) {
			
			return true;
		}
		bool prepared = false;
		__try {
			prepared = PrepareFaceSkinTintPSOverrideInternal(context);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			prepared = false;
		}
		if (!prepared)
			state.applyFaulted = true;

		return true;
	}

