	bool BeginMirrorEyeGroup8DrawOverride(ID3D11DeviceContext* context) noexcept
	{
		auto& state = g_mirrorEyeGroup8WindingOverrideState;
		if (!state.active)
			return false;

		if (state.drawLeaseActive)
			return false;
		if (!context || context != state.context) {
			state.faulted = true;
			return false;
		}

		state.drawLeaseActive = true;
		++state.drawCalls;
		bool applied = false;
		__try {
			applied = ApplyMirrorEyeGroup8WindingOverrideInternal(context);
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			state.faulted = true;
		}
		if (!applied)
			state.faulted = true;
		
		return true;
	}

