	struct AnimationGraphManagerHolder_Update_Hook
	{
		static bool thunk(const RE::IAnimationGraphManagerHolder* holder, void* animationUpdateData)
		{
			auto* player = RE::PlayerCharacter::GetSingleton();
			if (!player || holder != static_cast<const RE::IAnimationGraphManagerHolder*>(player)) {
				if (animationUpdateData && MirrorActorNeedsFullAnimation(holder)) {

					return MirrorActorAnimation::UpdateData::UpdateVisibleActor(animationUpdateData,
						[holder] { return const_cast<RE::IAnimationGraphManagerHolder*>(holder)->ShouldUpdateAnimation(); },
						[holder](void* data) { return func(holder, data); });
				}
				return func(holder, animationUpdateData);
			}
			if (g_playerGraphUpdatePoseLeaseHeld)
				return func(holder, animationUpdateData);

			bool result = false;
			std::uint64_t sourceUpdateSerial = 0;
			g_playerRetargetWaiters.fetch_add(1, std::memory_order_release);
			AcquireSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
			g_playerRetargetWaiters.fetch_sub(1, std::memory_order_acq_rel);
			g_playerGraphUpdatePoseLeaseHeld = true;
			__try {
				result = func(holder, animationUpdateData);
				if (result) {

					sourceUpdateSerial =
						g_playerNativeUpdateSerial.fetch_add(1, std::memory_order_acq_rel) + 1;
					g_playerPrivateUpdatePendingSource.store(sourceUpdateSerial, std::memory_order_release);
					g_playerNaturalPoseSnapshot.valid = false;
				}
			} __finally {
				g_playerGraphUpdatePoseLeaseHeld = false;
				ReleaseSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
			}

			if (result) {
				__try {
					UpdatePrivatePlayerBodyAfterNativePlayer(
						holder, animationUpdateData, func.get(), sourceUpdateSerial);
				} __finally {
					
					auto expectedSource = sourceUpdateSerial;
					g_playerPrivateUpdatePendingSource.compare_exchange_strong(
						expectedSource, 0, std::memory_order_acq_rel);
				}
			}
			return result;
		}
		static inline REL::Relocation<decltype(thunk)> func;
	};

	bool CurrentPlayerManagerMatchesPrivateSourceLeased(
		PrivatePlayerBodyResources* resources,
		RE::BSAnimationGraphManager* sourceManager,
		RE::BShkbAnimationGraph* sourceGraph) noexcept
	{

		if (!resources || g_privatePlayerBody.status != PrivatePlayerBodyStatus::kReady ||
			resources->loadGeneration != MirrorSceneRenderer::LoadGeneration() ||
			resources->stateGeneration != g_privatePlayerBodyGeneration.load(std::memory_order_acquire) ||
			!resources->holder || !resources->holder->Manager() || !resources->privateGraph)
			return false;
		if (sourceManager && resources->sourceManager.get() != sourceManager)
			return false;
		if (sourceGraph && resources->sourceGraph0 != sourceGraph &&
			(!resources->sourceManager || resources->sourceManager->graph.size() != 2 ||
			 resources->sourceManager->graph[1].get() != sourceGraph))
			return false;

		auto* player = RE::PlayerCharacter::GetSingleton();
		RE::BSTSmartPointer<RE::BSAnimationGraphManager> currentManager;
		return player && player == resources->player && !MirrorSceneRenderer::LoadBlocked() &&
			static_cast<const RE::IAnimationGraphManagerHolder*>(player)
				->GetAnimationGraphManagerImpl(currentManager) &&
			currentManager && currentManager.get() == resources->sourceManager.get() &&
			currentManager->graph.size() == 2 && currentManager->graph[0].get() == resources->sourceGraph0;
	}

	template <class Function, class Value>
	void MirrorPrivatePlayerVariable(
		RE::BShkbAnimationGraph* sourceGraph,
		const RE::BSFixedString& name,
		Value value,
		Function original, bool sourceAccepted = true) noexcept
	{
		if (g_privatePlayerBodyMutationHeld || !sourceGraph || MirrorSceneRenderer::LoadBlocked())
			return;

		const auto* preFilterInput = MirrorAnimationInputs::Find(name.c_str());
		if (!preFilterInput &&
			sourceGraph != g_privateSourceGraph0.load(std::memory_order_acquire))
			return;
		bool attempted = false;
		bool mirrored = false;
		AcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		auto* resources = g_privatePlayerBody.resources;
		if (CurrentPlayerManagerMatchesPrivateSourceLeased(resources, nullptr, sourceGraph)) {
			const auto* input = MirrorAnimationInputs::Find(name.c_str());
			const auto* manager = resources->sourceManager.get();
			const bool source0 = sourceGraph == resources->sourceGraph0;
			const bool source1 = manager->activeGraph == 1 && sourceGraph == manager->graph[1].get();
			if (!MirrorAnimationInputs::AcceptRequest(sourceAccepted, source0 ? 0u : (source1 ? 1u : 2u),
					manager->activeGraph, input && input->thirdPersonIntent)) {
				ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
				return;
			}
			bool sharedType = false;
			if constexpr (std::is_same_v<Value, float>) sharedType = input && input->type == MirrorAnimationInputs::Type::kFloat && std::isfinite(value);
			if constexpr (std::is_same_v<Value, std::int32_t>) sharedType = input && input->type == MirrorAnimationInputs::Type::kInt;

			if (!MirrorAnimationInputs::ShouldReplay(source0 ? 0u : (source1 ? 1u : 2u), manager->activeGraph,
					input != nullptr, sharedType, input && input->thirdPersonIntent)) {
				ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
				return;
			}
			attempted = true;
			ScopedPrivatePlayerBodyMutation mutationScope;
			mirrored = original(resources->privateGraph, name, value);
			if (mirrored)
				++resources->mirroredVariables;
		}
		ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
		if (attempted && !mirrored) {
			static std::atomic<std::uint32_t> s_rejectedVariableReplays{ 0 };
			const auto rejected = s_rejectedVariableReplays.fetch_add(1, std::memory_order_relaxed) + 1;
			if (!(rejected <= 8 || (rejected % 600u) == 0u))
				return;
			logger::warn(
				"[ReflectionPlayerBody] private variable replay rejected: name={} rejected={}",
				name.c_str(), rejected);
		}
	}

	const char* ClassifyPrivateEventRejectGate(
		const RE::BShkbAnimationGraph* graph,
		const RE::BSFixedString& eventName) noexcept
	{
		const char* gate = "unknown";
		__try {
			const auto* graphBytes = reinterpret_cast<const std::uint8_t*>(graph);
			const auto graphAddress = reinterpret_cast<std::uintptr_t>(graphBytes);
			if (graphAddress > 0x10000 && graphAddress <= 0x00007FFFFFFFFFFFULL) {
				const auto* project = *reinterpret_cast<const std::uint8_t* const*>(graphBytes + 0x370);
				const auto projectAddress = reinterpret_cast<std::uintptr_t>(project);
				if (projectAddress > 0x10000 && projectAddress <= 0x00007FFFFFFFFFFFULL) {
					const std::uint32_t capacity = *reinterpret_cast<const std::uint32_t*>(project + 0xB4);
					const auto* entries = *reinterpret_cast<const std::uint8_t* const*>(project + 0xD0);
					const void* internedName = *reinterpret_cast<void* const*>(
						const_cast<RE::BSFixedString*>(std::addressof(eventName)));
					if (entries && capacity != 0 && capacity <= 0x10000) {
						gate = "name-lookup-miss";
						for (std::uint32_t entry = 0; entry < capacity; ++entry) {
							if (*reinterpret_cast<const void* const*>(entries + entry * 24u) == internedName) {
								gate = "state-machine-refused";
								break;
							}
						}
					}
				}
			}
		} __except (EXCEPTION_EXECUTE_HANDLER) {
			gate = "gate-scan-faulted";
		}
		return gate;
	}

	bool WeaponEventName(const char* name) noexcept
	{
		return name && (_strnicmp(name, "attack", 6) == 0 || _strnicmp(name, "weap", 4) == 0 ||
			_strnicmp(name, "rifle", 5) == 0 || _strnicmp(name, "gun", 3) == 0 ||
			_strnicmp(name, "reload", 6) == 0 || _strnicmp(name, "bolt", 4) == 0 || _stricmp(name, "Unequip") == 0);
	}
	bool RecordPrivateEventCensusLeased(PrivatePlayerBodyResources* resources, const char* name, bool live, bool clone) noexcept
	{
		std::uint64_t key = 14695981039346656037ull;
		if (name) for (const auto* p = reinterpret_cast<const unsigned char*>(name); *p; ++p) key = (key ^ *p) * 1099511628211ull;
		key = (key ^ (live ? 1u : 0u) ^ (clone ? 2u : 0u)) * 1099511628211ull;
		const bool weapon = WeaponEventName(name) && resources->weaponCensusCount++ < 64u;
		for (std::uint32_t i = 0; i < resources->eventCensusCount; ++i)
			if (resources->eventCensusKeys[i] == key) return weapon;
		if (resources->eventCensusCount == resources->eventCensusKeys.size()) return weapon;
		resources->eventCensusKeys[resources->eventCensusCount++] = key;
		return true;
	}

	struct BSAnimationGraphManager_ProcessGraphEvent_Hook
	{

		static std::uint32_t thunk(RE::BSAnimationGraphManager* manager, const RE::BSFixedString& eventName)
		{
			const auto sourceResult = func(manager, eventName);
			if (g_privatePlayerBodyMutationHeld || !manager || MirrorSceneRenderer::LoadBlocked())
				return sourceResult;

			const char* eventText = eventName.c_str();

			const bool liveLanding = sourceResult && eventText &&
				(_stricmp(eventText, "jumpLand") == 0 ||
					_stricmp(eventText, "jumpLandSoft") == 0);
			const bool liveJumpLifecycle = sourceResult && eventText &&
				_strnicmp(eventText, "jump", 4u) == 0;
			g_processGraphEventHookCalls.fetch_add(1, std::memory_order_relaxed);

			if (!MirrorAnimationRequests::ShouldForward(sourceResult != 0, manager->activeGraph, eventText)) {
				bool emit = false;
				AcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
				auto* resources = g_privatePlayerBody.resources;
				if (CurrentPlayerManagerMatchesPrivateSourceLeased(resources, manager, nullptr))
					emit = RecordPrivateEventCensusLeased(resources, eventText, false, false);
				ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
				if (emit) logger::info("[ReflectionPlayerBody] EVENTCENSUS name={} liveAccepted=false forwarded=false", eventText);
				return sourceResult;
			}
			bool emitCensus = false;
			std::uint64_t censusGeneration = 0;
			bool attempted = false;
			bool mirrored = false;
			bool jumpRecoveryNeeded = false;
			bool landingCounterpartAttempted = false;
			const char* landingCounterpartName = nullptr;
			std::uint32_t sourceActiveGraph = 0xFFFFFFFFu;
			std::uint32_t privateActiveGraph = 0xFFFFFFFFu;
			const char* rejectGate = "unknown";
			AcquireSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
			auto* resources = g_privatePlayerBody.resources;
			if (CurrentPlayerManagerMatchesPrivateSourceLeased(resources, manager, nullptr)) {

				ScopedPrivatePlayerBodyMutation mutationScope;

				++resources->attemptedEvents;
				attempted = true;
				const bool privatePoseAuthoritative = !UsesNativeThirdPersonPose(
					PlayerThirdPersonModelShown(resources->player), manager->activeGraph);
				if (liveJumpLifecycle && privatePoseAuthoritative) {
					if (GetFileAttributesW(L"Data\\dynref_landingtrace") != INVALID_FILE_ATTRIBUTES) {
						g_landingTraceUntilMs.store(GetTickCount64()+4000u,std::memory_order_relaxed);
						logger::info("[MirrorLanding] event={} frame={} sourceUpdate={} landing={}",
							eventText,GetRenderFrame(),resources->sourceUpdateSerial,liveLanding);
					}

					resources->jumpRecoveryWatch = true;
					resources->consecutiveUnchangedPublishes = 0;
					resources->jumpLandingPending = liveLanding;
				}
				sourceActiveGraph = manager->activeGraph;
				auto* privateManager = resources->holder->Manager();
				privateActiveGraph = privateManager->activeGraph;
				SynchronizePrivateAnimationInputsLeased(resources);
				if (eventText && (_stricmp(eventText, "rifleSightedStart") == 0 || _stricmp(eventText, "rifleSightedEnd") == 0)) {
					using SetInt = bool (*)(RE::BShkbAnimationGraph*, const RE::BSFixedString&, std::int32_t);
					auto setInt = reinterpret_cast<SetInt>(REL::Offset(ReflectionRuntime::Rva(kRVA_BShkbAnimationGraph_SetVariableInt)).address());
					const RE::BSFixedString sightedName("iSyncSightedState");
					(void)setInt(resources->privateGraph, sightedName, _stricmp(eventText, "rifleSightedStart") == 0 ? 1 : 0);
				}
				const auto* postureCounterpart = MirrorAnimationRequests::WeaponPostureCounterpart(manager->activeGraph, eventText);
				if (postureCounterpart && resources->player->GetWeaponMagicDrawn()) {
					const RE::BSFixedString counterpart(postureCounterpart);
					mirrored = func(privateManager, counterpart) != 0;
				} else if (eventText && _stricmp(eventText, "weaponIdle") == 0 && resources->player->GetWeaponMagicDrawn()) {
					const RE::BSFixedString counterpart("weapForceEquip");
					mirrored = func(privateManager, counterpart) != 0;
				} else mirrored = func(privateManager, eventName) != 0;
				if (!mirrored && liveLanding) {

					landingCounterpartName = _stricmp(eventText, "jumpLandSoft") == 0 ?
						"jumpLand" : "jumpLandSoft";
					const RE::BSFixedString landingCounterpartEvent(landingCounterpartName);
					++resources->attemptedEvents;
					landingCounterpartAttempted = true;
					mirrored = func(privateManager, landingCounterpartEvent) != 0;
					if (!mirrored) {
						rejectGate = ClassifyPrivateEventRejectGate(
							privateManager->graph.size() > privateActiveGraph ?
								privateManager->graph[privateActiveGraph].get() : nullptr,
							landingCounterpartEvent);
					}
				}
				emitCensus = RecordPrivateEventCensusLeased(resources, eventText, sourceResult != 0, mirrored);
				censusGeneration = resources->stateGeneration;
				if (mirrored) {
					if (eventText && _stricmp(eventText, "attackStart") == 0)
						g_fireTraceRemaining.store(30u, std::memory_order_relaxed);
					if (WeaponEventName(eventText)) {
						resources->weaponEventMs = GetTickCount64();
						resources->animationStateLogAfterMs = 0;
						if (_stricmp(eventText, "WeapEquip") == 0) resources->weaponStateDrawn = true;
						if (_stricmp(eventText, "Unequip") == 0) resources->weaponStateDrawn = false;
						if (_stricmp(eventText, "rifleSightedStart") == 0) resources->weaponStateSighted = true;
						if (_stricmp(eventText, "rifleSightedEnd") == 0) resources->weaponStateSighted = false;
					}
					if (eventText && (_stricmp(eventText, "MoveStart") == 0 || _stricmp(eventText, "moveStartAnimated") == 0))
						resources->sneakMoveActive = true;
					else if (eventText && (_stricmp(eventText, "MoveStop") == 0 || _stricmp(eventText, "sneakStop") == 0))
						resources->sneakMoveActive = false;
					++resources->mirroredEvents;
				} else {
					
					if (!landingCounterpartAttempted) {
						rejectGate = ClassifyPrivateEventRejectGate(
							privateManager->graph.size() > privateActiveGraph ?
								privateManager->graph[privateActiveGraph].get() : nullptr,
							eventName);
					}
					if (liveJumpLifecycle && privatePoseAuthoritative) {

						g_privatePlayerBody.status = PrivatePlayerBodyStatus::kEmpty;
						g_privatePlayerBodyGeneration.fetch_add(1, std::memory_order_acq_rel);
						jumpRecoveryNeeded = true;
					}
				}
			}
			ReleaseSRWLockExclusive(std::addressof(g_privatePlayerBodyLock));
			if (landingCounterpartAttempted) {
				logger::info(
					"[ReflectionPlayerBody] landing counterpart replay: liveName={} counterpart={} accepted={}",
					eventText, landingCounterpartName, mirrored);
			}
			if (jumpRecoveryNeeded) {

				RequestPrivatePlayerBodyTeardown();
				static std::atomic<std::uint32_t> s_jumpRecoveries{ 0 };
				const auto recovery = s_jumpRecoveries.fetch_add(1, std::memory_order_relaxed) + 1;
				if (recovery <= 8u) {
					logger::warn(
						"[ReflectionPlayerBody] jump lifecycle recovery queued after clone refusal: name={} "
						"liveAccepted=true cloneAccepted=false recovery={}",
						eventText, recovery);
				}
			}
			if (attempted && emitCensus)
				logger::info("[ReflectionPlayerBody] EVENTCENSUS name={} liveAccepted={} cloneAccepted={} gate={} sourceActiveGraph={} privateActiveGraph={} generation={}",
					eventText, sourceResult != 0, mirrored, mirrored ? "accepted" : rejectGate, sourceActiveGraph, privateActiveGraph, censusGeneration);

			return sourceResult;
		}
		static inline REL::Relocation<decltype(thunk)> func;
	};

