	struct PlayerNaturalPose_PostUpdate_Hook
	{
		static void thunk(
			const RE::IAnimationGraphManagerHolder* holder,
			const RE::BSTSmartPointer<RE::BSAnimationGraphManager>& animationGraphManager)
		{
			bool captured = false;
			bool trustedCaptureExpected = false;
			std::uint32_t capturedCount = 0;
			std::uint32_t capturedFrame = 0;
			std::uint32_t capturedThread = 0;
			std::uint64_t capturedSerial = 0;
			const bool inheritedGraphUpdateLease = g_playerGraphUpdatePoseLeaseHeld;
			if (!inheritedGraphUpdateLease) {
				g_playerRetargetWaiters.fetch_add(1, std::memory_order_release);
				AcquireSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
				g_playerRetargetWaiters.fetch_sub(1, std::memory_order_acq_rel);
			}

			__try {
				auto* candidate = std::addressof(g_playerNaturalPoseCaptureStaging);
				auto* player = RE::PlayerCharacter::GetSingleton();
				trustedCaptureExpected = player &&
					holder == static_cast<const RE::IAnimationGraphManagerHolder*>(player) &&
					PlayerThirdPersonModelShown(player) && animationGraphManager &&
					animationGraphManager->graph.size() == 2 && animationGraphManager->activeGraph == 0;
				if (trustedCaptureExpected) {
					captured = CapturePlayerNaturalPoseNoexcept(
						holder, animationGraphManager.get(), candidate);
				}
				func(holder, animationGraphManager);
				if (captured) {
					if (PlayerPoseDiagnosticsRequested(candidate->captureFrame)) {
						static thread_local std::uint32_t s_diagnosticCallbackFrame = UINT32_MAX;
						static thread_local std::uint32_t s_diagnosticCallbackOrdinal = 0;
						if (s_diagnosticCallbackFrame != candidate->captureFrame) {
							s_diagnosticCallbackFrame = candidate->captureFrame;
							s_diagnosticCallbackOrdinal = 0;
						}
						candidate->diagnosticCallbackOrdinal = ++s_diagnosticCallbackOrdinal;
						candidate->diagnosticAnimationGraphManager = animationGraphManager.get();
						CompareSnapshotNaturalPoseNoexcept(
							candidate, std::addressof(candidate->nativeRetargetEvidence));
					}
					candidate->serial = g_playerNaturalPoseSerial.fetch_add(1, std::memory_order_relaxed) + 1;
					PublishPlayerNaturalPoseSnapshotLeased(candidate);
					capturedCount = candidate->count;
					capturedFrame = candidate->captureFrame;
					capturedThread = candidate->threadId;
					capturedSerial = candidate->serial;
				} else if (trustedCaptureExpected) {

					g_playerNaturalPoseSnapshot.valid = false;
				}
			} __finally {
				if (!inheritedGraphUpdateLease)
					ReleaseSRWLockExclusive(std::addressof(g_playerNaturalPoseLock));
			}

			if (captured) {
				static bool s_loggedFirstCapture = false;
				if (!s_loggedFirstCapture) {
					s_loggedFirstCapture = true;
					logger::info(
						"[MirrorSceneRenderer] captured diagnostic native graph-0 pose: treeEntries={} serial={} frame={} thread={}",
						capturedCount, capturedSerial, capturedFrame, capturedThread);
				}
			} else if (trustedCaptureExpected) {
				static std::uint32_t s_failedCaptureLogs = 0;
				if (++s_failedCaptureLogs <= 4 || (s_failedCaptureLogs % 600u) == 0u) {
					logger::warn(
						"[MirrorSceneRenderer] diagnostic native graph-0 pose capture unavailable: serial={} frame={} failures={}",
						capturedSerial, capturedFrame, s_failedCaptureLogs);
				}
			}
		}
		static inline REL::Relocation<decltype(thunk)> func;
	};

	thread_local std::uint32_t g_flatReflectionDriveActiveThread = 0;
	bool g_flatMirrorBeforeForwardInstalled = false;

	struct MirrorForwardPointLightsHook
	{
		using Function = void (*)(void*, const void*, const void*, int, bool, float, std::uint32_t);
		static inline Function original = nullptr;
		static void thunk(void* constants, const void* pass, const void* transform,
			int count, bool projected, float scale, std::uint32_t mode)
		{
			if (!g_flatReflectionDriveActiveThread || !IsMirrorPlanarDrive(g_activeDriveKind) ||
				MirrorLightFade::g_useEngineFade) {
				original(constants, pass, transform, count, projected, scale, mode);
				return;
			}
			MirrorForwardLights::Inputs inputs{};
			bool prepared = false;
			__try { prepared = inputs.Prepare(pass, count); }
			__except (EXCEPTION_EXECUTE_HANDLER) { prepared = false; }
			original(constants, prepared ? inputs.pass.data() : pass, transform, count, projected, scale, mode);
		}
		static void Install() noexcept
		{
			if (original || REL::Module::IsVR()) return;
			const auto rva = ReflectionRuntime::Rva(0x289F550u);
			if (!rva) return;
			const auto address = REL::Module::get().base() + rva;
			constexpr std::array<std::uint8_t, 10> entry{0x4C,0x89,0x44,0x24,0x18,0x48,0x89,0x54,0x24,0x10};
			if (std::memcmp(reinterpret_cast<const void*>(address), entry.data(), entry.size()) != 0) {
				logger::warn("[PlanarMirrors] reflected forward-light fade correction skipped: native entry differs");
				return;
			}
			original = reinterpret_cast<Function>(address);
			stl::DetourTransactionLock lock{ stl::DetourTransactionMutex() };
			LONG status = DetourTransactionBegin();
			const bool started = status == NO_ERROR;
			if (status == NO_ERROR) status = DetourUpdateThread(GetCurrentThread());
			if (status == NO_ERROR) status = DetourAttach(reinterpret_cast<PVOID*>(&original), reinterpret_cast<PVOID>(&thunk));
			if (status == NO_ERROR) status = DetourTransactionCommit();
			else if (started) (void)DetourTransactionAbort();
			if (status != NO_ERROR) original = nullptr;
			logger::info("[PlanarMirrors] reflected forward-light fade correction installed={} status={}", status == NO_ERROR, status);
		}
	};

