	struct BSBatchRenderer_GetCommandBufferPasses_Hook
	{
		static void* thunk(
			void* batchRenderer,
			std::int32_t instanceIndex,
			std::uint32_t technique,
			const void* batchRecord)
		{
			if (ShouldBypassExactFaceSkinTintCommandBuffer(
					instanceIndex, technique, batchRecord))
				return nullptr;
			if (ShouldBypassMirrorEyeGroup8CommandBuffer(
					instanceIndex, technique, batchRecord))
				return nullptr;
			if (ShouldBypassEyeGroup4CommandBuffer(instanceIndex, technique, batchRecord))
				return nullptr;
			return func(batchRenderer, instanceIndex, technique, batchRecord);
		}
		static inline REL::Relocation<decltype(thunk)> func;
	};

