	struct BSBatchRenderer_RenderPassImmediately_Hook
	{
		static bool thunk(RE::BSRenderPass* pass, std::uint32_t technique, bool alphaSetup)
		{

			const auto* mirrorEyeGroup8Record = FindExactMirrorEyeGroup8Record(pass, technique);
			bool mirrorEyeGroup8WindingOverride = false;
			bool mirrorEyeGroup8Query = false;
			bool eyeAlbedoDraw = false;
			bool faceSkinTintDraw = false;
			bool accepted = false;
			bool nativeCompleted = false;
			bool eyePixelQuery = false;
			bool ownsFlatOrdinaryPass = false;
			auto nativeWorldPassScope =
				FlatDeferredPlayerCapture::NativeWorldPassWindingScope::kInactive;
			__try {
				mirrorEyeGroup8Query = mirrorEyeGroup8Record &&
					BeginMirrorEyeGroup8QueryNoexcept(
						globals::d3d::context, pass, mirrorEyeGroup8Record);
				faceSkinTintDraw = BeginFaceSkinTintFinalDrawInternal(
					pass, globals::d3d::context);
				eyeAlbedoDraw = BeginEyeGroup4AlbedoFinalDraw(pass, globals::d3d::context);
				eyePixelQuery = eyeAlbedoDraw &&
					BeginEyeGroup4OcclusionQueryInternal(globals::d3d::context);
				ownsFlatOrdinaryPass =
					FlatDeferredPlayerCapture::TryBeginOrdinaryForwardPass(pass);
				if (ownsFlatOrdinaryPass)
					(void)FlatDeferredPlayerCapture::PrimeOrdinaryForwardPassCommit(pass);
				mirrorEyeGroup8WindingOverride = mirrorEyeGroup8Record &&
					BeginMirrorEyeGroup8WindingOverrideInternal(
						globals::d3d::context, pass, mirrorEyeGroup8Record);
				nativeWorldPassScope =
					FlatDeferredPlayerCapture::BeginNativeWorldGeometryPass(pass);
				accepted = func(pass, technique, alphaSetup);
				nativeCompleted = true;
			} __finally {
				FlatDeferredPlayerCapture::EndNativeWorldGeometryPass(
					nativeWorldPassScope);
				
				if (mirrorEyeGroup8Record) {
					if (mirrorEyeGroup8WindingOverride)
						(void)EndMirrorEyeGroup8WindingOverrideInternal(nativeCompleted, accepted);
					else
						RecordMirrorEyeGroup8PublicationFailure();
				}
				if (mirrorEyeGroup8Query) {
					EndMirrorEyeGroup8QueryNoexcept(
						globals::d3d::context, nativeCompleted, accepted);
				}
				if (ownsFlatOrdinaryPass)
					FlatDeferredPlayerCapture::EndOrdinaryForwardPass(
						pass, nativeCompleted, accepted);
				if (eyePixelQuery) {
					EndEyeGroup4OcclusionQueryInternal(
						globals::d3d::context, true, accepted, nativeCompleted);
				}
				if (eyeAlbedoDraw) {

					EndEyeGroup4AlbedoFinalDraw(
						pass, globals::d3d::context, true, accepted);
				}
				if (faceSkinTintDraw) {
					EndFaceSkinTintFinalDrawInternal(
						pass, globals::d3d::context, nativeCompleted, accepted);
				}
			}
			if (mirrorEyeGroup8Record) {
				static std::uint32_t s_group8ImmediateLogs = 0;
				if (s_group8ImmediateLogs++ < 16u) {
					logger::info(
						"[MirrorSceneRenderer] EYEGROUP8 native immediate completed: pass={} geometry={} material={} technique=0x{:08X} completed={} accepted={} queried={}",
						static_cast<const void*>(pass),
						static_cast<const void*>(mirrorEyeGroup8Record->geometry),
						mirrorEyeGroup8Record->material, technique, nativeCompleted,
						accepted, mirrorEyeGroup8Query);
				}
			}
			return accepted;
		}
		static inline REL::Relocation<decltype(thunk)> func;
	};

