	[[nodiscard]] bool MatchesDrawWorldEndEntry(std::uintptr_t a_address) noexcept
	{
		if (a_address <= 0x10000)
			return false;

		const auto* code = reinterpret_cast<const std::uint8_t*>(a_address);
		if (std::memcmp(code, ReflectionRuntime::Prologue(kRVA_DrawWorld_End, kDrawWorldEndPrologue).data(), kDrawWorldEndPrologue.size()) != 0)
			return false;

		auto resolveRel32Call = [](const std::uint8_t* a_call) noexcept {
			std::int32_t displacement = 0;
			std::memcpy(std::addressof(displacement), a_call + 1, sizeof(displacement));
			return reinterpret_cast<std::uintptr_t>(a_call + 5) + displacement;
		};
		const auto clearActivePassesAddress = REL::Offset(ReflectionRuntime::Rva(kRVA_ClearActivePasses)).address();
		return resolveRel32Call(code + 13) == clearActivePassesAddress &&
		       resolveRel32Call(code + 27) == clearActivePassesAddress;
	}

	[[nodiscard]] bool MatchesDrawWorldRenderPreUIEntry(std::uintptr_t a_address) noexcept
	{
		return a_address > 0x10000 && std::memcmp(
			reinterpret_cast<const void*>(a_address),
			ReflectionRuntime::Prologue(kRVA_DrawWorld_RenderPreUI, kDrawWorldRenderPreUIPrologue).data(),
			kDrawWorldRenderPreUIPrologue.size()) == 0;
	}

